window.DATA_C2_G=[{"id":"G1","q":"¡Qué preciosidad ____ niño!","o":["para","de","por","a"],"a":1,"k":"qué + 명사 + de","t":"아이가 정말 예쁘기도 하지!","e":"'¡Qué + 명사 + de + 명사!'는 사람이나 물건을 감탄하며 평가하는 구어 표현입니다. 앞의 명사(preciosidad, '아주 귀여움/예쁨')가 뒤의 명사(niño)를 설명하는 구조로, de가 둘을 이어 줍니다. 직역하면 '아이의 이 예쁨이란!'이지만 자연스럽게는 '정말 예쁜 아이구나!'라는 뜻이에요. 예: ¡Qué maravilla de día!(정말 멋진 날이야!)","x":["para: '~을 위해/~에게'라는 목적·방향을 나타내 감탄 구조에 쓰지 않습니다 ✗","de: 'qué + 평가 명사 + de + 대상'을 잇는 전치사 → 정답 ✓","por: 원인·경로를 나타내며 이 감탄 구조와 맞지 않습니다 ✗","a: 방향·간접목적을 나타내며 이 구조에는 쓰지 않습니다 ✗"]},{"id":"G2","q":"Doy esta discusión ____ terminada.","o":["por","de","para","en"],"a":0,"k":"dar por + 과거분사","t":"이 논쟁은 끝난 것으로 하겠습니다.","e":"'dar algo por + 과거분사/형용사'는 '~을 …한 것으로 간주하다, …로 치다'라는 관용 구문입니다. 'Doy esta discusión por terminada'는 말하는 사람이 일방적으로 '이 논의는 끝났다고 본다'는 단호한 선언 느낌이 있어요. 과거분사는 목적어(discusión, 여성 단수)와 성·수를 맞춰 terminada가 됩니다. 예: Lo dimos por perdido.(우리는 그것을 잃어버린 셈 쳤다)","x":["por: 'dar por ~'로 '~한 것으로 간주하다'라는 고정 표현 → 정답 ✓","de: 'dar de ~'는 이런 '간주하다' 뜻으로 쓰지 않습니다 ✗","para: 목적을 나타내 '끝내기 위해 준다'처럼 어색한 뜻이 됩니다 ✗","en: 'dar en ~'은 '~에 맞다/~하는 버릇이 들다' 뜻이라 맞지 않습니다 ✗"]},{"id":"G3","q":"____ estos precios tan altos no se puede ahorrar.","o":["Para","De","Con","Sobre"],"a":2,"k":"전치사 con (조건·상황)","t":"이렇게 비싼 물가로는 저축을 할 수가 없다.","e":"con은 '~와 함께'뿐 아니라 '~한 상황에서는, ~가 있으니'라는 조건·원인의 뜻으로도 자주 씁니다. 'Con estos precios tan altos'는 '물가가 이렇게 높은 상황에서는'이라는 의미예요. 'no se puede + 동사원형'은 무인칭(특정 주어 없이 '일반적으로') 표현으로 '~할 수 없다'입니다. 예: Con este frío no salgo.(이렇게 추운데 난 안 나가)","x":["Para: '~을 위해'라는 목적이라 '높은 물가를 위해'라는 이상한 뜻이 됩니다 ✗","De: 출처·소유를 나타내며 이런 상황·조건의 뜻으로는 쓰지 않습니다 ✗","Con: '~한 상황(조건)에서는'의 뜻 → 정답 ✓","Sobre: '~위에/~에 관해'라는 뜻이라 문맥에 맞지 않습니다 ✗"]},{"id":"G4","q":"____ mejor cuando vio a su padre.","o":["Se había sentido","Se ha sentido","Se sintió","Se sentía"],"a":2,"k":"단순과거 vs 불완료","t":"그는 아버지를 보았을 때 기분이 나아졌다.","e":"'cuando vio a su padre(아버지를 본 순간)'라는 특정 시점에 일어난 상태 변화는 단순과거(완료된 한 번의 사건을 나타내는 과거)로 씁니다. sentirse mejor는 '나아짐을 느꼈다'는 변화의 순간이므로 se sintió가 자연스럽습니다. 불완료과거(se sentía)는 배경 상태를 묘사할 때 써서 '보았을 때 (이미) 나아진 상태였다'는 다른 뉘앙스가 됩니다.","x":["Se había sentido: 대과거로 '보기 전에 이미 나았다'는 뜻이 되어 시간 관계가 어긋납니다 ✗","Se ha sentido: 현재완료는 현재와 연결된 과거라 vio(단순과거)와 어울리지 않습니다 ✗","Se sintió: 특정 순간의 상태 변화를 나타내는 단순과거 → 정답 ✓","Se sentía: 배경 묘사용 불완료과거라 '그 순간 나아졌다'는 변화가 드러나지 않습니다 ✗"]},{"id":"G5","q":"El viernes iremos ____ los González.","o":["dónde","adonde","adónde","en donde"],"a":1,"k":"adonde + 사람 (구어)","t":"금요일에 우리는 곤살레스 씨네 집에 갈 거야.","e":"adonde는 원래 '~하는 곳으로'라는 관계부사인데, 구어에서는 'adonde + 사람'으로 '~의 집(가게)으로'라는 전치사처럼 씁니다(ir adonde los González = 곤살레스네로 가다). 의문문이 아니므로 악센트 없는 adonde를 씁니다. 이 용법은 중남미에서 특히 흔하며, 스페인에서는 'a casa de los González'라고도 많이 말해요. 참고로 'los González'처럼 성(姓)은 복수여도 -s를 붙이지 않습니다.","x":["dónde: 악센트가 있는 의문사(어디)이고 방향(~로)도 나타내지 못합니다 ✗","adonde: 의문이 아닌 '~에게로/~네로'를 뜻하는 형태 → 정답 ✓","adónde: 악센트가 있는 의문사(어디로?)라 평서문에 맞지 않습니다 ✗","en donde: '~에서'라는 위치를 나타내 이동 동사 ir와 어울리지 않습니다 ✗"]},{"id":"G6","q":"Estos niños siempre están haciendo ____. Son muy traviesos.","o":["las suyas","de las suyas","de lo suyo","con lo suyo"],"a":1,"k":"hacer de las suyas","t":"이 아이들은 늘 말썽을 피운다. 정말 장난꾸러기들이다.","e":"'hacer de las suyas'는 '평소처럼 제멋대로 장난(말썽)을 치다'라는 관용 표현입니다. las suyas는 '그 사람 특유의 짓들'을 뜻하며, 주어에 따라 de las mías/tuyas/nuestras처럼 바뀝니다. 꼭 de를 넣어야 한다는 점이 포인트예요. 예: Ya estás haciendo de las tuyas.(너 또 버릇처럼 말썽 피우는구나)","x":["las suyas: de가 빠져 관용 표현이 완성되지 않습니다 ✗","de las suyas: 'hacer de las suyas(말썽을 피우다)'의 정확한 형태 → 정답 ✓","de lo suyo: 중성 lo를 쓴 형태는 이 관용구에 없습니다 ✗","con lo suyo: 'ir a lo suyo(제 일만 신경 쓰다)'와 혼동한 형태로 맞지 않습니다 ✗"]},{"id":"G7","q":"¿Cómo te explicas que Leo siempre se salga con ____?","o":["suya","el suyo","lo suyo","la suya"],"a":3,"k":"salirse con la suya","t":"레오가 항상 자기 뜻대로 해내는 걸 넌 어떻게 설명하겠니?","e":"'salirse con la suya'는 '(반대가 있어도) 결국 자기 뜻대로 하다, 고집을 관철하다'라는 관용 표현입니다. la suya는 '자기 뜻(voluntad)'을 가리키는 여성형으로 고정되어 있어요. 'que + 접속법(se salga)'은 '¿Cómo te explicas que...?'처럼 놀람·평가를 나타내는 구문 뒤라서 쓰였습니다. 예: Al final se salió con la suya.(결국 그는 자기 뜻대로 했다)","x":["suya: 정관사 la가 빠져 관용구가 성립하지 않습니다 ✗","el suyo: 남성형은 이 관용구에 쓰지 않습니다 ✗","lo suyo: 중성형으로 '자기 몫/자기 일'이라는 다른 뜻입니다 ✗","la suya: 'salirse con la suya(자기 뜻대로 하다)'의 정확한 형태 → 정답 ✓"]},{"id":"G8","q":"Los dos documentos llegaron en ____ sobres.","o":["mutuos","sendos","correspondientes","respectivos"],"a":1,"k":"sendos (각각 하나씩)","t":"두 서류는 각각 다른 봉투에 (하나씩) 담겨 도착했다.","e":"sendos/sendas는 '각자 하나씩의'라는 뜻의 격식 있는 형용사로, 항상 복수형으로 명사 앞에 씁니다. 'dos documentos llegaron en sendos sobres'는 '서류 하나당 봉투 하나씩'이라는 정확한 분배의 의미예요. '둘 다 큰 봉투'라는 뜻으로 오해해 쓰는 경우가 있는데 틀린 용법이니 주의하세요. 주로 문어·신문 기사에서 쓰는 고급 어휘입니다.","x":["mutuos: '서로의, 상호의'라는 뜻이라 봉투에는 어울리지 않습니다 ✗","sendos: '각각 하나씩의'라는 분배 의미 → 정답 ✓","correspondientes: '해당하는'이라는 뜻으로 가능해 보이지만 보통 los를 붙여 쓰고 '하나씩'의 의미가 약합니다 ✗","respectivos: '각자의'라는 뜻으로 보통 sus respectivos처럼 소유사와 함께 쓰여 여기선 부자연스럽습니다 ✗"]},{"id":"G9","q":"Será un viaje muy corto, así que llevaos ____ justo.","o":["al","lo","del","el"],"a":1,"k":"lo justo (중성 lo)","t":"아주 짧은 여행이 될 테니 꼭 필요한 것만 챙겨 가렴.","e":"중성 관사 lo + 형용사는 '~한 것'이라는 추상적 의미를 만듭니다. 'lo justo'는 '딱 필요한 만큼, 최소한의 것'이라는 뜻으로 'llevar lo justo(필요한 것만 가져가다)'처럼 자주 써요. llevaos는 vosotros 긍정명령 llevad + 재귀대명사 os에서 d가 빠진 형태로, 스페인에서 쓰는 형태입니다(중남미에서는 llévense). 예: Come lo justo.(필요한 만큼만 먹어)","x":["al: a + el 축약형으로 목적어 자리에 올 수 없습니다 ✗","lo: 'lo + 형용사'로 '딱 필요한 것'을 뜻함 → 정답 ✓","del: de + el 축약형이라 목적어가 될 수 없습니다 ✗","el: 'el justo'는 '정의로운 사람(남성)'이라는 다른 뜻이 됩니다 ✗"]},{"id":"G10","q":"¿Cuándo ____ vuestra clase de turco?","o":["es","está","esté","sea"],"a":0,"k":"ser (행사의 시간·장소)","t":"너희 터키어 수업은 언제야?","e":"수업·회의·파티 같은 '행사(일어나는 일)'의 시간이나 장소를 말할 때는 estar가 아니라 ser를 씁니다. '¿Cuándo es la clase?(수업이 언제야?)', 'La fiesta es en mi casa.(파티는 우리 집에서 해)'처럼요. 의문문으로 사실을 묻는 것이므로 직설법을 씁니다.","x":["es: 행사의 시간을 말할 때 쓰는 ser → 정답 ✓","está: estar는 사물·사람의 위치에 쓰고 행사의 시간에는 쓰지 않습니다 ✗","esté: estar의 접속법으로 일반 의문문에 쓰지 않습니다 ✗","sea: ser의 접속법이라 단순한 질문에는 맞지 않습니다 ✗"]},{"id":"G11","q":"No noté que Carmen ____ el pelo.","o":["se hubiera cortado","se ha cortado","le cortan","se cortaría"],"a":0,"k":"부정 지각동사+접속법","t":"카르멘이 머리를 자른 줄 몰랐다.","e":"notar(알아채다), ver, saber 같은 지각·인식 동사가 부정(no)이 되면 뒤의 que절은 보통 접속법을 씁니다. 주절이 과거(noté)이고, 머리를 자른 일이 그보다 먼저 일어났으므로 접속법 과거완료(se hubiera cortado)가 됩니다. 긍정이라면 'Noté que se había cortado el pelo.'처럼 직설법을 씁니다.","x":["se hubiera cortado: 부정 인식동사 뒤 + 이전 사건을 나타내는 접속법 과거완료 → 정답 ✓","se ha cortado: 현재완료 직설법이라 과거 주절(noté)과 시제가 맞지 않습니다 ✗","le cortan: '(누군가가) 그녀의 머리를 자른다'는 현재형이라 시제·구조가 어긋납니다 ✗","se cortaría: 조건법(~할 것)으로 이후 일을 나타내 의미가 맞지 않습니다 ✗"]},{"id":"G12","q":"Anoche llamé varias veces a Isabel, pero no contestó. ¿Dónde ____?","o":["estará","ha estado","habrá estado","estaría"],"a":3,"k":"조건법 (과거 추측)","t":"어젯밤 이사벨에게 여러 번 전화했는데 안 받았어. 어디 있었을까?","e":"스페인어는 미래형·조건법으로 '추측'을 나타냅니다. 현재에 대한 추측은 미래형(¿Dónde estará?, 지금 어디 있을까?), 과거 상황에 대한 추측은 조건법(¿Dónde estaría?, 그때 어디 있었을까?)을 써요. 어젯밤 전화한 그 시점의 상태를 궁금해하는 것이므로 estaría가 정답입니다.","x":["estará: 미래형 추측은 '지금 어디 있을까'라는 현재 추측이라 anoche와 맞지 않습니다 ✗","ha estado: 현재완료 직설법은 추측이 아닌 사실 서술이라 맞지 않습니다 ✗","habrá estado: 미래완료 추측(어디 있었을까)도 쓰이긴 하지만, 과거 특정 시점의 상태는 조건법이 더 정확하다는 것이 교재 기준입니다 ✗","estaría: 과거 시점의 상태를 추측하는 조건법 → 정답 ✓"]},{"id":"G13","q":"No me importó que ____ el evento porque no iba a ir.","o":["han suspendido","suspendiesen","suspenderían","habían suspendido"],"a":1,"k":"감정동사+접속법 과거","t":"어차피 갈 생각이 없었기 때문에 행사가 취소된 것은 상관없었다.","e":"'no me importa que ~(~하는 것은 상관없다)'처럼 감정·평가를 나타내는 표현 뒤의 que절에는 접속법을 씁니다. 주절이 과거(importó)이므로 접속법 과거 suspendiesen(=suspendieran)을 써요. 여기서 3인칭 복수는 '(사람들이) 취소했다'는 무인칭 용법입니다. -se형과 -ra형은 같은 의미이며 -ra형이 더 흔합니다.","x":["han suspendido: 직설법 현재완료라 감정 표현 뒤 접속법 규칙에 어긋납니다 ✗","suspendiesen: 과거 감정 표현 뒤에 오는 접속법 과거 → 정답 ✓","suspenderían: 조건법이라 감정 표현 뒤에 쓰지 않습니다 ✗","habían suspendido: 직설법 대과거라 접속법이 필요한 자리에 맞지 않습니다 ✗"]},{"id":"G14","q":"____ que no tenía ganas, fue a ayudar a su amigo.","o":["Pese a","Incluso","Excepto","Aun"],"a":0,"k":"양보 pese a que","t":"내키지 않았는데도 그는 친구를 도우러 갔다.","e":"'pese a que'는 '~에도 불구하고'라는 양보 접속사로 a pesar de que와 같은 뜻입니다. 실제 사실(내키지 않았다)을 말할 때는 직설법(tenía)을 씁니다. 'pese a + 명사/동사원형' 형태로도 써요. 예: Pese a la lluvia, salimos.(비가 왔는데도 우리는 나갔다)","x":["Pese a: 'pese a que(~에도 불구하고)'로 양보절을 이끕니다 → 정답 ✓","Incluso: '심지어'라는 부사로 que절을 이끌 수 없습니다 ✗","Excepto: '~을 제외하고'라는 뜻으로 의미가 맞지 않습니다 ✗","Aun: 'aun así/aun cuando'처럼 쓰며 'aun que'라는 형태는 없습니다(aunque는 붙여 씀) ✗"]},{"id":"G15","q":"¿Cómo es posible que ____ tanto éxito sin esforzarse?","o":["tenga","tiene","tenía","tendría"],"a":0,"k":"¿Cómo es posible que?","t":"노력도 안 하는데 어떻게 그렇게 성공할 수 있지?","e":"'es posible que ~(~일 수 있다)'는 가능성을 나타내므로 뒤에 접속법이 옵니다. 의문문 '¿Cómo es posible que...?'는 놀람·불신을 표현하는데 이때도 접속법 현재(tenga)를 씁니다. 예: ¿Cómo es posible que no lo sepas?(네가 그걸 모른다는 게 말이 돼?)","x":["tenga: 'es posible que' 뒤의 접속법 현재 → 정답 ✓","tiene: 직설법이라 가능성 표현 뒤에 쓸 수 없습니다 ✗","tenía: 직설법 불완료과거로 시제와 법 모두 맞지 않습니다 ✗","tendría: 조건법이라 이 구조에 쓰지 않습니다 ✗"]},{"id":"G16","q":"El examen es mañana, ____ ponte a estudiar ya.","o":["conque","de ahí que","pues","tal que"],"a":0,"k":"결과 접속사 conque","t":"시험이 내일이니까 당장 공부 시작해.","e":"conque(붙여 씀)는 '그러니까, 그러므로'라는 결과를 나타내는 구어 접속사로, 뒤에 명령이나 결론이 자주 옵니다. 'con que(~라는 조건이면)'나 'con qué(무엇으로)'와 철자가 다르니 주의하세요. ponerse a + 동사원형은 '~하기 시작하다'라는 뜻입니다.","x":["conque: '그러니까'라는 결과 접속사로 명령문과 잘 어울립니다 → 정답 ✓","de ahí que: '그래서 ~하다'라는 결과지만 뒤에 접속법 서술이 오고 명령문은 오지 않습니다 ✗","pues: 문장 중간의 pues는 주로 '왜냐하면'처럼 이유를 덧붙일 때 써서, 결과·명령을 이끄는 conque만큼 적절하지 않습니다 ✗","tal que: '~할 정도의'라는 정도 표현이라 맞지 않습니다 ✗"]},{"id":"G17","q":"____ vergüenza pasé cuando me caí.","o":["Qué","Cuál","Cómo","Cuánto"],"a":0,"k":"감탄문 qué + 명사","t":"넘어졌을 때 얼마나 창피했는지!","e":"'¡Qué + 명사!'는 '정말 ~한!'이라는 감탄문입니다. 'pasar vergüenza'는 '창피를 당하다'라는 표현이고, '¡Qué vergüenza pasé!'는 '정말 창피했어!'라는 뜻이에요. 감탄 의문사이므로 qué에 악센트가 붙습니다. '¡Cuánta vergüenza!'도 가능하지만 여성 명사라 cuánta여야 합니다.","x":["Qué: '¡Qué + 명사!' 감탄문 → 정답 ✓","Cuál: '어느 것'이라는 선택 의문사로 감탄문에 명사와 쓰지 않습니다 ✗","Cómo: 동사·형용사를 꾸미는 감탄(얼마나)이라 명사 앞에 오지 않습니다 ✗","Cuánto: 남성형이라 여성 명사 vergüenza와 맞지 않습니다(cuánta라야 가능) ✗"]},{"id":"G18","q":"Sabemos que lo has hecho tú, no lo ____.","o":["niegas","niegues","niega","niegue"],"a":1,"k":"부정 명령 (tú)","t":"네가 한 거 우리가 알아, 부정하지 마.","e":"tú에 대한 부정명령은 'no + 접속법 현재 2인칭 단수' 형태입니다. negar(부정하다)는 e→ie로 바뀌는 어간변화 동사라 접속법이 niegues가 돼요. 긍정명령이라면 'niégalo(그걸 부정해)'가 됩니다. 대명사 lo는 부정명령에서는 동사 앞에 옵니다.","x":["niegas: 직설법 현재라 명령의 의미가 되지 않습니다 ✗","niegues: tú 부정명령(no + 접속법) → 정답 ✓","niega: 긍정명령 형태라 no와 함께 쓸 수 없습니다 ✗","niegue: usted에 대한 명령이라 tú로 말하는 문장(has hecho)과 맞지 않습니다 ✗"]},{"id":"G19","q":"No ____ cómo puedes pensar eso de Alfredo.","o":["conozco","sé","sabría","he conocido"],"a":1,"k":"saber vs conocer","t":"네가 어떻게 알프레도를 그렇게 생각할 수 있는지 모르겠다.","e":"saber는 '정보·사실을 알다'로 의문사절(cómo, qué, dónde 등)을 목적어로 받을 수 있습니다. conocer는 '사람·장소를 경험으로 알다'라서 '어떻게 ~하는지'라는 내용을 받지 못해요. 'No sé cómo...'는 '어떻게 ~인지 이해가 안 된다'는 놀람·비판의 뉘앙스입니다.","x":["conozco: '경험으로 알다'라서 의문사절과 쓰지 않습니다 ✗","sé: 의문사절(cómo...)을 목적어로 받는 saber → 정답 ✓","sabría: 조건법은 '모를 것 같다'로 완곡해져 여기 직설적인 놀람과 맞지 않습니다 ✗","he conocido: conocer의 현재완료로 의미·구조가 맞지 않습니다 ✗"]},{"id":"G20","q":"Mejor contactas mañana, ahora es muy tarde ____ llamar por teléfono.","o":["sobre","de","para","por"],"a":2,"k":"demasiado/muy ~ para","t":"내일 연락하는 게 낫겠어, 지금은 전화하기에 너무 늦었어.","e":"'muy/demasiado + 형용사 + para + 동사원형'은 '~하기에 너무 …하다'라는 구문입니다. 'es muy tarde para llamar'는 '전화하기엔 너무 늦었다'는 뜻이에요. para가 목적·기준을 나타냅니다. 예: Es muy pronto para decidir.(결정하기엔 너무 이르다)","x":["sobre: '~에 관해'라서 기준을 나타낼 수 없습니다 ✗","de: 'es tarde de...'라는 구조는 쓰지 않습니다 ✗","para: '~하기에는'이라는 기준·목적 → 정답 ✓","por: 원인·경로라서 '~하기에'라는 뜻이 되지 않습니다 ✗"]},{"id":"G21","q":"Dejad de darme ____ lata, solo quiero dormir.","o":["la","ø","a la","una"],"a":0,"k":"dar la lata","t":"그만 좀 귀찮게 해, 나 그냥 자고 싶어.","e":"'dar la lata'는 '귀찮게 하다, 성가시게 굴다'라는 스페인의 구어 관용 표현입니다(lata는 원래 '깡통'). 정관사 la가 고정되어 있어 다른 관사로 바꿀 수 없어요. 'dejar de + 동사원형'은 '~하는 것을 그만두다'이고, dejad는 vosotros 명령형입니다. 중남미에서는 'molestar', 'fregar' 등을 더 많이 쓰기도 합니다.","x":["la: 'dar la lata(귀찮게 하다)'의 고정된 정관사 → 정답 ✓","ø: 관사 없이는 관용 표현이 되지 않습니다 ✗","a la: 전치사 a가 들어갈 자리가 아닙니다 ✗","una: 부정관사를 쓰면 '깡통 하나를 준다'는 문자 그대로의 뜻이 됩니다 ✗"]},{"id":"G22","q":"Los cacos entraron en el apartamento cuando ____.","o":["estábamos durmiendo","estuvimos durmiendo","habíamos estado durmiendo","hemos estado durmiendo"],"a":0,"k":"진행형 불완료과거","t":"우리가 자고 있을 때 도둑들이 아파트에 들어왔다.","e":"과거 사건(도둑이 들어옴, 단순과거 entraron)이 일어난 순간 '진행 중이던 배경 동작'은 불완료과거 진행형 'estaba + 현재분사'로 씁니다. estábamos durmiendo는 '자고 있던 중이었다'는 뜻이에요. caco는 스페인 구어로 '좀도둑'입니다.","x":["estábamos durmiendo: 사건이 일어날 때 진행 중이던 배경 → 정답 ✓","estuvimos durmiendo: 단순과거 진행형은 기간이 끝난 행동 전체를 말해 배경 묘사에 맞지 않습니다 ✗","habíamos estado durmiendo: 대과거라 '그 전에 이미 자고 있었다'로 시점이 어긋납니다 ✗","hemos estado durmiendo: 현재완료라 과거 이야기와 맞지 않습니다 ✗"]},{"id":"G23","q":"Me temo que hay una avería en ____ tren.","o":["ø","esta","esa","el"],"a":3,"k":"정관사 el","t":"유감스럽게도 열차에 고장이 난 것 같습니다.","e":"말하는 사람과 듣는 사람이 모두 알고 있는 특정한 대상(지금 타고 있는/기다리는 열차)은 정관사 el로 나타냅니다. 'Me temo que ~'는 '유감이지만 ~인 것 같다'라는 정중한 표현으로 직설법을 씁니다. tren은 남성 명사이므로 esta, esa 같은 여성형 지시사는 쓸 수 없어요.","x":["ø: 단수 가산명사 tren은 관사 없이 쓸 수 없습니다 ✗","esta: 여성형 지시사라 남성 명사 tren과 맞지 않습니다 ✗","esa: 역시 여성형이라 tren과 일치하지 않습니다 ✗","el: 알려진 특정한 열차를 가리키는 정관사 → 정답 ✓"]},{"id":"G24","q":"¿Es cierto que van a estudiar ____ idioma?","o":["un otro","otro","otra","una otra"],"a":1,"k":"otro (부정관사 없이)","t":"그들이 다른 언어를 공부할 거라는 게 사실이야?","e":"스페인어의 otro(다른)는 영어 another와 달리 앞에 부정관사 un/una를 붙이지 않습니다. 'un otro idioma'는 흔한 실수예요. idioma는 -a로 끝나지만 남성 명사(el idioma)이므로 otro를 씁니다. 예: Quiero otro café.(커피 한 잔 더 주세요)","x":["un otro: otro 앞에 부정관사를 쓰지 않으므로 틀립니다 ✗","otro: 남성 명사 idioma와 일치하는 형태 → 정답 ✓","otra: idioma는 남성 명사라 여성형이 맞지 않습니다 ✗","una otra: 부정관사도 쓸 수 없고 성도 맞지 않습니다 ✗"]},{"id":"G25","q":"Esta novela la ____ al español un amigo mío.","o":["tradució","tradujese","traduzco","tradujo"],"a":3,"k":"traducir 단순과거","t":"이 소설은 내 친구가 스페인어로 번역했다.","e":"traducir(번역하다)처럼 -ducir로 끝나는 동사는 단순과거에서 불규칙으로 -duj- 형태가 됩니다: traduje, tradujiste, tradujo... 3인칭 단수는 tradujo예요. 'Esta novela la tradujo...'는 목적어(novela)를 앞에 두고 대명사 la로 다시 받는 구조로, 강조할 때 자주 씁니다. conducir→condujo, producir→produjo도 같아요.","x":["tradució: 존재하지 않는 형태로, 규칙 변화로 착각한 오류입니다 ✗","tradujese: 접속법 과거라 단순한 사실 서술에 맞지 않습니다 ✗","traduzco: 1인칭 현재(나는 번역한다)라 주어 un amigo mío와 맞지 않습니다 ✗","tradujo: traducir의 3인칭 단수 단순과거 → 정답 ✓"]},{"id":"G26","q":"Isa ____ por ahí que os habéis separado.","o":["llega a decir","va diciendo","lleva diciendo","viene a decir"],"a":1,"k":"ir + 현재분사","t":"이사가 너희가 헤어졌다고 여기저기 말하고 다녀.","e":"'ir + 현재분사'는 '~하며 다니다, 점점 ~하다'라는 동사 우언법(동사 두 개가 함께 하나의 의미를 만드는 구문)입니다. 'ir diciendo por ahí'는 '여기저기 (소문을) 말하고 다니다'라는 부정적 뉘앙스의 관용적 표현이에요. 'llevar + 현재분사'는 '~해 온 지 (기간)이 되다'라서 기간 표현이 필요합니다.","x":["llega a decir: '심지어 ~라고까지 말하다'라는 뜻이라 por ahí와 어울리지 않습니다 ✗","va diciendo: '여기저기 말하고 다니다' → 정답 ✓","lleva diciendo: 보통 기간(dos días 등)이 함께 와야 자연스럽습니다 ✗","viene a decir: '결국 ~라는 말이다(요약)'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G27","q":"Niños, no salgáis ____ de clase.","o":["todavía","aun","ya","apenas"],"a":0,"k":"todavía (아직)","t":"얘들아, 아직 교실에서 나가지 마.","e":"todavía는 '아직'이라는 뜻으로, 부정문에서 '아직 ~하지 마/않다'를 나타냅니다. aún(악센트 있음)도 같은 뜻이지만, 보기의 aun(악센트 없음)은 '심지어(incluso)'라는 뜻이라 다릅니다. salgáis는 vosotros 부정명령(no + 접속법) 형태로 스페인식 표현이며, 중남미에서는 'no salgan'이라고 합니다.","x":["todavía: '아직'이라는 뜻으로 부정명령과 어울립니다 → 정답 ✓","aun: 악센트 없는 aun은 '심지어'라서 의미가 맞지 않습니다(aún이어야 '아직') ✗","ya: '이미/이제'라서 '이제 나가지 마'는 어색합니다 ✗","apenas: '거의 ~않다'라는 뜻이라 문맥과 맞지 않습니다 ✗"]},{"id":"G28","q":"Eres capaz de hacerlo, no ____ duda.","o":["le quepa","te quepa","se quepa","quepa la"],"a":1,"k":"no te quepa duda","t":"넌 그걸 해낼 수 있어, 의심하지 마.","e":"'no caber duda'는 '의심의 여지가 없다'라는 표현이고, 'que no te quepa duda/no te quepa (la menor) duda'는 '절대 의심하지 마, 확실해'라는 강조 관용구입니다. caber(들어갈 여지가 있다)의 접속법이 불규칙형 quepa예요. 의심이 들어갈 자리가 '너(te)'이므로 간접목적격 te를 씁니다.","x":["le quepa: '그/당신에게'라서 tú로 말하는 문장(Eres)과 맞지 않습니다 ✗","te quepa: 'no te quepa duda(의심하지 마)'의 정확한 형태 → 정답 ✓","se quepa: caber는 이 표현에서 재귀형으로 쓰지 않습니다 ✗","quepa la: 대명사가 없고 관사 la도 어색합니다 ✗"]},{"id":"G29","q":"Perdona, pero este asunto no te ____.","o":["concerniere","concerniera","concierna","concierne"],"a":3,"k":"concernir 직설법","t":"미안하지만 이 일은 너와 상관없어.","e":"concernir(~에 관계되다)는 3인칭으로만 주로 쓰는 동사로, e→ie 어간변화를 합니다(concierne, conciernen). 단정적으로 '상관없다'고 말하는 평서문이므로 직설법 현재 concierne가 맞습니다. 비슷한 뜻으로 incumbir, importar도 쓰는데, concernir는 좀 더 격식 있는 표현이에요.","x":["concerniere: 거의 쓰이지 않는 접속법 미래형이라 맞지 않습니다 ✗","concerniera: 접속법 과거라 단순 평서문에 맞지 않습니다 ✗","concierna: 접속법 현재라 사실을 단정하는 문장에 맞지 않습니다 ✗","concierne: 직설법 현재 3인칭 단수 → 정답 ✓"]},{"id":"G30","q":"____ molestos porque nadie les dijo nada sobre la celebración.","o":["Sienten","Son","Están","Se parecen"],"a":2,"k":"estar + 감정 형용사","t":"축하 행사에 대해 아무도 아무 말도 해 주지 않아서 그들은 기분이 상해 있다.","e":"molesto(언짢은, 기분 상한)처럼 어떤 일 때문에 생긴 일시적 감정·상태는 estar로 씁니다. 'Están molestos porque...'는 '~때문에 언짢아하고 있다'는 뜻이에요. 'ser molesto'는 '(사람·사물이) 성가신 성격/성질이다'라는 다른 뜻이 됩니다. 참고로 중남미에서는 molesto가 '화난(enojado)'의 의미로 특히 많이 쓰입니다.","x":["Sienten: sentir는 명사를 목적어로 받아 'se sienten molestos'처럼 재귀형이어야 합니다 ✗","Son: 'ser molesto'는 '성가신 사람이다'라는 성질의 뜻이 됩니다 ✗","Están: 원인이 있는 일시적 감정 상태 → 정답 ✓","Se parecen: '서로 닮았다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G31","q":"____ simpático que es y no encuentra pareja.","o":["Aunque","Si bien","Incluso","Con lo"],"a":3,"k":"con lo + 형용사 + que","t":"그렇게 착하고 다정한데도 짝을 못 찾는다니.","e":"'Con lo + 형용사 + que + 동사'는 '그렇게 ~한데도'라는 양보·놀람을 나타내는 구어 표현입니다. 형용사는 주어의 성·수와 상관없이 lo와 함께 쓰지만 형용사 자체는 주어에 맞춰요(con lo simpática que es). 'Con lo + 형용사'는 문맥에 따라 '그렇게 ~하니까'라는 원인도 될 수 있습니다. 예: Con lo listo que eres, seguro que apruebas.(넌 그렇게 똑똑하니 분명 합격할 거야)","x":["Aunque: '비록 ~이지만'이지만 뒤에 'simpático que es' 같은 구조가 올 수 없습니다 ✗","Si bien: '~이긴 하지만'이라는 문어적 양보로 역시 이 구조와 맞지 않습니다 ✗","Incluso: '심지어'라는 부사라 이 구조를 만들지 못합니다 ✗","Con lo: 'con lo + 형용사 + que'로 '그렇게 ~한데도'라는 의미 → 정답 ✓"]},{"id":"G32","q":"Antes ____ fácilmente, ahora se controla más.","o":["se ha enfadado","se enfadaba","estaba enfadándose","se estuvo enfadando"],"a":1,"k":"불완료과거 (과거 습관)","t":"예전에는 쉽게 화를 냈는데, 지금은 더 잘 참는다.","e":"'antes(예전에는)'와 함께 과거에 반복되던 습관이나 성향을 말할 때는 불완료과거를 씁니다. se enfadaba는 '자주 화를 내곤 했다'는 뜻이에요. 'enfadarse'는 스페인에서 주로 쓰고, 중남미에서는 'enojarse'를 더 많이 씁니다.","x":["se ha enfadado: 현재완료는 한 번의 사건을 말해 과거 습관을 나타내지 못합니다 ✗","se enfadaba: antes와 어울리는 과거 습관의 불완료과거 → 정답 ✓","estaba enfadándose: 진행형이라 '그때 화나는 중이었다'로 습관 의미가 아닙니다 ✗","se estuvo enfadando: 단순과거 진행형으로 끝난 기간의 동작이라 맞지 않습니다 ✗"]},{"id":"G33","q":"____ pasan las horas, me pongo más nervioso.","o":["Conforme","A medida","Siempre y cuando","Nada más"],"a":0,"k":"conforme (~함에 따라)","t":"시간이 지날수록 나는 점점 더 초조해진다.","e":"conforme는 '~함에 따라, ~할수록'이라는 비례 접속사로, 두 변화가 함께 진행됨을 나타냅니다. 같은 뜻으로 'a medida que'도 쓰지만 반드시 que가 붙어야 해요. 'ponerse + 형용사'는 '(일시적으로) ~해지다'라는 변화 표현입니다. 예: Conforme crecía, se parecía más a su madre.(자랄수록 엄마를 더 닮아 갔다)","x":["Conforme: '~함에 따라'라는 비례 접속사 → 정답 ✓","A medida: 'a medida que'처럼 que가 있어야 해서 이 형태만으로는 틀립니다 ✗","Siempre y cuando: '~하는 경우에 한해'라는 조건이고 뒤에 접속법이 옵니다 ✗","Nada más: '~하자마자'는 'nada más + 동사원형' 형태로 씁니다 ✗"]},{"id":"G34","q":"Vimos una procesión ____ lejos.","o":["de lo","al","a lo","por"],"a":2,"k":"a lo lejos","t":"우리는 멀리서 행렬을 보았다.","e":"'a lo lejos'는 '저 멀리, 멀리서'라는 고정된 부사 표현으로, 멀리 있는 것이 보이거나 들릴 때 씁니다. 'de lejos(멀리서부터)'도 있지만 보기에는 'de lo'로 나와 있어 틀린 형태예요. procesión은 특히 스페인의 부활절 주간(Semana Santa) 종교 행렬을 가리킬 때 자주 쓰는 단어입니다.","x":["de lo: 'de lo lejos'라는 표현은 쓰지 않습니다(de lejos는 가능) ✗","al: 'al lejos'라는 표현은 없습니다 ✗","a lo: 'a lo lejos(저 멀리)'의 정확한 형태 → 정답 ✓","por: 'por lejos'는 '단연, 훨씬'(중남미)이라는 다른 뜻입니다 ✗"]},{"id":"G35","q":"Preferimos que ____ con alguien de tu edad.","o":["saldrías","saldrás","salgas","salieras"],"a":2,"k":"preferir que + 접속법","t":"우리는 네가 네 또래의 사람과 사귀었으면 좋겠어.","e":"preferir, querer, desear처럼 바람·선호를 나타내는 동사 뒤에 주어가 다른 que절이 오면 접속법을 씁니다. 주절이 현재(Preferimos)이므로 접속법 현재 salgas가 됩니다. salir con alguien은 '~와 데이트하다, 사귀다'라는 뜻이에요. salir의 접속법은 불규칙(salga, salgas...)입니다.","x":["saldrías: 조건법이라 바람 표현 뒤에 쓰지 않습니다 ✗","saldrás: 직설법 미래라 접속법이 필요한 자리에 맞지 않습니다 ✗","salgas: 현재 주절 + 바람 표현 뒤 접속법 현재 → 정답 ✓","salieras: 접속법 과거로 주절이 과거·조건법(preferiríamos)일 때 씁니다 ✗"]},{"id":"G36","q":"Me molesta ____ que fingir que me siento bien.","o":["teniendo","al tener","tener","de tener"],"a":2,"k":"동사원형 주어 구문","t":"기분이 좋은 척해야 하는 게 싫다.","e":"molestar(짜증 나게 하다)는 gustar처럼 '짜증 나게 만드는 것'이 주어가 되는 동사입니다. 동사가 주어가 될 때는 동사원형(infinitivo)을 써요: 'tener que fingir(척해야 하는 것)'가 주어입니다. 예: Me molesta esperar.(기다리는 게 싫어) 영어의 -ing처럼 현재분사(teniendo)를 주어로 쓰지 않는다는 점에 주의하세요.","x":["teniendo: 현재분사는 스페인어에서 주어가 될 수 없습니다 ✗","al tener: 'al + 동사원형'은 '~할 때'라는 시간 표현이라 주어가 될 수 없습니다 ✗","tener: 동사원형이 molesta의 주어 역할을 합니다 → 정답 ✓","de tener: 전치사 de가 붙으면 주어가 될 수 없습니다 ✗"]},{"id":"G37","q":"No estoy ____ satisfecho con nuestros resultados.","o":["algo","ni muy","absoluto","nada"],"a":3,"k":"no ... nada (전혀)","t":"우리의 결과에 나는 전혀 만족하지 않는다.","e":"nada는 '아무것도'라는 대명사 외에 'no ... nada + 형용사'로 '전혀 ~하지 않다'라는 부사로도 씁니다. 스페인어는 이중 부정이 정상이라 no와 nada를 함께 써요. 'en absoluto'도 '전혀'라는 뜻이지만 en이 필요하고 보통 문장 끝에 둡니다. 예: No es nada fácil.(전혀 쉽지 않아)","x":["algo: '약간'이라는 뜻이라 'no estoy algo...'는 비문입니다 ✗","ni muy: 'ni muy ... ni muy ...'처럼 짝을 이뤄야 하므로 맞지 않습니다 ✗","absoluto: 'en absoluto'처럼 en이 필요하고 형용사 앞에 오지 않습니다 ✗","nada: 'no ... nada + 형용사'로 '전혀 ~않다' → 정답 ✓"]},{"id":"G38","q":"No vimos a ____ allí, así que nos marchamos a casa.","o":["ningún","nadie","ninguno","alguien"],"a":1,"k":"부정어 nadie","t":"거기서 아무도 보지 못해서 우리는 집으로 돌아갔다.","e":"nadie는 '아무도'라는 뜻으로 사람을 가리키는 부정 대명사이며, 명사 없이 단독으로 씁니다. 사람이 목적어일 때는 전치사 a가 필요해 'a nadie'가 됩니다. ninguno도 가능하지만 '그 중 아무도'처럼 정해진 무리를 전제할 때 쓰고, ningún은 뒤에 명사가 와야 합니다.","x":["ningún: 형용사형이라 뒤에 남성 명사가 반드시 와야 합니다 ✗","nadie: 사람에 대한 부정 대명사 '아무도' → 정답 ✓","ninguno: 특정 집단 중 '아무도'라는 뜻이라 맥락 없이 쓰기엔 부자연스럽습니다 ✗","alguien: '누군가'라는 긍정어라 no와 함께 쓰면 의미가 맞지 않습니다 ✗"]},{"id":"G39","q":"Estuvo varios años presa, pero en cuanto salió volvió ____ andadas.","o":["por las","en las","a las","desde las"],"a":2,"k":"volver a las andadas","t":"그녀는 몇 년간 수감되어 있었지만 출소하자마자 다시 옛 버릇(나쁜 짓)으로 돌아갔다.","e":"'volver a las andadas'는 '(나쁜) 옛 버릇으로 되돌아가다, 다시 예전 짓을 하다'라는 관용 표현입니다. andadas는 원래 '지나온 길, 발자취'라는 뜻이에요. 주로 범죄, 음주, 도박처럼 부정적인 습관에 씁니다. 'en cuanto + 단순과거'는 '~하자마자'입니다.","x":["por las: 'volver por'는 '~을 가지러 돌아가다'라서 관용구가 아닙니다 ✗","en las: 이동 동사 volver에 en은 맞지 않습니다 ✗","a las: 'volver a las andadas(옛 버릇으로 돌아가다)'의 정확한 형태 → 정답 ✓","desde las: '~로부터'라서 방향이 반대입니다 ✗"]},{"id":"G40","q":"No me achanto fácilmente ____ los problemas.","o":["de","ante","a","sobre"],"a":1,"k":"achantarse ante","t":"나는 문제 앞에서 쉽게 기죽지 않는다.","e":"achantarse는 '겁먹다, 기가 죽다, 움츠러들다'라는 스페인 구어 동사입니다. 무엇 앞에서 위축되는지는 전치사 ante(~앞에서, ~에 직면하여)로 나타내요. ante는 'ante el peligro(위험 앞에서)'처럼 상황에 맞서는 장면에 자주 씁니다. 비슷한 표현으로 'acobardarse ante', 'echarse atrás'가 있습니다.","x":["de: 'achantarse de'라는 결합은 쓰지 않습니다 ✗","ante: '~앞에서, ~에 직면하여' → 정답 ✓","a: 방향을 나타내 이 동사와 어울리지 않습니다 ✗","sobre: '~위에/~에 관해'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G41","q":"Me ____ hacer jefe del departamento de ventas.","o":["están yendo a","vienen a","van","van a"],"a":3,"k":"ir a + 동사원형","t":"나를 영업부 부장으로 임명할 거래.","e":"'ir a + 동사원형'은 '~할 것이다'라는 가까운 미래·예정을 나타냅니다. 여기서 'Me van a hacer jefe'는 3인칭 복수 무인칭(그들이=회사가)으로 '나를 부장으로 만들 것이다'라는 뜻이에요. 'hacer + 사람 + 직위'는 '~을 …로 임명하다'입니다. ir a 구문은 진행형(están yendo a)으로 쓰지 않습니다.","x":["están yendo a: 'ir a' 미래 구문은 진행형으로 쓰지 않습니다 ✗","vienen a: 'venir a'는 '~하러 오다'라서 뜻이 달라집니다 ✗","van: 전치사 a가 빠져 'ir a + 동사원형' 구조가 깨집니다 ✗","van a: 가까운 미래를 나타내는 ir a → 정답 ✓"]},{"id":"G42","q":"¡Qué vestido ____ novia tan bonito!","o":["por","a","de","para"],"a":2,"k":"명사 + de + 명사","t":"정말 예쁜 웨딩드레스네!","e":"'명사 + de + 명사'는 종류·용도를 나타내 하나의 복합 명사처럼 쓰입니다. 'vestido de novia'는 '신부의 드레스', 즉 '웨딩드레스'라는 고정 표현이에요. '¡Qué + 명사 + tan + 형용사!'는 '정말 ~한 …이구나!'라는 감탄문입니다. 예: ¡Qué casa tan bonita!(집이 정말 예쁘다!)","x":["por: 원인·경로를 나타내 복합 명사를 만들지 못합니다 ✗","a: 'vestido a novia'라는 표현은 없습니다 ✗","de: 'vestido de novia(웨딩드레스)' → 정답 ✓","para: '신부를 위한 드레스'로 문법상 가능해 보이지만 고정 표현은 de입니다 ✗"]},{"id":"G43","q":"Martina nos dijo que no ____ la primera vez que venía a México.","o":["era","fuera","fue","sería"],"a":0,"k":"간접화법 시제 일치","t":"마르티나는 멕시코에 오는 게 처음이 아니라고 우리에게 말했다.","e":"과거 동사(dijo)로 말을 전하는 간접화법에서, 원래 현재형(No es la primera vez)은 불완료과거(no era)로 바뀝니다. 'decir que'는 사실을 전달하므로 직설법을 써요. 'es la primera vez que...'는 '~하는 것은 처음이다'라는 고정 표현으로 ser를 씁니다.","x":["era: 간접화법에서 현재 es가 바뀐 불완료과거 → 정답 ✓","fuera: 접속법이라 사실을 전달하는 decir que 뒤에 맞지 않습니다 ✗","fue: 단순과거라 '처음이었다'는 상태 묘사에 맞지 않습니다 ✗","sería: 조건법은 원래 미래형(será)을 전할 때 씁니다 ✗"]},{"id":"G44","q":"A veces mis hijos me ponen ____ los nervios.","o":["por","a","de","con"],"a":2,"k":"poner de los nervios","t":"가끔 우리 아이들은 나를 신경질 나게 만든다.","e":"'poner a alguien de los nervios'는 '누군가를 짜증 나게(신경 쓰이게) 만들다'라는 스페인 구어 관용 표현입니다. 'ponerse de los nervios'는 '신경이 곤두서다'라는 뜻이에요. 같은 의미로 'poner nervioso a alguien'도 쓰며, 중남미에서는 이쪽이나 'sacar de quicio'가 더 일반적입니다.","x":["por: 'poner por los nervios'라는 표현은 없습니다 ✗","a: 'poner a los nervios'라는 표현은 없습니다 ✗","de: 'poner de los nervios(신경질 나게 하다)' → 정답 ✓","con: 'poner con los nervios'라는 표현은 없습니다 ✗"]},{"id":"G45","q":"Señora Esteban, ha venido alguien preguntando ____ usted.","o":["de","a","para","por"],"a":3,"k":"preguntar por","t":"에스테반 부인, 누군가 부인을 찾으러 왔었습니다.","e":"'preguntar por + 사람'은 '~을 찾다, ~이 있는지 묻다' 또는 '~의 안부를 묻다'라는 뜻입니다. 'preguntar a + 사람'은 '~에게 질문하다'라서 의미가 다릅니다. 예: Me preguntó por tu madre.(그가 너희 어머니 안부를 물었어)","x":["de: 'preguntar de'는 이 뜻으로 쓰지 않습니다 ✗","a: 'preguntar a usted'는 '당신에게 질문하다'라서 문맥과 맞지 않습니다 ✗","para: '~을 위해 묻다'라는 어색한 뜻이 됩니다 ✗","por: '~을 찾다/~에 대해 묻다' → 정답 ✓"]},{"id":"G46","q":"____ tú y yo podemos levantar la mesa.","o":["Sobre","Hacia","Entre","Según"],"a":2,"k":"entre tú y yo","t":"너랑 나랑 둘이서 그 테이블을 들 수 있어.","e":"entre는 '~사이에'라는 뜻 외에 '~가 함께 힘을 합쳐'라는 협력의 의미도 있습니다. 'Entre tú y yo podemos...'는 '너와 나 둘이 함께라면 ~할 수 있다'는 뜻이에요. 주의할 점은 entre 뒤에서는 mí, ti가 아니라 주격 tú, yo를 쓴다는 것입니다(según도 마찬가지). levantar la mesa는 문맥상 '테이블을 들어 올리다'입니다(스페인에서는 '상을 치우다'라는 뜻도 있음).","x":["Sobre: '~위에'라서 의미가 통하지 않습니다 ✗","Hacia: '~쪽으로'라는 방향이라 맞지 않습니다 ✗","Entre: '함께 힘을 합쳐'라는 협력의 의미 → 정답 ✓","Según: '~에 따르면'이라는 뜻이라 문맥과 맞지 않습니다 ✗"]},{"id":"G47","q":"Tu último comentario está ____ más, pues no viene al caso.","o":["por","de","a","para"],"a":1,"k":"estar de más","t":"네 마지막 말은 쓸데없었어, 주제와 상관이 없으니까.","e":"'estar de más'는 '불필요하다, 쓸데없다, 군더더기다'라는 관용 표현입니다. 'no venir al caso'는 '주제와 관계없다, 엉뚱하다'라는 뜻이에요. 사람에게 쓰면 '그 자리에 있을 필요가 없다(눈치 없이 끼어 있다)'는 뜻도 됩니다. 예: Aquí estoy de más.(여기선 내가 필요 없겠네)","x":["por: 'estar por más'라는 표현은 없습니다 ✗","de: 'estar de más(불필요하다)' → 정답 ✓","a: 'estar a más'라는 표현은 없습니다 ✗","para: 'estar para + 동사원형'은 '~할 참이다'라는 다른 뜻입니다 ✗"]},{"id":"G48","q":"No ____ beber alcohol.","o":["deberías","tendrías","convendrías","habrías"],"a":0,"k":"deber 조건법 (충고)","t":"술은 마시지 않는 게 좋겠어.","e":"deber + 동사원형은 '~해야 한다'라는 의무를 나타내고, 조건법 deberías는 '~하는 게 좋겠다'라는 부드러운 충고가 됩니다. tener도 의무를 나타내지만 반드시 'tener que + 동사원형'으로 que가 필요해요. 'convenir(유리하다)'는 'Te conviene...'처럼 3인칭으로 씁니다.","x":["deberías: 조건법으로 부드러운 충고 → 정답 ✓","tendrías: 'tener que'로 써야 해서 que 없이는 틀립니다 ✗","convendrías: convenir는 '~에게 유리하다'로 주어가 일(no beber)이라 2인칭이 될 수 없습니다 ✗","habrías: 'haber de/haber que'가 필요하고 이 형태로는 의미가 없습니다 ✗"]},{"id":"G49","q":"Yo nunca ____ eso. Otra persona lo hizo.","o":["dije","decía","dijera","digo"],"a":0,"k":"단순과거 (사실 부정)","t":"난 그런 말 한 적 없어. 다른 사람이 그런 거야.","e":"과거에 '한 번' 일어난 행동(말한 것)을 부정할 때는 단순과거를 씁니다. 'Yo nunca dije eso'는 '난 결코 그렇게 말하지 않았다'는 단호한 부정이에요. 뒷문장 'Otra persona lo hizo'도 단순과거로 맞춰져 있습니다. 불완료과거(decía)는 '평소에 말하곤 했다'는 습관을 나타냅니다.","x":["dije: 한 번의 행동을 나타내는 단순과거 → 정답 ✓","decía: 불완료과거라 '말하곤 했다'는 습관이 됩니다 ✗","dijera: 접속법 과거라 평서문 주절에 쓰지 않습니다 ✗","digo: 현재형이라 과거 사실과 맞지 않습니다 ✗"]},{"id":"G50","q":"Echa la verdura ____ esté caliente el aceite.","o":["en cuanto","como","por si","si"],"a":0,"k":"en cuanto + 접속법","t":"기름이 뜨거워지자마자 채소를 넣어.","e":"'en cuanto'는 '~하자마자'라는 시간 접속사입니다. 아직 일어나지 않은 미래의 일(기름이 뜨거워지는 것)을 말할 때는 뒤에 접속법(esté)을 써요. 명령문(Echa)과 함께 요리법에서 자주 나오는 구조입니다. 예: En cuanto llegues, llámame.(도착하자마자 전화해)","x":["en cuanto: '~하자마자' + 접속법(미래의 일) → 정답 ✓","como: '~하는 대로/~이므로'라서 접속법과 쓰면 '만약 ~하면(위협)'이 됩니다 ✗","por si: '~할 경우를 대비해'라서 뜻이 맞지 않고 보통 직설법이 옵니다 ✗","si: 조건 si 뒤에는 접속법 현재(esté)를 쓸 수 없습니다 ✗"]},{"id":"G51","q":"____ que ponernos las pilas.","o":["Vamos","Tenemos","Debemos","Hemos"],"a":1,"k":"tener que + 동사원형","t":"우리 정신 바짝 차려야 해.","e":"'tener que + 동사원형'은 '~해야 한다'라는 강한 의무를 나타냅니다. 'ponerse las pilas'는 직역하면 '배터리를 끼우다'로, '정신 차리고 열심히 하다, 분발하다'라는 구어 관용 표현이에요. 예: Si quieres aprobar, ponte las pilas.(합격하고 싶으면 분발해)","x":["Vamos: 'vamos a + 동사원형'이어야 하고 que와는 쓰지 않습니다 ✗","Tenemos: 'tener que(~해야 한다)' → 정답 ✓","Debemos: deber는 que 없이 바로 동사원형이 옵니다 ✗","Hemos: 'haber de'(~해야 한다)는 de가 필요하고 'hemos que'는 틀립니다 ✗"]},{"id":"G52","q":"Hazlo si ____.","o":["se atreva","se atreve","te atreves","te atrevas"],"a":2,"k":"si + 직설법 현재","t":"할 용기가 있으면 해 봐.","e":"현실적인 조건을 나타내는 si 뒤에는 직설법 현재가 옵니다(si + 접속법 현재는 쓰지 않음). 명령형 Hazlo가 tú에게 하는 말이므로 재귀동사 atreverse(감히 ~하다)도 te atreves가 되어야 해요. 'Hazlo si te atreves'는 도발하는 뉘앙스의 관용적 표현입니다.","x":["se atreva: 접속법이고 3인칭이라 두 가지 모두 틀립니다 ✗","se atreve: 3인칭(그/당신)이라 tú 명령(Hazlo)과 맞지 않습니다 ✗","te atreves: tú에 맞는 직설법 현재 → 정답 ✓","te atrevas: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗"]},{"id":"G53","q":"Cuando conocí a Juana, hacía poco que me ____ de mi exmujer.","o":["me separaba","me separé","me he separado","había separado"],"a":3,"k":"대과거 hacía poco que","t":"후아나를 만났을 때 나는 전처와 헤어진 지 얼마 안 됐었다.","e":"과거의 어느 시점(Juana를 만난 때)보다 더 앞선 일은 대과거(haber 불완료과거 + 과거분사)로 나타냅니다. 'hacía poco que + 대과거'는 '(그때) ~한 지 얼마 안 됐었다'라는 뜻이에요. 문장에 이미 재귀대명사 me가 있으므로 빈칸에는 'había separado'만 들어가 'me había separado'가 완성됩니다.","x":["me separaba: me가 중복되고 불완료과거라 '이미 헤어진' 의미를 나타내지 못합니다 ✗","me separé: me가 중복되어 'me me separé'가 됩니다 ✗","me he separado: me 중복에 현재완료라 과거 이야기와 맞지 않습니다 ✗","había separado: 앞의 me와 합쳐 대과거 'me había separado'가 됩니다 → 정답 ✓"]},{"id":"G54","q":"Te ____ todo el apoyo que me has brindado.","o":["agradezca","agradecida","agradece","agradezco"],"a":3,"k":"agradecer 현재","t":"네가 내게 베풀어 준 모든 지원에 감사해.","e":"agradecer(감사하다)는 -cer로 끝나는 동사로, 1인칭 단수 현재가 -zco로 바뀝니다(agradezco). 'agradecer algo a alguien'은 '누구에게 무엇을 감사하다'라는 구조로, Te(너에게)가 간접목적어예요. brindar apoyo는 '지원을 베풀다'라는 격식 있는 표현입니다.","x":["agradezca: 접속법이라 평서문 주절에 맞지 않습니다 ✗","agradecida: 형용사(감사하는)로 동사 자리에 올 수 없습니다(Estoy agradecida라면 가능) ✗","agradece: 3인칭이라 '내가 감사한다'는 문맥과 맞지 않습니다 ✗","agradezco: 1인칭 단수 직설법 현재 → 정답 ✓"]},{"id":"G55","q":"Es un manitas, arregla ____ que se estropea.","o":["todas las","todos los","todo lo","toda la"],"a":2,"k":"todo lo que","t":"그는 손재주꾼이라 고장 나는 건 뭐든지 고친다.","e":"'todo lo que'는 '~하는 모든 것'이라는 뜻으로, 구체적 명사 없이 '것' 전체를 가리킬 때 씁니다. 'manitas'는 스페인 구어로 '손재주 좋은 사람, 뭐든 잘 고치는 사람'이라는 뜻이며 단수로도 -s를 붙입니다(ser un manitas). estropearse는 '고장 나다, 망가지다'입니다.","x":["todas las: 뒤에 여성 복수 명사가 필요해 'que'와 바로 이어질 수 없습니다 ✗","todos los: 뒤에 남성 복수 명사가 필요해 맞지 않습니다 ✗","todo lo: 'todo lo que(~하는 모든 것)' → 정답 ✓","toda la: 뒤에 여성 단수 명사가 필요해 맞지 않습니다 ✗"]},{"id":"G56","q":"Si ____ mi pasaporte, dímelo, por favor.","o":["encuentres","encontrarías","encontrarás","encuentras"],"a":3,"k":"si + 직설법 현재","t":"내 여권을 찾으면 꼭 말해 줘.","e":"현실 가능한 조건문 'si + 직설법 현재, 명령문/미래'의 구조입니다. si 뒤에는 접속법 현재나 미래형을 쓰지 않는다는 것이 중요한 규칙이에요. 'dímelo'는 decir의 tú 긍정명령 di + me(나에게) + lo(그것을)입니다.","x":["encuentres: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","encontrarías: 조건법은 si절이 아니라 주절에 씁니다 ✗","encontrarás: 미래형도 조건의 si 뒤에는 쓰지 않습니다 ✗","encuentras: 현실 조건 si + 직설법 현재 → 정답 ✓"]},{"id":"G57","q":"____ una hora por el pueblo hasta que vino el autobús.","o":["Andábamos","Anduvimos","Andemos","Andamos"],"a":1,"k":"단순과거 + 기간","t":"버스가 올 때까지 우리는 한 시간 동안 마을을 걸어 다녔다.","e":"'una hora(한 시간)'처럼 시작과 끝이 정해진 기간 동안의 행동은 단순과거로 씁니다. andar(걷다)는 단순과거가 불규칙(anduve, anduvimos...)이에요. 'hasta que + 단순과거'는 실제로 일어난 과거의 끝점을 나타냅니다.","x":["Andábamos: 불완료과거는 기간이 한정된 완결 행동에 맞지 않습니다 ✗","Anduvimos: 기간이 정해진 완결된 과거 행동(불규칙 단순과거) → 정답 ✓","Andemos: 접속법 현재/청유형(걸읍시다)이라 맞지 않습니다 ✗","Andamos: 현재형(또는 규칙형 오류)으로 과거 문장에 맞지 않습니다 ✗"]},{"id":"G58","q":"Tus niñas ya ____ son mayorcitas, ¡claro que pueden salir con sus amigos!","o":["lo","las","ø","les"],"a":2,"k":"불필요한 대명사","t":"네 딸들은 이제 다 컸잖아, 당연히 친구들이랑 놀러 나가도 되지!","e":"ser + 형용사(mayorcitas) 문장에서는 주어(Tus niñas)가 이미 있으므로 목적격 대명사를 넣을 이유가 없습니다. 'mayorcito/a'는 mayor의 축소형으로 '제법 다 큰'이라는 친근한 뉘앙스예요. 대명사 lo는 '이미 말한 내용'을 받을 때(Lo son.)에만 쓰고, 형용사가 직접 나오면 쓰지 않습니다.","x":["lo: 형용사 mayorcitas가 이미 있어 lo로 다시 받을 필요가 없습니다 ✗","las: 직접목적격이라 ser 문장에 올 수 없습니다 ✗","ø: 아무것도 넣지 않는 것이 맞습니다 → 정답 ✓","les: 간접목적격이라 이 문장 구조에 맞지 않습니다 ✗"]},{"id":"G59","q":"Menuda sorpresa ____ cuando vi a Lidia.","o":["llevé","me llevé","me la llevé","la que llevé"],"a":1,"k":"llevarse una sorpresa","t":"리디아를 봤을 때 얼마나 놀랐는지!","e":"'llevarse una sorpresa'는 '놀라다'라는 고정 표현으로, 반드시 재귀형(llevarse)을 씁니다. 'Menuda + 명사'는 '대단한/엄청난 ~'이라는 감탄 표현(스페인 구어)으로, 반어적으로도 씁니다. 예: Menudo lío.(엄청난 난리네) 명사(sorpresa)가 이미 있으니 대명사 la를 또 넣을 필요는 없어요.","x":["llevé: 재귀대명사 me가 없어 '놀라다'의 의미가 되지 않습니다 ✗","me llevé: 'llevarse una sorpresa(놀라다)'의 1인칭 단순과거 → 정답 ✓","me la llevé: sorpresa가 이미 있어 la가 중복됩니다 ✗","la que llevé: 관계절로 만들면 감탄 구조가 깨집니다 ✗"]},{"id":"G60","q":"Felisa, ____ padre es médico, está estudiando veterinaria.","o":["cuya","el del","cuyo","de quien"],"a":2,"k":"관계형용사 cuyo","t":"아버지가 의사인 펠리사는 수의학을 공부하고 있다.","e":"cuyo/cuya/cuyos/cuyas는 '그 사람의/그것의'라는 소유 관계사입니다. 중요한 것은 소유자(Felisa)가 아니라 뒤에 오는 소유물(padre)에 성·수를 맞춘다는 점이에요. padre는 남성 단수이므로 cuyo가 됩니다. 예: La casa, cuyas ventanas son azules...(창문이 파란 그 집은...) 주로 문어에서 쓰고 구어에서는 'que su padre...'처럼 말하기도 합니다(비표준).","x":["cuya: 소유자 Felisa에 맞춘 여성형인데, cuyo는 뒤의 padre(남성)에 맞춰야 합니다 ✗","el del: 의미가 통하지 않는 구조입니다 ✗","cuyo: 소유물 padre(남성 단수)와 일치하는 형태 → 정답 ✓","de quien: 'de quien es médico el padre'처럼 구조가 달라야 해서 여기선 맞지 않습니다 ✗"]},{"id":"G61","q":"____ momento no puedo quejarme, el negocio va viento en popa.","o":["Al","Hasta","Del","Por el"],"a":3,"k":"por el momento","t":"지금으로서는 불평할 게 없어, 사업이 순풍에 돛 단 듯 잘되고 있거든.","e":"'por el momento'는 '지금으로서는, 당분간은'이라는 고정 표현으로 'por ahora'와 같은 뜻입니다. 'ir viento en popa'는 직역하면 '바람이 배 뒤쪽에서 분다'로, '순조롭게 잘 진행되다'라는 관용 표현이에요. 'al momento'는 '즉시'라는 다른 뜻이니 구별하세요.","x":["Al: 'al momento'는 '즉시, 곧바로'라는 뜻이라 문맥과 맞지 않습니다 ✗","Hasta: 'hasta el momento(지금까지)'라면 가능하지만 관사 el이 빠져 틀립니다 ✗","Del: 'del momento'는 '그 시기의(유행하는)'라는 뜻으로 부사구가 되지 않습니다 ✗","Por el: 'por el momento(지금으로서는)' → 정답 ✓"]},{"id":"G62","q":"Ese reloj, ____ muy caro que sea, no parece de calidad.","o":["para","por","incluso","ø"],"a":1,"k":"por muy ~ que + 접속법","t":"그 시계는 아무리 비싸다 해도 품질이 좋아 보이지 않는다.","e":"'por (muy) + 형용사/부사 + que + 접속법'은 '아무리 ~하더라도'라는 강한 양보 표현입니다. 'por muy caro que sea'는 '아무리 비싸다고 해도'라는 뜻이에요. 명사일 때는 'por mucho dinero que tenga(아무리 돈이 많아도)'처럼 mucho를 씁니다. 접속법 sea를 쓰는 이유는 '비싼지 아닌지와 상관없이'라는 양보의 의미 때문입니다.","x":["para: 'para muy caro que sea'라는 구조는 없습니다 ✗","por: 'por muy + 형용사 + que + 접속법(아무리 ~해도)' → 정답 ✓","incluso: '심지어'라는 부사라 이 구조를 만들지 못합니다 ✗","ø: 앞에 아무것도 없으면 'muy caro que sea'가 문장이 되지 않습니다 ✗"]},{"id":"G63","q":"Visitadnos cuando ____.","o":["queráis","queréis","querríais","querréis"],"a":0,"k":"cuando + 접속법","t":"원할 때 언제든 우리 집에 놀러 와.","e":"cuando가 아직 일어나지 않은 미래의 일을 가리킬 때는 접속법을 씁니다. 'cuando queráis'는 '너희가 원할 때(언제든)'라는 뜻이에요. Visitadnos는 vosotros 긍정명령 visitad + nos(우리를)이며, 스페인식 형태입니다(중남미에서는 Visítennos cuando quieran).","x":["queráis: 미래 시점을 가리키는 cuando 뒤의 접속법 → 정답 ✓","queréis: 직설법은 습관·사실일 때 써서 명령과 함께 쓰는 미래 의미에는 맞지 않습니다 ✗","querríais: 조건법은 cuando 뒤에 쓰지 않습니다 ✗","querréis: cuando 뒤에는 미래형을 쓰지 않습니다 ✗"]},{"id":"G64","q":"Aunque al principio no me gustaba nada, al final acabó ____ gustarme esa película.","o":["de","con","por","para"],"a":2,"k":"acabar por + 동사원형","t":"처음엔 전혀 마음에 안 들었지만 결국 그 영화가 좋아졌다.","e":"'acabar por + 동사원형'은 '결국 ~하게 되다'라는 뜻으로 'acabar + 현재분사(acabó gustándome)'와 같은 의미입니다. 'acabar de + 동사원형'은 '막 ~했다'라는 전혀 다른 뜻이니 주의하세요. 'terminar por'도 같은 의미로 쓰입니다. 예: Acabó por aceptar.(그는 결국 받아들였다)","x":["de: 'acabar de'는 '방금 ~했다'라는 뜻이 됩니다 ✗","con: 'acabar con'은 '~을 끝장내다, 없애다'라는 뜻입니다 ✗","por: 'acabar por(결국 ~하게 되다)' → 정답 ✓","para: 'acabar para'라는 표현은 없습니다 ✗"]},{"id":"G65","q":"Tengo ____ sueño que me caigo.","o":["el","un","ese","ø"],"a":1,"k":"강조의 un ... que","t":"졸려 죽겠어.(쓰러질 만큼 졸려)","e":"'tener un + 명사 + que + 결과'는 '~할 정도로 엄청 …하다'라는 구어 강조 구문입니다. 'Tengo un sueño que me caigo'는 '쓰러질 정도로 졸리다'는 뜻이에요. 보통 tener sueño에는 관사를 쓰지 않지만, 정도를 강조할 때는 부정관사 un을 넣습니다. 예: Tengo una hambre que me muero.(배고파 죽겠어)","x":["el: 정관사는 이 강조 구문에 쓰지 않습니다 ✗","un: '그만큼 엄청난'이라는 강조의 부정관사 → 정답 ✓","ese: 지시사는 이미 언급된 것을 가리켜 맞지 않습니다 ✗","ø: 관사가 없으면 'que me caigo'의 정도 강조가 성립하지 않습니다 ✗"]},{"id":"G66","q":"No ____ todavía, está muy caliente.","o":["lo bebéis","os lo bebáis","os bebáis","se beban"],"a":1,"k":"부정명령 + 대명사","t":"아직 마시지 마, 너무 뜨거워.","e":"vosotros 부정명령은 'no + 접속법(bebáis)'이고, 대명사는 동사 앞에 놓입니다. 'beberse algo'는 '(남김없이) 다 마셔 버리다'라는 강조 재귀형이에요. 그래서 os(재귀) + lo(그것을) 순서로 'No os lo bebáis'가 됩니다. 중남미에서는 'No se lo beban'이라고 합니다.","x":["lo bebéis: 직설법이라 명령이 되지 않습니다 ✗","os lo bebáis: 재귀 os + 목적어 lo + 접속법 → 정답 ✓","os bebáis: 마실 대상(뜨거운 음료)을 가리키는 lo가 빠졌습니다 ✗","se beban: ustedes 형태라 주어가 맞지 않고 lo도 빠졌습니다 ✗"]},{"id":"G67","q":"Sinceramente, ese asunto carece ____ interés para mí.","o":["de","a","sin","por"],"a":0,"k":"carecer de","t":"솔직히 그 일은 나에게 아무런 흥미가 없다.","e":"carecer(~이 없다, 부족하다)는 항상 전치사 de와 함께 씁니다. 'carecer de interés'는 '흥미가 없다'는 격식 있는 표현으로, 'no tener interés'보다 문어적이에요. 예: El plan carece de sentido.(그 계획은 말이 안 된다)","x":["de: 'carecer de(~이 없다)'의 고정 전치사 → 정답 ✓","a: carecer는 a와 쓰지 않습니다 ✗","sin: '~없이'를 뜻해 carecer와 의미가 중복됩니다 ✗","por: carecer는 por와 쓰지 않습니다 ✗"]},{"id":"G68","q":"Los dos equipos han empatado, ____ habrá que ir a la prórroga.","o":["por lo que","en vista de que","de lo que","por que"],"a":0,"k":"결과 por lo que","t":"두 팀이 비겼으니 연장전으로 가야 할 것이다.","e":"'por lo que'는 앞 문장 전체를 받아 '그래서, 그 때문에'라는 결과를 나타냅니다(lo가 앞의 내용 전체를 가리킴). 'en vista de que'는 '~을 고려하여'라는 원인 표현이라 원인절 앞에 와야 해요. 'haber que + 동사원형'은 '~해야 한다'는 무인칭 의무 표현입니다.","x":["por lo que: 앞 내용의 결과를 이끄는 '그래서' → 정답 ✓","en vista de que: 원인을 나타내 결과절 앞에는 맞지 않습니다 ✗","de lo que: 비교(más de lo que)나 'hablar de lo que'처럼 쓰여 결과를 나타내지 못합니다 ✗","por que: 띄어 쓴 por que는 '~하는 이유로'라는 관계 표현이라 맞지 않습니다 ✗"]},{"id":"G69","q":"¿Todavía no ____ listos?","o":["habéis estado","estáis","sois","habéis sido"],"a":1,"k":"estar listo vs ser listo","t":"너희 아직 준비 안 됐어?","e":"listo는 ser와 estar에 따라 뜻이 달라지는 대표적인 형용사입니다. 'estar listo'는 '준비가 되다', 'ser listo'는 '영리하다'라는 뜻이에요. todavía no(아직)와 함께 현재 상태를 묻고 있으므로 estáis listos가 정답입니다. 중남미에서는 'ustedes están listos'라고 합니다.","x":["habéis estado: 현재완료라 '지금 준비됐는지'라는 현재 상태 질문에 맞지 않습니다 ✗","estáis: 'estar listo(준비되다)' 현재형 → 정답 ✓","sois: 'ser listo'는 '영리하다'라는 뜻이 됩니다 ✗","habéis sido: '영리했었다'라는 뜻이 되어 맞지 않습니다 ✗"]},{"id":"G70","q":"Han llamado preguntando ____ Luisa.","o":["para","a","de","por"],"a":3,"k":"preguntar por","t":"루이사를 찾는 전화가 왔었어.","e":"'preguntar por + 사람'은 '~을 찾다, ~이 있는지 묻다'라는 뜻입니다. 'Han llamado'는 3인칭 복수 무인칭으로 '(누군가) 전화했다'는 의미예요. 'preguntar a Luisa'는 '루이사에게 질문하다'라서 전화 건 사람이 루이사에게 직접 물은 것이 됩니다.","x":["para: 'preguntar para'는 '~하려고 묻다'라는 목적이 되어 어색합니다 ✗","a: '루이사에게 질문했다'는 뜻이라 문맥과 맞지 않습니다 ✗","de: 'preguntar de'는 이 뜻으로 쓰지 않습니다 ✗","por: '~을 찾다/~에 대해 묻다' → 정답 ✓"]},{"id":"G71","q":"____ muy segura de lo que dices.","o":["Te pareces","Parece","Pareces","Te parece"],"a":2,"k":"parecer + 형용사","t":"너는 네가 하는 말에 아주 확신하는 것처럼 보여.","e":"parecer + 형용사는 '~처럼 보이다'라는 뜻으로 재귀형 없이 씁니다. 주어는 '너(tú)'이므로 pareces이고, 형용사 segura는 주어(여성)에 맞춥니다. 'parecerse a'는 '~와 닮다', 'Te parece...'는 '네가 보기에 ~하다(의견)'라는 다른 구조예요.","x":["Te pareces: 'parecerse'는 '닮다'라는 뜻이라 맞지 않습니다 ✗","Parece: 3인칭이라 'lo que dices(네가 하는 말)'의 주어 tú와 어긋납니다 ✗","Pareces: tú가 주어인 '~처럼 보이다' → 정답 ✓","Te parece: '네 생각에 ~하다'라는 의견 구조라 맞지 않습니다 ✗"]},{"id":"G72","q":"¿Cómo prefieres ____ café, con o sin azúcar?","o":["del","el","al","ø"],"a":1,"k":"정관사 (일반적 대상)","t":"커피는 어떻게 마시는 게 좋아, 설탕 넣어서 아니면 안 넣고?","e":"취향이나 습관을 말할 때 일반적인 대상(커피라는 음료 일반)은 정관사를 붙여 el café라고 합니다. 'Prefiero el café sin azúcar.(난 커피를 설탕 없이 마시는 게 좋아)'처럼요. preferir의 목적어로 사물이 올 때는 전치사 a가 필요 없습니다.","x":["del: de + el이라 목적어 자리에 올 수 없습니다 ✗","el: 일반적 대상을 가리키는 정관사 → 정답 ✓","al: a + el이라 사물 목적어 앞에 쓰지 않습니다 ✗","ø: 관사 없이 'prefieres café'는 '(어떤 음료 중) 커피'를 고를 때 쓰여, '어떻게' 마시는지 묻는 문맥엔 정관사가 자연스럽습니다 ✗"]},{"id":"G73","q":"Ha llovido sin parar durante horas. ____ mal que ya ha escampado.","o":["Menos","Poco","Algún","Algo"],"a":0,"k":"menos mal que","t":"몇 시간 동안 쉬지 않고 비가 왔다. 이제 그쳐서 다행이다.","e":"'Menos mal que + 직설법'은 '~해서 다행이다'라는 구어 관용 표현입니다. 안도감을 나타내며, 뒤에 실제 사실이 오므로 직설법을 써요. escampar는 '(비가) 그치다, 날이 개다'라는 동사입니다. 예: Menos mal que llegaste a tiempo.(네가 제시간에 와서 다행이야)","x":["Menos: 'menos mal que(~해서 다행이다)' → 정답 ✓","Poco: 'poco mal'이라는 표현은 없습니다 ✗","Algún: 형용사형이라 명사 앞에 와야 하고 관용구도 아닙니다 ✗","Algo: 'algo mal'은 '뭔가 잘못'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G74","q":"Será mejor que usemos los vasos ____ plástico en la fiesta.","o":["de","a","por","con"],"a":0,"k":"재료의 de","t":"파티에서는 플라스틱 컵을 쓰는 게 좋겠어.","e":"물건의 재료를 나타낼 때는 'de + 재료'를 씁니다: vaso de plástico(플라스틱 컵), mesa de madera(나무 탁자). 'vaso de agua'처럼 내용물을 나타낼 때도 de를 써요. 'Será mejor que + 접속법'은 '~하는 게 좋겠다'라는 제안 표현입니다.","x":["de: 재료를 나타내는 de → 정답 ✓","a: 재료를 나타내지 않습니다('a mano'처럼 방식에 씀) ✗","por: 원인·경로 전치사라 재료와 맞지 않습니다 ✗","con: '~이 달린/~와 함께'라서 '플라스틱이 들어 있는 컵'처럼 어색합니다 ✗"]},{"id":"G75","q":"No es fácil llevarse bien con mi tío. Es muy ____.","o":["suyo","a lo suyo","de lo suyo","lo suyo"],"a":0,"k":"ser muy suyo","t":"우리 삼촌이랑 잘 지내기는 쉽지 않아. 성격이 아주 독특하거든.","e":"'ser muy suyo/suya'는 '자기 방식이 확고하다, 성격이 별나다(까다롭다)'라는 구어 표현입니다. 주어에 따라 soy muy mío, eres muy tuyo처럼 바뀌어요. 'ir a lo suyo'는 '자기 일에만 신경 쓰다(이기적이다)'라는 다른 표현으로, ser가 아니라 ir와 함께 씁니다.","x":["suyo: 'ser muy suyo(성격이 독특하다)' → 정답 ✓","a lo suyo: 'ir a lo suyo'로 써야 하므로 ser와 맞지 않습니다 ✗","de lo suyo: 이런 관용 표현은 없습니다 ✗","lo suyo: '자기 몫/자기 일'이라 'muy lo suyo'는 비문입니다 ✗"]},{"id":"G76","q":"El padre de mi marido, ____, mi suegro, es abogado.","o":["por eso","de tal","o sea","pues"],"a":2,"k":"설명 접속어 o sea","t":"내 남편의 아버지, 즉 내 시아버지는 변호사다.","e":"'o sea'는 '즉, 다시 말해'라는 뜻으로 앞의 말을 다른 말로 풀어 설명할 때 씁니다. 'es decir'와 같은 의미이며 구어에서 아주 자주 써요. suegro는 '시아버지/장인'을 모두 뜻합니다. 예: Llego el lunes, o sea, dentro de tres días.(월요일에 도착해, 즉 3일 뒤야)","x":["por eso: '그래서'라는 결과 표현이라 맞지 않습니다 ✗","de tal: 'de tal palo, tal astilla(부전자전)'처럼 쓰며 여기서는 의미가 없습니다 ✗","o sea: '즉, 다시 말해' → 정답 ✓","pues: '그러니까/왜냐하면'이라서 동격 설명에 맞지 않습니다 ✗"]},{"id":"G77","q":"Te lo voy a contar, pero pásate por casa si puedes, prefiero ____ en persona.","o":["a decírtelo","de decirlo","decírselo","decírtelo"],"a":3,"k":"preferir + 동사원형","t":"얘기해 줄게, 그런데 가능하면 집에 들러. 직접 만나서 말하는 게 좋겠어.","e":"preferir 뒤에 같은 주어의 동작이 오면 전치사 없이 바로 동사원형이 옵니다. 대명사는 동사원형 뒤에 붙여 쓰며, 간접목적어 te(너에게) + 직접목적어 lo(그것을) 순서로 'decírtelo'가 돼요. 대명사를 붙이면 강세 위치를 지키기 위해 decírtelo처럼 악센트를 찍습니다.","x":["a decírtelo: preferir 뒤에는 전치사 a가 오지 않습니다 ✗","de decirlo: 전치사 de도 쓰지 않고 '너에게(te)'도 빠졌습니다 ✗","decírselo: se는 '그/그녀/당신에게'라서 tú로 말하는 문장과 맞지 않습니다 ✗","decírtelo: te(너에게) + lo(그것을)를 붙인 동사원형 → 정답 ✓"]},{"id":"G78","q":"____ gritando, no te escucha bien.","o":["Aun","A pesar de","Por mucho que","Incluso si"],"a":0,"k":"aun + 현재분사","t":"소리를 질러도 그는 네 말을 잘 못 들어.","e":"'aun + 현재분사'는 '~하더라도, ~하는데도'라는 양보의 의미를 나타냅니다. 이때 aun은 '심지어(incluso)'라는 뜻이라 악센트가 없어요. 'aun así(그런데도)', 'aun cuando(~할지라도)'도 같은 aun입니다. 'a pesar de'는 뒤에 동사원형이나 명사가 와야 합니다.","x":["Aun: '~하더라도'라는 양보 + 현재분사 → 정답 ✓","A pesar de: 뒤에 동사원형(gritar)이 와야 하고 현재분사와는 쓰지 않습니다 ✗","Por mucho que: 뒤에 동사의 활용형(grites)이 와야 합니다 ✗","Incluso si: 뒤에 활용된 동사(gritas)가 와야 해서 현재분사와 맞지 않습니다 ✗"]},{"id":"G79","q":"Jorge y yo ____ toda la tarde de nuestras diferencias.","o":["hablamos","estuvimos hablando","hablábamos","estábamos hablando"],"a":1,"k":"단순과거 진행형","t":"호르헤와 나는 오후 내내 우리의 차이점에 대해 이야기했다.","e":"'toda la tarde(오후 내내)'처럼 기간이 정해지고 끝난 행동의 '지속'을 강조할 때는 단순과거 진행형 'estuve + 현재분사'를 씁니다. 'estuvimos hablando'는 '(오후 내내) 계속 이야기했다'는 뜻이에요. 단순과거 hablamos도 문법상 가능하지만, 오래 지속된 과정을 강조하는 진행형이 이 문맥에 가장 자연스럽다는 것이 교재 기준입니다.","x":["hablamos: 문법상 가능하나 '내내 지속된' 과정의 뉘앙스가 약합니다 ✗","estuvimos hablando: 끝난 기간 동안의 지속을 강조하는 단순과거 진행형 → 정답 ✓","hablábamos: 불완료과거는 배경 묘사라 끝난 기간(toda la tarde)과 어울리지 않습니다 ✗","estábamos hablando: 배경 진행형이라 다른 사건이 필요하고 완결된 기간과 맞지 않습니다 ✗"]},{"id":"G80","q":"Llegué dos horas tarde ____ de las obras en la carretera.","o":["con motivo","debido","por culpa","en función"],"a":2,"k":"por culpa de","t":"도로 공사 때문에 두 시간이나 늦게 도착했다.","e":"'por culpa de'는 '~탓에, ~때문에'라는 뜻으로 부정적인 원인(잘못)을 나타냅니다. 'debido a'도 원인을 나타내지만 전치사 a가 필요해서 보기의 'debido + de'는 규범상 틀린 형태예요. 'con motivo de'는 '~을 기념하여, ~을 계기로'라는 뜻입니다. 예: Por culpa de la lluvia, se canceló el partido.(비 때문에 경기가 취소됐다)","x":["con motivo: 'con motivo de'는 '~을 계기로/기념해'라서 부정적 원인에 맞지 않습니다 ✗","debido: 'debido a'로 써야 하고 'debido de'는 규범상 틀립니다 ✗","por culpa: 'por culpa de(~탓에)' → 정답 ✓","en función: 'en función de'는 '~에 따라'라는 뜻입니다 ✗"]},{"id":"G81","q":"Voy a indicarle dónde está la sala de espera, ____.","o":["siga me","sígame","sígueme","seguirme"],"a":1,"k":"usted 긍정명령","t":"대기실이 어디 있는지 안내해 드릴게요, 저를 따라오세요.","e":"'indicarle(당신에게 알려 드리다)'의 le를 보면 상대를 usted로 대하고 있습니다. usted 긍정명령은 접속법 3인칭 단수 형태(siga)이고, 대명사는 동사 뒤에 붙여 씁니다: sígame. 대명사가 붙으면 원래 강세를 지키기 위해 악센트를 찍어요. tú라면 sígueme가 됩니다.","x":["siga me: 긍정명령에서는 대명사를 붙여 써야 합니다 ✗","sígame: usted 긍정명령 + 대명사 me → 정답 ✓","sígueme: tú 명령이라 indicarle(usted)과 맞지 않습니다 ✗","seguirme: 동사원형이라 명령이 되지 않습니다 ✗"]},{"id":"G82","q":"¡Qué maravilla ____ canción!","o":["en","por","de","a"],"a":2,"k":"qué + 명사 + de","t":"정말 멋진 노래야!","e":"'¡Qué + 평가 명사 + de + 명사!'는 감탄문 구조입니다. maravilla(경이로운 것, 멋진 것)가 뒤의 canción을 평가하고, de가 둘을 연결해요. 'maravilla de canción'은 '멋진 노래'라는 뜻이 됩니다. 같은 구조: ¡Qué desastre de día!(정말 엉망인 하루야!)","x":["en: 이 감탄 구조에 쓰지 않습니다 ✗","por: 원인 전치사라 맞지 않습니다 ✗","de: '평가 명사 + de + 대상' 구조 → 정답 ✓","a: 방향 전치사라 맞지 않습니다 ✗"]},{"id":"G83","q":"El almuerzo ya ____ hecho. ¡A comer!","o":["va a estar","es","va a ser","está"],"a":3,"k":"estar + 과거분사 (결과)","t":"점심이 다 됐어. 먹자!","e":"'estar + 과거분사'는 어떤 행동이 끝난 뒤의 '결과 상태'를 나타냅니다. 'El almuerzo está hecho'는 '점심이 (만들어져서) 준비된 상태다'라는 뜻이에요. 'ser + 과거분사'는 수동태(~에 의해 만들어지다)로 행위 자체를 나타냅니다. ya(이미)와 함께 현재 결과를 말하므로 está가 맞습니다.","x":["va a estar: '될 것이다'라는 미래라 ya·¡A comer!와 맞지 않습니다 ✗","es: 'ser hecho'는 수동태 행위로 결과 상태를 나타내지 않습니다 ✗","va a ser: 미래 수동 행위라 맞지 않습니다 ✗","está: 결과 상태를 나타내는 estar + 과거분사 → 정답 ✓"]},{"id":"G84","q":"En el futuro, tendrás que ser capaz de valerte ____.","o":["de ti misma","por ti misma","a ti misma","tú misma"],"a":1,"k":"valerse por sí mismo","t":"앞으로 너는 스스로 해 나갈 수 있어야 해.","e":"'valerse por sí mismo/a'는 '남의 도움 없이 스스로 해 나가다, 자립하다'라는 표현입니다. 주어에 따라 por mí mismo, por ti misma처럼 바뀌어요. 여기서는 tú(여성)이므로 'valerte por ti misma'가 됩니다. 'valerse de'는 '~을 이용하다'라는 다른 뜻이에요.","x":["de ti misma: 'valerse de'는 '~을 이용하다'라는 다른 뜻입니다 ✗","por ti misma: '스스로 해 나가다' → 정답 ✓","a ti misma: 'valerse a'라는 결합은 없습니다 ✗","tú misma: 전치사가 없어 구조가 성립하지 않습니다 ✗"]},{"id":"G85","q":"Esta noticia tiene que ____ ya.","o":["publicar","se publicar","publicar se","publicarse"],"a":3,"k":"수동 se + 동사원형","t":"이 뉴스는 당장 보도되어야 한다.","e":"'se + 동사'는 수동의 의미(~되다)를 만들 수 있습니다(수동 se). 동사원형과 함께 쓸 때는 대명사 se를 동사원형 뒤에 붙여 'publicarse'로 씁니다. 'tiene que publicarse' 대신 'se tiene que publicar'처럼 앞으로 뺄 수도 있어요. 동사원형 앞에 바로 se를 두거나 띄어 쓰는 것은 틀립니다.","x":["publicar: se가 없으면 '뉴스가 (무언가를) 발표해야 한다'는 이상한 뜻이 됩니다 ✗","se publicar: 동사원형 바로 앞에 se를 둘 수 없습니다 ✗","publicar se: 붙여 써야 하므로 틀립니다 ✗","publicarse: 동사원형에 수동 se를 붙인 형태 → 정답 ✓"]},{"id":"G86","q":"No ____ la televisión, estoy a punto de ver mi serie preferida.","o":["apages","apagas","apagues","apaga"],"a":2,"k":"tú 부정명령","t":"텔레비전 끄지 마, 내가 좋아하는 드라마를 막 보려던 참이야.","e":"tú 부정명령은 'no + 접속법 현재'입니다. apagar(끄다)는 -gar 동사라 접속법에서 발음을 유지하려고 g 뒤에 u를 넣어 apague, apagues가 돼요(apages는 틀린 철자). 'estar a punto de + 동사원형'은 '막 ~하려던 참이다'라는 뜻입니다.","x":["apages: 철자 오류로, -gar 동사는 접속법에서 gu로 바뀝니다 ✗","apagas: 직설법이라 명령이 되지 않습니다 ✗","apagues: tú 부정명령(no + 접속법) → 정답 ✓","apaga: 긍정명령이라 no와 함께 쓸 수 없습니다 ✗"]},{"id":"G87","q":"Como no llegabas, pensé que te ____ algo.","o":["hubo ocurrido","ha ocurrido","hubiese ocurrido","había ocurrido"],"a":3,"k":"pensar que + 대과거","t":"네가 안 와서 무슨 일이 생긴 줄 알았어.","e":"긍정의 pensar que는 생각한 내용을 사실처럼 전달하므로 직설법을 씁니다. 주절이 과거(pensé)이고, 무슨 일이 생긴 것은 그보다 앞선 일이므로 대과거 'había ocurrido'가 됩니다. 만약 'No pensé que...'처럼 부정이라면 접속법(hubiese ocurrido)이 올 수 있어요.","x":["hubo ocurrido: 직전과거는 거의 쓰지 않는 문어 형태로 여기에 맞지 않습니다 ✗","ha ocurrido: 현재완료라 과거 주절과 시제가 맞지 않습니다 ✗","hubiese ocurrido: 접속법이라 긍정 pensar que 뒤에 쓰지 않습니다 ✗","había ocurrido: 과거보다 앞선 일을 나타내는 직설법 대과거 → 정답 ✓"]},{"id":"G88","q":"____ fondo, todas estamos de acuerdo en un tema tan fundamental.","o":["En el","Por el","Al","Del"],"a":0,"k":"en el fondo","t":"속으로는(근본적으로는) 우리 모두 그렇게 중요한 문제에 대해 같은 생각이다.","e":"'en el fondo'는 '마음속으로는, 근본적으로는, 사실은'이라는 고정 표현입니다. 겉보기와 달리 본질적으로는 그렇다는 뉘앙스예요. 'a fondo'는 '철저히'라는 다른 뜻입니다. 예: En el fondo es buena persona.(사실 그는 좋은 사람이야)","x":["En el: 'en el fondo(근본적으로는)' → 정답 ✓","Por el: 'por el fondo'는 '바닥 쪽으로'처럼 공간적 의미입니다 ✗","Al: 'al fondo'는 '안쪽 끝에'라는 위치 표현입니다 ✗","Del: 'del fondo'는 '안쪽(바닥)의'라는 뜻이라 부사구가 되지 않습니다 ✗"]},{"id":"G89","q":"Ojalá ____ qué nos depara el futuro.","o":["supiera","sabré","supe","sepa"],"a":0,"k":"ojalá + 접속법 과거","t":"앞으로 미래가 우리에게 무엇을 가져다줄지 알 수 있으면 좋을 텐데.","e":"ojalá 뒤에는 항상 접속법이 옵니다. 접속법 현재(ojalá sepa)는 실현 가능한 바람, 접속법 과거(ojalá supiera)는 실현이 어렵거나 불가능한 바람을 나타내요. 미래를 미리 아는 것은 불가능에 가까운 소망이므로 supiera가 가장 적절합니다. deparar은 '(운명 등이) 가져다주다'라는 문어적 동사입니다.","x":["supiera: 실현 불가능한 바람을 나타내는 접속법 과거 → 정답 ✓","sabré: 직설법 미래라 ojalá 뒤에 쓰지 않습니다 ✗","supe: 직설법 단순과거라 ojalá 뒤에 쓰지 않습니다 ✗","sepa: 접속법 현재로 실현 가능한 바람에 쓰여, 불가능한 소망인 이 문맥에는 덜 적절합니다 ✗"]},{"id":"G90","q":"____ hablarme porque se sintió muy ofendida por mis palabras.","o":["Se puso a","Quedó en","Acabó de","Dejó de"],"a":3,"k":"dejar de + 동사원형","t":"그녀는 내 말에 크게 상처를 받아서 나와 말을 끊었다.","e":"'dejar de + 동사원형'은 '~하는 것을 그만두다'라는 뜻입니다. 'Dejó de hablarme'는 '나에게 말을 걸지 않게 되었다(연락을 끊었다)'는 의미예요. 'ponerse a(~하기 시작하다)', 'quedar en(~하기로 약속하다)', 'acabar de(막 ~했다)'와 구별해 두세요.","x":["Se puso a: '~하기 시작했다'라서 기분이 상한 이유와 맞지 않습니다 ✗","Quedó en: '~하기로 약속했다'라는 뜻이라 맞지 않습니다 ✗","Acabó de: '막 ~했다'라는 뜻이라 문맥과 맞지 않습니다 ✗","Dejó de: '~하는 것을 그만두었다' → 정답 ✓"]},{"id":"G91","q":"María ____ poco antes de salir de su casa.","o":["se peina","peina","peinarse","peinándose"],"a":0,"k":"재귀동사 peinarse","t":"마리아는 집을 나서기 직전에 머리를 빗는다.","e":"peinarse는 '(자기) 머리를 빗다'라는 재귀동사로, 행동이 자기 자신에게 돌아올 때 se를 씁니다. 'peinar'만 쓰면 '다른 사람(의 머리)을 빗기다'가 되어 목적어가 필요해요. 주어 María가 있으므로 활용된 동사 se peina가 와야 합니다. 'antes de + 동사원형'은 '~하기 전에'입니다.","x":["se peina: 자기 머리를 빗는 재귀동사 3인칭 현재 → 정답 ✓","peina: 재귀대명사가 없어 '누군가를 빗긴다'가 되고 목적어도 없습니다 ✗","peinarse: 동사원형이라 주어 María의 서술어가 될 수 없습니다 ✗","peinándose: 현재분사만으로는 서술어가 되지 않습니다 ✗"]},{"id":"G92","q":"____ gritó, se quedó afónico.","o":["De tanto que","Tanto que","Tanto como","De tal que"],"a":0,"k":"de tanto que (원인)","t":"하도 소리를 질러서 그는 목이 쉬어 버렸다.","e":"'de tanto + 동사원형'이나 'de tanto que + 활용 동사'는 '너무 ~한 나머지, 하도 ~해서'라는 원인을 나타냅니다. 'De tanto que gritó, se quedó afónico'는 '하도 소리를 질러서 목이 쉬었다'는 뜻이에요. 'De tanto gritar'라고 해도 같은 의미입니다. quedarse afónico는 '목소리가 안 나오게 되다'라는 표현입니다.","x":["De tanto que: '하도 ~해서'라는 원인 → 정답 ✓","Tanto que: '너무 ~해서 (결과)'는 'gritó tanto que...'처럼 동사 뒤에 와야 합니다 ✗","Tanto como: '~만큼'이라는 비교 표현이라 맞지 않습니다 ✗","De tal que: 'de tal manera que'처럼 명사가 필요해 이 형태는 틀립니다 ✗"]},{"id":"G93","q":"¡Qué bien ____ esta colonia!","o":["olería","huele","está oliendo","estaba oliendo"],"a":1,"k":"oler 현재 (huele)","t":"이 향수 냄새 정말 좋다!","e":"oler(냄새가 나다)는 불규칙 동사로, 강세가 있는 어간에서 o가 hue-로 바뀝니다: huelo, hueles, huele, olemos, oléis, huelen. '¡Qué bien huele!'는 '냄새 정말 좋다!'라는 감탄이에요. 지금 느끼는 감각이라 단순 현재가 자연스럽습니다. colonia는 '오드콜로뉴(가벼운 향수)'입니다.","x":["olería: 조건법이라 지금 느끼는 감각 감탄에 맞지 않습니다 ✗","huele: oler의 3인칭 단수 현재 → 정답 ✓","está oliendo: 진행형은 상태 동사 oler(냄새가 나다)에 어색합니다 ✗","estaba oliendo: 과거 진행형이라 현재 감탄과 맞지 않습니다 ✗"]},{"id":"G94","q":"Estás cada día ____ guapa. ¡Dime cómo lo haces!","o":["totalmente","más","completamente","toda"],"a":1,"k":"cada día más","t":"너는 날이 갈수록 더 예뻐지는구나. 비결이 뭔지 말해 줘!","e":"'cada día/vez + más + 형용사'는 '날이 갈수록 더 ~하다'라는 점진적 변화를 나타냅니다. 'Estás cada día más guapa'에서 estar는 '(지금 보기에) ~해 보인다'는 상태의 뉘앙스예요. 반대는 'cada día menos(점점 덜)'입니다. 예: Hace cada vez más frío.(점점 더 추워진다)","x":["totalmente: '완전히'라서 cada día와 어울리지 않습니다 ✗","más: 'cada día más(날이 갈수록 더)' → 정답 ✓","completamente: '완전히'라서 점진적 변화와 맞지 않습니다 ✗","toda: '온통'이라는 뜻이라 문맥과 맞지 않습니다 ✗"]},{"id":"G95","q":"Si ____ que iba a suspender, no habría hecho el test.","o":["haya sabido","hubiera sabido","habría sabido","ha sabido"],"a":1,"k":"과거 사실 반대 가정","t":"떨어질 줄 알았다면 시험을 보지 않았을 텐데.","e":"과거의 사실과 반대되는 가정은 'si + 접속법 과거완료, 조건법 완료'로 만듭니다. 'Si hubiera sabido..., no habría hecho...'는 '(실제로는 몰랐지만) 알았더라면 하지 않았을 것이다'라는 뜻이에요. 주의: si절에는 조건법(habría sabido)을 쓰지 않습니다. suspender는 스페인에서 '(시험에) 떨어지다'라는 뜻입니다(중남미는 reprobar).","x":["haya sabido: 접속법 현재완료는 si 뒤에 쓰지 않습니다 ✗","hubiera sabido: 과거 반대 가정의 접속법 과거완료 → 정답 ✓","habría sabido: 조건법 완료는 si절이 아니라 결과절에 씁니다 ✗","ha sabido: 직설법 현재완료라 반대 가정이 되지 않습니다 ✗"]},{"id":"G96","q":"Estoy ____ la espada y la pared, no sé qué hacer.","o":["sobre","a","hacia","entre"],"a":3,"k":"entre la espada y la pared","t":"나는 진퇴양난이야, 어떻게 해야 할지 모르겠어.","e":"'estar entre la espada y la pared'는 직역하면 '칼과 벽 사이에 있다'로, '이러지도 저러지도 못하는 궁지에 몰리다, 진퇴양난'이라는 관용 표현입니다. 두 가지 사이를 나타내므로 전치사 entre가 고정이에요. 비슷한 표현: estar en un callejón sin salida(막다른 골목에 있다).","x":["sobre: '~위에'라는 뜻이라 관용구가 되지 않습니다 ✗","a: 'a la espada'라는 결합은 없습니다 ✗","hacia: '~쪽으로'라는 방향이라 맞지 않습니다 ✗","entre: 'entre la espada y la pared(진퇴양난)' → 정답 ✓"]},{"id":"G97","q":"Me gustaría reservar una habitación doble que ____ al mar.","o":["da","dará","de","dé"],"a":3,"k":"관계절 접속법 + dar a","t":"바다가 보이는 더블룸을 예약하고 싶습니다.","e":"원하는 조건의 대상(아직 정해지지 않은 방)을 설명하는 관계절에는 접속법을 씁니다. 'dar a + 장소'는 '(창문·방이) ~을 향하다, ~쪽으로 나 있다'라는 표현이에요. dar의 접속법 현재 3인칭 단수는 전치사 de와 구별하기 위해 악센트를 찍은 dé입니다.","x":["da: 직설법은 이미 존재하는 특정한 방을 말할 때 씁니다 ✗","dará: 미래형은 관계절의 바람 표현에 맞지 않습니다 ✗","de: 악센트가 없으면 전치사 de(~의)가 됩니다 ✗","dé: 원하는 조건을 나타내는 접속법(악센트 필수) → 정답 ✓"]},{"id":"G98","q":"¿Me permite que le ____ un consejo?","o":["da","de","dé","doy"],"a":2,"k":"permitir que + 접속법","t":"제가 조언 하나 드려도 될까요?","e":"permitir(허락하다)처럼 허가·바람을 나타내는 동사 뒤의 que절에는 접속법을 씁니다. '¿Me permite que le dé un consejo?'는 usted에게 정중하게 조언해도 되는지 묻는 표현이에요. dar의 접속법 dé는 전치사 de와 구별하기 위해 악센트를 찍습니다.","x":["da: 직설법이라 permitir que 뒤에 쓰지 않고 주어도 맞지 않습니다 ✗","de: 악센트가 없으면 전치사 de가 됩니다 ✗","dé: 허락 표현 뒤 접속법(1인칭 단수) → 정답 ✓","doy: 직설법이라 permitir que 뒤에 맞지 않습니다 ✗"]},{"id":"G99","q":"Siéntate, Pablito, te ____ muy mal hoy.","o":["portas","vas a portar","estás portando","estarías portando"],"a":2,"k":"현재진행형 (오늘 행동)","t":"앉아라, 파블리토. 너 오늘 정말 말썽이구나.","e":"'estar + 현재분사'는 지금 이 순간이나 일시적 기간(hoy)에 진행 중인 행동을 나타냅니다. 'te estás portando muy mal hoy'는 '오늘따라 행동이 나쁘다'는 일시적 상황을 강조해요. 단순현재 te portas는 '평소에 버릇이 나쁘다'는 습관적 의미가 강합니다. portarse bien/mal은 '행실이 좋다/나쁘다'입니다.","x":["portas: 단순현재는 평소 습관처럼 들려 hoy의 일시성을 살리지 못합니다 ✗","vas a portar: 미래라 지금 벌어지는 행동과 맞지 않습니다 ✗","estás portando: 오늘 진행 중인 일시적 행동 → 정답 ✓","estarías portando: 조건법 진행형이라 추측이 되어 맞지 않습니다 ✗"]},{"id":"G100","q":"No hay ni una sola familia que ____ perfecta.","o":["sean","son","es","sea"],"a":3,"k":"존재 부정 관계절+접속법","t":"완벽한 가족은 단 하나도 없다.","e":"'No hay ninguno/nadie/ni uno que...'처럼 존재하지 않는 대상을 설명하는 관계절에는 접속법을 씁니다. 선행사가 'una sola familia(단 하나의 가족)'로 단수이므로 동사도 단수 sea입니다. 예: No hay nadie que me entienda.(나를 이해하는 사람은 아무도 없다)","x":["sean: 복수형이라 단수 선행사 familia와 맞지 않습니다 ✗","son: 직설법 복수라 두 가지 모두 틀립니다 ✗","es: 직설법이라 존재하지 않는 대상 설명에 맞지 않습니다 ✗","sea: 존재 부정 + 단수 접속법 → 정답 ✓"]},{"id":"G101","q":"No puedo salir ahora, ve ____ al supermercado, por favor.","o":["tu","ti","por ti","tú"],"a":3,"k":"명령문 주어 강조 tú","t":"나 지금 못 나가니까 네가 슈퍼에 좀 가 줘.","e":"명령문에서 '다른 사람이 아니라 네가'라고 주어를 강조할 때는 동사 뒤에 주격 대명사 tú를 넣습니다. 've tú'는 '네가 가'라는 뜻이에요. ve는 ir의 tú 긍정명령입니다. tu(악센트 없음)는 소유사(너의), ti는 전치사 뒤에 오는 형태라 주어가 될 수 없어요.","x":["tu: 악센트 없는 tu는 소유사(너의)라 명사가 필요합니다 ✗","ti: 전치사 뒤에서만 쓰는 형태라 주어가 될 수 없습니다 ✗","por ti: '너를 위해/너 대신'이라는 뜻이 되어 문맥과 맞지 않습니다 ✗","tú: 명령문 주어를 강조하는 주격 대명사 → 정답 ✓"]},{"id":"G102","q":"Nos preguntó si ____ hambre.","o":["teníamos","tuviéramos","tendremos","tengamos"],"a":0,"k":"간접의문 si + 직설법","t":"그는 우리에게 배고프냐고 물었다.","e":"'preguntar si...(~인지 묻다)'는 간접의문문으로 직설법을 씁니다. 원래 질문 '¿Tenéis hambre?'가 과거 주절(preguntó)로 전달되면서 현재가 불완료과거 teníamos로 바뀌었어요. 의문의 si 뒤에도 접속법은 쓰지 않습니다.","x":["teníamos: 간접의문 + 시제 일치된 불완료과거 → 정답 ✓","tuviéramos: 접속법이라 의문 si 뒤에 쓰지 않습니다 ✗","tendremos: 미래형이라 과거 주절과 시제가 맞지 않습니다 ✗","tengamos: 접속법 현재라 법·시제 모두 맞지 않습니다 ✗"]},{"id":"G103","q":"____ todo pronóstico, ganó el candidato menos conocido.","o":["Por contra","Contra","En contra","Contra de"],"a":1,"k":"contra todo pronóstico","t":"모든 예상을 깨고 가장 덜 알려진 후보가 당선되었다.","e":"'contra todo pronóstico'는 '모든 예상을 뒤엎고, 예상 밖으로'라는 고정 표현입니다. contra는 '~에 반하여'라는 전치사로 바로 명사가 와요. 'en contra de'라는 형태도 있지만 de가 필요하고 이 관용구에는 쓰지 않습니다. 'por contra'는 '반면에'라는 연결어입니다.","x":["Por contra: '반면에'라는 연결어라 맞지 않습니다 ✗","Contra: 'contra todo pronóstico(모든 예상을 깨고)' → 정답 ✓","En contra: 'en contra de'처럼 de가 필요합니다 ✗","Contra de: contra 뒤에는 de를 쓰지 않습니다 ✗"]},{"id":"G104","q":"Que nosotros ____, Irene sigue viviendo en Italia.","o":["sepamos","sabríamos","supiéramos","sabemos"],"a":0,"k":"que yo sepa (관용)","t":"우리가 아는 한, 이레네는 아직 이탈리아에 살고 있다.","e":"'que yo sepa / que nosotros sepamos'는 '내가(우리가) 아는 한'이라는 관용 표현으로, 항상 접속법 현재를 씁니다. 정보가 확실하지 않을 수 있다는 단서를 다는 말이에요. 예: Que yo sepa, no ha llamado nadie.(내가 알기로는 아무도 전화 안 했어)","x":["sepamos: 'que nosotros sepamos(우리가 아는 한)'의 고정 형태 → 정답 ✓","sabríamos: 조건법은 이 관용구에 쓰지 않습니다 ✗","supiéramos: 접속법 과거는 이 관용구 형태가 아닙니다 ✗","sabemos: 직설법은 이 관용구에 쓰지 않습니다 ✗"]},{"id":"G105","q":"Yo desayuné ____ salir de casa.","o":["hasta","antes de","en cuanto","desde"],"a":1,"k":"antes de + 동사원형","t":"나는 집을 나서기 전에 아침을 먹었다.","e":"'antes de + 동사원형'은 '~하기 전에'라는 뜻입니다. 주어가 같을 때(내가 먹고, 내가 나감)는 동사원형을 써요. 주어가 다르면 'antes de que + 접속법'이 됩니다. 예: Desayuné antes de que salieras.(네가 나가기 전에 나는 아침을 먹었다)","x":["hasta: '~할 때까지'라 '나갈 때까지 아침을 먹었다'는 어색한 뜻이 됩니다 ✗","antes de: '~하기 전에' + 동사원형 → 정답 ✓","en cuanto: '~하자마자'는 뒤에 활용된 동사가 와야 합니다 ✗","desde: '~부터'라는 시작점이라 맞지 않습니다 ✗"]},{"id":"G106","q":"El vecino pregunta por cosas que no ____.","o":["le incumben","le incumban","se incumben","las incumben"],"a":0,"k":"incumbir + 간접목적어","t":"그 이웃은 자기와 상관없는 일들을 캐묻는다.","e":"incumbir(~에게 관계되다, ~의 소관이다)는 gustar처럼 '관계되는 일'이 주어이고 사람은 간접목적격(le)으로 씁니다. 주어 cosas가 복수이므로 incumben이에요. 실제로 상관없는 일들을 묻는다는 사실을 말하므로 직설법을 씁니다. 예: Eso no te incumbe.(그건 네가 상관할 일 아니야)","x":["le incumben: 간접목적격 le + 직설법 복수 → 정답 ✓","le incumban: 접속법은 실제로 존재하는 특정한 일을 말할 때 쓰지 않습니다 ✗","se incumben: incumbir는 재귀형으로 쓰지 않습니다 ✗","las incumben: 직접목적격이라 이 동사 구조와 맞지 않습니다 ✗"]},{"id":"G107","q":"Paso por este callejón ____ los días.","o":["cada","algunos","todos","todas"],"a":2,"k":"todos los días","t":"나는 매일 이 골목길을 지나간다.","e":"'todos los días'는 '매일'이라는 뜻으로, todo는 뒤의 명사(días, 남성 복수)에 맞춰 todos가 되고 정관사를 동반합니다. 'cada día'도 '매일'이지만 cada 뒤에는 관사 없이 단수 명사가 와요(cada día). 'cada los días'는 틀린 형태입니다.","x":["cada: cada 뒤에는 관사·복수가 오지 않아 'cada día'여야 합니다 ✗","algunos: '어떤 날들에'라는 뜻이 되어 습관의 뉘앙스가 약하고 관사도 맞지 않습니다 ✗","todos: 'todos los días(매일)' → 정답 ✓","todas: 여성형이라 남성 명사 días와 맞지 않습니다 ✗"]},{"id":"G108","q":"Con el tiempo, este pueblo llegará ____ ser uno de los más grandes de la región.","o":["de","en","hacia","a"],"a":3,"k":"llegar a + 동사원형","t":"시간이 지나면 이 마을은 그 지역에서 가장 큰 곳 중 하나가 될 것이다.","e":"'llegar a + 동사원형'은 '(노력·시간 끝에) ~하기에 이르다, 결국 ~가 되다'라는 뜻입니다. 'llegará a ser'는 '마침내 ~이 될 것이다'라는 의미예요. 이동 동사 llegar는 목적지·도달점을 나타낼 때 전치사 a를 씁니다. 예: Llegó a ser presidente.(그는 결국 대통령이 되었다)","x":["de: 'llegar de'는 '~에서 도착하다'라는 출발점입니다 ✗","en: 'llegar en'은 교통수단(llegar en tren) 등에 씁니다 ✗","hacia: '~쪽으로'라는 방향이라 이 구문에 쓰지 않습니다 ✗","a: 'llegar a ser(결국 ~이 되다)' → 정답 ✓"]},{"id":"G109","q":"Que ____ mayor de edad no significa que puedas hacer lo que te venga en gana.","o":["estés","eres","seas","estás"],"a":2,"k":"que 주어절 + 접속법","t":"네가 성인이라고 해서 하고 싶은 대로 다 해도 된다는 뜻은 아니야.","e":"'Que + 절'이 문장 맨 앞에서 주어로 쓰이면(…라는 것은) 보통 접속법을 씁니다. 또 'mayor de edad(성인)'는 신분·성질을 나타내므로 estar가 아니라 ser를 써요. 그래서 'Que seas mayor de edad'가 됩니다. 'lo que te venga en gana'는 '네 마음 내키는 대로'라는 구어 표현입니다.","x":["estés: 'mayor de edad'는 estar와 쓰지 않습니다 ✗","eres: 문두의 que 주어절에서는 보통 직설법을 쓰지 않습니다 ✗","seas: ser + 접속법 현재 → 정답 ✓","estás: estar도 틀리고 직설법도 맞지 않습니다 ✗"]},{"id":"G110","q":"Me conformo ____ aprobar, no necesito una nota alta.","o":["de","para","por","con"],"a":3,"k":"conformarse con","t":"나는 합격만 하면 만족해, 높은 점수는 필요 없어.","e":"conformarse(만족하다, 감수하다)는 전치사 con과 함께 써서 '~으로 만족하다'라는 뜻이 됩니다. 뒤에 명사나 동사원형이 올 수 있어요. 큰 기대 없이 '그 정도로 충분하다'는 뉘앙스가 있습니다. 예: Me conformo con poco.(난 적은 것에 만족해)","x":["de: 'conformarse de'라는 결합은 쓰지 않습니다 ✗","para: '~하기 위해'라는 목적이라 맞지 않습니다 ✗","por: conformarse와 함께 쓰지 않습니다 ✗","con: 'conformarse con(~으로 만족하다)' → 정답 ✓"]},{"id":"G111","q":"El preso del que te hablaba el otro día ____ de la cárcel.","o":["se fugaría","se ha fugado","había fugado","ha fugado"],"a":1,"k":"현재완료 (최근 소식)","t":"내가 저번에 말했던 그 죄수가 감옥에서 탈옥했어.","e":"방금 알게 된 최근 소식이나 현재와 연결된 과거 사건은 스페인에서 주로 현재완료로 전합니다. fugarse(도망치다, 탈옥하다)는 재귀동사라 se가 반드시 필요해서 'se ha fugado'가 돼요. 중남미에서는 이런 경우 단순과거(se fugó)를 더 많이 씁니다.","x":["se fugaría: 조건법이라 실제 일어난 사건 전달에 맞지 않습니다 ✗","se ha fugado: 재귀 se + 현재완료(최근 소식) → 정답 ✓","había fugado: 재귀대명사 se가 빠졌습니다 ✗","ha fugado: 역시 se가 빠져 fugarse의 형태가 되지 않습니다 ✗"]},{"id":"G112","q":"¿____ en la misma empresa?","o":["Vienes trabajando","Sigues trabajando","Llevas trabajando","Vas trabajando"],"a":1,"k":"seguir + 현재분사","t":"아직도 같은 회사에서 일하고 있니?","e":"'seguir + 현재분사'는 '계속 ~하고 있다, 여전히 ~하다'라는 뜻입니다. 'Sigues trabajando en la misma empresa?'는 '여전히 같은 회사에 다니니?'라는 질문이에요. 'llevar + 현재분사'는 '~해 온 지 (기간)째'라서 'Llevas dos años trabajando'처럼 기간이 필요합니다.","x":["Vienes trabajando: 'venir + 현재분사'는 '(오래전부터) ~해 오다'로 보통 desde hace 등 기간과 씁니다 ✗","Sigues trabajando: '여전히 ~하다' → 정답 ✓","Llevas trabajando: 기간 표현(dos años 등)이 없어 불완전합니다 ✗","Vas trabajando: 'ir + 현재분사'는 점진적 진행이라 의미가 맞지 않습니다 ✗"]},{"id":"G113","q":"¿Conocéis a alguien que ____ de fontanería?","o":["sabrá","sepa","sabe","ha sabido"],"a":1,"k":"불특정 선행사+접속법","t":"너희, 배관 일 할 줄 아는 사람 알아?","e":"존재하는지 확실하지 않은 사람·사물을 찾거나 물을 때, 그것을 설명하는 관계절에는 접속법을 씁니다. '¿Conocéis a alguien que sepa...?'는 '그런 사람이 있는지' 묻는 것이므로 sepa(saber의 접속법)가 됩니다. 'saber de + 분야'는 '~에 대해 잘 알다'라는 뜻이에요.","x":["sabrá: 미래형은 관계절의 불특정 대상 설명에 맞지 않습니다 ✗","sepa: 존재가 불확실한 선행사를 설명하는 접속법 → 정답 ✓","sabe: 직설법은 이미 아는 특정한 사람일 때 씁니다 ✗","ha sabido: 현재완료 직설법이라 맞지 않습니다 ✗"]},{"id":"G114","q":"Ojalá nos ____ la beca.","o":["han concedido","conceden","concedan","concederían"],"a":2,"k":"ojalá + 접속법 현재","t":"우리가 장학금을 받으면 좋겠다.","e":"ojalá(~이면 좋겠다) 뒤에는 반드시 접속법이 옵니다. 실현 가능한 미래의 바람이므로 접속법 현재 concedan을 써요. 3인칭 복수는 '(심사위원들이) 장학금을 준다'는 무인칭 용법입니다. 예: Ojalá haga buen tiempo mañana.(내일 날씨가 좋았으면)","x":["han concedido: 직설법이라 ojalá 뒤에 쓰지 않습니다 ✗","conceden: 직설법 현재라 ojalá 뒤에 맞지 않습니다 ✗","concedan: 실현 가능한 바람의 접속법 현재 → 정답 ✓","concederían: 조건법이라 ojalá 뒤에 쓰지 않습니다 ✗"]},{"id":"G115","q":"Si ____ una idea mejor, decídnoslo.","o":["se ocurre","se os ocurre","os ocurra","os ocurre"],"a":1,"k":"ocurrírsele algo a uno","t":"더 좋은 아이디어가 떠오르면 우리에게 말해 줘.","e":"'ocurrírsele algo a alguien'은 '(생각이) 누구에게 떠오르다'라는 구조로, se + 간접목적격 대명사 + 동사 순서로 씁니다. 떠오르는 '생각'이 주어이고, 생각이 떠오르는 사람은 간접목적어예요. decídnoslo(vosotros 명령)에 맞춰 'se os ocurre'가 됩니다. si 뒤이므로 직설법이에요.","x":["se ocurre: 생각이 떠오르는 사람(os)이 빠졌습니다 ✗","se os ocurre: se + 간접목적격 os + 직설법 → 정답 ✓","os ocurra: se가 빠졌고 si 뒤에 접속법 현재도 쓸 수 없습니다 ✗","os ocurre: se가 없으면 '너희에게 (어떤 일이) 일어나다'라는 뜻이 됩니다 ✗"]},{"id":"G116","q":"Porque ____ mayor no eres más fuerte que yo.","o":["seas","eres","serás","serías"],"a":0,"k":"원인 부정 + 접속법","t":"네가 나이가 많다고 해서 나보다 힘이 센 건 아니야.","e":"'Porque + 접속법, no...'는 '~라고 해서 …인 것은 아니다'라는 구조로, 원인 자체를 부정할 때 porque 뒤에 접속법을 씁니다. 'Porque seas mayor no eres más fuerte'는 '나이가 많다는 이유가 힘이 세다는 근거가 되지 않는다'는 뜻이에요. 일반적인 원인(~때문에)을 말할 때는 직설법을 씁니다.","x":["seas: 부정되는 원인을 나타내는 접속법 → 정답 ✓","eres: 직설법이면 '네가 나이가 많아서 안 세다'라는 이상한 뜻이 됩니다 ✗","serás: 미래형이라 원인 부정 구조에 맞지 않습니다 ✗","serías: 조건법이라 맞지 않습니다 ✗"]},{"id":"G117","q":"No tengo ninguna preferencia, ____ mí podemos ver la peli que quieras.","o":["sobre","por","para","según"],"a":1,"k":"por mí (나로서는)","t":"난 특별히 선호하는 건 없어, 나는 네가 원하는 영화를 봐도 괜찮아.","e":"'por mí'는 '나로서는 상관없어, 내 쪽에선 괜찮아'라는 뜻으로, 상대의 결정에 동의를 표할 때 씁니다. 'Por mí, vale.(난 괜찮아)'처럼 짧게도 많이 써요. 'para mí'는 '내 생각에는'이라는 의견 표현이고, 'según'은 뒤에 mí가 아니라 yo가 옵니다(según yo는 구어).","x":["sobre: '~에 관해'라서 이 의미가 되지 않습니다 ✗","por: 'por mí(나로서는 상관없다)' → 정답 ✓","para: 'para mí'는 '내 의견으로는'이라서 허락의 뉘앙스가 없습니다 ✗","según: '~에 따르면'이고 mí와 함께 쓰지 않습니다 ✗"]},{"id":"G118","q":"____, no bebe casi nada, pero come muchísimo.","o":["Beber","Bebiendo","Bebido","Bebe"],"a":0,"k":"동사원형 주제화","t":"마시는 거라면 거의 안 마시는데, 먹기는 엄청 먹는다.","e":"스페인어 구어에서는 동사원형을 문장 앞에 꺼내 '~하는 것으로 말하자면'이라는 주제(화제)를 만든 뒤, 같은 동사를 다시 활용해서 쓰는 강조 구문이 있습니다. 'Beber, no bebe casi nada'는 '마시는 건 거의 안 마셔'라는 뜻이고, 뒤의 'pero come muchísimo'와 대조를 이뤄요. 예: Saber, sabe mucho.(알기는 많이 알아)","x":["Beber: 화제를 제시하는 동사원형 → 정답 ✓","Bebiendo: 현재분사는 이런 주제화 구문에 쓰지 않습니다 ✗","Bebido: 과거분사는 '마신(취한)'이라는 형용사가 되어 맞지 않습니다 ✗","Bebe: 활용형을 반복하면 이 강조 구문이 되지 않습니다 ✗"]},{"id":"G119","q":"Hay gente ____ no piensa antes de hablar.","o":["que","la que","cual","quien"],"a":0,"k":"관계대명사 que","t":"말하기 전에 생각하지 않는 사람들이 있다.","e":"선행사(gente) 바로 뒤에서 관계절의 주어 역할을 할 때는 기본 관계대명사 que를 씁니다. quien은 쉼표가 있는 설명절이나 전치사 뒤에서 주로 쓰고, 이렇게 한정하는 관계절의 주어로는 거의 쓰지 않아요. la que는 선행사 없이 '~하는 사람/것'이라는 뜻일 때 씁니다.","x":["que: 한정 관계절 주어의 기본 관계대명사 → 정답 ✓","la que: 선행사 gente가 이미 있어 관사를 쓰지 않습니다 ✗","cual: 'el/la cual'처럼 관사가 필요하고 한정절 주어로 쓰지 않습니다 ✗","quien: 쉼표 없는 한정 관계절의 주어로는 쓰지 않습니다 ✗"]},{"id":"G120","q":"____ lo que soy es gracias a mis padres.","o":["Todo","Toda","Todos","Todas"],"a":0,"k":"todo lo que (중성)","t":"지금의 나는 모두 부모님 덕분이다.","e":"'todo lo que'는 '~하는 모든 것'이라는 중성 표현으로, 특정 명사가 아니라 추상적인 '것'을 가리킵니다. 'Todo lo que soy'는 '내가 (지금) 이루고 있는 모든 것', 즉 '지금의 나 자체'라는 뜻이에요. 중성 lo와 함께 쓰므로 todo는 항상 남성 단수형입니다. 'gracias a'는 '~ 덕분에'입니다.","x":["Todo: 중성 lo와 함께 쓰는 todo → 정답 ✓","Toda: 여성형은 중성 lo와 함께 쓰지 않습니다 ✗","Todos: 복수형은 lo와 맞지 않습니다(todos los que라면 '~하는 모든 사람들') ✗","Todas: 여성 복수형이라 lo와 맞지 않습니다 ✗"]},{"id":"G121","q":"Isabel es un encanto ____ persona.","o":["de","por","para","a"],"a":0,"k":"un encanto de persona","t":"이사벨은 정말 매력적인 사람이다.","e":"'un/una + 평가 명사 + de + 명사'는 '정말 ~한 사람/것'이라는 강조 표현입니다. 'un encanto de persona'는 '매력 덩어리 같은 사람', 즉 '아주 상냥하고 매력적인 사람'이라는 뜻이에요. 같은 구조: un desastre de hombre(엉망인 남자), una maravilla de niño(멋진 아이).","x":["de: '평가 명사 + de + 명사' 강조 구조 → 정답 ✓","por: 이 구조에 쓰지 않습니다 ✗","para: '사람을 위한 매력'이라는 어색한 뜻이 됩니다 ✗","a: 이 구조에 쓰지 않습니다 ✗"]},{"id":"G122","q":"____ periodismo deportivo es mi especialidad.","o":["Un","Del","ø","El"],"a":3,"k":"주어 명사 + 정관사","t":"스포츠 저널리즘이 나의 전문 분야다.","e":"스페인어에서 문장 앞의 주어 자리에 오는 추상 명사·분야 이름은 보통 정관사를 붙입니다. 'El periodismo deportivo es...'처럼요. 한국어나 영어(Sports journalism is...)와 달리 관사를 생략하지 않는다는 점이 중요합니다. 예: El fútbol es mi pasión.(축구는 나의 열정이다)","x":["Un: 부정관사는 '어떤 하나의 저널리즘'이 되어 분야 전체를 가리키지 못합니다 ✗","Del: de + el이라 주어 자리에 올 수 없습니다 ✗","ø: 주어 자리의 추상 명사는 관사 없이 쓰지 않습니다 ✗","El: 분야 전체를 가리키는 정관사 → 정답 ✓"]},{"id":"G123","q":"Niños, ____ buenos con vuestros compañeros.","o":["sea","sean","seáis","sed"],"a":3,"k":"vosotros 긍정명령","t":"얘들아, 친구들한테 착하게 굴어라.","e":"vosotros 긍정명령은 동사원형의 끝 -r을 -d로 바꿔 만듭니다: ser → sed, comer → comed, hablar → hablad. 'vuestros compañeros'를 보아 vosotros에게 하는 말이에요. seáis는 부정명령(no seáis)에 씁니다. 중남미에서는 vosotros 대신 ustedes를 써서 'sean buenos'라고 합니다.","x":["sea: usted 명령이라 vosotros(vuestros)와 맞지 않습니다 ✗","sean: ustedes 명령으로 중남미에선 쓰지만, vuestros가 있어 vosotros 형태가 맞습니다 ✗","seáis: 접속법으로 부정명령(no seáis)에만 씁니다 ✗","sed: ser의 vosotros 긍정명령 → 정답 ✓"]},{"id":"G124","q":"____ sabía contar historias, nunca escribió nada.","o":["Incluso","Como","Pese a","Aunque"],"a":3,"k":"aunque + 직설법","t":"그는 이야기를 할 줄 알았지만 결코 아무것도 쓰지 않았다.","e":"aunque(~이지만) 뒤에 실제 사실이 오면 직설법을 씁니다(sabía). '이야기를 잘했다'는 것은 사실이고, 그럼에도 글을 쓰지 않았다는 대조를 나타내요. 'pese a'는 뒤에 que나 명사·동사원형이 필요하고, como는 문두에서 '~이므로'라는 원인이 됩니다.","x":["Incluso: '심지어'라는 부사라 절을 이끌 수 없습니다 ✗","Como: 문두의 como는 '~이므로'라는 원인이라 논리가 맞지 않습니다 ✗","Pese a: 'pese a que'처럼 que가 있어야 활용 동사가 올 수 있습니다 ✗","Aunque: 사실을 나타내는 양보 + 직설법 → 정답 ✓"]},{"id":"G125","q":"Mi padre es ____ complexión ancha.","o":["de","con","a","sobre"],"a":0,"k":"ser de + 특징","t":"우리 아버지는 체격이 큰(다부진) 편이다.","e":"'ser de + 명사(+형용사)'는 사람이나 사물의 특징·성질을 나타냅니다. 'ser de complexión ancha'는 '체격이 다부지다', 'ser de estatura media'는 '중간 키다'처럼 써요. complexión은 '체격, 몸집'이라는 뜻입니다.","x":["de: 특징을 나타내는 'ser de' → 정답 ✓","con: 'ser con'은 이런 특징을 나타내지 않습니다('tener una complexión'은 가능) ✗","a: 이 구조에 쓰지 않습니다 ✗","sobre: '~위에'라서 의미가 맞지 않습니다 ✗"]},{"id":"G126","q":"____ pendientes de este barrio me cansan muchísimo.","o":["Las","Con las","Los","Con los"],"a":0,"k":"la pendiente vs el pendiente","t":"이 동네의 언덕길(비탈길)은 나를 무척 지치게 한다.","e":"pendiente는 성(性)에 따라 뜻이 달라지는 명사입니다. 'la pendiente'는 '비탈, 경사', 'el pendiente'는 '귀걸이'(스페인)예요. '동네의 ~가 나를 지치게 한다'는 문맥상 '비탈길'이 맞으므로 여성 관사 las를 씁니다. 동사 cansar의 주어이므로 전치사 con은 필요 없어요. 중남미에서 귀걸이는 보통 aretes라고 합니다.","x":["Las: 'las pendientes(비탈길들)'로 cansan의 주어 → 정답 ✓","Con las: 전치사가 붙으면 cansan의 주어가 없어집니다 ✗","Los: 'los pendientes'는 '귀걸이'라 문맥에 맞지 않습니다 ✗","Con los: 주어가 없어지고 뜻도 '귀걸이'가 됩니다 ✗"]},{"id":"G127","q":"Lorena ____ muy despierta para la edad que tiene.","o":["se parece","está","muestra","es"],"a":3,"k":"ser despierto vs estar","t":"로레나는 나이에 비해 아주 영리하다.","e":"despierto는 ser와 estar에 따라 뜻이 달라집니다. 'ser despierto'는 '영리하다, 눈치가 빠르다'(성격·자질), 'estar despierto'는 '깨어 있다'(상태)예요. 'para la edad que tiene(나이에 비해)'라는 말이 자질을 평가하고 있으므로 es가 맞습니다.","x":["se parece: '닮다'라는 뜻이라 형용사만으로는 맞지 않습니다 ✗","está: 'estar despierta'는 '깨어 있다'라서 나이와 관계없습니다 ✗","muestra: '보여 주다'는 목적어 명사가 필요해 형용사와 맞지 않습니다 ✗","es: 'ser despierto(영리하다)' → 정답 ✓"]},{"id":"G128","q":"¿Dónde ____ la boda de tu amiga?","o":["se halló","estuvo","fue","se encontró"],"a":2,"k":"ser (행사의 장소)","t":"네 친구의 결혼식은 어디서 했어?","e":"결혼식·파티·회의처럼 '일어나는 행사'의 장소를 말할 때는 estar가 아니라 ser를 씁니다. '¿Dónde fue la boda?'는 '결혼식이 어디서 열렸어?'라는 뜻이에요. 과거에 한 번 열린 행사이므로 단순과거 fue입니다. 사물·사람의 위치에는 estar를 씁니다(¿Dónde está el libro?).","x":["se halló: hallarse는 '위치하다(격식)'로 행사의 개최에는 쓰지 않습니다 ✗","estuvo: estar는 행사의 개최 장소에 쓰지 않습니다 ✗","fue: 행사의 장소를 나타내는 ser의 단순과거 → 정답 ✓","se encontró: '위치했다/발견되었다'라서 행사 개최와 맞지 않습니다 ✗"]},{"id":"G129","q":"¡____ piso! Es enorme.","o":["Vaya con","Dale","Vaya","Toma"],"a":2,"k":"감탄 ¡Vaya + 명사!","t":"집 진짜 크다! 엄청 넓어.","e":"'¡Vaya + 명사!'는 '대단한 ~이네!, 이게 웬 ~야!'라는 감탄 표현으로, 좋은 뜻과 나쁜 뜻 모두 씁니다(¡Vaya día!: 무슨 이런 날이!). 'Vaya con...'은 '~ 참 대단하네(못마땅함)'처럼 쓰이지만 명사 앞 감탄으로는 vaya 단독이 기본이에요. piso는 스페인에서 '아파트(한 세대)'를 뜻하고, 중남미에서는 '층/바닥'을 의미하는 경우가 많습니다.","x":["Vaya con: 주로 사람·행동에 대한 놀람·비꼼에 쓰여 여기서는 부자연스럽습니다 ✗","Dale: '어서 해/좋아'(특히 중남미)라는 뜻이라 감탄문이 되지 않습니다 ✗","Vaya: '¡Vaya + 명사!' 감탄 → 정답 ✓","Toma: '받아/옜다'라는 뜻이라 명사 감탄에 쓰지 않습니다 ✗"]},{"id":"G130","q":"No se escuchaba nada ____ ruido que había en la sala.","o":["para tanto","desde tanto","de tanto","a tanto"],"a":2,"k":"de tanto + 명사 (원인)","t":"홀 안이 너무 시끄러워서 아무것도 들리지 않았다.","e":"'de tanto/tanta + 명사'는 '너무 많은 ~ 때문에'라는 원인을 나타냅니다. 'de tanto ruido que había'는 '그렇게나 소음이 많아서'라는 뜻이에요. tanto는 뒤의 명사(ruido, 남성 단수)에 맞춥니다. 동사가 오면 'de tanto gritar(하도 소리 질러서)'가 됩니다.","x":["para tanto: 'no es para tanto(그렇게까지는 아니다)'처럼 쓰는 다른 표현입니다 ✗","desde tanto: 원인을 나타내지 않습니다 ✗","de tanto: '너무 많은 ~ 때문에'라는 원인 → 정답 ✓","a tanto: 원인을 나타내지 않습니다 ✗"]},{"id":"G131","q":"Vivo ____ de la estación de autobuses.","o":["lejísimos","de lejos","lejísimas","lejísima"],"a":0,"k":"부사 최상급 -ísimo","t":"나는 버스 터미널에서 아주 멀리 산다.","e":"형용사뿐 아니라 일부 부사에도 -ísimo를 붙여 '아주 ~하게'라는 절대최상급을 만들 수 있습니다. lejos(멀리) → lejísimos, cerca(가까이) → cerquísima예요. 부사는 성·수 변화가 없으므로 원형 끝소리를 따라 lejísimos(‑s 유지)로 고정됩니다. 'de lejos'는 '멀리서'라는 다른 뜻입니다.","x":["lejísimos: lejos의 절대최상급 부사 → 정답 ✓","de lejos: '멀리서(보면)'라는 뜻이라 사는 위치를 나타내지 못합니다 ✗","lejísimas: 부사는 여성형이 없어 틀린 형태입니다 ✗","lejísima: 역시 존재하지 않는 형태입니다 ✗"]},{"id":"G132","q":"No sé ____ me pasa, pero no me acuerdo de nada.","o":["por que","lo qué","que","qué"],"a":3,"k":"간접의문문 qué","t":"나한테 무슨 일이 있는지 모르겠지만 아무것도 기억이 안 나.","e":"saber, preguntar 같은 동사 뒤에 의문의 의미를 담은 절(간접의문문)이 올 때도 의문사에 악센트를 찍습니다. 'No sé qué me pasa'는 '나한테 뭐가 문제인지 모르겠다'는 뜻이에요. que(악센트 없음)는 접속사·관계사이고, 'lo que'는 관사와 함께 쓰므로 악센트를 찍지 않습니다(lo qué는 틀림).","x":["por que: '~하는 이유(로)'라는 관계 표현이라 의미가 맞지 않습니다 ✗","lo qué: lo que에는 악센트를 찍지 않으므로 틀린 형태입니다 ✗","que: 악센트가 없으면 의문사가 아니라 접속사가 되어 문장이 성립하지 않습니다 ✗","qué: 간접의문문의 의문사(악센트 필수) → 정답 ✓"]},{"id":"G133","q":"El tiempo ____ sin que nos demos cuenta.","o":["pasa","lo pasa","se lo pasa","se pasa"],"a":0,"k":"pasar (시간이 흐르다)","t":"시간은 우리도 모르는 사이에 흘러간다.","e":"'el tiempo pasa'는 '시간이 흐르다'라는 기본 표현으로, 재귀형 없이 씁니다. 'pasárselo bien/mal'은 '즐겁게/힘들게 시간을 보내다'(스페인 구어)라는 다른 표현이에요. 'sin que + 접속법'은 '~하지 않은 채로, ~도 모르게'라는 뜻입니다. 'pasarse'는 '지나치다, 도를 넘다'라는 뜻이 됩니다.","x":["pasa: '(시간이) 흐르다'의 기본형 → 정답 ✓","lo pasa: 목적어 lo가 들어가 '그것을 넘기다'라는 이상한 뜻이 됩니다 ✗","se lo pasa: 'pasárselo bien(즐겁게 보내다)'에서 온 형태로 bien 등이 필요합니다 ✗","se pasa: 'pasarse'는 '도를 넘다, 지나치다'라는 뜻이 됩니다 ✗"]},{"id":"G134","q":"Me gustaría que ____ más en mí.","o":["confiases","confiarías","confíes","confías"],"a":0,"k":"조건법 주절 + 접속법 과거","t":"네가 나를 좀 더 믿어 줬으면 좋겠어.","e":"'Me gustaría que ~'는 바람을 나타내는 표현이라 que절에 접속법을 씁니다. 주절이 조건법(gustaría)이면 que절은 접속법 과거(confiases/confiaras)가 되는 것이 시제 일치 규칙이에요. 현재형 'Me gusta que...' 뒤라면 접속법 현재(confíes)를 씁니다. 'confiar en'은 '~을 믿다, 신뢰하다'입니다.","x":["confiases: 조건법 주절에 맞춘 접속법 과거 → 정답 ✓","confiarías: 조건법은 que절에 쓰지 않습니다 ✗","confíes: 접속법 현재는 주절이 현재(me gusta)일 때 씁니다 ✗","confías: 직설법이라 바람 표현 뒤에 쓰지 않습니다 ✗"]},{"id":"G135","q":"____ fallecer su esposa, cayó en una profunda depresión.","o":["Desde","Después de","De","Con"],"a":1,"k":"después de + 동사원형","t":"아내가 세상을 떠난 뒤, 그는 깊은 우울증에 빠졌다.","e":"'después de + 동사원형'은 '~한 후에'라는 뜻입니다. 동사원형 뒤에 주어(su esposa)가 올 수도 있어요: 'Después de fallecer su esposa(그의 아내가 사망한 후)'. 'al + 동사원형(~했을 때)'도 이 문맥에 쓸 수 있습니다. 'caer en una depresión'은 '우울증에 빠지다'라는 표현입니다.","x":["Desde: '~부터'는 'desde que falleció'처럼 활용 동사가 필요합니다 ✗","Después de: '~한 후에' + 동사원형 → 정답 ✓","De: 'de + 동사원형'은 '만약 ~라면'이라는 조건이 되어 의미가 맞지 않습니다 ✗","Con: 'con + 동사원형'은 '~하기만 하면'이라는 뜻이 되어 맞지 않습니다 ✗"]},{"id":"G136","q":"No veo mi boli por ninguna parte. ¿Dónde lo ____?","o":["haya puesto","hubiese puesto","habré puesto","habría puesto"],"a":2,"k":"미래완료 (과거 추측)","t":"내 볼펜이 어디에도 안 보이네. 내가 그걸 어디에 뒀더라?","e":"미래완료(habré + 과거분사)는 '방금 전·조금 전에 일어난 일'에 대한 추측을 나타냅니다. '¿Dónde lo habré puesto?'는 '내가 그걸 어디 뒀을까?'라는 혼잣말 같은 추측이에요. 현재와 가까운 과거의 추측은 미래완료, 먼 과거 특정 시점의 추측은 조건법(완료)을 씁니다.","x":["haya puesto: 접속법이라 독립된 의문문에 쓰지 않습니다 ✗","hubiese puesto: 접속법 과거완료라 의문문에 쓰지 않습니다 ✗","habré puesto: 최근 과거에 대한 추측의 미래완료 → 정답 ✓","habría puesto: 조건법 완료는 더 먼 과거나 가정에 쓰여 이 문맥에는 덜 자연스럽습니다 ✗"]},{"id":"G137","q":"¿____ en un globo aerostático alguna vez?","o":["Te has montado","Te montabas","Te montas","Te estuviste montando"],"a":0,"k":"현재완료 (경험)","t":"열기구를 타 본 적 있어?","e":"'alguna vez(한 번이라도)'와 함께 지금까지의 경험을 물을 때는 현재완료를 씁니다. '¿Te has montado alguna vez en...?'은 '~를 타 본 적 있어?'라는 뜻이에요. montarse en은 '(탈것에) 올라타다'입니다. 중남미에서는 '¿Alguna vez te subiste a un globo?'처럼 단순과거를 쓰는 경우도 많습니다.","x":["Te has montado: 경험을 묻는 현재완료 → 정답 ✓","Te montabas: 불완료과거는 과거 습관이라 경험 질문에 맞지 않습니다 ✗","Te montas: 현재형이라 경험을 나타내지 못합니다 ✗","Te estuviste montando: 단순과거 진행형으로 경험 질문에 쓰지 않습니다 ✗"]},{"id":"G138","q":"Explíquenos ____ vio exactamente al acusado.","o":["dónde","donde","adónde","adonde"],"a":0,"k":"간접의문 dónde","t":"피고인을 정확히 어디서 보았는지 저희에게 설명해 주세요.","e":"explicar, decir, saber 같은 동사 뒤의 간접의문문에서도 의문사에는 악센트를 찍습니다. 여기서는 '어디에서(장소)' 보았는지 묻는 것이므로 dónde가 맞아요. adónde는 '어디로'라는 방향으로 ir, venir 같은 이동 동사와 씁니다. Explíquenos는 usted 명령 + nos(우리에게)입니다.","x":["dónde: '어디서'라는 간접의문(악센트 필수) → 정답 ✓","donde: 악센트가 없으면 관계부사라서 간접의문문이 되지 않습니다 ✗","adónde: '어디로'라는 방향이라 ver(보다)와 맞지 않습니다 ✗","adonde: 관계부사 '~로'라서 의문의 뜻도 방향도 맞지 않습니다 ✗"]},{"id":"G139","q":"Quiero que ____ que tienes mi apoyo incondicional.","o":["supiste","sabes","sabrías","sepas"],"a":3,"k":"querer que + 접속법","t":"내가 너를 무조건 지지한다는 걸 알아 줬으면 해.","e":"querer(원하다) 뒤에 주어가 다른 que절이 오면 접속법을 씁니다. 주절이 현재(Quiero)이므로 접속법 현재 sepas(saber의 불규칙 접속법)가 돼요. 'Quiero que sepas que...'는 진심을 전할 때 아주 자주 쓰는 표현입니다.","x":["supiste: 직설법 과거라 바람 표현 뒤에 쓰지 않습니다 ✗","sabes: 직설법 현재라 querer que 뒤에 맞지 않습니다 ✗","sabrías: 조건법이라 querer que 뒤에 쓰지 않습니다 ✗","sepas: 바람 표현 뒤의 접속법 현재 → 정답 ✓"]},{"id":"G140","q":"Quise decirte la verdad, pero no ____.","o":["me atrevía","había atrevido","atrevería","me atreviera"],"a":0,"k":"불완료과거 (심리 상태)","t":"너에게 진실을 말하고 싶었지만 용기가 나지 않았다.","e":"불완료과거는 과거의 심리 상태나 배경을 묘사할 때 씁니다. 'no me atrevía'는 '(그 당시) 용기가 나지 않는 상태였다'는 뜻으로 머뭇거리던 마음을 그려요. 'no me atreví'(단순과거)도 가능하지만 보기에 없고, 나머지는 문법적으로 틀립니다. atreverse는 재귀동사라 me가 꼭 필요합니다.","x":["me atrevía: 과거의 심리 상태를 묘사하는 불완료과거 → 정답 ✓","había atrevido: 재귀대명사 me가 빠졌고 대과거도 맞지 않습니다 ✗","atrevería: me가 빠졌고 조건법이라 맞지 않습니다 ✗","me atreviera: 접속법이라 평서문 주절에 쓰지 않습니다 ✗"]},{"id":"G141","q":"Hazme un favor, ____ esta carne en el congelador.","o":["pon","ponla","ponga","poned"],"a":0,"k":"tú 긍정명령 pon","t":"부탁 하나만 들어줘, 이 고기 냉동실에 좀 넣어 줘.","e":"poner의 tú 긍정명령은 불규칙형 pon입니다(hacer → haz, decir → di, salir → sal도 마찬가지). 'Hazme un favor'에서 tú로 말하고 있으므로 pon이 맞아요. 목적어 'esta carne'가 이미 있으니 대명사 la를 붙이면 중복됩니다.","x":["pon: poner의 tú 불규칙 긍정명령 → 정답 ✓","ponla: 목적어 esta carne가 이미 있어 la가 중복됩니다 ✗","ponga: usted 명령이라 tú로 말하는 문장(Hazme)과 맞지 않습니다 ✗","poned: vosotros 명령이라 단수 tú와 맞지 않습니다 ✗"]},{"id":"G142","q":"¡____ de gente hay aquí hoy!","o":["Cuánta","Cómo","Qué","Cuánto"],"a":2,"k":"감탄 ¡Qué de + 명사!","t":"오늘 여기 사람 정말 많다!","e":"'¡Qué de + 명사!'는 '정말 많은 ~!'이라는 구어 감탄 표현입니다. '¡Qué de gente!'는 '사람이 얼마나 많은지!'라는 뜻이에요. 같은 의미로 '¡Cuánta gente!'라고도 하지만, 이때는 de 없이 바로 명사를 씁니다. 예: ¡Qué de cosas tienes!(물건이 정말 많네!)","x":["Cuánta: '¡Cuánta gente!'처럼 de 없이 써야 해서 틀립니다 ✗","Cómo: 'cómo de'는 정도를 묻는 표현이라 이 감탄문에 맞지 않습니다 ✗","Qué: '¡Qué de + 명사!(정말 많은 ~!)' → 정답 ✓","Cuánto: de도 맞지 않고 남성형이라 gente와도 일치하지 않습니다 ✗"]},{"id":"G143","q":"Estoy harto de este auto. No pasa ni un día ____ me dé algún problema.","o":["en que","desde que","para que","sin que"],"a":3,"k":"sin que + 접속법","t":"이 차 정말 지긋지긋해. 하루도 말썽 안 부리는 날이 없어.","e":"'No pasa ni un día sin que + 접속법'은 '~하지 않고 지나가는 날이 하루도 없다', 즉 '매일 ~한다'는 이중 부정 강조 표현입니다. sin que 뒤에는 항상 접속법을 써요(dé). auto는 중남미에서 '자동차'를 뜻하는 말로, 스페인에서는 주로 coche라고 합니다.","x":["en que: 'un día en que...'는 가능하지만 'no pasa ni un día'와 이어지면 의미가 통하지 않습니다 ✗","desde que: '~한 이후로'라서 맞지 않습니다 ✗","para que: '~하도록'이라는 목적이라 의미가 맞지 않습니다 ✗","sin que: '~하지 않고는 (하루도 안 지나간다)' → 정답 ✓"]},{"id":"G144","q":"Hay mucho ____ original en esta pintura.","o":["a","de","hacia","sobre"],"a":1,"k":"mucho de + 형용사","t":"이 그림에는 독창적인 면이 많다.","e":"'mucho/algo/nada/poco + de + 형용사'는 '~한 점(요소)이 많다/조금 있다/전혀 없다'라는 표현입니다. 'Hay mucho de original'은 '독창적인 부분이 많다'는 뜻이에요. 형용사는 남성 단수 형태로 고정되어 중성적 의미(~한 것)를 나타냅니다. 예: No tiene nada de raro.(전혀 이상할 게 없다)","x":["a: 이 구조에 쓰지 않습니다 ✗","de: 'mucho de + 형용사(~한 점이 많다)' → 정답 ✓","hacia: '~쪽으로'라는 방향이라 맞지 않습니다 ✗","sobre: '~에 관해'라서 이 구조에 쓰지 않습니다 ✗"]},{"id":"G145","q":"¿Qué piensa usted ____ Picasso cubista?","o":["por el","al","del","de"],"a":2,"k":"pensar de + 정관사","t":"입체파 시기의 피카소에 대해 어떻게 생각하세요?","e":"'¿Qué piensas de...?'는 '~에 대해 어떻게 생각해?'라는 의견을 묻는 표현입니다. 고유명사는 보통 관사 없이 쓰지만, 형용사(cubista)가 붙어 '특정 시기·면모의 피카소'를 가리키면 정관사가 붙어요: el Picasso cubista. 그래서 de + el = del이 됩니다.","x":["por el: 'pensar por'는 '~ 대신 생각하다'라서 의견을 묻는 뜻이 아닙니다 ✗","al: 'pensar a'라는 결합은 쓰지 않습니다 ✗","del: de + el(형용사가 붙은 고유명사의 정관사) → 정답 ✓","de: 'el Picasso cubista'에 필요한 정관사가 빠졌습니다 ✗"]},{"id":"G146","q":"Cuando ____ de la oficina, ya no había nadie en el edificio.","o":["me fuese","me iría","iba","me fui"],"a":3,"k":"단순과거 vs 불완료","t":"내가 사무실을 나섰을 때는 건물에 이미 아무도 없었다.","e":"과거의 특정 순간에 일어난 '완결된 행동'(사무실을 나섰다)은 단순과거 me fui로, 그때의 배경 상태(아무도 없었다)는 불완료과거 había로 씁니다. irse(떠나다)는 재귀형으로 '자리를 떠나다'의 의미를 분명히 해요. 접속법이나 조건법은 과거 사실을 나타내는 cuando절에 쓰지 않습니다.","x":["me fuese: 접속법이라 과거 사실의 cuando절에 쓰지 않습니다 ✗","me iría: 조건법은 cuando 뒤에 쓰지 않습니다 ✗","iba: '가는 중이었다'는 배경이 되고 재귀형도 아니라 '떠난' 순간이 표현되지 않습니다 ✗","me fui: 완결된 행동을 나타내는 단순과거 → 정답 ✓"]},{"id":"G147","q":"¿Qué le hace pensar que estamos hablando ____ usted?","o":["hasta","ante","de","por"],"a":2,"k":"hablar de","t":"왜 저희가 당신에 대해 이야기하고 있다고 생각하시나요?","e":"'hablar de + 대상'은 '~에 대해 이야기하다'라는 기본 결합입니다. 'hablar sobre'도 같은 뜻이에요. 'hablar por'는 '~을 대신해 말하다'(hablar por teléfono는 '전화로 말하다'), 'hablar ante'는 '~ 앞에서 연설하다'라는 다른 뜻입니다.","x":["hasta: '~까지'라서 의미가 맞지 않습니다 ✗","ante: '~ 앞에서 말하다'라는 뜻이 되어 문맥과 맞지 않습니다 ✗","de: 'hablar de(~에 대해 이야기하다)' → 정답 ✓","por: '~ 대신 말하다'라는 뜻이 되어 맞지 않습니다 ✗"]},{"id":"G148","q":"No ____ todavía, quédense un ratito más.","o":["se vayan","vayan","van","idos"],"a":0,"k":"ustedes 부정명령","t":"아직 가지 마세요, 조금만 더 있다 가세요.","e":"'quédense(머무르세요)'를 보면 ustedes에게 말하고 있습니다. ustedes 부정명령은 'no + 접속법 3인칭 복수'이고, 재귀동사 irse(떠나다)의 대명사 se는 부정명령에서 동사 앞에 옵니다: no se vayan. 'idos'는 vosotros 긍정명령(스페인)이에요.","x":["se vayan: ustedes 부정명령 + 재귀 se → 정답 ✓","vayan: se가 빠지면 '떠나다'가 아니라 단순히 '가다'가 됩니다 ✗","van: 직설법이라 명령이 되지 않습니다 ✗","idos: vosotros 긍정명령이라 no와 쓸 수 없고 ustedes와도 맞지 않습니다 ✗"]},{"id":"G149","q":"Ese hombre afirma ____ el verdadero padre de la famosa cantante.","o":["que sea","de ser","ser","que ser"],"a":2,"k":"afirmar + 동사원형","t":"그 남자는 자신이 그 유명 가수의 진짜 아버지라고 주장한다.","e":"afirmar, decir, creer 같은 동사는 주절과 종속절의 주어가 같을 때 'que + 활용 동사' 대신 동사원형을 바로 쓸 수 있습니다. 'afirma ser el padre'는 'afirma que es el padre'와 같은 뜻이에요. 이 용법은 신문 기사 같은 격식체에서 특히 많이 쓰입니다. afirmar는 단언하는 동사라 que절이라면 직설법(que es)이 와야 해요.","x":["que sea: afirmar는 단언이라 que절에 접속법을 쓰지 않습니다 ✗","de ser: afirmar 뒤에는 전치사 de가 오지 않습니다 ✗","ser: 같은 주어일 때 쓰는 동사원형 → 정답 ✓","que ser: que 뒤에는 동사원형이 아닌 활용 동사가 와야 합니다 ✗"]},{"id":"G150","q":"No hace falta que ____ todo lo que hay en el plato.","o":["comas","comes","te comas","te comes"],"a":2,"k":"no hace falta que+접속법","t":"접시에 있는 걸 다 먹을 필요는 없어.","e":"'No hace falta que + 접속법'은 '~할 필요는 없다'라는 뜻으로, 필요·불필요를 나타내는 표현 뒤에는 접속법을 씁니다. 또 'comerse algo'처럼 재귀형을 쓰면 '(남김없이) 다 먹어 치우다'라는 완결의 의미가 강조돼요. 'todo lo que hay en el plato'와 함께 쓰여 te comas가 가장 자연스럽습니다.","x":["comas: 접속법은 맞지만 '다 먹어 치우다'라는 완결 뉘앙스의 재귀 te가 없습니다 ✗","comes: 직설법이라 'no hace falta que' 뒤에 쓰지 않습니다 ✗","te comas: 재귀형(다 먹다) + 접속법 → 정답 ✓","te comes: 직설법이라 필요 표현 뒤에 맞지 않습니다 ✗"]},{"id":"G151","q":"¿Tiene usted muchos planes ____ el fin de semana?","o":["ante","por","para","entre"],"a":2,"k":"전치사 para (목적·기한)","t":"주말에 계획이 많으세요?","e":"para는 '~을 위한, ~에 할(목적·예정된 시점)'을 나타냅니다. 'planes para el fin de semana'는 '주말을 위한(주말에 할) 계획'이라는 아주 자주 쓰는 표현입니다. 예: Tengo planes para esta noche(오늘 밤에 약속이 있어). usted로 묻고 있어 정중한 말투라는 점도 함께 봐 두세요.","x":["ante: '~앞에서, ~에 직면하여'라는 뜻으로 계획의 대상 시점에는 쓰지 않습니다 ✗","por: 'por el fin de semana'는 '주말쯤에, 주말 무렵에'처럼 막연한 시간을 뜻해 '주말 계획'이라는 의미가 되지 않습니다 ✗","para: 계획이 향하는 목적·시점(주말에 할 것)을 나타냄 → 정답 ✓","entre: '~사이에'라는 뜻으로 문맥에 맞지 않습니다 ✗"]},{"id":"G152","q":"Mis padres nunca se acuestan ____ llegamos todos los hermanos.","o":["antes de que","hasta que","después que","nada más"],"a":1,"k":"hasta que (~할 때까지)","t":"우리 부모님은 우리 형제들이 모두 들어올 때까지 절대 잠자리에 들지 않으신다.","e":"hasta que는 '~할 때까지'로, 어떤 행동이 계속되다가 다른 일이 일어나면 끝나는 경계를 나타냅니다. 부정문 'no se acuestan hasta que...'는 '~하기 전에는 자지 않는다 = ~하고 나서야 잔다'는 뜻이 됩니다. 이 문장은 매번 반복되는 습관이므로 직설법 llegamos를 씁니다(아직 일어나지 않은 미래 일이라면 lleguemos처럼 접속법).","x":["antes de que: '~하기 전에'라는 뜻이며 뒤에 반드시 접속법이 와야 하는데 llegamos는 직설법이고 의미도 반대가 됩니다 ✗","hasta que: '~할 때까지', 습관이므로 직설법과 함께 씀 → 정답 ✓","después que: '~한 후에'는 'nunca se acuestan'(절대 자지 않는다)과 합치면 의미가 어색해집니다 ✗","nada más: 'nada más llegar(도착하자마자)'처럼 동사원형과 쓰는 표현이라 활용된 동사 앞에는 맞지 않습니다 ✗"]},{"id":"G153","q":"La segunda planta de la casa todavía no ____ pintada.","o":["es","ha estado","está","sea"],"a":2,"k":"estar + 과거분사 (결과)","t":"집 2층은 아직 칠해져 있지 않다.","e":"estar + 과거분사는 어떤 행동이 끝난 뒤의 '결과 상태'(~되어 있다)를 나타냅니다. '아직 칠해진 상태가 아니다'라는 현재 상태이므로 está pintada가 맞습니다. 반면 ser + 과거분사는 '~되다'라는 수동태로 행동 자체를 강조합니다(La casa fue pintada por mi padre: 집은 아버지에 의해 칠해졌다).","x":["es: ser 수동태는 행위 과정을 말할 때 쓰며, todavía no와 함께 현재 상태를 말하기엔 부자연스럽습니다 ✗","ha estado: '(지금까지) ~였던 적이 있다'는 경험·기간의 뉘앙스라 '아직 안 칠해졌다'는 현재 상태에 맞지 않습니다 ✗","está: estar + 과거분사로 현재 결과 상태 표현 → 정답 ✓","sea: 접속법으로, 이 문장은 사실을 말하는 평서문이라 쓸 이유가 없습니다 ✗"]},{"id":"G154","q":"____ mío con Eva es indescriptible. Nos entendemos incluso sin hablar.","o":["El","Eso","Lo","Al"],"a":2,"k":"중성 lo + 소유형용사","t":"에바와 나 사이의 그것(관계)은 말로 표현할 수 없다. 우리는 말하지 않아도 서로 통한다.","e":"lo + 소유형용사 강세형(mío, tuyo, suyo…)은 '나의 일, 나와 관련된 것'이라는 추상적인 뜻을 만듭니다. 'lo mío con Eva'는 '에바와 나의 관계/사이'를 은근하게 가리키는 구어 표현으로, 연애나 우정 같은 특별한 관계를 말할 때 자주 씁니다. 예: Lo nuestro se acabó(우리 사이는 끝났어).","x":["El: 남성 정관사로 뒤에 명사가 필요하며 'el mío'는 '내 것(특정 남성 명사)'이 되어 의미가 달라집니다 ✗","Eso: 지시대명사 '그것'으로 'eso mío'라는 조합은 쓰지 않습니다 ✗","Lo: 중성 lo + mío로 '나와 관련된 일·관계'를 뜻함 → 정답 ✓","Al: a + el의 축약형으로 주어 자리에 올 수 없습니다 ✗"]},{"id":"G155","q":"Siempre crees ____ razón, pero a veces te equivocas.","o":["a tener","de tener","tener","teniendo"],"a":2,"k":"creer + 동사원형","t":"너는 항상 네가 옳다고 생각하지만, 가끔은 틀린다.","e":"creer(믿다, 생각하다) 뒤에서 주어가 같으면 전치사 없이 바로 동사원형을 씁니다. 'crees tener razón'은 'crees que tienes razón(네가 옳다고 생각한다)'과 같은 뜻으로, 좀 더 격식 있고 간결한 형태입니다. tener razón은 '옳다, 맞다'라는 관용 표현입니다.","x":["a tener: creer 뒤에 전치사 a를 넣지 않습니다 ✗","de tener: 'creer de'는 틀린 형태(dequeísmo와 비슷한 오류)입니다 ✗","tener: 주어가 같을 때 creer + 동사원형 → 정답 ✓","teniendo: 현재분사는 creer의 목적어 역할을 할 수 없습니다 ✗"]},{"id":"G156","q":"____ no sos de acá, ¿cierto?","o":["Tú","Vosotros","Usted","Vos"],"a":3,"k":"voseo (vos)","t":"너는 여기 출신이 아니지, 그렇지?","e":"sos는 ser의 voseo(아르헨티나·우루과이·중미 등에서 tú 대신 vos를 쓰는 말투) 형태입니다. tú eres에 해당하는 것이 vos sos이므로 주어는 Vos가 맞습니다. 'de acá(여기)'도 중남미에서 aquí 대신 많이 쓰는 표현이라 지역색이 일치합니다.","x":["Tú: tú의 ser 현재형은 eres이므로 sos와 맞지 않습니다 ✗","Vosotros: 스페인의 2인칭 복수로 동사는 sois가 됩니다 ✗","Usted: 존칭 3인칭 형태로 동사는 es가 됩니다 ✗","Vos: 중남미 voseo의 주어, vos sos → 정답 ✓"]},{"id":"G157","q":"No faltó nadie. ____ mi abuelo estuvo en mi fiesta de cumpleaños.","o":["Hasta","Tanto","Desde","Hacia"],"a":0,"k":"hasta (~까지도, 심지어)","t":"아무도 빠지지 않았다. 할아버지까지도 내 생일 파티에 오셨다.","e":"hasta는 '~까지'라는 범위 외에, 문장 앞에서 '심지어 ~조차도(incluso)'라는 강조의 뜻으로 쓰입니다. '아무도 빠지지 않았다'는 앞 문장과 연결하여 '오기 힘든 할아버지까지도 왔다'는 놀라움을 표현합니다. 예: Hasta los niños lo entienden(아이들조차 그걸 이해한다).","x":["Hasta: '심지어 ~까지도'라는 강조 부사 → 정답 ✓","Tanto: 'tanto... como...' 구조로 쓰며 단독으로는 '심지어'의 뜻이 없습니다 ✗","Desde: '~부터'라는 출발점을 나타내 문맥에 맞지 않습니다 ✗","Hacia: '~쪽으로'라는 방향을 나타냅니다 ✗"]},{"id":"G158","q":"Aquello fue ____ me hizo renunciar a mi puesto.","o":["el que","el cual","lo que","al que"],"a":2,"k":"중성 관계사 lo que","t":"그것이 내가 직장을 그만두게 만든 원인이었다.","e":"aquello(그것, 그 일)는 특정 명사가 아닌 막연한 '일·사건'을 가리키는 중성 지시대명사입니다. 이렇게 앞선 내용이 중성일 때는 '~하는 것'이라는 뜻의 중성 관계사 lo que를 씁니다. 'Aquello fue lo que…'는 '그것이 바로 ~한 것이었다'로 원인을 강조하는 구조입니다.","x":["el que: 남성 단수 명사를 가리킬 때 쓰며 중성 aquello와 맞지 않습니다 ✗","el cual: 앞에 남성 명사 선행사가 있어야 하고 ser 뒤 강조 구문에는 쓰지 않습니다 ✗","lo que: 중성 '~한 것', aquello와 일치 → 정답 ✓","al que: a + el que로 '~에게/~을'이라는 전치사가 필요한 경우에 씁니다 ✗"]},{"id":"G159","q":"____ me interesa lo que tienes que decir.","o":["Si","Claro","Natural","Sí"],"a":3,"k":"sí (강조 부사)","t":"나는 네가 하려는 말에 정말 관심이 있어.","e":"악센트가 있는 sí는 '예'라는 대답 외에 동사 앞에서 '정말로, 분명히'라는 긍정 강조로 쓰입니다. 상대가 '관심 없지?'라고 의심할 때 'Sí me interesa'라고 하면 '아니, 진짜 관심 있어'라는 뉘앙스가 됩니다. 악센트 없는 si는 '만약 ~라면'이라는 조건 접속사이니 꼭 구별하세요.","x":["Si: 악센트가 없으면 '만약 ~라면'이라는 조건 접속사로, 뒤에 주절이 없어 문장이 완성되지 않습니다 ✗","Claro: '물론'이라는 뜻이지만 보통 'Claro que me interesa'처럼 que가 필요합니다 ✗","Natural: '당연한'이라는 형용사로 이 위치에 단독으로 오지 않습니다 ✗","Sí: 동사 앞의 긍정 강조 부사 '정말로' → 정답 ✓"]},{"id":"G160","q":"____ estando casados, hacen vidas separadas.","o":["Ni siquiera","Aunque","Aun","Pese a"],"a":2,"k":"aun + 현재분사 (양보)","t":"결혼한 상태인데도 그들은 각자 따로 살아간다.","e":"aun(악센트 없음)은 '~조차, ~인데도(incluso)'라는 뜻으로, 현재분사와 함께 'aun + -ndo'가 되면 '~인데도 불구하고'라는 양보 표현이 됩니다. 'Aun estando casados'는 'Aunque están casados'와 같은 뜻입니다. 악센트 있는 aún은 '아직(todavía)'이라는 뜻이니 구별하세요.","x":["Ni siquiera: '~조차 ~않다'는 부정 강조로, 뒤 문장이 부정문이 아니라 맞지 않습니다 ✗","Aunque: '~이지만' 접속사로 뒤에 활용된 동사(están)가 와야 하며 현재분사와는 함께 쓰지 않습니다 ✗","Aun: aun + 현재분사로 양보(~인데도) → 정답 ✓","Pese a: '~에도 불구하고' 뒤에는 명사나 동사원형(pese a estar casados)이 와야 합니다 ✗"]},{"id":"G161","q":"Señoras, ¿qué ____ pasa?","o":["se","les","se les","las"],"a":1,"k":"간접목적격 les","t":"여러분(부인들), 무슨 일이세요?","e":"pasar가 '(일이) 일어나다'라는 뜻일 때는 gustar처럼 '일을 겪는 사람'을 간접목적격 대명사로 씁니다. 'Señoras'는 ustedes(여러분, 존칭 복수)에 해당하므로 간접목적격은 les입니다. ¿Qué te pasa?(너 무슨 일이야?), ¿Qué les pasa?(여러분 무슨 일이세요?)는 매우 자주 쓰는 표현입니다.","x":["se: 재귀·무인칭 대명사로 '겪는 사람'을 나타낼 수 없습니다 ✗","les: ustedes에 대한 간접목적격, 일을 겪는 사람 → 정답 ✓","se les: 'se les pasa'는 '(무심코) 놓치다, 잊다'라는 다른 뜻의 비의도 구문입니다 ✗","las: 여성 복수 직접목적격(그녀들을)으로 pasar 구문에 쓰지 않습니다 ✗"]},{"id":"G162","q":"El jarrón ____ a causa del viento.","o":["se ha roto","ha roto","es roto","he roto"],"a":0,"k":"se 자동사화 (romperse)","t":"꽃병이 바람 때문에 깨졌다.","e":"romper는 '~을 깨다'라는 타동사이고, romperse는 '(저절로) 깨지다'라는 자동사입니다. 꽃병이 바람 때문에 깨진 것이므로 주어는 꽃병, 동사는 se ha roto가 됩니다. 스페인에서는 오늘 일어난 일에 현재완료를 많이 쓰고, 중남미에서는 단순과거 se rompió를 더 자주 씁니다.","x":["se ha roto: romperse의 현재완료, '깨졌다' → 정답 ✓","ha roto: '(누군가가) ~을 깼다'로 목적어가 필요하며 꽃병이 주어일 수 없습니다 ✗","es roto: ser + 과거분사 수동태는 행위자가 있을 때 쓰며, 이 맥락에서는 매우 부자연스럽습니다 ✗","he roto: '내가 깼다'라는 1인칭이라 주어 el jarrón과 맞지 않습니다 ✗"]},{"id":"G163","q":"No nos iremos ____ nos den lo prometido.","o":["desde que","antes de","por que","hasta que"],"a":3,"k":"hasta que + 접속법","t":"약속받은 것을 줄 때까지 우리는 떠나지 않을 것이다.","e":"hasta que(~할 때까지)가 아직 일어나지 않은 미래의 일을 가리키면 뒤에 접속법을 씁니다. 'nos den'은 dar의 접속법 현재입니다. 'No nos iremos hasta que…'는 '~하기 전엔 안 간다'라는 단호한 요구 표현입니다.","x":["desde que: '~한 이후로'라는 시작점을 나타내 의미가 맞지 않습니다 ✗","antes de: 뒤에 동사원형이 와야 하며, 활용된 동사가 오려면 antes de que가 필요합니다 ✗","por que: '~하도록/~이라는 이유로'의 드문 형태로 이 문맥과 맞지 않습니다 ✗","hasta que: 미래의 끝 시점을 나타내며 접속법과 함께 → 정답 ✓"]},{"id":"G164","q":"Es lógico que ____, es que lo habéis tratado fatal.","o":["se ha enfadado","haya enfadado","ha enfadado","se haya enfadado"],"a":3,"k":"접속법 현재완료","t":"그가 화난 건 당연해, 너희가 그를 너무 심하게 대했잖아.","e":"'Es lógico que(~은 당연하다)'처럼 가치 판단을 나타내는 표현 뒤에는 접속법을 씁니다. 이미 화가 난 상태(과거에 일어나 현재와 연결된 일)이므로 접속법 현재완료 haya + 과거분사가 됩니다. enfadarse(화나다)는 재귀동사라 se가 반드시 필요합니다. 참고로 중남미에서는 enojarse를 더 많이 씁니다.","x":["se ha enfadado: 직설법이라 'es lógico que' 뒤에 쓸 수 없습니다 ✗","haya enfadado: 재귀대명사 se가 빠져 '(누군가를) 화나게 했다'라는 뜻이 됩니다 ✗","ha enfadado: 직설법이고 se도 없어 두 가지 모두 틀립니다 ✗","se haya enfadado: 재귀동사 + 접속법 현재완료 → 정답 ✓"]},{"id":"G165","q":"Esta dinastía reina en España ____ siglos.","o":["desde","a partir de","desde hace","por los"],"a":2,"k":"desde hace (기간)","t":"이 왕조는 수 세기 전부터 스페인을 통치하고 있다.","e":"현재까지 계속되는 일의 '기간'을 말할 때는 desde hace + 기간을 씁니다(desde hace tres años: 3년 전부터). desde만 쓰면 뒤에 구체적 시점(desde 1975, desde el lunes)이 와야 합니다. 동사 reinar는 '통치하다, 군림하다'라는 뜻입니다.","x":["desde: 시점과 쓰며 'siglos' 같은 기간 앞에는 hace가 필요합니다 ✗","a partir de: '~부터(이후)'라는 시점 표현으로 기간 앞에 쓰지 않습니다 ✗","desde hace: 현재까지 이어지는 기간 표현 → 정답 ✓","por los: 'por los siglos'는 '수 세기 동안' 같은 문어적 표현이며 현재까지 계속되는 의미와 맞지 않습니다 ✗"]},{"id":"G166","q":"¡Quién ____ rico!","o":["sería","sea","fuera","era"],"a":2,"k":"¡Quién + 접속법 과거!","t":"내가 부자라면 얼마나 좋을까!","e":"'¡Quién + 접속법 과거!'는 '누가 ~이면 좋을까 = 내가 ~라면 좋겠다'라는 이룰 수 없는(가능성 낮은) 소망을 나타내는 관용 구문입니다. fuera는 ser의 접속법 과거로, fuese로 바꿔도 됩니다. 예: ¡Quién pudiera volar!(날 수 있다면 좋을 텐데!)","x":["sería: 가정법 조건형으로 소망 감탄문 구조에 쓰지 않습니다 ✗","sea: 접속법 현재는 이 관용 구문에 쓰지 않습니다 ✗","fuera: 접속법 과거로 이루기 어려운 소망 표현 → 정답 ✓","era: 직설법 불완료과거로 소망을 나타낼 수 없습니다 ✗"]},{"id":"G167","q":"¿Cómo se llama la calle ____ la que te diriges?","o":["entre","hacia","de","con"],"a":1,"k":"전치사 + 관계사 (hacia)","t":"네가 향하고 있는 거리 이름이 뭐야?","e":"관계절 속 동사가 전치사를 요구하면 그 전치사를 관계사 앞에 둡니다. dirigirse는 '~쪽으로 향하다'라는 뜻으로 'dirigirse hacia/a + 장소'로 씁니다. 그래서 'la calle hacia la que te diriges(네가 향하는 거리)'가 됩니다.","x":["entre: '~사이로'라는 뜻이라 dirigirse와 어울리지 않습니다 ✗","hacia: dirigirse hacia(~쪽으로 향하다) → 정답 ✓","de: '~로부터'라는 출발점을 나타내 방향과 반대입니다 ✗","con: '~와 함께'라는 뜻으로 맞지 않습니다 ✗"]},{"id":"G168","q":"Yo suelo echar la sal ____ ojo.","o":["desde","de","por","a"],"a":3,"k":"관용 표현 a ojo","t":"나는 보통 소금을 눈대중으로 넣는다.","e":"a ojo는 '눈대중으로, 대충 어림잡아'라는 관용 표현입니다. 계량하지 않고 감으로 양을 정할 때 씁니다. 비슷한 표현으로 'a ojo de buen cubero(대충 어림으로)'가 있습니다. echar la sal은 '소금을 치다'라는 뜻입니다.","x":["desde: '~부터'라는 뜻으로 관용 표현을 만들지 않습니다 ✗","de: 'de ojo'라는 표현은 없습니다 ✗","por: 'por ojo'라는 표현은 없습니다 ✗","a: a ojo '눈대중으로' 관용 표현 → 정답 ✓"]},{"id":"G169","q":"____ nos diéramos cuenta, se había marchado.","o":["Antes de que","Cada vez que","Siempre que","Mientras"],"a":0,"k":"antes de que + 접속법","t":"우리가 알아차리기도 전에 그는 가 버렸다.","e":"antes de que(~하기 전에)는 항상 접속법을 요구합니다. 주절이 과거(se había marchado)이므로 접속법 과거 diéramos가 옵니다. darse cuenta는 '알아차리다, 깨닫다'라는 매우 흔한 표현입니다.","x":["Antes de que: 항상 접속법과 함께, 과거 문맥이라 diéramos → 정답 ✓","Cada vez que: '~할 때마다'라는 반복으로, 과거 사실이면 직설법을 씁니다 ✗","Siempre que: '~할 때마다/~한다면'으로 의미가 맞지 않습니다 ✗","Mientras: '~하는 동안'은 사실을 말할 때 직설법을 쓰며 의미도 맞지 않습니다 ✗"]},{"id":"G170","q":"Te acompaño ____ la parada de autobús, ¿vale?","o":["para","hasta","de","en"],"a":1,"k":"전치사 hasta (도착점)","t":"버스 정류장까지 데려다줄게, 알았지?","e":"hasta는 '~까지'라는 도착점을 나타냅니다. acompañar a alguien hasta + 장소는 '누구를 ~까지 바래다주다'라는 표현입니다. ¿vale?는 스페인에서 '알았지?, 괜찮지?'라는 뜻으로 많이 쓰며, 중남미에서는 ¿sí?, ¿dale?(아르헨티나) 등을 씁니다.","x":["para: 목적·방향을 나타내지만 '~까지 바래다주다'의 끝 지점으로는 쓰지 않습니다 ✗","hasta: 도착점 '~까지' → 정답 ✓","de: '~부터'라는 출발점입니다 ✗","en: '~에서'라는 위치로 이동의 끝을 나타내지 않습니다 ✗"]},{"id":"G171","q":"El almuerzo ya está preparado. ¡____!","o":["Para comer","Se come","A comer","Comemos"],"a":2,"k":"a + 동사원형 (명령)","t":"점심 다 준비됐어. 밥 먹자!","e":"'¡A + 동사원형!'은 '자, ~하자!/~해라!'라는 구어적인 명령·권유 표현입니다. '¡A comer!'는 식사 준비가 끝났을 때 가족을 부르는 전형적인 말입니다. 예: ¡A dormir!(자, 자러 가자!), ¡A trabajar!(자, 일하자!).","x":["Para comer: '먹기 위해'라는 목적 표현으로 감탄 명령이 되지 않습니다 ✗","Se come: '(여기선) 먹는다'라는 무인칭 표현으로 부르는 말이 아닙니다 ✗","A comer: '자, 먹자!' 관용 명령 표현 → 정답 ✓","Comemos: '우리는 먹는다'라는 서술문이라 감탄 권유로는 부자연스럽습니다 ✗"]},{"id":"G172","q":"____ podéis empezar a redactar vuestro texto.","o":["Tras","Ya","Aun","Antes"],"a":1,"k":"부사 ya (이제)","t":"이제 너희는 글을 쓰기 시작해도 된다.","e":"ya는 '이미' 외에 '이제, 지금부터'라는 뜻으로, 어떤 일이 가능해진 시점을 알립니다. 'Ya podéis empezar'는 선생님이 '이제 시작해도 돼요'라고 허락하는 말입니다. podéis는 스페인의 vosotros 형태이고, 중남미라면 'Ya pueden empezar'라고 합니다.","x":["Tras: '~후에'라는 전치사로 뒤에 명사가 필요합니다 ✗","Ya: '이제'라는 시점 부사 → 정답 ✓","Aun: '~조차'라는 뜻으로 문맥에 맞지 않습니다 ✗","Antes: '전에'라는 부사로 '전에 시작해도 된다'가 되어 어색합니다 ✗"]},{"id":"G173","q":"Bailaron ____ caer rendidos.","o":["a","hasta","desde","hacia"],"a":1,"k":"hasta + 동사원형 (결과)","t":"그들은 녹초가 되어 쓰러질 때까지 춤을 췄다.","e":"hasta + 동사원형은 '~할 때까지(~할 정도로)'라는 극단적인 결과·한계를 나타냅니다. 'caer rendidos'는 '지쳐 쓰러지다'라는 표현으로, 'bailar hasta caer rendidos'는 '쓰러질 때까지 춤추다'라는 생생한 과장 표현입니다.","x":["a: 'a caer'는 '쓰러지기 위해'처럼 들려 '~할 때까지'의 한계를 나타내지 못합니다 ✗","hasta: '~할 때까지' 한계 → 정답 ✓","desde: '~부터'라는 출발점입니다 ✗","hacia: '~쪽으로'라는 방향이라 동사원형과 쓰지 않습니다 ✗"]},{"id":"G174","q":"Afortunadamente, el estado de salud de Mari Carmen tiende ____ mejorar.","o":["hacia","a","para","hasta"],"a":1,"k":"tender a + 동사원형","t":"다행히 마리 카르멘의 건강 상태는 나아지는 경향이 있다.","e":"tender a + 동사원형은 '~하는 경향이 있다, ~쪽으로 기울다'라는 뜻으로 전치사 a가 고정입니다. 'tiende a mejorar'는 '점점 좋아지고 있다'라는 뉘앙스입니다. 예: Los precios tienden a subir en verano(여름에는 물가가 오르는 경향이 있다).","x":["hacia: 'tender hacia + 명사'는 가능하지만 동사원형 앞에는 a를 씁니다 ✗","a: tender a + 동사원형 고정 표현 → 정답 ✓","para: tender와 함께 쓰지 않습니다 ✗","hasta: '~까지'라는 뜻으로 경향을 나타내지 않습니다 ✗"]},{"id":"G175","q":"____ que vengan más invitados de lo previsto, haremos la fiesta en la azotea.","o":["En el caso de","Como si","Si","Como"],"a":0,"k":"en el caso de que","t":"예상보다 손님이 더 오는 경우에는 옥상에서 파티를 할 것이다.","e":"en (el) caso de que는 '~하는 경우에는'이라는 조건 표현으로 반드시 접속법(vengan)을 씁니다. si도 조건이지만 si 뒤에는 현재 접속법을 쓸 수 없고 직설법(vienen)이 와야 하며, 'que'와 결합하지도 않습니다. 'de lo previsto'는 '예상했던 것보다'라는 비교 표현입니다.","x":["En el caso de: que와 합쳐 en el caso de que + 접속법 → 정답 ✓","Como si: '마치 ~인 것처럼'으로 접속법 과거와 쓰며 의미도 다릅니다 ✗","Si: 'si que vengan'은 문법적으로 성립하지 않습니다 ✗","Como: 'como que vengan'은 성립하지 않으며, como + 접속법 조건도 이 구조가 아닙니다 ✗"]},{"id":"G176","q":"Nos consta que Amelia ____ por completo de su dolencia.","o":["se ha recuperado","ha recuperado","haya recuperado","se haya recuperado"],"a":0,"k":"constar que + 직설법","t":"아멜리아가 병에서 완전히 회복했다는 것을 우리는 확실히 알고 있다.","e":"'Me/Nos consta que…'는 '~라는 것이 확실하다, ~임을 알고 있다'라는 격식 있는 표현으로, 사실을 확인하므로 직설법을 씁니다. recuperarse de(~에서 회복하다)는 재귀동사이므로 se가 필요합니다. 'dolencia'는 '질환, 병'을 뜻하는 다소 격식 있는 단어입니다.","x":["se ha recuperado: 재귀동사 + 직설법 현재완료, 확실한 사실 → 정답 ✓","ha recuperado: se가 없으면 '(무언가를) 되찾았다'라는 타동사가 되어 de와 맞지 않습니다 ✗","haya recuperado: 접속법이고 se도 빠졌습니다 ✗","se haya recuperado: 접속법인데, 확실함을 나타내는 consta 뒤에는 직설법을 씁니다 ✗"]},{"id":"G177","q":"Yo quiero a ____ mis sobrinos por igual.","o":["estos","todos","todos los","ellos"],"a":1,"k":"todos + 소유사","t":"나는 내 조카들을 모두 똑같이 사랑한다.","e":"todos(모든)는 정관사·소유형용사·지시형용사 앞에 옵니다: todos los niños, todos mis sobrinos, todos estos libros. 이미 소유형용사 mis가 있으므로 정관사 los를 겹쳐 쓰지 않습니다. querer a + 사람은 '~를 사랑하다'라는 뜻입니다.","x":["estos: 'estos mis sobrinos'는 지시사와 소유사를 겹친 형태로 일반적이지 않습니다 ✗","todos: todos + mis sobrinos → 정답 ✓","todos los: 정관사와 소유형용사 mis를 함께 쓸 수 없습니다 ✗","ellos: 주격 대명사로 명사 앞에 오지 않습니다 ✗"]},{"id":"G178","q":"Nos ____ que se había divorciado recientemente.","o":["comenta","comentaba","habría comentado","comentó"],"a":3,"k":"단순과거 (완료된 일)","t":"그는 최근에 이혼했다고 우리에게 말해 주었다.","e":"과거의 특정 시점에 한 번 일어나고 끝난 행동은 단순과거(pretérito indefinido)를 씁니다. '말해 주었다'는 한 번의 완결된 행동이므로 comentó가 자연스럽습니다. 뒤의 se había divorciado는 그보다 더 이전의 일이라 과거완료입니다.","x":["comenta: 현재형으로 과거완료(se había divorciado)와 시제가 어울리지 않습니다 ✗","comentaba: 불완료과거는 반복·배경 묘사로, 한 번 말한 사건에는 덜 자연스럽습니다 ✗","habría comentado: '말했을 텐데'라는 추측·가정의 뜻이 됩니다 ✗","comentó: 한 번 완결된 과거 행동 → 정답 ✓"]},{"id":"G179","q":"No ____ en esa silla, que está rota.","o":["te sientas","sientes","te sientes","sientas"],"a":2,"k":"부정 명령 (재귀동사)","t":"그 의자에 앉지 마, 부서졌거든.","e":"tú에 대한 부정 명령은 'no + 접속법 현재'로 만듭니다. sentarse(앉다)는 재귀동사이므로 'no te sientes'가 됩니다(긍정 명령은 siéntate). 'que está rota'의 que는 '왜냐하면'의 뜻을 갖는 구어적 연결어입니다.","x":["te sientas: 직설법 현재로 '너는 앉는다'라는 서술이라 명령이 아닙니다 ✗","sientes: 재귀대명사가 없고 sentir(느끼다)의 직설법 형태입니다 ✗","te sientes: no + 재귀대명사 + 접속법 현재 = 부정 명령 → 정답 ✓","sientas: sentir(느끼다)의 접속법이며 재귀대명사도 없습니다 ✗"]},{"id":"G180","q":"Exijo hablar con alguien ____ sepa lo que ha pasado.","o":["el cual","el que","que","quien"],"a":2,"k":"관계사 que (한정)","t":"무슨 일이 있었는지 아는 사람과 이야기하게 해 달라고 요구합니다.","e":"선행사 바로 뒤에서 쉼표 없이 쓰는 한정 관계절에서는 주로 que를 씁니다. 'alguien que sepa…'처럼 사람이 선행사여도 que가 기본입니다. 또 존재가 불확실한 대상(그런 사람이 있는지 모름)을 찾을 때는 관계절 동사에 접속법(sepa)을 씁니다.","x":["el cual: 쉼표 없는 한정 관계절의 주어로는 쓰지 않습니다 ✗","el que: 앞에 전치사가 없는 한정절 주어 자리에서는 쓰지 않습니다 ✗","que: 한정 관계절의 기본 관계사 → 정답 ✓","quien: 쉼표 없는 한정절에서 주어로 quien을 쓰는 것은 비표준입니다 ✗"]},{"id":"G181","q":"Juana nunca ____ algo así, es una persona íntegra.","o":["haría","habrá hecho","haya hecho","haga"],"a":0,"k":"조건형 (단정·추측)","t":"후아나는 절대 그런 짓을 하지 않을 거야, 그녀는 정직한 사람이야.","e":"조건형(condicional, ~할 것이다/~하지 않을 것이다)은 '어떤 상황이 와도 ~하지 않을 것'이라는 가정적 판단을 나타냅니다. 'nunca haría algo así'는 '그녀라면 그런 일은 절대 안 할 것'이라는 성격에 근거한 확신입니다. íntegra는 '청렴한, 올곧은'이라는 뜻입니다.","x":["haría: 조건형으로 가정적 판단 '절대 하지 않을 것' → 정답 ✓","habrá hecho: 미래완료 '했을 것이다(추측)'로, 이미 일어났을지 모르는 일을 추측하는 뜻이라 성격 묘사와 맞지 않습니다 ✗","haya hecho: 접속법이라 독립된 평서문에 쓸 수 없습니다 ✗","haga: 접속법 현재로 이 문장에 쓸 근거가 없습니다 ✗"]},{"id":"G182","q":"Nunca ____ la lotería, pero no pierdo la esperanza.","o":["habríamos ganado","habíamos ganado","hemos ganado","ganábamos"],"a":2,"k":"현재완료 (경험)","t":"우리는 한 번도 복권에 당첨된 적이 없지만 희망을 잃지 않는다.","e":"현재완료(he/has/ha + 과거분사)는 '지금까지 ~한 적이 있다/없다'라는 경험을 나타냅니다. nunca와 함께 '지금까지 한 번도 ~한 적 없다'가 되며, 뒤 문장의 현재형 no pierdo와 시간적으로 연결됩니다. 중남미에서는 'Nunca ganamos la lotería'처럼 단순과거로도 자주 말합니다.","x":["habríamos ganado: '당첨되었을 텐데'라는 가정 표현이라 맞지 않습니다 ✗","habíamos ganado: 과거완료로, 과거의 기준 시점이 없어 쓸 수 없습니다 ✗","hemos ganado: 현재까지의 경험을 나타내는 현재완료 → 정답 ✓","ganábamos: 과거 습관·배경을 나타내는 불완료과거로 경험 의미가 아닙니다 ✗"]},{"id":"G183","q":"¿Todavía hay cosas que os ____?","o":["sorprenden","habían sorprendido","sorprendieran","sorprendían"],"a":0,"k":"관계절 직설법","t":"아직도 너희를 놀라게 하는 것들이 있니?","e":"관계절의 선행사(cosas)가 실제로 존재할 수 있는 것을 묻는 일반적인 질문이고, 현재 시점이므로 직설법 현재 sorprenden을 씁니다. sorprender는 gustar처럼 '놀라는 사람'을 간접목적격(os: 너희에게)으로 씁니다. 중남미라면 os 대신 les를 써서 '¿cosas que les sorprenden?'이 됩니다.","x":["sorprenden: 현재 사실을 묻는 관계절 직설법 → 정답 ✓","habían sorprendido: 과거완료로 현재 시점 질문(Todavía hay)과 맞지 않습니다 ✗","sorprendieran: 접속법 과거로 현재형 주절과 시제가 맞지 않습니다 ✗","sorprendían: 불완료과거로 todavía hay(지금도 있다)와 시제가 어긋납니다 ✗"]},{"id":"G184","q":"Para optar al puesto, es necesario cumplir ____ todos los requisitos.","o":["con","por","ante","para"],"a":0,"k":"cumplir con","t":"그 자리에 지원하려면 모든 요건을 충족해야 한다.","e":"cumplir con은 '(의무·조건·약속 등을) 이행하다, 충족하다'라는 뜻입니다. 'cumplir (con) los requisitos'는 con 없이도 쓰지만, 보기 중에서는 con만 올바릅니다. optar a는 '(직위 등에) 지원하다, 도전하다'라는 격식 있는 표현입니다.","x":["con: cumplir con '~을 충족하다/이행하다' → 정답 ✓","por: cumplir와 함께 쓰는 전치사가 아닙니다 ✗","ante: '~앞에서'라는 뜻이라 맞지 않습니다 ✗","para: cumplir para는 '요건을 충족하다'라는 뜻이 되지 않습니다 ✗"]},{"id":"G185","q":"Estamos hartas ____ su mal carácter.","o":["con","sobre","de","para"],"a":2,"k":"estar harto de","t":"우리는 그의 고약한 성격에 질렸다.","e":"estar harto/a de는 '~에 질리다, 진저리 나다'라는 뜻으로 전치사 de가 고정입니다. 주어가 여성 복수(우리 여자들)라 hartas로 일치시켰습니다. 예: Estoy harto de esperar(기다리는 데 질렸어). 'mal carácter'는 '나쁜 성질, 까다로운 성격'입니다.","x":["con: harto와 쓰지 않습니다(다만 'harto con'은 일부 지역 구어에 있으나 비표준) ✗","sobre: '~에 대하여'라는 뜻으로 harto와 쓰지 않습니다 ✗","de: estar harto de 고정 표현 → 정답 ✓","para: '~을 위해'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G186","q":"No creas que me ____ ilusión visitar ese museo.","o":["haga","hace","hiciese","haya hecho"],"a":1,"k":"No creas que + 직설법","t":"내가 그 박물관에 가는 걸 기대하고 있다고 생각하지 마.","e":"보통 'no creer que' 뒤에는 접속법이 오지만, 명령형 'No creas que…'(~라고 생각하지 마)는 상대의 오해를 바로잡는 표현이라 구어에서 직설법이 흔히 쓰입니다. 'hacer ilusión'은 '설레게 하다, 기대되게 하다'라는 관용 표현으로 gustar처럼 me를 씁니다(Me hace ilusión el viaje: 여행이 기대된다).","x":["haga: 접속법 현재로 실제로는 문법적으로 가능하지만, 교재는 구어에서 더 흔한 직설법을 정답으로 봅니다 ✗","hace: 상대의 오해를 바로잡는 'No creas que + 직설법' → 정답 ✓","hiciese: 접속법 과거로 현재 시점 문장과 시제가 맞지 않습니다 ✗","haya hecho: 접속법 현재완료로 '이미 기대하게 했다'는 뜻이 되어 앞으로의 방문과 어울리지 않습니다 ✗"],"f":"'No creas que me haga ilusión'(접속법)도 표준 문법상 가능하여 A도 정답이 될 수 있음"},{"id":"G187","q":"Lo cierto es que ____ muy bien en nuestro nuevo trabajo.","o":["nos vamos","se va","nos va","vayamos"],"a":2,"k":"irle bien a alguien","t":"사실 우리는 새 직장에서 아주 잘 지내고 있다.","e":"'ir bien/mal a alguien'은 '(누구에게) 일이 잘/안 풀리다'라는 뜻으로 gustar처럼 간접목적격을 씁니다. 그래서 '우리에게 잘 풀린다'는 nos va bien입니다. 예: ¿Cómo te va?(어떻게 지내?). 'Lo cierto es que'는 '사실은, 실은'이라는 강조 표현입니다.","x":["nos vamos: irse(떠나다)의 1인칭 복수로 '우리는 떠난다'라는 뜻이 됩니다 ✗","se va: '그/그녀가 떠난다'라는 뜻으로 문맥과 맞지 않습니다 ✗","nos va: ir bien a alguien '우리에게 잘 풀린다' → 정답 ✓","vayamos: 접속법이며 lo cierto es que(사실은) 뒤에는 직설법을 씁니다 ✗"]},{"id":"G188","q":"Para mí que Luis y Carla ya no ____ juntos.","o":["habían estado","estarán","han estado","están"],"a":3,"k":"Para mí que + 직설법","t":"내 생각엔 루이스와 카를라는 이제 같이 안 사귀는 것 같아.","e":"'Para mí que…'는 구어로 '내 생각엔 ~인 것 같다'라는 뜻이며, 의견을 말하므로 직설법을 씁니다. '이제 함께가 아니다'라는 현재 상태이므로 estar의 현재형 están이 맞습니다. 'estar juntos'는 '사귀다, 함께 지내다'라는 뜻입니다.","x":["habían estado: 과거완료로 현재 상태를 말하는 ya no와 맞지 않습니다 ✗","estarán: 미래형도 추측을 나타낼 수 있지만, 'Para mí que' 자체가 이미 추측이라 겹쳐 쓰지 않는 것이 자연스럽습니다 ✗","han estado: '함께였던 적이 있다'라는 뜻이 되어 ya no(이제는 아님)와 어울리지 않습니다 ✗","están: 현재 상태 직설법 → 정답 ✓"]},{"id":"G189","q":"Quiero un diccionario que ____ ilustraciones.","o":["tenga","tendría","tendrá","tiene"],"a":0,"k":"관계절 접속법 (불특정)","t":"그림이 들어 있는 사전을 원한다.","e":"관계절의 선행사가 '아직 정해지지 않은, 원하는 조건의 것'이면 접속법을 씁니다. 'un diccionario que tenga ilustraciones'는 '(어떤 것이든) 그림이 있는 사전'을 찾는 뜻입니다. 만약 특정 사전을 이미 알고 있다면 'Quiero el diccionario que tiene ilustraciones'처럼 직설법을 씁니다.","x":["tenga: 불특정 대상을 원할 때 관계절 접속법 → 정답 ✓","tendría: 조건형으로 원하는 조건을 나타내지 못합니다 ✗","tendrá: 미래형으로 '가질 것이다'라는 뜻이 되어 맞지 않습니다 ✗","tiene: 직설법은 특정·실재하는 대상을 가리킬 때 씁니다 ✗"]},{"id":"G190","q":"____ una conferencia muy instructiva.","o":["Consistió","Estuvo","Fue","Trató de"],"a":2,"k":"ser (사건의 성격)","t":"아주 유익한 강연이었다.","e":"'명사(una conferencia)'를 보어로 받아 '~였다'라고 정체를 말할 때는 ser를 씁니다. 'Fue una conferencia muy instructiva'는 '그것은 매우 유익한 강연이었다'라는 평가입니다. estar는 뒤에 명사를 바로 받을 수 없습니다(Estuvo muy instructiva는 가능).","x":["Consistió: consistir en(~로 구성되다)이라 전치사 en이 필요하고 의미도 맞지 않습니다 ✗","Estuvo: estar는 명사 보어를 직접 받지 않습니다 ✗","Fue: ser + 명사로 정체·평가를 나타냄 → 정답 ✓","Trató de: '~에 관한 것이었다/~하려고 했다'라는 뜻이라 뒤에 주제나 동사원형이 와야 합니다 ✗"]},{"id":"G191","q":"Dicen que ____ barato sale caro.","o":["eso","lo","esto","aquello"],"a":1,"k":"중성 lo + 형용사 (속담)","t":"싼 게 비지떡이라는 말이 있다.","e":"lo + 형용사는 '~한 것'이라는 추상 명사를 만듭니다. 'Lo barato sale caro'는 '싼 것은 (결국) 비싸게 먹힌다'라는 유명한 속담으로, 한국어의 '싼 게 비지떡'에 해당합니다. salir caro는 '비싸게 치이다'라는 표현입니다.","x":["eso: 지시대명사로 형용사 앞에서 추상 명사를 만들지 않습니다 ✗","lo: 중성 관사 lo + 형용사 = '~한 것' → 정답 ✓","esto: 지시대명사로 속담 구조와 맞지 않습니다 ✗","aquello: 지시대명사로 이 위치에 쓰지 않습니다 ✗"]},{"id":"G192","q":"Hoy hablaremos de los diferentes tipos ____ prensa.","o":["del","ø","de","de la"],"a":2,"k":"tipos de + 무관사 명사","t":"오늘은 여러 종류의 언론에 대해 이야기하겠다.","e":"'tipo(s) de + 명사'로 종류를 말할 때 뒤의 명사는 보통 관사 없이 씁니다: tipos de prensa(언론의 종류), tipos de música(음악 장르). 관사를 넣으면 특정한 언론을 가리키게 되어 '종류'라는 일반적인 의미가 흐려집니다.","x":["del: de + el이며 prensa는 여성 명사라 성도 맞지 않습니다 ✗","ø: 전치사 de가 빠지면 두 명사가 연결되지 않습니다 ✗","de: tipos de + 무관사 명사 → 정답 ✓","de la: 관사를 넣으면 특정 언론을 가리켜 종류 분류 표현으로 부자연스럽습니다 ✗"]},{"id":"G193","q":"____ importante es que te recuperes lo antes posible.","o":["Lo","De","El","Esto"],"a":0,"k":"lo + 형용사 (Lo importante)","t":"중요한 건 네가 최대한 빨리 회복하는 것이다.","e":"'Lo importante es que…'는 '중요한 것은 ~이다'라는 아주 자주 쓰는 구문입니다. lo + 형용사로 '~한 점/것'을 만듭니다. 'es que' 뒤에 바람을 담은 내용이 오므로 접속법 recuperes를 씁니다. 'lo antes posible'은 '가능한 한 빨리'라는 표현입니다.","x":["Lo: lo + 형용사 '중요한 것' → 정답 ✓","De: 전치사로 주어 자리에 올 수 없습니다 ✗","El: 남성 관사로 뒤에 명사가 필요합니다(el punto importante 등) ✗","Esto: 'esto importante'는 문법적으로 맞지 않습니다 ✗"]},{"id":"G194","q":"Por favor, contacte con nosotros ____ telefónica.","o":["por medio de","a través","por vía","mediante"],"a":2,"k":"por vía + 형용사","t":"저희에게 전화로 연락해 주십시오.","e":"'por vía + 형용사'는 '~ 경로로, ~ 방식으로'라는 격식 있는 표현입니다: por vía telefónica(전화로), por vía oral(구두로/복용으로), por vía aérea(항공편으로). 뒤의 telefónica가 여성 형용사라 여성 명사 vía와 일치합니다.","x":["por medio de: 뒤에 명사가 와야 하며 형용사 telefónica만으로는 안 됩니다(por medio del teléfono) ✗","a través: 'a través de'가 되어야 하며 뒤에 명사가 필요합니다 ✗","por vía: por vía telefónica '전화로' → 정답 ✓","mediante: '~을 통해'라는 전치사로 뒤에 명사가 필요합니다 ✗"]},{"id":"G195","q":"Siempre soy yo ____ acaba cediendo.","o":["que","a que","cual","la que"],"a":3,"k":"강조 구문 la que","t":"항상 결국 양보하는 사람은 나야.","e":"'Ser + 강조 대상 + 관사 + que'는 '~하는 사람은 바로 ~다'라는 강조 구문입니다. 화자 yo가 여성이라는 것을 la que로 알 수 있습니다(남성이라면 el que). 'acabar + 현재분사'는 '결국 ~하게 되다'라는 뜻입니다.","x":["que: 강조 구문에서 사람을 가리킬 때는 관사가 필요해 que만으로는 부족합니다 ✗","a que: 전치사 a가 필요한 구조가 아닙니다 ✗","cual: 관사 없이 단독 관계사로 쓰지 않습니다 ✗","la que: 여성 화자를 가리키는 강조 구문 → 정답 ✓"]},{"id":"G196","q":"No creo que encontremos una solución satisfactoria ____ corto plazo.","o":["por","a","de","en"],"a":1,"k":"a corto plazo","t":"우리가 단기간에 만족스러운 해결책을 찾을 거라고 생각하지 않는다.","e":"a corto plazo는 '단기적으로, 가까운 시일 안에'라는 고정 표현입니다. 반대는 a largo plazo(장기적으로), 중간은 a medio plazo(중기적으로)입니다. 'No creo que' 뒤라 접속법 encontremos가 쓰였습니다.","x":["por: 'por corto plazo'라는 표현은 없습니다 ✗","a: a corto plazo '단기적으로' 고정 표현 → 정답 ✓","de: 'de corto plazo'는 형용사처럼 명사를 꾸밀 때(un préstamo de corto plazo) 쓰며 여기서는 부적절합니다 ✗","en: 'en corto plazo'는 일부 지역에서 들리지만 표준 표현은 a corto plazo입니다 ✗"]},{"id":"G197","q":"¡Madre mía! ¡____ cosas has comprado!","o":["Cuántas de","Cómo de","Qué de","Cuáles de"],"a":2,"k":"¡Qué de + 명사!","t":"세상에! 물건을 얼마나 많이 산 거야!","e":"'¡Qué de + 명사!'는 '얼마나 많은 ~!'이라는 구어 감탄 표현으로, ¡Cuántas cosas!와 같은 뜻입니다. 주로 스페인에서 쓰며 약간 친근하고 놀라는 말투입니다. '¡Madre mía!'도 '세상에!, 맙소사!'라는 감탄사입니다.","x":["Cuántas de: '¡Cuántas cosas!'는 맞지만 de가 들어가면 틀립니다 ✗","Cómo de: 'cómo de + 형용사'(¿Cómo de grande?: 얼마나 큰?)로 쓰며 명사 앞에 오지 않습니다 ✗","Qué de: ¡Qué de + 명사! '얼마나 많은 ~!' → 정답 ✓","Cuáles de: '~중 어느 것들'이라는 선택 의문사로 감탄문이 아닙니다 ✗"]},{"id":"G198","q":"¡Cómo ____ Mercedes y sus hermanas!","o":["parecen","se parezcan","se parecen","se aparecen"],"a":2,"k":"parecerse (닮다)","t":"메르세데스와 그녀의 자매들은 정말 닮았어!","e":"parecerse는 '(서로/누구를) 닮다'라는 재귀동사입니다. 그냥 parecer는 '~처럼 보이다'라는 뜻이라 뒤에 보어가 필요합니다. '¡Cómo se parecen!'은 '어쩜 이렇게 닮았을까!'라는 감탄이며, 사실을 말하므로 직설법을 씁니다.","x":["parecen: '~처럼 보인다'라서 뒤에 보어가 없으면 의미가 불완전합니다 ✗","se parezcan: 접속법이라 감탄문에 쓸 이유가 없습니다 ✗","se parecen: parecerse '닮다' 직설법 → 정답 ✓","se aparecen: aparecerse는 '(유령 등이) 나타나다'라는 뜻입니다 ✗"]},{"id":"G199","q":"¿____ viviendo en la casa de vuestros padres?","o":["Vais","Seguís","Lleváis","Andáis"],"a":1,"k":"seguir + 현재분사","t":"너희는 아직도 부모님 집에서 살고 있니?","e":"seguir + 현재분사는 '계속 ~하고 있다, 여전히 ~하다'라는 뜻으로 어떤 상태가 이어짐을 나타냅니다. '¿Seguís viviendo…?'는 '아직도 ~에 살아?'라는 자연스러운 질문입니다. seguís는 vosotros 형태이고, 중남미에서는 '¿Siguen viviendo…?'라고 합니다.","x":["Vais: ir + 현재분사는 '점점 ~해 가다'라는 점진적 진행이라 맞지 않습니다 ✗","Seguís: seguir + 현재분사 '여전히 ~하다' → 정답 ✓","Lleváis: llevar + 현재분사는 뒤에 기간이 필요합니다(Lleváis dos años viviendo…) ✗","Andáis: andar + 현재분사는 '여기저기 ~하고 다니다'라는 뉘앙스라 어색합니다 ✗"]},{"id":"G200","q":"¿Crees que Sofía ____ venir conmigo al evento?","o":["quisiese","querrá","quiera","está queriendo"],"a":1,"k":"¿Crees que + 직설법?","t":"소피아가 나랑 같이 행사에 가고 싶어 할 거라고 생각해?","e":"긍정 'creer que' 뒤에는 직설법을 씁니다. 의문문 '¿Crees que…?'에서는 직설법과 접속법이 모두 가능한데, 직설법은 단순히 상대의 의견을 묻는 느낌, 접속법은 화자가 의심을 품고 있는 느낌입니다. 앞으로의 일이므로 미래형 querrá가 자연스럽습니다.","x":["quisiese: 접속법 과거라 현재 시점 질문과 시제가 맞지 않습니다 ✗","querrá: 미래 일에 대한 의견을 묻는 직설법 미래 → 정답 ✓","quiera: 의심을 담은 질문에서 문법적으로 가능하지만, 교재는 직설법을 정답으로 봅니다 ✗","está queriendo: querer는 진행형으로 거의 쓰지 않습니다 ✗"],"f":"의문문 ¿Crees que…? 뒤에는 접속법 quiera도 표준적으로 가능하여 C도 정답이 될 수 있음"},{"id":"G201","q":"Mamá, no voy a llegar a tiempo al colegio, ¿puedes ____ tú?","o":["llevarme","de llevar","que me lleves","llevar me"],"a":0,"k":"poder + 동사원형 + 대명사","t":"엄마, 학교에 제시간에 못 갈 것 같아요, 엄마가 데려다줄 수 있어요?","e":"poder(~할 수 있다) 뒤에는 동사원형이 바로 오고, 목적격 대명사는 동사원형 끝에 붙이거나(llevarme) 활용 동사 앞에 둡니다(¿me puedes llevar?). 'llevar a alguien'은 '누구를 (차로) 데려다주다'라는 뜻입니다.","x":["llevarme: 동사원형 + 대명사 붙여 쓰기 → 정답 ✓","de llevar: poder 뒤에 전치사 de를 넣지 않습니다 ✗","que me lleves: poder 뒤에는 que절이 오지 않습니다 ✗","llevar me: 대명사는 동사원형에 붙여 써야 하며 띄어 쓰면 틀립니다 ✗"]},{"id":"G202","q":"Si te ____ los zapatos, es que necesitas otro número.","o":["aprieta","aprietan","apretarán","apretarían"],"a":1,"k":"apretar (꽉 끼다) 일치","t":"신발이 꽉 끼면 다른 치수가 필요하다는 거야.","e":"apretar는 '꽉 끼다, 조이다'라는 뜻으로, 이 문장의 문법상 주어는 los zapatos(복수)이고 te는 '너에게'입니다. 그래서 동사는 3인칭 복수 aprietan이 됩니다. 사실·일반 조건을 말하는 si 뒤에는 미래형이나 조건형을 쓰지 않고 현재형을 씁니다. número는 여기서 '(신발) 치수'를 뜻합니다.","x":["aprieta: 3인칭 단수라 복수 주어 los zapatos와 맞지 않습니다 ✗","aprietan: 복수 주어와 일치하는 현재형 → 정답 ✓","apretarán: si 조건절에는 미래형을 쓰지 않습니다 ✗","apretarían: si 조건절에 조건형을 쓰지 않습니다 ✗"]},{"id":"G203","q":"A Julia ____ ha ocurrido una idea genial.","o":["le","se la","se","se le"],"a":3,"k":"ocurrírsele algo a alguien","t":"훌리아에게 기발한 아이디어가 떠올랐다.","e":"'ocurrírsele algo a alguien'은 '(누구에게) 생각이 떠오르다'라는 구문입니다. se는 고정이고, 떠오른 사람을 간접목적격(le)으로 씁니다. 예: Se me ocurrió una idea(나에게 아이디어가 떠올랐다). a Julia와 le가 같은 사람을 가리키는 중복 표현입니다.","x":["le: se가 빠지면 ocurrir가 '일어나다'라는 뜻이 되어 '아이디어가 일어났다'처럼 어색해집니다 ✗","se la: la는 직접목적격이라 이 구문에 쓰지 않습니다 ✗","se: 떠오른 사람(Julia)을 받는 간접목적격 le가 빠졌습니다 ✗","se le: ocurrírsele 구문, se + le(훌리아에게) → 정답 ✓"]},{"id":"G204","q":"Cuando llueve, huele ____ tierra mojada.","o":["de","a","con","ø"],"a":1,"k":"oler a (~냄새가 나다)","t":"비가 오면 젖은 흙 냄새가 난다.","e":"oler a + 명사는 '~의 냄새가 나다'라는 뜻으로 전치사 a가 고정입니다. 예: Huele a café(커피 냄새가 난다). 비유적으로 'Esto me huele a mentira(이건 거짓말 같은 냄새가 나)'처럼도 씁니다. 같은 식으로 'saber a(~맛이 나다)'도 a를 씁니다.","x":["de: 'oler de'는 표준 스페인어에서 쓰지 않습니다 ✗","a: oler a '~냄새가 나다' 고정 표현 → 정답 ✓","con: 냄새의 내용을 나타내지 못합니다 ✗","ø: 전치사 없이 쓰면 '젖은 흙을 냄새 맡다'라는 타동사 의미가 되어 주어가 없습니다 ✗"]},{"id":"G205","q":"Como no me salía bien, ____ la actividad.","o":["volví a hacer","estuve haciendo","llegué a hacer","llevé haciendo"],"a":0,"k":"volver a + 동사원형","t":"잘 안 돼서 나는 그 활동을 다시 했다.","e":"volver a + 동사원형은 '다시 ~하다'라는 뜻의 아주 흔한 동사 구문입니다. 잘 안 되어 처음부터 다시 했다는 문맥에 정확히 맞습니다. 'salir bien'은 '(일이) 잘 되다'라는 표현입니다(No me salía bien: 나는 잘 안 되었다).","x":["volví a hacer: '다시 했다' → 정답 ✓","estuve haciendo: '한동안 하고 있었다'로 '잘 안 돼서'라는 원인과 연결이 약합니다 ✗","llegué a hacer: '마침내 ~하기에 이르렀다'라는 뜻으로 맞지 않습니다 ✗","llevé haciendo: llevar + 현재분사는 기간이 필요하며 보통 현재형으로 씁니다 ✗"]},{"id":"G206","q":"____ de mis amigos tiene un don para algo.","o":["Algún","Ningunos","Mucho","Cada uno"],"a":3,"k":"cada uno de","t":"내 친구들은 저마다 무언가에 재능이 있다.","e":"cada uno de + 복수 명사는 '~ 각자, ~ 하나하나'라는 뜻이며 동사는 단수(tiene)로 씁니다. 'tener un don para algo'는 '~에 타고난 재능이 있다'라는 표현입니다. 예: Cada uno de nosotros es diferente(우리 각자는 다르다).","x":["Algún: 'alguno de'가 되어야 하며 algún은 명사 바로 앞에서만 씁니다 ✗","Ningunos: 복수형은 거의 쓰지 않고 단수 동사와도 맞지 않습니다 ✗","Mucho: 'muchos de'가 되어야 하고 동사도 복수가 됩니다 ✗","Cada uno: cada uno de + 복수 명사 + 단수 동사 → 정답 ✓"]},{"id":"G207","q":"Terminaremos el proyecto un ____ día de estos.","o":["otro","tal","cualquier","ø"],"a":3,"k":"un día de estos","t":"우리는 조만간 언젠가 그 프로젝트를 끝낼 것이다.","e":"'un día de estos'는 '조만간, 머지않아 언젠가'라는 관용 표현으로 그 사이에 아무것도 넣지 않습니다. 날짜를 정하지 않은 막연한 미래를 말할 때 씁니다. 비슷하게 'cualquier día de estos'도 가능하지만 그때는 un을 쓰지 않습니다.","x":["otro: 'un otro día'는 틀린 형태입니다(otro 앞에 un을 쓰지 않음) ✗","tal: 'un tal día'는 쓰지 않으며 'un tal + 이름'은 '~라는 사람'이라는 뜻입니다 ✗","cualquier: 'cualquier día de estos'는 가능하지만 un과 함께 쓰지 않습니다 ✗","ø: 아무것도 넣지 않은 un día de estos → 정답 ✓"]},{"id":"G208","q":"Por fin conocimos al novio de Pilar. ¡Qué encanto ____ hombre!","o":["para","sobre","de","por"],"a":2,"k":"¡Qué + 명사 + de + 명사!","t":"드디어 필라르의 남자친구를 만났어. 정말 매력적인 남자더라!","e":"'¡Qué + 평가 명사 + de + 명사!'는 '얼마나 ~한 ~인가!'라는 감탄 구조입니다: ¡Qué encanto de hombre!(정말 매력적인 남자다!), ¡Qué maravilla de día!(정말 멋진 날이다!). encanto는 '매력, 사랑스러운 사람'이라는 뜻입니다.","x":["para: 이 감탄 구조에 쓰지 않습니다 ✗","sobre: '~에 대해'라는 뜻이라 맞지 않습니다 ✗","de: ¡Qué encanto de hombre! 감탄 구조 → 정답 ✓","por: 이 구조에 쓰지 않습니다 ✗"]},{"id":"G209","q":"Aunque parecen nuevos, estos zapatos ____ muy viejos.","o":["serían","son","estarían","están"],"a":1,"k":"ser vs estar (viejo)","t":"새것처럼 보이지만 이 신발은 아주 오래된 것이다.","e":"ser viejo는 '실제로 오래된 것이다(나이·연식)'라는 본질적 특성을, estar viejo는 '낡아 보인다, 헌 상태다'라는 상태를 말합니다. '새것처럼 보이지만(겉모습) 사실은 오래됐다(본질)'라는 대조이므로 son이 맞습니다. 사실을 말하므로 조건형은 쓰지 않습니다.","x":["serían: 조건형으로 추측을 나타내 사실 대조와 맞지 않습니다 ✗","son: 실제 연식을 말하는 ser → 정답 ✓","estarían: 조건형이고 상태 의미라 맞지 않습니다 ✗","están: '낡은 상태다'라는 뜻이 되어 '새것처럼 보인다'와 모순됩니다 ✗"]},{"id":"G210","q":"Sus bromas no tienen ____ gracia.","o":["alguna","ninguna","cierta","cualquier"],"a":1,"k":"ninguno (전혀 ~없다)","t":"그의 농담은 전혀 재미가 없다.","e":"부정문 'no + 동사' 뒤에서 '전혀 ~없다'라고 할 때 ninguno/a를 씁니다. gracia는 여성 명사이므로 ninguna가 됩니다. 'tener gracia'는 '재미있다, 웃기다'라는 표현으로, 'No tiene ninguna gracia'는 '하나도 안 웃기다'라는 단호한 말입니다.","x":["alguna: 부정문에서 명사 뒤(gracia alguna)에 오면 '전혀'의 뜻이 되지만 명사 앞에서는 부정 강조가 되지 않습니다 ✗","ninguna: 부정문의 '전혀 ~없는' → 정답 ✓","cierta: '어느 정도의'라는 뜻이라 부정문과 어울리지 않습니다 ✗","cualquier: '아무 ~나'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G211","q":"Tenemos que comentar ____ un tema muy serio.","o":["ø","a","por","de"],"a":0,"k":"comentar + 직접목적어","t":"우리는 아주 심각한 문제 하나를 이야기해야 한다.","e":"comentar(언급하다, 논의하다)는 타동사라서 '무엇을' 논의하는지를 전치사 없이 바로 씁니다: comentar un tema. 사물 목적어 앞에는 a를 붙이지 않습니다. 반면 hablar는 'hablar de un tema'처럼 de가 필요하니 헷갈리지 마세요.","x":["ø: comentar + 직접목적어, 전치사 없음 → 정답 ✓","a: 인칭 a는 사람 목적어 앞에만 붙이며 un tema는 사물입니다 ✗","por: comentar와 함께 쓰는 전치사가 아닙니다 ✗","de: 'hablar de'와 혼동한 것으로 comentar에는 de를 쓰지 않습니다 ✗"]},{"id":"G212","q":"No hay ____ malo en rechazar un plan si no nos gusta.","o":["algo de","nada de","ninguno de","alguno de"],"a":1,"k":"nada de + 형용사","t":"마음에 들지 않는 계획을 거절하는 데는 아무 잘못도 없다.","e":"'No hay nada de malo en + 동사원형'은 '~하는 데 나쁜 점은 하나도 없다'라는 관용 구문입니다. 부정문(no hay)이므로 부정어 nada가 와야 하고, 'nada de + 형용사 남성 단수'로 '~한 것 하나도'라는 뜻이 됩니다. 'Tiene algo de malo?(뭐 나쁜 점 있어?)'처럼 긍정·의문문에서는 algo de를 씁니다.","x":["algo de: 긍정·의문문에 쓰며 부정문 no hay와는 맞지 않습니다 ✗","nada de: 부정문의 '아무 ~한 것도' → 정답 ✓","ninguno de: '~중 아무도/아무것도'로 뒤에 복수 명사가 필요합니다 ✗","alguno de: '~중 어떤 것'으로 형용사 malo와 결합하지 않습니다 ✗"]},{"id":"G213","q":"No finjas que no me ____.","o":["conocerías","conozcas","conoces","conocieras"],"a":2,"k":"fingir que + 직설법","t":"나를 모르는 척하지 마.","e":"fingir que(~인 척하다)는 '꾸며 내는 내용'을 마치 사실처럼 제시하므로 뒤에 직설법을 씁니다. 바깥 동사가 부정 명령(no finjas)이어도 que절의 법은 바뀌지 않습니다. 예: Finge que está dormido(그는 자는 척한다).","x":["conocerías: 조건형으로 가정을 나타내 맞지 않습니다 ✗","conozcas: fingir que 뒤에는 접속법을 쓰지 않습니다 ✗","conoces: fingir que + 직설법 → 정답 ✓","conocieras: 접속법 과거로 시제와 법 모두 맞지 않습니다 ✗"]},{"id":"G214","q":"Su reacción hizo que luego ____ fatal consigo mismo.","o":["sintiera","se sintiera","se sentiría","se hubiera sentido"],"a":1,"k":"hacer que + 접속법","t":"그의 반응 때문에 그는 나중에 스스로 몹시 괴로워했다.","e":"'hacer que + 접속법'은 '~가 ~하게 만들다'라는 사역 구문입니다. 주절이 과거(hizo)이므로 접속법 과거 sintiera를 씁니다. 'sentirse + 형용사/부사'는 '(기분이) ~하다'라는 재귀동사라서 se가 필요하고, 'fatal'은 '아주 나쁘게'라는 구어입니다.","x":["sintiera: 재귀대명사 se가 빠져 '(무엇을) 느꼈다'가 되어 fatal과 맞지 않습니다 ✗","se sintiera: 재귀동사 + 접속법 과거 → 정답 ✓","se sentiría: 조건형이라 hacer que 뒤의 접속법 자리에 쓸 수 없습니다 ✗","se hubiera sentido: 접속법 과과거로 'luego(그 후에)'라는 이후 시점과 맞지 않습니다 ✗"]},{"id":"G215","q":"Tengo todos los ____ de este grupo.","o":["álbunes","álbumes","albums","álbums"],"a":1,"k":"외래어 복수형","t":"나는 이 그룹의 앨범을 모두 가지고 있다.","e":"álbum(앨범)의 복수형은 RAE(스페인 왕립 학술원) 규범에 따라 -es를 붙인 álbumes입니다. 악센트도 그대로 유지합니다. 비슷하게 currículum → currículums, club → clubes처럼 외래어는 단어마다 복수형이 다르니 따로 기억해 두세요.","x":["álbunes: m을 n으로 바꾸지 않습니다 ✗","álbumes: 표준 복수형 → 정답 ✓","albums: 악센트가 없고 영어식 복수라 틀립니다 ✗","álbums: 구어에서 들리지만 표준 형태는 álbumes입니다 ✗"]},{"id":"G216","q":"Mi abuelo me decía que tenemos que luchar ____ nuestros sueños.","o":["por","hacia","para","hasta"],"a":0,"k":"luchar por","t":"할아버지는 우리가 꿈을 위해 싸워야 한다고 말씀하시곤 했다.","e":"luchar por는 '~을 위해 싸우다, ~을 얻으려고 노력하다'라는 고정 표현입니다. por가 '대의·동기·얻고자 하는 것'을 나타냅니다. 예: luchar por la libertad(자유를 위해 싸우다). decía는 과거의 반복된 말을 나타내는 불완료과거입니다.","x":["por: luchar por '~을 위해 싸우다' → 정답 ✓","hacia: '~쪽으로'라는 방향이라 맞지 않습니다 ✗","para: 'luchar para + 동사원형(~하기 위해 싸우다)'은 가능하지만 명사 sueños 앞에는 por를 씁니다 ✗","hasta: '~까지'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G217","q":"El perro estuvo ladrando ____ noche.","o":["toda","todo el","todo","toda la"],"a":3,"k":"todo + 관사 + 명사","t":"개가 밤새도록 짖어 댔다.","e":"todo는 '전체의'라는 뜻으로 관사 앞에 두고 명사와 성·수를 일치시킵니다. noche는 여성 단수이므로 toda la noche(밤새도록)입니다. 같은 방식으로 todo el día(하루 종일), toda la semana(일주일 내내)라고 합니다.","x":["toda: 관사 la 없이 toda noche라고 하면 '모든 밤마다'처럼 의미가 달라지고 부자연스럽습니다 ✗","todo el: 남성형이라 여성 명사 noche와 맞지 않습니다 ✗","todo: 성도 맞지 않고 관사도 없습니다 ✗","toda la: 여성 단수 일치 + 관사, '밤새도록' → 정답 ✓"]},{"id":"G218","q":"Llevo ____ la mitad del libro.","o":["leyendo","leyéndola","habiendo leído","leída"],"a":3,"k":"llevar + 과거분사","t":"나는 그 책을 절반 읽었다.","e":"'llevar + 과거분사'는 '(지금까지) ~해 놓은 상태다'라는 진척·누적을 나타냅니다. 이때 과거분사는 목적어와 성·수를 일치시키므로 la mitad(여성 단수)에 맞춰 leída가 됩니다. 예: Llevo escritas diez páginas(나는 10쪽을 써 놓았다).","x":["leyendo: llevar + 현재분사는 '~한 지 (기간)째다'라는 뜻이라 기간 표현이 필요합니다 ✗","leyéndola: 이미 목적어 la mitad가 있으므로 대명사를 또 붙이면 중복됩니다 ✗","habiendo leído: 완료 현재분사는 llevar와 이 구조를 만들지 않습니다 ✗","leída: llevar + 목적어와 일치한 과거분사 → 정답 ✓"]},{"id":"G219","q":"Lo hizo ____ de que podría volverse en su contra.","o":["al saber","sabiendo","a sabiendas","sin saber"],"a":2,"k":"a sabiendas de que","t":"그는 그것이 자신에게 불리하게 돌아올 수 있다는 걸 알면서도 그렇게 했다.","e":"a sabiendas de que는 '~임을 잘 알면서도, 일부러'라는 뜻의 격식 있는 표현입니다. 위험이나 결과를 알고도 고의로 했다는 뉘앙스를 줍니다. 'volverse en contra de alguien'은 '~에게 불리하게 돌아오다, 역효과가 나다'라는 뜻입니다.","x":["al saber: 'al saber que'(~을 알자마자)는 de가 붙지 않습니다 ✗","sabiendo: 'sabiendo que'로 써야 하며 뒤에 de를 쓰지 않습니다 ✗","a sabiendas: a sabiendas de que '알면서도' → 정답 ✓","sin saber: 'sin saber que'로 써야 하며 의미도 반대('모른 채')입니다 ✗"]},{"id":"G220","q":"Hace un frío que pela, ____ voy a ponerme el abrigo antes de salir.","o":["pues","o sea","así que","ya que"],"a":2,"k":"결과 접속사 así que","t":"살을 에는 듯이 추우니까 나가기 전에 외투를 입을 거야.","e":"así que는 '그래서, 그러니까'라는 결과 접속사로, 앞 문장이 원인이고 뒤 문장이 결과입니다. 'Hace un frío que pela'는 '껍질이 벗겨질 정도로 춥다 = 몹시 춥다'라는 스페인 구어 관용 표현입니다.","x":["pues: '왜냐하면'이라는 이유를 나타내는 경우가 많아 결과 연결로는 부자연스럽습니다 ✗","o sea: '즉, 다시 말해'라는 재설명 표현입니다 ✗","así que: '그래서'라는 결과 → 정답 ✓","ya que: '~이기 때문에'라는 원인을 나타내 순서가 반대가 됩니다 ✗"]},{"id":"G221","q":"____ prisa, que no llegamos a tiempo.","o":["Dame","Date","Te das","Da"],"a":1,"k":"darse prisa (명령)","t":"서둘러, 제시간에 못 도착하겠어.","e":"darse prisa는 '서두르다'라는 재귀 표현이며, tú에 대한 긍정 명령은 da + te = date입니다. 스페인에서 매우 흔히 쓰고, 중남미에서는 보통 '¡Apúrate!'라고 합니다. 'que no llegamos'의 que는 '왜냐하면'의 구어적 연결입니다.","x":["Dame: '나에게 줘'라는 뜻이 되어 '서두르다'가 되지 않습니다 ✗","Date: darse prisa의 tú 긍정 명령 → 정답 ✓","Te das: 직설법 현재로 명령이 아닙니다 ✗","Da: 재귀대명사가 빠져 '서두르다'라는 뜻이 되지 않습니다 ✗"]},{"id":"G222","q":"Qué cuadro tan bonito. Estás hecho ____ un artista.","o":["bastante","mucho","menudo","todo"],"a":3,"k":"estar hecho todo un","t":"정말 멋진 그림이다. 너 완전히 진짜 예술가가 다 됐구나.","e":"'estar hecho + (todo) un/una + 명사'는 '완전히 ~가 되었다'라는 칭찬·감탄의 구어 표현입니다. todo un은 '진정한, 어엿한'이라는 강조로, 'Es todo un caballero(그는 진정한 신사다)'처럼 씁니다. 이 문장은 상대를 칭찬하며 약간 놀라는 뉘앙스입니다.","x":["bastante: '꽤'라는 정도 부사로 un artista 앞에 이런 강조로 쓰지 않습니다 ✗","mucho: 'mucho un artista'는 성립하지 않습니다 ✗","menudo: 'menudo artista'는 관사 없이 써야 하며 보통 반어적입니다 ✗","todo: estar hecho todo un '완전히 ~가 되다' → 정답 ✓"]},{"id":"G223","q":"Me gustaría que charláramos con calma. Ojalá no ____ mucha gente en la cafetería.","o":["ha habido","haya","haya habido","hayan"],"a":1,"k":"Ojalá + 접속법 현재","t":"차분하게 이야기하고 싶어. 카페에 사람이 많지 않으면 좋겠어.","e":"Ojalá(~하면 좋겠다) 뒤에는 접속법을 씁니다. 앞으로 갈 카페에 대한 바람이므로 접속법 현재 haya가 맞습니다. haber가 '있다'라는 뜻일 때는 뒤 명사가 복수여도 항상 단수형으로 씁니다(hay, haya, había…).","x":["ha habido: 직설법 현재완료라 ojalá 뒤에 쓸 수 없습니다 ✗","haya: ojalá + 접속법 현재, 앞으로의 바람 → 정답 ✓","haya habido: 접속법 현재완료로 '이미 사람이 없었기를' 바라는 뜻이 되어 시점이 맞지 않습니다 ✗","hayan: 존재의 haber는 복수형으로 쓰지 않습니다(비표준) ✗"]},{"id":"G224","q":"No conseguimos que nos ____ el sueldo a pesar de las protestas.","o":["aumentarían","aumentarán","aumentaran","aumentaren"],"a":2,"k":"conseguir que + 접속법","t":"항의에도 불구하고 우리는 월급을 올려 받지 못했다.","e":"'conseguir que + 접속법'은 '~가 ~하도록 만들다(해내다)'라는 뜻입니다. 주절이 과거(conseguimos, 단순과거)이므로 접속법 과거 aumentaran이 옵니다. 'a pesar de'는 '~에도 불구하고'라는 표현입니다.","x":["aumentarían: 조건형이라 conseguir que 뒤 접속법 자리에 쓸 수 없습니다 ✗","aumentarán: 미래형으로 과거 주절과 법·시제 모두 맞지 않습니다 ✗","aumentaran: 접속법 과거 → 정답 ✓","aumentaren: 접속법 미래로 오늘날 법률 문서 외에는 쓰지 않는 고어 형태입니다 ✗"]},{"id":"G225","q":"____ iba escribiendo, se me iban ocurriendo nuevas ideas.","o":["Desde que","Siempre y cuando","En el entretanto","A medida que"],"a":3,"k":"a medida que (~할수록)","t":"글을 써 나갈수록 새로운 아이디어가 계속 떠올랐다.","e":"a medida que는 '~함에 따라, ~할수록'이라는 뜻으로 두 일이 함께 비례해서 진행됨을 나타냅니다. 'ir + 현재분사(iba escribiendo)'와 잘 어울리는데, 둘 다 점진적인 과정을 나타내기 때문입니다. 비슷한 표현으로 conforme, según도 있습니다.","x":["Desde que: '~한 이후로'라는 시작점이라 점진적 비례 관계가 아닙니다 ✗","Siempre y cuando: '~하기만 한다면'이라는 조건이며 접속법과 씁니다 ✗","En el entretanto: '그동안에'라는 부사구로 que절을 이끌지 않습니다 ✗","A medida que: '~할수록' 비례 진행 → 정답 ✓"]},{"id":"G226","q":"Qué raro que Ana no nos ____ nada del tema todavía.","o":["habría dicho","ha dicho","haya dicho","había dicho"],"a":2,"k":"Qué raro que + 접속법","t":"아나가 그 일에 대해 아직 우리에게 아무 말도 안 한 게 참 이상하다.","e":"'Qué raro que…(~하다니 참 이상하다)'처럼 감정·평가를 나타내는 표현 뒤에는 접속법을 씁니다. todavía(아직)와 함께 현재까지 일어나지 않은 일을 말하므로 접속법 현재완료 haya dicho가 맞습니다.","x":["habría dicho: 조건완료로 가정을 나타내 평가 표현 뒤에 맞지 않습니다 ✗","ha dicho: 직설법이라 qué raro que 뒤에 쓸 수 없습니다 ✗","haya dicho: 평가 표현 + 접속법 현재완료 → 정답 ✓","había dicho: 직설법 과거완료라 법과 시제 모두 맞지 않습니다 ✗"]},{"id":"G227","q":"¿Por qué ____ sin despedirse?","o":["fueron","se vayan","iban","se fueron"],"a":3,"k":"irse (떠나다)","t":"왜 그들은 인사도 없이 가 버렸지?","e":"irse는 '(어떤 곳을) 떠나다, 가 버리다'라는 뜻으로, 단순히 '가다'인 ir와 다릅니다. 과거에 한 번 일어난 일이므로 단순과거 se fueron을 씁니다. despedirse(작별 인사를 하다)도 재귀동사입니다.","x":["fueron: ir만 쓰면 목적지가 필요하며 '떠나 버렸다'는 뜻이 되지 않습니다 ✗","se vayan: 접속법이라 단순 의문문에 쓸 이유가 없습니다 ✗","iban: 불완료과거로 '가고 있었다'라는 배경 묘사가 됩니다 ✗","se fueron: irse 단순과거 '떠나 버렸다' → 정답 ✓"]},{"id":"G228","q":"Alicia nos aconsejó que ____ a su tienda a primera hora.","o":["vamos","iríamos","fuéramos","va"],"a":2,"k":"aconsejar que + 접속법","t":"알리시아는 우리에게 아침 일찍 그녀의 가게에 가라고 조언했다.","e":"aconsejar(조언하다)처럼 영향·요청을 나타내는 동사 뒤 que절에는 접속법을 씁니다. 주절이 과거(aconsejó)이므로 접속법 과거 fuéramos가 옵니다. 'a primera hora'는 '(아침·오후의) 이른 시간에'라는 표현입니다.","x":["vamos: 직설법 현재라 aconsejar que 뒤에 쓸 수 없습니다 ✗","iríamos: 조건형으로 조언 내용에 쓰지 않습니다 ✗","fuéramos: 과거 주절 + 접속법 과거 → 정답 ✓","va: 3인칭 단수 직설법으로 주어와 법 모두 맞지 않습니다 ✗"]},{"id":"G229","q":"En caso de que no ____ la casa fácilmente, avísame y voy a buscarte.","o":["encuentro","encuentres","encuentras","encuentre"],"a":1,"k":"en caso de que + 접속법","t":"혹시 집을 쉽게 못 찾으면 나한테 알려 줘, 데리러 갈게.","e":"en caso de que(~하는 경우에)는 항상 접속법을 씁니다. 뒤의 avísame, buscarte에서 상대가 tú임을 알 수 있으므로 2인칭 단수 접속법 encuentres가 맞습니다. 'ir a buscar a alguien'은 '누구를 데리러 가다'입니다.","x":["encuentro: 1인칭 직설법이라 법도 인칭도 맞지 않습니다 ✗","encuentres: tú에 맞는 접속법 현재 → 정답 ✓","encuentras: 직설법이라 en caso de que 뒤에 쓸 수 없습니다 ✗","encuentre: 1·3인칭 접속법이라 tú와 맞지 않습니다 ✗"]},{"id":"G230","q":"____ conmigo cada vez que necesites algo.","o":["Contad","Cuente","Cuenta","Contáis"],"a":2,"k":"tú 긍정 명령","t":"뭐든 필요할 때마다 나를 믿고 말해.","e":"contar con alguien은 '~를 믿고 의지하다'라는 뜻입니다. 뒤의 necesites가 tú 형태이므로 tú 긍정 명령 cuenta를 씁니다(규칙적으로 3인칭 단수 현재형과 같음). 'Cuenta conmigo'는 '나만 믿어, 언제든 도와줄게'라는 다정한 표현입니다.","x":["Contad: vosotros 명령이라 necesites(tú)와 맞지 않습니다 ✗","Cuente: usted 명령이라 necesites(tú)와 맞지 않습니다(usted라면 necesite) ✗","Cuenta: tú 긍정 명령 → 정답 ✓","Contáis: vosotros 직설법 현재라 명령이 아닙니다 ✗"]},{"id":"G231","q":"Antes de tener a Emilia, yo ____ una persona muy descuidada.","o":["fui","era","ha sido","estaba"],"a":1,"k":"불완료과거 ser (과거 성격)","t":"에밀리아를 낳기 전에 나는 아주 덜렁대는 사람이었다.","e":"과거의 성격·특징처럼 일정 기간 지속된 상태를 묘사할 때는 불완료과거를 씁니다. 사람의 성격은 본질적 특성이라 ser를 사용하므로 era가 맞습니다. 'tener a + 아기'는 '아이를 낳다'라는 구어 표현이고, descuidado/a는 '부주의한, 덜렁대는'입니다.","x":["fui: 단순과거로 완결된 사건을 말할 때 쓰며, 과거의 지속적 성격 묘사로는 부자연스럽습니다 ✗","era: 과거 성격 묘사 ser 불완료과거 → 정답 ✓","ha sido: 현재완료로 'antes de' 이후 달라졌다는 과거 대조와 맞지 않습니다 ✗","estaba: estar는 성격이 아닌 일시적 상태에 씁니다 ✗"]},{"id":"G232","q":"Fueron ellos ____ empezaron la trifulca.","o":["los quienes","quienes","que","cuales"],"a":1,"k":"강조 구문 quienes","t":"싸움을 시작한 건 바로 그들이었다.","e":"'Ser + 사람 + quien(es)/el que…'는 '~한 사람은 바로 ~다'라는 강조 구문입니다. ellos가 복수이므로 quienes를 쓰고, 관사 없이 씁니다. 'Fueron ellos los que…'도 같은 뜻입니다. trifulca는 '소동, 싸움'이라는 구어 단어입니다.","x":["los quienes: quienes 앞에는 관사를 붙이지 않습니다 ✗","quienes: 복수 사람을 강조하는 관계사 → 정답 ✓","que: 사람 강조 구문에서 관사 없는 que는 표준적이지 않습니다(los que로 써야 함) ✗","cuales: 관사 없이 관계사로 쓰지 않습니다 ✗"]},{"id":"G233","q":"Ha llamado ____ Jesús preguntando por usted.","o":["alguien","un","un tal","algún"],"a":2,"k":"un tal + 이름","t":"헤수스라는 사람이 전화해서 당신을 찾았어요.","e":"'un tal + 이름'은 '~라는 (모르는) 사람'이라는 뜻으로, 화자가 그 사람을 잘 모른다는 뉘앙스를 줍니다. 예: Te busca un tal Pedro(페드로라는 사람이 너를 찾아). 'preguntar por alguien'은 '누구를 찾다, 누구의 안부를 묻다'입니다.","x":["alguien: '누군가'라는 대명사로 이름 앞에 오지 않습니다 ✗","un: 'un Jesús'는 '헤수스라는 이름의 사람 하나'처럼 어색합니다 ✗","un tal: '~라는 사람' → 정답 ✓","algún: 명사 앞 한정사로 사람 이름 앞에 쓰지 않습니다 ✗"]},{"id":"G234","q":"Si ____ más barata, reservaría una habitación con vistas al mar.","o":["es","fuera","era","sería"],"a":1,"k":"si + 접속법 과거","t":"더 싸다면 바다 전망 방을 예약할 텐데.","e":"현재 사실과 다르거나 가능성이 낮은 가정은 'si + 접속법 과거, 조건형' 구조로 씁니다. 주절이 조건형 reservaría이므로 si절에는 fuera가 옵니다. si 바로 뒤에는 조건형(sería)이나 접속법 현재를 쓰지 않는다는 점을 꼭 기억하세요.","x":["es: 직설법 현재는 현실적 조건이라 주절이 미래·현재형이 되어야 합니다 ✗","fuera: si + 접속법 과거 + 조건형 → 정답 ✓","era: 직설법 불완료과거는 이 가정 구조에 쓰지 않습니다 ✗","sería: si 바로 뒤에는 조건형을 쓰지 않습니다 ✗"]},{"id":"G235","q":"Me dijo que ____ a las 9, como muy tarde.","o":["vaya a venir","haya venido","vendría","habría venido"],"a":2,"k":"간접화법 조건형","t":"그는 늦어도 9시에는 오겠다고 내게 말했다.","e":"과거 시점(dijo)에서 본 미래를 전할 때는 조건형을 씁니다. 원래 말이 'Vendré a las 9'(9시에 올게)였다면 간접화법에서는 'dijo que vendría'가 됩니다. 'como muy tarde'는 '아무리 늦어도'라는 표현입니다.","x":["vaya a venir: 접속법이라 dijo que(정보 전달) 뒤에 쓰지 않습니다 ✗","haya venido: 접속법 현재완료로 법과 시제 모두 맞지 않습니다 ✗","vendría: 과거에서 본 미래 조건형 → 정답 ✓","habría venido: 조건완료로 '왔을 것이다'라는 완료 의미가 되어 맞지 않습니다 ✗"]},{"id":"G236","q":"____ apruebo todas las asignaturas, este será el mejor verano de mi vida.","o":["Si","Con tal de que","En caso de que","Como"],"a":0,"k":"si + 직설법 현재","t":"모든 과목을 통과하면 올여름은 내 인생 최고의 여름이 될 거야.","e":"실현 가능성 있는 조건은 'si + 직설법 현재, 직설법 미래' 구조로 씁니다. apruebo가 직설법 현재이므로 si만 가능합니다. 나머지 조건 접속사(con tal de que, en caso de que)는 접속법을 요구합니다.","x":["Si: si + 직설법 현재 조건 → 정답 ✓","Con tal de que: '~하기만 한다면' 뒤에는 접속법(apruebe)이 와야 합니다 ✗","En caso de que: '~하는 경우' 뒤에도 접속법이 와야 합니다 ✗","Como: 조건의 como 뒤에는 접속법이 오고, 직설법이면 '~이므로'라는 이유가 되어 의미가 달라집니다 ✗"]},{"id":"G237","q":"____ venir José, lo hará a partir de las diez.","o":["De","A","Entre","Con"],"a":0,"k":"de + 동사원형 (조건)","t":"호세가 온다면 10시 이후에 올 것이다.","e":"'de + 동사원형'은 'si(만약 ~라면)'와 같은 조건을 나타내는 격식 있는 구문입니다. 'De venir José'는 'Si viene José'와 같은 뜻입니다. 이 구조에서는 주어가 동사원형 뒤에 놓입니다. 예: De haberlo sabido, te lo habría dicho(알았더라면 너에게 말했을 텐데).","x":["De: de + 동사원형 = 조건 → 정답 ✓","A: 'a + 동사원형'은 명령(¡A comer!)이나 조건의 특수 표현(a no ser que)에 쓰입니다 ✗","Entre: '~사이에'라는 뜻이라 맞지 않습니다 ✗","Con: 'con + 동사원형'은 '~하기만 하면'이라는 다른 뉘앙스이고 이 문장 구조와 맞지 않습니다 ✗"]},{"id":"G238","q":"El ladrón se coló por la ventana de la cocina cuando ____ todos en el salón.","o":["estaríamos","estuvimos","habíamos estado","estábamos"],"a":3,"k":"불완료과거 (배경)","t":"우리가 모두 거실에 있을 때 도둑이 부엌 창문으로 몰래 들어왔다.","e":"과거 이야기에서 어떤 사건(도둑이 들어왔다, 단순과거)이 일어난 '배경 상황'은 불완료과거로 씁니다. '우리가 거실에 있었다'는 지속되던 상황이므로 estábamos가 맞습니다. colarse는 '몰래 들어가다, 새치기하다'라는 뜻입니다.","x":["estaríamos: 조건형으로 추측을 나타내 배경 묘사에 쓰지 않습니다 ✗","estuvimos: 단순과거는 완결된 사건으로, 다른 사건의 배경으로는 부자연스럽습니다 ✗","habíamos estado: 과거완료로 '이미 있었던 적이 있다'라는 뜻이 되어 동시 상황과 맞지 않습니다 ✗","estábamos: 배경 상황 불완료과거 → 정답 ✓"]},{"id":"G239","q":"Mi hermano ____ mucho a mi padre.","o":["se parece","parece","parecen","se parecen"],"a":0,"k":"parecerse a","t":"내 남동생은 아버지를 많이 닮았다.","e":"'parecerse a alguien'은 '~를 닮다'라는 재귀동사 구문입니다. 주어가 mi hermano(3인칭 단수)이므로 se parece가 됩니다. 그냥 parecer는 '~처럼 보이다'라는 뜻이라 a mi padre와 연결하면 의미가 어긋납니다. a mi padre의 a는 parecerse가 요구하는 전치사입니다.","x":["se parece: parecerse a, 3인칭 단수 → 정답 ✓","parece: se가 없으면 '닮다'가 아니라 '~처럼 보이다/~에게 ~로 여겨지다'라는 뜻이 됩니다 ✗","parecen: 복수형이라 주어 mi hermano와 맞지 않습니다 ✗","se parecen: 복수형이라 단수 주어와 맞지 않습니다 ✗"]},{"id":"G240","q":"¡Qué aburrimiento ____ fiesta! Vámonos a casa...","o":["por","para","de","con"],"a":2,"k":"¡Qué + 명사 + de + 명사!","t":"정말 지루한 파티다! 집에 가자…","e":"'¡Qué + 감정 명사 + de + 명사!'는 '정말 ~한 ~이다!'라는 감탄 구조입니다. '¡Qué aburrimiento de fiesta!'는 '파티가 정말 지루하다!'라는 뜻으로, 앞 명사(aburrimiento: 지루함)가 뒤 명사(fiesta)를 평가합니다. 'Vámonos'는 '(우리) 가자'라는 1인칭 복수 명령입니다.","x":["por: 이 감탄 구조에 쓰지 않습니다 ✗","para: 이 감탄 구조에 쓰지 않습니다 ✗","de: ¡Qué + 명사 + de + 명사! → 정답 ✓","con: 'con fiesta'라고 하면 '파티와 함께'가 되어 의미가 맞지 않습니다 ✗"]},{"id":"G241","q":"No es verdad que ____ a punto de quebrar.","o":["somos","seamos","estemos","son"],"a":2,"k":"estar a punto de + 접속법","t":"우리가 파산 직전이라는 건 사실이 아니다.","e":"'estar a punto de + 동사원형'은 '막 ~하려는 참이다, ~할 직전이다'라는 표현으로 항상 estar를 씁니다. 'No es verdad que(~은 사실이 아니다)'는 부정·부인 표현이라 뒤에 접속법이 오므로 estemos가 됩니다. quebrar는 '파산하다'라는 뜻입니다.","x":["somos: ser는 a punto de와 쓰지 않고, 직설법이라 법도 맞지 않습니다 ✗","seamos: 접속법은 맞지만 a punto de는 estar와 씁니다 ✗","estemos: estar a punto de + 부인 표현 뒤 접속법 → 정답 ✓","son: ser이며 직설법이라 두 가지 모두 틀립니다 ✗"]},{"id":"G242","q":"Nos equivocamos de autobús y cogimos uno que ____ a otro barrio.","o":["fue","iría","iba","estaba yendo"],"a":2,"k":"불완료과거 (묘사)","t":"우리는 버스를 잘못 타서 다른 동네로 가는 버스를 탔다.","e":"관계절 'uno que iba a otro barrio'는 그 버스의 특징(다른 동네로 가는 버스)을 묘사합니다. 과거의 대상이나 상황을 묘사할 때는 불완료과거를 쓰므로 iba가 맞습니다. 'equivocarse de + 명사'는 '~을 잘못 고르다'라는 표현이고, coger(타다)는 스페인에서 흔하며 중남미에서는 tomar를 씁니다.","x":["fue: 단순과거는 완결된 사건을 말해 버스 노선 묘사에는 부자연스럽습니다 ✗","iría: 조건형으로 추측·가정을 나타내 맞지 않습니다 ✗","iba: 과거 묘사의 불완료과거 → 정답 ✓","estaba yendo: 진행형은 그 순간 이동 중임을 강조해 노선 묘사에 어색합니다 ✗"]},{"id":"G243","q":"A esta actriz ____ ha subido la fama a la cabeza.","o":["se le","le","la","se la"],"a":0,"k":"subírsele a la cabeza","t":"이 여배우는 인기 때문에 우쭐해졌다.","e":"'subírsele algo a la cabeza a alguien'은 '(명성·성공 등이) 머리끝까지 올라 우쭐해지다, 거만해지다'라는 관용 표현입니다. se는 고정이고, 영향을 받는 사람(a esta actriz)을 간접목적격 le로 받습니다. 술이 '머리에 오르다(취하다)'라는 뜻으로도 씁니다.","x":["se le: subírsele a la cabeza 구문 → 정답 ✓","le: se가 빠지면 '(누군가가) 그녀에게 명성을 올렸다'처럼 어색해집니다 ✗","la: 직접목적격이라 이 구문에 쓰지 않습니다 ✗","se la: la는 직접목적격으로 간접목적격 le가 필요한 자리에 맞지 않습니다 ✗"]},{"id":"G244","q":"María no ____ molesta cuando dicen algo de ella, le da igual.","o":["la","le","se","se la"],"a":2,"k":"molestarse (기분 상하다)","t":"마리아는 사람들이 자기에 대해 뭐라고 해도 기분 나빠하지 않는다, 신경 안 쓴다.","e":"molestar는 '(누구를) 귀찮게 하다'라는 타동사이고, molestarse는 '(스스로) 기분이 상하다, 언짢아하다'라는 재귀동사입니다. 주어가 마리아 자신이므로 se molesta가 맞습니다. 'Le da igual'은 '그녀에게는 상관없다'라는 표현입니다.","x":["la: 'no la molesta'는 '(그것이) 그녀를 귀찮게 하지 않는다'로, 그러면 María가 주어일 수 없습니다 ✗","le: 마찬가지로 María를 목적어로 만드는 형태라 주어 María와 맞지 않습니다 ✗","se: molestarse '기분 상하다' → 정답 ✓","se la: 이 두 대명사의 조합은 이 문장에서 의미가 성립하지 않습니다 ✗"]},{"id":"G245","q":"Os agradezco ____ corazón vuestra inestimable ayuda.","o":["a","con","en","de"],"a":3,"k":"de corazón","t":"너희의 귀중한 도움에 진심으로 감사한다.","e":"de corazón은 '진심으로, 마음속 깊이'라는 관용 표현입니다. agradecer(감사하다)는 '감사하는 대상'을 직접목적어로 받으므로 'agradecer la ayuda'처럼 por 없이 씁니다. inestimable은 '헤아릴 수 없이 귀한'이라는 격식 있는 형용사입니다.","x":["a: 'a corazón'이라는 표현은 없습니다 ✗","con: 'con todo mi corazón'은 가능하지만 'con corazón'만으로는 이 뜻이 되지 않습니다 ✗","en: 'en corazón'이라는 표현은 없습니다 ✗","de: de corazón '진심으로' → 정답 ✓"]},{"id":"G246","q":"Siempre pago mis facturas ____ principios de mes.","o":["por","a","de","en"],"a":1,"k":"a principios de","t":"나는 항상 월초에 공과금을 낸다.","e":"a principios de는 '~초에', a mediados de는 '~중순에', a finales de는 '~말에'라는 시기 표현으로 모두 전치사 a를 씁니다. 예: a principios de año(연초에), a finales de mayo(5월 말에). factura는 '청구서, 영수증'입니다.","x":["por: 'por principios de'라는 표현은 없습니다 ✗","a: a principios de '~초에' → 정답 ✓","de: 'de principios de'는 '~초부터의'라는 다른 의미입니다 ✗","en: 'en principio'는 '원칙적으로'라는 다른 표현입니다 ✗"]},{"id":"G247","q":"Nunca ____ casarse porque no encontró a la persona ideal para él.","o":["se echó a","se puso a","acabó de","llegó a"],"a":3,"k":"llegar a + 동사원형","t":"그는 자신에게 이상적인 사람을 찾지 못해 결국 결혼하지 않았다.","e":"'llegar a + 동사원형'은 '(마침내) ~하기에 이르다'라는 뜻이며, 부정문 'nunca llegó a casarse'는 '끝내 결혼에 이르지 못했다'라는 뉘앙스입니다. 기대하거나 가능했던 일이 끝내 이루어지지 않았음을 표현합니다.","x":["se echó a: echarse a는 '갑자기 ~하기 시작하다(울다, 웃다, 뛰다)'에 쓰입니다 ✗","se puso a: ponerse a는 '~하기 시작하다'로 결혼에는 어울리지 않습니다 ✗","acabó de: acabar de는 '막 ~했다'라는 뜻으로 의미가 맞지 않습니다 ✗","llegó a: '끝내 ~하기에 이르다' → 정답 ✓"]},{"id":"G248","q":"Me irrita que me trates como si ____ tonto.","o":["fuera","soy","sería","sea"],"a":0,"k":"como si + 접속법 과거","t":"나를 바보처럼 대하는 게 짜증 나.","e":"como si(마치 ~인 것처럼)는 항상 접속법 과거(또는 과거완료)를 씁니다. 현재 일을 말해도 como si 뒤에는 fuera가 옵니다. 'Me irrita que'는 감정 표현이라 뒤에 접속법 trates가 쓰였습니다.","x":["fuera: como si + 접속법 과거 → 정답 ✓","soy: como si 뒤에는 직설법을 쓰지 않습니다 ✗","sería: como si 뒤에는 조건형을 쓰지 않습니다 ✗","sea: como si 뒤에는 접속법 현재를 쓰지 않습니다 ✗"]},{"id":"G249","q":"Qué extraño, Amelia dijo que ____ a la fiesta, pero al final no ha aparecido.","o":["vendría","vendrá","venga","viniera"],"a":0,"k":"간접화법 조건형","t":"이상하네, 아멜리아가 파티에 오겠다고 했는데 결국 나타나지 않았어.","e":"과거에 한 말(dijo)에서 그 당시의 미래를 전할 때는 조건형을 씁니다. 원래 말 'Iré/Vendré a la fiesta'가 간접화법에서 'dijo que vendría'가 됩니다. 'al final'은 '결국', aparecer는 '나타나다'입니다.","x":["vendría: 과거에서 본 미래 조건형 → 정답 ✓","vendrá: 미래형은 아직 올 가능성이 남은 경우에 쓰는데, 이미 오지 않았으므로 맞지 않습니다 ✗","venga: 접속법이라 decir que(정보 전달) 뒤에 쓰지 않습니다 ✗","viniera: 접속법 과거는 decir가 '명령'의 뜻일 때(오라고 했다) 씁니다 ✗"]},{"id":"G250","q":"____ tan tranquilos cuando de pronto escuchamos la explosión.","o":["Caminamos","Éramos caminando","Íbamos caminando","Fuimos caminando"],"a":2,"k":"ir + 현재분사 (배경)","t":"우리가 아주 평온하게 걷고 있는데 갑자기 폭발음이 들렸다.","e":"'cuando de pronto…(그때 갑자기)'로 사건이 끼어드는 구조에서는 앞 부분이 진행 중이던 배경이 되므로 불완료과거를 씁니다. 'ir + 현재분사'는 '~하며 가고 있었다'로, íbamos caminando는 '걸어가고 있었다'입니다. 'estábamos caminando'와 비슷한 의미입니다.","x":["Caminamos: 단순과거로 완결된 행동이라 배경이 되지 못합니다 ✗","Éramos caminando: ser는 현재분사와 진행형을 만들지 않습니다 ✗","Íbamos caminando: 진행 중이던 배경 불완료과거 → 정답 ✓","Fuimos caminando: '걸어서 갔다'라는 완결된 사건이 되어 배경 의미가 아닙니다 ✗"]},{"id":"G251","q":"No voy al teatro ____ hace tres años.","o":["por","de","desde","hasta"],"a":2,"k":"desde hace (부정 기간)","t":"나는 3년 전부터 극장에 가지 않는다.","e":"'desde hace + 기간'은 '~ 전부터 (지금까지)'라는 뜻입니다. 부정문과 함께 쓰면 '그 기간 동안 계속 ~하지 않았다'라는 의미가 됩니다. 'hace tres años'는 '3년 전'이므로 앞에 desde를 붙여 '3년 전부터'가 됩니다. 비슷하게 'Hace tres años que no voy al teatro'라고도 합니다.","x":["por: 'por hace'라는 조합은 없습니다 ✗","de: 'de hace tres años'는 '3년 전의(것)'라는 수식 표현입니다 ✗","desde: desde hace '~ 전부터' → 정답 ✓","hasta: 'hasta hace tres años'는 '3년 전까지'로 의미가 반대가 됩니다 ✗"]},{"id":"G252","q":"____ mis gafas de sol.","o":["Se me ha perdido","Me he perdido","He perdido","Me estaba perdiendo"],"a":2,"k":"perder (잃어버리다)","t":"선글라스를 잃어버렸다.","e":"perder는 '~을 잃어버리다'라는 타동사로 'He perdido mis gafas'가 가장 기본적인 표현입니다. 비의도 구문(실수로 잃어버림)을 쓰면 'Se me han perdido las gafas'처럼 동사가 복수 주어 gafas와 일치해야 합니다. 스페인에서는 gafas, 중남미에서는 lentes, anteojos를 주로 씁니다.","x":["Se me ha perdido: 비의도 구문은 가능하지만 동사가 단수라 복수 gafas와 맞지 않습니다(han이어야 함) ✗","Me he perdido: '내가 길을 잃었다'라는 뜻이 됩니다 ✗","He perdido: '~을 잃어버렸다' → 정답 ✓","Me estaba perdiendo: '나는 길을 잃어 가고 있었다/놓치고 있었다'라는 다른 뜻입니다 ✗"]},{"id":"G253","q":"A veces vivimos como si los recursos del planeta no ____ a agotar jamás.","o":["fuesen","se irían","se fueran","se van"],"a":2,"k":"como si + 접속법 과거","t":"때때로 우리는 지구의 자원이 절대 고갈되지 않을 것처럼 살아간다.","e":"como si 뒤에는 항상 접속법 과거가 옵니다. 'ir a + 동사원형(~할 것이다)'이 como si 안에 들어가면 'se fueran a agotar'가 됩니다. agotarse(다 떨어지다, 고갈되다)는 재귀동사로, 여기서는 se가 ir 앞으로 이동했습니다.","x":["fuesen: ser/ir의 접속법 과거지만 agotarse의 se가 없어 '자원이 고갈되다'라는 뜻이 되지 않습니다 ✗","se irían: 조건형이라 como si 뒤에 쓸 수 없습니다 ✗","se fueran: como si + 접속법 과거, se 포함 → 정답 ✓","se van: 직설법이라 como si 뒤에 쓸 수 없습니다 ✗"]},{"id":"G254","q":"A mi padre ____ beber zumo de limón en ayunas.","o":["le ha dado por","le ha dado a","se ha dado en","se le ha dado por"],"a":0,"k":"darle por + 동사원형","t":"우리 아버지는 빈속에 레몬주스를 마시는 데 빠지셨다.","e":"'darle a alguien por + 동사원형'은 '(갑자기) ~하는 데 빠지다, ~하는 버릇이 생기다'라는 구어 표현입니다. 다소 엉뚱하거나 새로운 습관에 대해 말할 때 씁니다. 예: Le ha dado por correr(그는 달리기에 빠졌다). 'en ayunas'는 '공복에'입니다.","x":["le ha dado por: darle por '~에 빠지다' → 정답 ✓","le ha dado a: 'darle a algo'는 '~을 열심히 하다/치다'라는 다른 구어 의미이고 동사원형과 이 뜻으로 쓰지 않습니다 ✗","se ha dado en: 이런 조합은 쓰지 않습니다 ✗","se le ha dado por: se가 들어간 형태는 일부 중남미 구어에 있지만 표준은 se 없이 씁니다 ✗"]},{"id":"G255","q":"La otra noche ____ sobre la gastronomía japonesa.","o":["hemos hablado","estábamos hablando","estuvimos hablando","hemos estado hablando"],"a":2,"k":"estar 단순과거 진행형","t":"요전날 밤 우리는 일본 요리에 대해 한동안 이야기했다.","e":"'La otra noche(요전날 밤)'는 이미 끝난 과거 시점이라 현재완료가 아닌 단순과거를 씁니다. 'estuvimos hablando'(estar 단순과거 + 현재분사)는 '일정 시간 동안 ~하고 있었다(그리고 끝났다)'라는 완결된 지속 행동을 나타냅니다.","x":["hemos hablado: 현재완료는 오늘·이번 주처럼 현재와 이어진 시간에 쓰므로 la otra noche와 맞지 않습니다 ✗","estábamos hablando: 불완료과거 진행형은 다른 사건의 배경일 때 자연스러워 단독으로는 이야기가 덜 끝납니다 ✗","estuvimos hablando: 끝난 과거 시점의 완결된 지속 행동 → 정답 ✓","hemos estado hablando: 현재완료 진행형으로 la otra noche와 시간이 맞지 않습니다 ✗"]},{"id":"G256","q":"Cuando hace calor, bajo ____ persianas de la casa.","o":["todas","cada","todas y cada","todas las"],"a":3,"k":"todas las + 명사","t":"더우면 나는 집의 블라인드를 전부 내린다.","e":"todo/a는 '모든'이라는 뜻일 때 정관사 앞에 두어 'todas las persianas'처럼 씁니다. persiana(블라인드, 셔터)는 여성 복수이므로 todas las가 됩니다. 'todas y cada una de las persianas'처럼 강조할 수도 있지만 그때는 'una de las'가 필요합니다.","x":["todas: 정관사가 빠져 'todas persianas'는 틀린 형태입니다 ✗","cada: '각각의'는 단수 명사와 써야 합니다(cada persiana) ✗","todas y cada: 'todas y cada una de las'까지 써야 완성됩니다 ✗","todas las: todas + 정관사 + 복수 명사 → 정답 ✓"]},{"id":"G257","q":"Yo, ____ que te conozco, soy otra persona.","o":["hasta que","desde","de","antes de"],"a":1,"k":"desde que (~한 이후로)","t":"나는 너를 알게 된 이후로 다른 사람이 되었어.","e":"desde que는 '~한 이후로 (지금까지)'라는 뜻으로 변화가 시작된 시점을 나타냅니다. 현재형 conozco와 함께 쓰여 '너를 알게 된 뒤부터 계속'이라는 뜻이 됩니다. 'ser otra persona'는 '딴사람이 되다'라는 표현입니다.","x":["hasta que: '~할 때까지'라는 끝 시점이라 의미가 맞지 않습니다 ✗","desde: desde que '~한 이후로' → 정답 ✓","de: 'de que'는 시간 표현을 만들지 않습니다 ✗","antes de: 'antes de que + 접속법(conozca)'이 되어야 하고 의미도 반대입니다 ✗"]},{"id":"G258","q":"Los jugadores entraban en el campo ____ los iban nombrando.","o":["al tiempo","según","a medida","hasta que"],"a":1,"k":"según (~하는 대로)","t":"선수들은 이름이 불리는 대로 차례차례 경기장에 들어왔다.","e":"según은 활용된 동사 앞에서 '~하는 대로, ~함에 따라(동시에 진행)'라는 접속사 역할을 합니다. 'según los iban nombrando'는 '이름을 하나씩 부르는 대로'라는 뜻이며, a medida que, conforme와 비슷합니다. 'ir + 현재분사'가 점진적 진행을 나타냅니다.","x":["al tiempo: 'al tiempo que'가 되어야 하며 que가 빠졌습니다 ✗","según: '~하는 대로' 동시 진행 → 정답 ✓","a medida: 'a medida que'가 되어야 하며 que가 빠졌습니다 ✗","hasta que: '~할 때까지'로 의미가 맞지 않습니다 ✗"]},{"id":"G259","q":"Todavía no han dado ____ el responsable del accidente.","o":["con","sobre","en","para"],"a":0,"k":"dar con (찾아내다)","t":"아직 사고 책임자를 찾아내지 못했다.","e":"'dar con algo/alguien'은 '(찾던 것을) 찾아내다, 마주치다'라는 관용 동사구입니다. 'dar con el responsable'은 '책임자를 찾아내다'라는 뜻입니다. 예: Por fin di con la solución(마침내 해결책을 찾아냈다). 이 구조에서 주어는 막연한 '그들(당국)'입니다.","x":["con: dar con '찾아내다' → 정답 ✓","sobre: 'dar sobre'는 이 뜻으로 쓰지 않습니다 ✗","en: 'dar en'은 '(목표에) 맞히다'라는 다른 뜻입니다 ✗","para: 'dar para'는 '(~하기에) 충분하다'라는 다른 뜻입니다 ✗"]},{"id":"G260","q":"Me ____ el último bizcocho que hiciste.","o":["ha encantado","encanté","encantaba","encantó"],"a":3,"k":"encantar 단순과거","t":"네가 지난번에 만든 스펀지케이크 정말 맛있었어.","e":"encantar(정말 마음에 들다)는 gustar처럼 대상(el último bizcocho)이 주어이므로 3인칭 단수를 씁니다. 지난번에 먹고 끝난 경험이므로 단순과거 encantó가 자연스럽습니다. 스페인에서 오늘 막 먹은 경우라면 'me ha encantado'도 쓸 수 있습니다.","x":["ha encantado: 현재완료는 오늘처럼 현재와 이어진 시간에 쓰며, hiciste(지난번)라는 과거 문맥에는 단순과거가 더 자연스럽습니다 ✗","encanté: 1인칭(내가 매혹했다)이라 gustar형 구조와 맞지 않습니다 ✗","encantaba: 불완료과거는 반복·지속을 나타내 한 번의 경험에는 맞지 않습니다 ✗","encantó: 한 번 완결된 과거 경험, 3인칭 단수 → 정답 ✓"]},{"id":"G261","q":"No ____ de la sala sin recoger sus pertenencias.","o":["van","vayan","se vayan","os vais"],"a":2,"k":"ustedes 부정 명령","t":"소지품을 챙기지 않고 방을 나가지 마세요.","e":"sus pertenencias(여러분의 소지품)로 보아 ustedes에게 하는 말입니다. ustedes 부정 명령은 'no + 접속법 현재'이고, irse(떠나다)는 재귀동사이므로 'no se vayan'이 됩니다. 중남미에서는 친구들끼리도 ustedes를 쓰므로 이 형태가 매우 흔합니다.","x":["van: 직설법이라 명령이 아니고 se도 없습니다 ✗","vayan: 접속법이지만 irse의 se가 빠져 '떠나다'라는 뜻이 되지 않습니다 ✗","se vayan: ustedes 부정 명령, 재귀동사 → 정답 ✓","os vais: vosotros 직설법이라 sus(ustedes)와 맞지 않고 명령도 아닙니다 ✗"]},{"id":"G262","q":"Cuando mis abuelos se casaron, ni siquiera ____ casa propia.","o":["tenían","tuvieron","tendrían","estaban teniendo"],"a":0,"k":"불완료과거 (과거 상태)","t":"조부모님이 결혼하셨을 때는 자기 집조차 없으셨다.","e":"과거 특정 시점(결혼했을 때)의 소유·상황을 묘사할 때는 불완료과거를 씁니다. '자기 집이 없었다'는 지속된 상태이므로 tenían이 맞습니다. 'ni siquiera'는 '~조차 (없다)'라는 강조 부정입니다.","x":["tenían: 과거 상태 묘사 불완료과거 → 정답 ✓","tuvieron: 단순과거 tener는 '얻었다, 생겼다'라는 사건 의미가 되어 상태 묘사로 어색합니다 ✗","tendrían: 조건형으로 추측을 나타내 사실 묘사와 맞지 않습니다 ✗","estaban teniendo: tener는 소유의 의미로 진행형을 쓰지 않습니다 ✗"]},{"id":"G263","q":"Cuente conmigo si le ____ falta algo.","o":["haría","haga","hará","hace"],"a":3,"k":"si + 직설법 현재","t":"뭔가 필요하시면 저를 믿고 말씀하세요.","e":"si(만약 ~라면) 조건절에는 접속법 현재·조건형·미래형을 쓰지 않고 직설법 현재를 씁니다. 'hacer falta a alguien'은 '(누구에게) ~이 필요하다'라는 표현으로 gustar처럼 le를 씁니다. cuente(usted 명령)와 le가 모두 존칭입니다.","x":["haría: si절에는 조건형을 쓰지 않습니다 ✗","haga: si절에는 접속법 현재를 쓰지 않습니다 ✗","hará: si절에는 미래형을 쓰지 않습니다 ✗","hace: si + 직설법 현재 → 정답 ✓"]},{"id":"G264","q":"Según ____, ¿cómo deberíamos abordar este asunto?","o":["tu","ti","tú","por ti"],"a":2,"k":"según + 주격 대명사","t":"네 생각엔 우리가 이 문제를 어떻게 다뤄야 할까?","e":"대부분의 전치사 뒤에는 mí, ti 같은 전치격 대명사를 쓰지만, según, entre, excepto 등은 예외로 주격 대명사(yo, tú)를 씁니다. 그래서 'según tú(네 말에 따르면, 네 생각엔)', 'según yo'가 됩니다. abordar는 '(문제를) 다루다'입니다.","x":["tu: 악센트 없는 tu는 소유형용사(너의)로 뒤에 명사가 필요합니다 ✗","ti: según 뒤에는 전치격 ti를 쓰지 않습니다 ✗","tú: según + 주격 대명사 → 정답 ✓","por ti: 'según por ti'는 성립하지 않습니다 ✗"]},{"id":"G265","q":"El hombre se alejó del grupo y, de pronto, estaba solo ____ el peligro.","o":["ante","delante","frente","en"],"a":0,"k":"전치사 ante (직면)","t":"그 남자는 무리에서 떨어졌고, 갑자기 위험 앞에 홀로 놓였다.","e":"ante는 '~앞에, ~에 직면하여'라는 뜻으로 추상적인 상황(위험, 문제, 어려움)과 잘 어울립니다. 'solo ante el peligro'는 '위험 앞에 홀로'라는 극적인 표현입니다. delante와 frente는 뒤에 de가 있어야 명사를 받을 수 있습니다(delante de, frente a).","x":["ante: '~앞에, ~에 직면하여' → 정답 ✓","delante: 'delante del peligro'처럼 de가 필요합니다 ✗","frente: 'frente al peligro'처럼 a가 필요합니다 ✗","en: 'en el peligro'는 '위험 속에'로 의미가 달라집니다 ✗"]},{"id":"G266","q":"Me muero ____ sed, ¿me das un vaso de agua?","o":["con","en","por","de"],"a":3,"k":"morirse de + 명사","t":"목말라 죽겠어, 물 한 잔 줄래?","e":"'morirse de + 명사'는 '~해서 죽겠다'라는 과장된 구어 표현으로 원인을 de로 나타냅니다. 예: Me muero de hambre(배고파 죽겠다), Me muero de risa(웃겨 죽겠다), Me muero de ganas de verte(너무 보고 싶어). 'tener sed'와 같은 의미를 강하게 말하는 것입니다.","x":["con: 원인을 나타내지 못합니다 ✗","en: 이 표현에 쓰지 않습니다 ✗","por: 'morirse por + 명사/동사원형'은 '~을 몹시 원하다'라는 다른 뜻입니다 ✗","de: morirse de '~해서 죽겠다' → 정답 ✓"]},{"id":"G267","q":"¡Quién ____ veinte años menos!","o":["tenía","tendrá","tendría","tuviera"],"a":3,"k":"¡Quién + 접속법 과거!","t":"20년만 더 젊다면 얼마나 좋을까!","e":"'¡Quién + 접속법 과거!'는 '(내가) ~라면 좋을 텐데!'라는 실현 불가능한 소망을 나타내는 관용 감탄문입니다. tuviera는 tener의 접속법 과거(tuviese도 가능)입니다. 'tener veinte años menos'는 '나이가 20살 적다'라는 뜻입니다.","x":["tenía: 직설법 불완료과거라 소망 감탄문에 쓸 수 없습니다 ✗","tendrá: 미래형으로 '누가 가질까?'라는 추측 의문이 됩니다 ✗","tendría: 조건형은 이 관용 구문에 쓰지 않습니다 ✗","tuviera: ¡Quién + 접속법 과거! → 정답 ✓"]},{"id":"G268","q":"Si es tan amable, ____ el recibo para que podamos cambiarle el producto.","o":["tráiganos","nos lo traiga","tráenos","traed"],"a":0,"k":"usted 긍정 명령 + 대명사","t":"괜찮으시다면 영수증을 가져다주세요, 그래야 제품을 교환해 드릴 수 있어요.","e":"'Si es tan amable(친절하시다면 = 괜찮으시다면)'은 usted에게 하는 정중한 부탁입니다. usted 긍정 명령은 접속법 형태(traiga)를 쓰고, 목적격 대명사는 뒤에 붙입니다: tráiganos(저희에게 가져다주세요). 대명사가 붙으면 강세를 지키기 위해 악센트를 찍습니다.","x":["tráiganos: usted 긍정 명령 + nos → 정답 ✓","nos lo traiga: 긍정 명령은 대명사를 뒤에 붙여야 하고, el recibo가 있는데 lo를 또 쓰면 중복됩니다 ✗","tráenos: tú 명령이라 'Si es tan amable'(usted)과 맞지 않습니다 ✗","traed: vosotros 명령이라 usted와 맞지 않습니다 ✗"]},{"id":"G269","q":"Si ____ todos, sería un día perfecto.","o":["vendréis","vinierais","vendríais","viniereis"],"a":1,"k":"si + 접속법 과거","t":"너희가 모두 온다면 완벽한 하루가 될 텐데.","e":"주절이 조건형(sería)인 가정문에서는 si절에 접속법 과거를 씁니다. 주어가 vosotros(너희)이므로 venir의 접속법 과거 vinierais가 됩니다. 중남미에서는 ustedes를 써서 'Si vinieran todos'라고 합니다.","x":["vendréis: si절에는 미래형을 쓰지 않습니다 ✗","vinierais: si + 접속법 과거 + 조건형 → 정답 ✓","vendríais: si절에는 조건형을 쓰지 않습니다 ✗","viniereis: 접속법 미래로 현대 일상어에서는 쓰지 않는 고어 형태입니다 ✗"]},{"id":"G270","q":"Dicen que ayer ____ una pelea en este barrio.","o":["habría","hay","ha habido","hubo"],"a":3,"k":"hubo (단순과거 haber)","t":"어제 이 동네에서 싸움이 있었다고 한다.","e":"'ayer(어제)'처럼 끝난 과거 시점의 사건은 단순과거로 표현합니다. '~이 있었다(사건이 발생했다)'는 haber의 단순과거 hubo입니다. 'Dicen que'는 '~라고들 한다'라는 전언 표현입니다.","x":["habría: 조건형으로 '있었을 것이다'라는 추측이 되어 ayer와 맞지 않습니다 ✗","hay: 현재형이라 ayer와 시제가 맞지 않습니다 ✗","ha habido: 현재완료는 스페인 표준에서 ayer와 함께 쓰지 않습니다 ✗","hubo: 끝난 과거 사건 haber 단순과거 → 정답 ✓"]},{"id":"G271","q":"Odio que me hables así. ¿Es ____ no sabes lo que es el respeto?","o":["ya que","que","qué","como"],"a":1,"k":"¿Es que…? (강조 의문)","t":"네가 나한테 그렇게 말하는 거 정말 싫어. 너 존중이 뭔지 모르는 거야?","e":"'¿Es que…?'는 '혹시 ~라는 거야?, 설마 ~인 거야?'라는 구어 의문 표현으로, 상대의 행동에 놀라거나 따지는 뉘앙스가 있습니다. 'Es que…'는 평서문에서 '그게 말이야, ~해서 그래'라는 변명·설명으로도 자주 씁니다. 여기서 que는 접속사라 악센트를 찍지 않습니다.","x":["ya que: '~이기 때문에'라는 이유 접속사로 ¿Es…? 뒤에 맞지 않습니다 ✗","que: ¿Es que…? '설마 ~인 거야?' → 정답 ✓","qué: 악센트 있는 의문사 '무엇'으로 'Es qué'는 성립하지 않습니다 ✗","como: 'Es como…'는 '~같은 거야'라는 비유가 되어 문장이 성립하지 않습니다 ✗"]},{"id":"G272","q":"Llegamos con retraso ____ el atasco que pillamos.","o":["a causa","por","gracias","debido"],"a":1,"k":"por (원인)","t":"우리는 꽉 막힌 교통 체증 때문에 늦게 도착했다.","e":"por는 '~ 때문에'라는 원인을 나타내며 바로 명사를 받을 수 있습니다. 같은 뜻의 a causa de, debido a, gracias a는 뒤에 de나 a가 꼭 있어야 합니다. 'pillar un atasco'는 '교통 체증에 걸리다'라는 스페인 구어 표현입니다(중남미에서는 'agarrar un trancón/tráfico' 등).","x":["a causa: 'a causa de'처럼 de가 필요합니다 ✗","por: 원인의 por + 명사 → 정답 ✓","gracias: 'gracias a'가 필요하고 긍정적 원인에 쓰므로 의미도 맞지 않습니다 ✗","debido: 'debido a'처럼 a가 필요합니다 ✗"]},{"id":"G273","q":"____ al verte el brazo roto.","o":["Te desmayé","Me desmayé","Lo desmayé","Desmayé"],"a":1,"k":"desmayarse (기절하다)","t":"네 팔이 부러진 걸 보고 나는 기절했다.","e":"desmayarse(기절하다)는 재귀동사로 항상 재귀대명사와 함께 씁니다. 내가 기절한 것이므로 'me desmayé'가 됩니다. 'al + 동사원형'은 '~하자, ~할 때'라는 동시 표현입니다(al verte: 너를 보았을 때).","x":["Te desmayé: '내가 너를 기절시켰다'처럼 들리며 desmayar는 이렇게 쓰지 않습니다 ✗","Me desmayé: 재귀동사 1인칭 단순과거 → 정답 ✓","Lo desmayé: 타동사처럼 쓴 형태로 의미가 맞지 않습니다 ✗","Desmayé: 재귀대명사 me가 빠졌습니다 ✗"]},{"id":"G274","q":"Como no nos ____ quién lo hizo, lo vas a pagar.","o":["diríais","dijeras","digas","dirías"],"a":2,"k":"como + 접속법 (조건·경고)","t":"누가 그랬는지 우리한테 말하지 않으면 네가 대가를 치르게 될 거야.","e":"como 뒤에 접속법이 오면 '만약 ~하면'이라는 조건이 되며, 주로 경고·위협의 뉘앙스가 있습니다. 현재·미래 조건이므로 접속법 현재 digas를 씁니다. 반면 'como + 직설법'은 '~이니까'라는 이유를 나타냅니다. 'lo vas a pagar'는 '대가를 치를 거야'라는 표현입니다.","x":["diríais: 조건형이고 인칭도 vosotros라 맞지 않습니다 ✗","dijeras: 접속법 과거로 현재·미래 경고(vas a pagar)와 시제가 맞지 않습니다 ✗","digas: 조건·경고의 como + 접속법 현재 → 정답 ✓","dirías: 조건형은 como 조건절에 쓰지 않습니다 ✗"]},{"id":"G275","q":"No hay ____ malo en decir lo que se piensa.","o":["apenas","nada de","algo de","de lo"],"a":1,"k":"nada de + 형용사","t":"생각하는 것을 말하는 데 나쁜 점은 하나도 없다.","e":"'No hay nada de malo en + 동사원형'은 '~하는 데 전혀 잘못된 것이 없다'라는 관용 구문입니다. no hay라는 부정문이므로 부정어 nada가 짝을 이루고, de + 형용사 남성 단수가 뒤따릅니다. 'lo que se piensa'는 '(사람들이) 생각하는 것'이라는 무인칭 표현입니다.","x":["apenas: '거의 ~않다'라는 부사로 뒤에 malo를 바로 받지 못합니다 ✗","nada de: 부정문 + nada de + 형용사 → 정답 ✓","algo de: 긍정문에 쓰며 no hay와 함께 쓰지 않습니다 ✗","de lo: 'de lo malo'는 '나쁜 것 중의'라는 다른 의미로 이 구조에 맞지 않습니다 ✗"]},{"id":"G276","q":"¿____ estás tan decepcionado?","o":["Porqué","Por que","Por qué","Porque"],"a":2,"k":"por qué / porque","t":"너는 왜 그렇게 실망했니?","e":"의문문에서 '왜'라고 물을 때는 띄어 쓰고 악센트를 찍은 por qué를 씁니다. 대답의 '왜냐하면'은 붙여 쓰고 악센트 없는 porque입니다. 붙여 쓰고 악센트를 찍은 porqué는 '이유'라는 명사입니다(el porqué de su decisión: 그의 결정 이유).","x":["Porqué: '이유'라는 명사로 의문문 첫머리에 쓰지 않습니다 ✗","Por que: 악센트가 없으면 의문사가 아니며 '~하도록' 같은 드문 용법입니다 ✗","Por qué: 의문사 '왜' → 정답 ✓","Porque: '왜냐하면'이라는 대답용 접속사입니다 ✗"]},{"id":"G277","q":"____ que no se queje, haremos lo que dice.","o":["De ser","A condición","Con tal de","En caso de"],"a":2,"k":"con tal de que + 접속법","t":"그가 불평하지 않기만 한다면, 그가 말하는 대로 하자.","e":"con tal de que는 '~하기만 한다면, ~하도록'이라는 뜻으로 항상 접속법과 씁니다. 여기서는 '그가 불평하지 않게만 할 수 있다면'이라는 최소 조건(또는 목적)을 나타냅니다. 'a condición de que'도 같은 의미지만 보기에는 de가 빠져 있습니다.","x":["De ser: 'de ser así(그렇다면)'처럼 쓰며 que절과 결합하지 않습니다 ✗","A condición: 'a condición de que'가 되어야 하며 de가 빠졌습니다 ✗","Con tal de: con tal de que + 접속법 → 정답 ✓","En caso de: '~하는 경우에'라는 뜻이라 문맥상 '불평하는 경우에 그가 말하는 대로 한다'가 어색해집니다 ✗"]},{"id":"G278","q":"A Juan siempre ____ nota mucho cuando está de mal humor.","o":["le","se lo","lo","se le"],"a":3,"k":"notársele algo a alguien","t":"후안은 기분이 나쁠 때면 항상 티가 많이 난다.","e":"'notársele algo a alguien'은 '(어떤 상태가) 누구에게서 눈에 띄다, 티가 나다'라는 무인칭 구문입니다. se는 무인칭, le는 그 특징을 보이는 사람(a Juan)입니다. 예: Se te nota cansado(너 피곤해 보여). 'estar de mal humor'는 '기분이 언짢다'입니다.","x":["le: se가 빠지면 '누군가 그에게 알아차리다'처럼 주어가 필요해져 성립하지 않습니다 ✗","se lo: lo는 직접목적격이라 '그에게 티가 나다' 구조와 맞지 않습니다 ✗","lo: '(누가) 그를 알아차린다'라는 뜻이 되어 주어가 없습니다 ✗","se le: 무인칭 se + 간접목적격 le → 정답 ✓"]},{"id":"G279","q":"No logro aumentar de peso, ____ que coma.","o":["incluso tanto","por más","tanto más","por tanto"],"a":1,"k":"por más que + 접속법","t":"아무리 먹어도 나는 살이 찌지 않는다.","e":"'por más que + 접속법'은 '아무리 ~해도'라는 강한 양보 표현입니다. 'por mucho que'도 같은 뜻입니다. 노력해도 결과가 달라지지 않는다는 뉘앙스가 있습니다. 'aumentar de peso'는 '체중이 늘다'입니다.","x":["incluso tanto: 이런 양보 표현은 없습니다 ✗","por más: por más que '아무리 ~해도' → 정답 ✓","tanto más: '그만큼 더'라는 비교 표현으로 양보가 아닙니다 ✗","por tanto: '따라서'라는 결과 접속사입니다 ✗"]},{"id":"G280","q":"Soy lo bastante independiente ____ vivir solo.","o":["como ya","como si","como para","como por"],"a":2,"k":"lo bastante… como para","t":"나는 혼자 살 수 있을 만큼 충분히 독립적이다.","e":"'lo bastante/lo suficientemente + 형용사 + (como) para + 동사원형'은 '~할 만큼 충분히 ~하다'라는 정도 표현입니다. como는 생략할 수도 있지만, 보기 중에는 como para만 맞습니다. 반대 의미는 'demasiado + 형용사 + para'(~하기엔 너무 ~하다)입니다.","x":["como ya: '이미 ~하듯이'라는 뜻으로 정도 표현이 되지 않습니다 ✗","como si: '마치 ~인 것처럼'으로 뒤에 접속법 과거가 와야 합니다 ✗","como para: lo bastante… como para '~할 만큼' → 정답 ✓","como por: 'como por + 동사원형'은 이 구조에 쓰지 않습니다 ✗"]},{"id":"G281","q":"Esta chica, ____ lo que se ponga, siempre está guapa.","o":["habiéndose puesto","se pone","poniéndose","se ponga"],"a":3,"k":"반복 양보 구문","t":"이 여자애는 무엇을 입든 항상 예쁘다.","e":"'동사(접속법) + lo que + 같은 동사(접속법)'은 '무엇을 ~하든'이라는 양보 구문입니다. 'se ponga lo que se ponga'는 '무엇을 입든'이라는 뜻으로, 첫 번째 동사가 빈칸에 들어갑니다. 예: Diga lo que diga(그가 무슨 말을 하든), Pase lo que pase(무슨 일이 있어도).","x":["habiéndose puesto: 완료 현재분사는 이 반복 양보 구문을 만들지 않습니다 ✗","se pone: 직설법이라 양보 구문에 쓸 수 없습니다 ✗","poniéndose: 현재분사는 이 구조에 맞지 않습니다 ✗","se ponga: 접속법 반복 구문 se ponga lo que se ponga → 정답 ✓"]},{"id":"G282","q":"Me pregunto qué ____ para que esté tan enfadado.","o":["habría pasado","habrá pasado","haya pasado","hubiera pasado"],"a":1,"k":"미래완료 (과거 추측)","t":"그가 그렇게 화가 난 걸 보면 무슨 일이 있었던 걸까.","e":"미래완료(habrá + 과거분사)는 '~했을 것이다, ~한 걸까'라는 과거 일에 대한 현재의 추측을 나타냅니다. 'Me pregunto qué habrá pasado'는 '무슨 일이 있었던 걸까 궁금하다'라는 뜻입니다. 이처럼 스페인어 미래형은 현재·과거에 대한 짐작을 표현하는 데 자주 쓰입니다.","x":["habría pasado: 조건완료는 과거 시점에서의 추측이나 가정에 써서 현재 시점(me pregunto, esté)과 맞지 않습니다 ✗","habrá pasado: 현재 시점에서 과거 일을 추측하는 미래완료 → 정답 ✓","haya pasado: 간접 의문문 qué 뒤에는 보통 직설법을 씁니다 ✗","hubiera pasado: 접속법 과거완료로 현재 시점 문장과 맞지 않습니다 ✗"]},{"id":"G283","q":"Te lo advierto, no ____ a venir tan tarde.","o":["vuelvas","vuelvan","vuelves","volvieras"],"a":0,"k":"부정 명령 + volver a","t":"경고하는데, 다시는 이렇게 늦게 오지 마.","e":"tú에 대한 부정 명령은 'no + 접속법 현재'입니다. 'volver a + 동사원형'은 '다시 ~하다'라는 뜻이라 'no vuelvas a venir tan tarde'는 '다시는 이렇게 늦게 오지 마'가 됩니다. 'Te lo advierto'는 '경고하는데'라는 단호한 표현입니다.","x":["vuelvas: tú 부정 명령(접속법 현재) → 정답 ✓","vuelvan: ustedes 형태라 te(tú)와 맞지 않습니다 ✗","vuelves: 직설법이라 부정 명령이 되지 않습니다 ✗","volvieras: 접속법 과거라 명령에 쓰지 않습니다 ✗"]},{"id":"G284","q":"Quiere que yo haga su parte del trabajo. ¡____ listo!","o":["Será","Sería","Fuera","Habrá sido"],"a":0,"k":"감탄 미래형 (¡Será…!)","t":"내 몫까지 일하라는 거야. 참 약았네!","e":"미래형은 감탄문에서 놀람·분개를 나타낼 수 있습니다. '¡Será listo!'는 '정말 영악하네!(뻔뻔하네!)'라는 반어적·비꼬는 표현입니다. listo는 ser와 쓰면 '영리한', estar와 쓰면 '준비된'이라는 뜻인데, 여기서는 반어로 '약삭빠른'의 의미입니다.","x":["Será: 분개·놀람의 감탄 미래형 → 정답 ✓","Sería: 조건형은 이런 감탄 용법이 없습니다 ✗","Fuera: 접속법 과거로 단독 감탄문이 되지 않습니다 ✗","Habrá sido: 미래완료로 '~였을 것이다'라는 과거 추측이 되어 맞지 않습니다 ✗"]},{"id":"G285","q":"Necesitan que vayas ____ antes posible.","o":["lo","el","entre","como"],"a":0,"k":"lo antes posible","t":"가능한 한 빨리 네가 와 주길 바란다.","e":"'lo antes posible'은 '가능한 한 빨리'라는 고정 표현으로, 중성 lo + 부사 + posible 구조입니다. 'lo más rápido posible(최대한 빠르게)', 'lo mejor posible(최선을 다해)'도 같은 방식입니다. 'Necesitan que' 뒤라 접속법 vayas가 쓰였습니다.","x":["lo: lo antes posible '가능한 한 빨리' → 정답 ✓","el: 남성 관사는 부사 antes 앞에 오지 않습니다 ✗","entre: '~사이에'라는 뜻으로 맞지 않습니다 ✗","como: 'como antes posible'은 틀린 형태입니다 ✗"]},{"id":"G286","q":"La cena ya ____ hecha.","o":["será","esté","es","está"],"a":3,"k":"estar + 과거분사 (결과)","t":"저녁 식사는 이미 다 되어 있다.","e":"'estar + 과거분사'는 행동이 끝난 결과 상태를 나타냅니다. ya(이미)와 함께 '이미 만들어져 있다'라는 현재 상태이므로 está hecha가 맞습니다. cena가 여성 명사라 과거분사도 hecha로 일치시킵니다.","x":["será: 미래형으로 ya와 함께 현재 결과 상태를 나타내지 못합니다 ✗","esté: 접속법이라 단순 평서문에 쓸 수 없습니다 ✗","es: ser + 과거분사는 '만들어지다'라는 수동 동작이라 ya와 함께 상태를 말하기 어색합니다 ✗","está: estar + 과거분사 결과 상태 → 정답 ✓"]},{"id":"G287","q":"Fermín ____ una persona impulsiva.","o":["se parece","es","está","se encuentra"],"a":1,"k":"ser (성격)","t":"페르민은 충동적인 사람이다.","e":"'una persona + 형용사'처럼 명사가 오면 ser를 씁니다. 사람의 성격·본질을 말하는 문장이므로 es가 맞습니다. estar는 명사를 바로 보어로 받지 못합니다. impulsivo/a는 '충동적인'입니다.","x":["se parece: parecerse는 'a + 대상'이 필요하며 '~를 닮다'라는 뜻입니다 ✗","es: ser + 명사(성격·정체) → 정답 ✓","está: estar는 명사 보어를 직접 받지 않습니다 ✗","se encuentra: '(~한 상태로) 있다'라는 뜻으로 명사를 받지 않습니다 ✗"]},{"id":"G288","q":"Esta habitación ____ una porquería, hay que ordenarla y limpiarla ya.","o":["está hecha","es hecha","se hace","está haciéndose"],"a":0,"k":"estar hecho una porquería","t":"이 방은 엉망진창이야, 당장 정리하고 청소해야 해.","e":"'estar hecho/a + un/una + 명사'는 '~처럼 되어 버리다'라는 구어 표현으로, 부정적인 상태 변화에 자주 씁니다. 'estar hecho una porquería'는 '완전히 엉망이다, 지저분하다'라는 뜻입니다. 비슷하게 'estar hecho un desastre(엉망이다)', 'estar hecha un mar de lágrimas(눈물바다다)'도 있습니다.","x":["está hecha: estar hecho + 명사 '~가 되어 버리다' → 정답 ✓","es hecha: ser 수동태라 이 관용 표현을 만들지 못합니다 ✗","se hace: '~이 된다/만들어진다'라는 과정의 뜻이라 현재 상태 묘사로 맞지 않습니다 ✗","está haciéndose: '만들어지는 중이다'라는 진행 의미가 됩니다 ✗"]},{"id":"G289","q":"No sería capaz ____ hacer algo tan rastrero.","o":["de","a","para","con"],"a":0,"k":"ser capaz de","t":"나는 그렇게 비열한 짓은 절대 못 할 것이다.","e":"'ser capaz de + 동사원형'은 '~할 수 있다, ~할 능력(배짱)이 있다'라는 표현으로 de가 고정입니다. 부정 조건형 'No sería capaz de…'는 '도저히 ~할 수 없을 것이다'라는 도덕적 거부감을 나타냅니다. rastrero는 '비열한, 치사한'이라는 뜻입니다.","x":["de: ser capaz de 고정 표현 → 정답 ✓","a: capaz와 함께 쓰지 않습니다 ✗","para: capaz para는 일부에서 들리지만 동사원형 앞 표준 형태는 de입니다 ✗","con: capaz con은 쓰지 않습니다 ✗"]},{"id":"G290","q":"____ que me hablases de tú.","o":["Prefiera","Preferiría","Preferiré","Prefiriera"],"a":1,"k":"조건형 + que + 접속법 과거","t":"나한테 반말(tú)로 말해 주면 좋겠어.","e":"조건형 preferiría(~하는 편이 좋겠다)는 바람을 공손하게 표현하며, 뒤 que절에는 접속법 과거(hablases/hablaras)가 옵니다. 'hablar de tú(tutear)'는 '서로 tú로 부르다, 말을 놓다'라는 뜻으로, 반대는 'hablar de usted(존댓말을 쓰다)'입니다.","x":["Prefiera: 접속법 현재라 독립된 주절 동사로 쓸 수 없습니다 ✗","Preferiría: 공손한 바람의 조건형 + 접속법 과거 → 정답 ✓","Preferiré: 미래형이라 뒤 접속법 과거(hablases)와 시제가 맞지 않습니다 ✗","Prefiriera: 접속법 과거라 주절 동사로 쓸 수 없습니다 ✗"]},{"id":"G291","q":"Le ruego que no ____ insistiendo.","o":["sigas","sigue","siga","seguirá"],"a":2,"k":"rogar que + 접속법","t":"더 이상 고집하지 말아 주시기 바랍니다.","e":"'Le ruego que + 접속법'은 '~해 주시기를 부탁드립니다'라는 매우 정중한 요청입니다. le(당신에게)로 보아 상대가 usted이므로 3인칭 단수 접속법 siga가 됩니다. 'seguir + 현재분사'는 '계속 ~하다'라서 'no siga insistiendo'는 '계속 고집하지 마세요'입니다.","x":["sigas: tú 형태라 le(usted)와 맞지 않습니다 ✗","sigue: 직설법이라 rogar que 뒤에 쓸 수 없습니다 ✗","siga: usted 접속법 현재 → 정답 ✓","seguirá: 미래형이라 rogar que 뒤에 쓸 수 없습니다 ✗"]},{"id":"G292","q":"¿Alguien sabe cuándo ____ este edificio?","o":["se hubiese construido","se construyera","era construido","se construyó"],"a":3,"k":"수동 se + 단순과거","t":"이 건물이 언제 지어졌는지 아는 사람 있어요?","e":"행위자가 중요하지 않을 때 스페인어는 'se + 3인칭 동사'로 수동 의미를 많이 표현합니다(수동의 se). 건물이 지어진 것은 과거에 완결된 일이므로 단순과거 se construyó가 맞습니다. 간접 의문문(cuándo…) 안이라도 사실을 묻는 것이니 직설법을 씁니다.","x":["se hubiese construido: 접속법 과거완료라 사실을 묻는 간접 의문문에 쓰지 않습니다 ✗","se construyera: 접속법 과거라 법이 맞지 않습니다 ✗","era construido: 불완료과거 수동태로 '지어지고 있었다'라는 뜻이 되어 완결된 사건에 맞지 않습니다 ✗","se construyó: 수동 se + 단순과거 → 정답 ✓"]},{"id":"G293","q":"A esta parte de la casa ____ por la puerta trasera.","o":["se entra","está entrado","está siendo entrado","es entrado"],"a":0,"k":"무인칭 se","t":"집의 이 부분으로는 뒷문을 통해 들어간다.","e":"'se + 3인칭 단수 동사'는 '(사람들은 일반적으로) ~한다'라는 무인칭 표현입니다. entrar는 자동사라 수동태(ser + 과거분사)로 만들 수 없고, 무인칭 se로만 '들어간다'를 표현할 수 있습니다. 예: Se entra por aquí(이쪽으로 들어갑니다).","x":["se entra: 무인칭 se + 자동사 → 정답 ✓","está entrado: 자동사 entrar는 이런 결과 상태 표현을 만들지 않습니다 ✗","está siendo entrado: 자동사는 수동 진행형을 만들 수 없습니다 ✗","es entrado: 자동사는 ser 수동태가 될 수 없습니다 ✗"]},{"id":"G294","q":"Cuando regresé a casa, mi mujer ____ se había acostado.","o":["ya","aún","todavía","aun"],"a":0,"k":"ya (이미)","t":"내가 집에 돌아왔을 때 아내는 이미 잠자리에 들어 있었다.","e":"ya는 '이미, 벌써'라는 뜻으로 과거완료(se había acostado)와 함께 '기준 시점보다 앞서 이미 끝났다'를 나타냅니다. aún과 todavía는 '아직'이라는 뜻이라 긍정 과거완료와 함께 쓰면 의미가 맞지 않습니다(부정문이라면 'todavía no se había acostado': 아직 자지 않았다).","x":["ya: '이미' → 정답 ✓","aún: '아직'이라는 뜻으로 긍정 완료문과 의미가 충돌합니다 ✗","todavía: '아직'이라는 뜻으로 의미가 맞지 않습니다 ✗","aun: 악센트 없는 aun은 '~조차'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G295","q":"¡Qué niño ____ simpático!","o":["ø","tan","tanto","tantísimo"],"a":1,"k":"¡Qué + 명사 + tan + 형용사!","t":"정말 상냥한 아이구나!","e":"'¡Qué + 명사 + tan/más + 형용사!'는 '정말 ~한 ~이구나!'라는 감탄 구조입니다. 형용사 앞에 tan이나 más를 넣는 것이 표준입니다. 예: ¡Qué día tan bonito!(정말 아름다운 날이다!). simpático는 '상냥한, 호감 가는'이라는 뜻입니다.","x":["ø: '¡Qué niño simpático!'도 구어에서 들리지만 이 교재는 tan을 넣는 표준 구조를 정답으로 봅니다 ✗","tan: ¡Qué + 명사 + tan + 형용사! → 정답 ✓","tanto: tanto는 형용사 앞에서 tan으로 줄어야 합니다 ✗","tantísimo: 형용사 앞에 쓰지 않는 형태입니다 ✗"]},{"id":"G296","q":"Alberto dice que ____ está dispuesto a colaborar con nosotros.","o":["sí","claro","bueno","vale"],"a":0,"k":"sí (긍정 강조)","t":"알베르토는 우리와 협력할 의향이 정말로 있다고 말한다.","e":"동사 앞에 악센트가 있는 sí를 두면 '정말로, 분명히 ~하다'라는 긍정 강조가 됩니다. 앞에서 '안 할 거야'라는 의심이나 대조가 있을 때 '그는 (분명히) 하겠다고 한다'는 뉘앙스를 줍니다. 'estar dispuesto a'는 '~할 의향이 있다'입니다.","x":["sí: 동사 앞 긍정 강조 '정말로' → 정답 ✓","claro: '물론'이라는 감탄사로 que절 안에서 동사를 강조하는 용법이 아닙니다 ✗","bueno: '좋아, 음'이라는 담화 표지로 이 자리에서 뜻이 통하지 않습니다 ✗","vale: '오케이'라는 스페인 구어 감탄사로 que절 안에 오지 않습니다 ✗"]},{"id":"G297","q":"____ no ser por ti, habríamos perdido el partido.","o":["A","De","Sin","Por"],"a":1,"k":"de no ser por","t":"네가 아니었다면 우리는 경기에서 졌을 것이다.","e":"'De no ser por + 명사/대명사'는 '~이 아니었다면, ~가 없었다면'이라는 가정 표현입니다. 'de + 동사원형'이 si 조건절을 대신하는 구조로, 'Si no fuera/hubiera sido por ti'와 같은 뜻입니다. 주절은 조건완료 habríamos perdido입니다.","x":["A: 'a no ser por'는 '~을 제외하면'이라는 다른 표현에 가깝습니다 ✗","De: de no ser por '~이 아니었다면' → 정답 ✓","Sin: 'sin no ser'는 이중 부정이라 성립하지 않습니다 ✗","Por: 'por no ser por'는 성립하지 않습니다 ✗"]},{"id":"G298","q":"¿Todavía no has encontrado ____ pendientes que perdiste?","o":["a las","las","los","a los"],"a":2,"k":"사물 직접목적어 (무 a)","t":"잃어버린 귀걸이 아직 못 찾았어?","e":"사물이 직접목적어일 때는 인칭의 a를 붙이지 않습니다. pendiente(귀걸이)는 남성 명사이므로 los pendientes가 됩니다. 스페인에서는 pendientes, 중남미에서는 주로 aretes(멕시코 등) 또는 aros(아르헨티나·칠레)라고 합니다.","x":["a las: 사물에 a를 붙이지 않고 성도 여성이라 틀립니다 ✗","las: pendiente는 남성 명사라 las가 맞지 않습니다 ✗","los: 남성 복수 정관사, 사물 목적어 → 정답 ✓","a los: 사물 목적어 앞에는 a를 붙이지 않습니다 ✗"]},{"id":"G299","q":"Estamos barajando la posibilidad ____ mudarnos a Francia.","o":["de","para","por","a"],"a":0,"k":"barajar la posibilidad de","t":"우리는 프랑스로 이사할 가능성을 검토하고 있다.","e":"'la posibilidad de + 동사원형'은 '~할 가능성'으로 de가 고정입니다. barajar는 원래 '(카드를) 섞다'라는 뜻이지만, 'barajar la posibilidad/opciones'는 '(여러 가능성을) 저울질하다, 검토하다'라는 관용 표현입니다. mudarse는 '이사하다'입니다.","x":["de: posibilidad de + 동사원형 → 정답 ✓","para: posibilidad와 함께 쓰는 전치사가 아닙니다 ✗","por: posibilidad por는 쓰지 않습니다 ✗","a: posibilidad a는 쓰지 않습니다 ✗"]},{"id":"G300","q":"Enrique ya tiene 20 años, está hecho ____ hombre.","o":["ø","el","todo","un"],"a":3,"k":"estar hecho un + 명사","t":"엔리케는 벌써 스무 살이야, 어엿한 남자가 다 됐어.","e":"'estar hecho/a + un/una + 명사'는 '(완전히) ~가 되었다'라는 구어 감탄 표현입니다. 'está hecho un hombre'는 '어엿한 어른 남자가 되었다'라는 성장의 감탄입니다. 같은 구조로 'Estás hecha una princesa(공주님 같구나)'처럼 칭찬이나 놀람을 표현합니다.","x":["ø: 관사 없이 'está hecho hombre'라고 하면 이 관용 표현이 되지 않습니다 ✗","el: 정관사는 이 구조에 쓰지 않습니다 ✗","todo: 'todo un hombre'라면 가능하지만 todo만으로는 부족합니다 ✗","un: estar hecho un + 명사 → 정답 ✓"]},{"id":"G301","q":"¡Qué calor ____ estar pasando tu padre en la cocina!","o":["viene a","hay que","llega a","debe de"],"a":3,"k":"deber de 추측","t":"너희 아버지가 부엌에서 얼마나 더우실까!","e":"'deber de + 동사원형'은 '~임에 틀림없다, 아마 ~일 것이다'라는 추측을 나타냅니다. 화자는 아버지가 부엌에서 더위를 겪고 있을 거라고 짐작하므로 debe de가 맞습니다. 참고로 'deber + 동사원형'(de 없이)은 원래 '~해야 한다'(의무)라는 뜻이지만, 구어에서는 추측에도 섞어 쓰는 경우가 많습니다.","x":["viene a: 'venir a + 동사원형'은 '대략 ~에 해당하다, 결국 ~이 되다'라는 뜻이라 추측 감탄문에 어울리지 않습니다 ✗","hay que: '(일반적으로) ~해야 한다'는 무인칭 의무 표현이라 주어(tu padre)와 함께 쓸 수 없습니다 ✗","llega a: 'llegar a + 동사원형'은 '~하기에 이르다'라는 뜻이라 의미가 맞지 않습니다 ✗","debe de: '~임에 틀림없다'라는 추측 표현 → 정답 ✓"]},{"id":"G302","q":"Mario es ____ un chef, cocina muy bien.","o":["todo","algo","mucho","bastante"],"a":0,"k":"ser todo un","t":"마리오는 진정한 셰프야, 요리를 정말 잘해.","e":"'ser todo un + 명사'는 '그야말로 진정한 ~이다, 제대로 된 ~이다'라는 강조 표현입니다. 여성 명사면 'toda una'가 됩니다. 예: Es toda una artista. (그녀는 진정한 예술가야.)","x":["todo: 'todo un chef'로 '진정한 셰프'라는 강조 표현을 만듭니다 → 정답 ✓","algo: '약간, 어느 정도'라는 뜻으로 'algo un chef'는 문법적으로 성립하지 않습니다 ✗","mucho: '많이'라는 부사로 'un chef' 같은 명사구 앞에 쓰지 않습니다 ✗","bastante: '꽤, 상당히'라는 뜻으로 이 강조 구문에 쓰지 않습니다 ✗"]},{"id":"G303","q":"En unos minutos tendrán ____ sus manos nuestro nuevo modelo de teléfono.","o":["en","por","a","de"],"a":0,"k":"tener en manos","t":"몇 분 후면 여러분 손에 저희 새 휴대폰 모델이 들려 있을 겁니다.","e":"'tener algo en las manos'는 '~을 손에 쥐고 있다'라는 뜻으로, 장소·위치를 나타내는 전치사 en을 씁니다. 광고에서 자주 쓰는 표현으로 '곧 직접 손에 넣게 된다'는 느낌을 줍니다.","x":["en: 손 '안에' 있다는 위치를 나타냄 → 정답 ✓","por: '~을 통해, ~때문에'라는 뜻이라 손 안의 위치를 나타낼 수 없습니다 ✗","a: 방향(~로)을 나타내며 'tener a sus manos'는 쓰지 않는 표현입니다 ✗","de: 소유·출처(~의, ~에서)를 나타내 이 문장에 맞지 않습니다 ✗"]},{"id":"G304","q":"____ en el caso de que sea culpable, no se puede tratar así al acusado.","o":["Sino","Si","Aun","Como"],"a":2,"k":"aun(~조차도)","t":"설령 그가 유죄라 하더라도 피고인을 그렇게 대해서는 안 된다.","e":"'aun'(악센트 없음)은 '~조차도, 심지어'(incluso)라는 뜻입니다. 'aun en el caso de que + 접속법'은 '설령 ~인 경우라도'라는 양보 표현입니다. 악센트가 있는 'aún'은 '아직'(todavía)이라는 뜻이니 구별하세요.","x":["Sino: '~이 아니라 ~이다'라는 대조 접속사로 앞에 부정문이 있어야 합니다 ✗","Si: '만약'이라는 뜻이지만 'si en el caso de que'는 중복되어 어색합니다 ✗","Aun: '~조차도'라는 뜻으로 양보의 의미를 만듭니다 → 정답 ✓","Como: '~처럼, ~이므로'라는 뜻이라 양보 의미가 나오지 않습니다 ✗"]},{"id":"G305","q":"Los domingos nos levantamos ____ las 11.","o":["por","alrededor","a eso de","en torno"],"a":2,"k":"a eso de(시간)","t":"일요일마다 우리는 11시쯤 일어난다.","e":"'a eso de + 시각'은 '~시쯤에, ~시 무렵에'라는 뜻의 구어 표현입니다. 비슷한 표현으로 'alrededor de las 11', 'en torno a las 11', 'sobre las 11'이 있지만, 보기에는 뒤의 전치사(de, a)가 빠져 있어서 a eso de만 완전합니다.","x":["por: 'por la mañana'처럼 시간대를 말할 때는 쓰지만 'por las 11'은 정확한 시각 근처를 나타내기에 어색합니다 ✗","alrededor: 'alrededor de las 11'처럼 de가 필요한데 빠져 있습니다 ✗","a eso de: '~시쯤'이라는 완전한 표현 → 정답 ✓","en torno: 'en torno a las 11'처럼 a가 필요한데 빠져 있습니다 ✗"]},{"id":"G306","q":"Estamos muy ____ en nuestro nuevo hogar.","o":["con gusto","a gusto","agusto","de gusto"],"a":1,"k":"estar a gusto","t":"우리는 새 집에서 아주 편안하게 지내고 있다.","e":"'estar a gusto'는 '편안하다, 마음이 편하다, 기분 좋게 지내다'라는 뜻의 관용 표현입니다. 반대는 'estar a disgusto'(불편하다)입니다. 'agusto'처럼 붙여 쓰는 것은 흔한 철자 실수입니다.","x":["con gusto: '기꺼이'라는 뜻(예: Lo haré con gusto.)으로 estar와 결합해 '편하다'는 뜻이 되지 않습니다 ✗","a gusto: '편안하게'라는 뜻의 관용 표현 → 정답 ✓","agusto: 띄어 써야 하는 'a gusto'를 붙여 쓴 잘못된 철자입니다 ✗","de gusto: 'de buen gusto'(취향이 좋은)처럼 쓰이며 이 문장에 맞지 않습니다 ✗"]},{"id":"G307","q":"Cada día se para ____ ese escaparate durante un buen rato.","o":["delante","detrás","a","ante"],"a":3,"k":"전치사 ante","t":"그는 매일 그 진열창 앞에서 한참 동안 멈춰 선다.","e":"'ante'는 '~앞에서'라는 뜻의 전치사로 바로 명사 앞에 씁니다. 같은 뜻의 'delante'는 부사라서 명사 앞에 쓰려면 'delante de ese escaparate'처럼 de가 꼭 필요합니다. ante는 delante de보다 약간 문어적인 느낌입니다.","x":["delante: 'delante de'처럼 de가 있어야 명사와 연결됩니다 ✗","detrás: '뒤에'라는 뜻이고 역시 'detrás de'가 필요합니다 ✗","a: 방향을 나타내며 'pararse a ese escaparate'는 비문입니다 ✗","ante: '~앞에서'라는 전치사로 바로 명사와 연결됩니다 → 정답 ✓"]},{"id":"G308","q":"Vinieron ____ pedirnos explicaciones de lo ocurrido.","o":["sobre","a","hasta","por"],"a":1,"k":"venir a + 동사원형","t":"그들은 일어난 일에 대해 우리에게 해명을 요구하러 왔다.","e":"이동 동사(ir, venir, salir 등) 뒤에 목적을 나타낼 때는 'a + 동사원형'을 씁니다. 'vinieron a pedirnos'는 '우리에게 요구하러 왔다'라는 뜻입니다. 'pedir explicaciones'는 '해명을 요구하다'라는 자주 쓰는 표현입니다.","x":["sobre: '~에 대해'라는 뜻으로 이동의 목적을 나타내지 않습니다 ✗","a: 이동 동사 뒤에서 '~하러'라는 목적을 나타냄 → 정답 ✓","hasta: '~까지'라는 뜻이라 의미가 맞지 않습니다 ✗","por: 'venir por'는 '~을 가지러/데리러 오다'(스페인 구어 'a por')라는 뜻이 되어 동사원형 앞에서는 어색합니다 ✗"]},{"id":"G309","q":"Estoy aquí ____ me atiendan en persona.","o":["por que","ya que","para que","puesto que"],"a":2,"k":"para que + 접속법","t":"저는 직접 응대를 받으려고 여기 와 있습니다.","e":"'para que'는 '~하도록, ~하기 위해'라는 목적 접속사로 뒤에 항상 접속법(바람·목적을 나타내는 동사 형태)이 옵니다. 'atiendan'이 접속법 현재형이라는 점도 힌트가 됩니다. 'en persona'는 '직접, 몸소'라는 뜻입니다.","x":["por que: '~때문에/~을 위해' 등으로 드물게 쓰이는 형태로, 이 목적 의미에는 para que가 표준입니다 ✗","ya que: '~이므로'라는 이유 접속사로 직설법이 오며 의미도 맞지 않습니다 ✗","para que: 목적을 나타내며 접속법과 함께 씀 → 정답 ✓","puesto que: '~이므로'라는 이유 접속사로 목적의 의미가 없습니다 ✗"]},{"id":"G310","q":"¿Te molesta que te ____ de tú?","o":["hablen","hablan","hablaban","hablarían"],"a":0,"k":"감정 동사+접속법","t":"사람들이 너에게 반말(tú)로 말하는 게 싫니?","e":"'molestar que'(~하는 것이 거슬리다)처럼 감정을 나타내는 동사 뒤의 que절에는 접속법을 씁니다. 주절이 현재형(molesta)이므로 접속법 현재 'hablen'이 맞습니다. 'hablar de tú'는 상대에게 tú(반말)를 쓰다, 'hablar de usted'는 존댓말을 쓰다라는 뜻입니다.","x":["hablen: 감정 표현 뒤 접속법 현재 → 정답 ✓","hablan: 직설법 현재라 감정 동사 뒤 que절에 맞지 않습니다 ✗","hablaban: 직설법 불완료과거로 시제와 법이 모두 맞지 않습니다 ✗","hablarían: 가능법(조건형)이라 이 구조에 쓰지 않습니다 ✗"]},{"id":"G311","q":"Os pido que no hagáis ruido ____ la hora de la siesta.","o":["por","de","en","a"],"a":3,"k":"a la hora de","t":"낮잠 시간에는 시끄럽게 하지 말아 달라고 너희에게 부탁할게.","e":"정해진 시각이나 시간을 말할 때는 'a la hora de ~'(~ 시간에)를 씁니다. 예: a la hora de comer(점심 시간에). 'a la hora de + 동사원형'은 '~할 때가 되면'이라는 뜻으로도 많이 씁니다. 'siesta'는 스페인 등에서 점심 후 짧게 자는 낮잠을 말합니다.","x":["por: 'por la tarde'처럼 시간대에는 쓰지만 'por la hora de'는 쓰지 않습니다 ✗","de: '~의'라는 뜻으로 시간 표현을 만들지 못합니다 ✗","en: 'en la hora de'는 스페인어에서 부자연스러운 표현입니다 ✗","a: 'a la hora de'로 특정 시간을 나타냄 → 정답 ✓"]},{"id":"G312","q":"En esta calle no hay manera ____ aparcar.","o":["por","para","a","de"],"a":3,"k":"no hay manera","t":"이 거리에서는 도저히 주차할 방법이 없다.","e":"'no hay manera de + 동사원형'은 '도저히 ~할 수가 없다, ~할 방법이 없다'라는 뜻의 자주 쓰는 표현입니다. 'manera', 'forma', 'modo' 같은 명사 뒤에 동사원형을 연결할 때는 de를 씁니다. 예: No hay forma de convencerlo. (그를 설득할 방법이 없어.)","x":["por: 명사 manera와 동사원형을 이어 주지 못합니다 ✗","para: '~하기 위한'이라는 뜻이지만 이 관용 표현에서는 de만 씁니다 ✗","a: 'manera a'는 쓰지 않는 결합입니다 ✗","de: 'manera de + 동사원형'으로 방법을 나타냄 → 정답 ✓"]},{"id":"G313","q":"Si quieres irte de vacaciones en verano, más vale ____ a ahorrar.","o":["que empiezas","que empezarías","que empieces","si empieces"],"a":2,"k":"más vale que","t":"여름에 휴가를 가고 싶다면 저축을 시작하는 게 좋을 거야.","e":"'más vale que + 접속법'은 '~하는 편이 낫다'라는 조언·경고 표현입니다. 'más vale + 동사원형'도 가능하지만(Más vale empezar...), que를 쓰면 반드시 접속법이 옵니다. 'empieces'는 empezar의 접속법 현재 tú 형태입니다.","x":["que empiezas: 직설법이라 'más vale que' 뒤에 쓸 수 없습니다 ✗","que empezarías: 가능법(조건형)이라 이 구조에 맞지 않습니다 ✗","que empieces: 접속법 현재로 조언을 나타냄 → 정답 ✓","si empieces: si 뒤에는 접속법 현재를 쓰지 않으며 구조도 틀립니다 ✗"]},{"id":"G314","q":"No ____ bromas, así que no me molestes.","o":["estoy de","soy de","estoy para","soy para"],"a":2,"k":"estar para + 명사","t":"나 지금 농담할 기분 아니니까 귀찮게 하지 마.","e":"'no estar para + 명사/동사원형'은 '~할 기분(상태)이 아니다'라는 뜻의 관용 표현입니다. 예: No estoy para fiestas. (파티할 기분이 아니야.) 한편 'estar de broma'는 '농담하고 있다'라는 뜻이라 의미가 다릅니다.","x":["estoy de: 'estar de broma'(농담 중이다)는 단수 broma로 쓰며, 이 문장의 '기분이 아니다'라는 의미와 맞지 않습니다 ✗","soy de: ser de는 출신·소유를 나타내 의미가 맞지 않습니다 ✗","estoy para: '~할 기분이다'라는 관용 표현 → 정답 ✓","soy para: ser para는 용도·대상을 나타내며 기분을 표현하지 않습니다 ✗"]},{"id":"G315","q":"No ____ tan buena nota sin la ayuda de nuestra profesora particular. Estamos agradecidos.","o":["hemos sacado","habríamos sacado","habíamos sacado","hayamos sacado"],"a":1,"k":"가능법 완료","t":"과외 선생님의 도움이 없었다면 우리는 그렇게 좋은 점수를 받지 못했을 거야. 정말 감사해.","e":"'sin + 명사'가 '~이 없었다면'이라는 가정 조건을 대신하고 있습니다. 과거에 일어나지 않은 일을 가정할 때 결과는 가능법 완료(habría + 과거분사, '~했을 것이다')로 씁니다. 실제로는 도움을 받아서 좋은 점수를 받았다는 뜻입니다.","x":["hemos sacado: 현재완료로 사실을 말할 뿐 가정의 의미가 없습니다 ✗","habríamos sacado: 과거 사실의 반대를 가정한 결과 → 정답 ✓","habíamos sacado: 과거완료(대과거)로 가정 의미가 나오지 않습니다 ✗","hayamos sacado: 접속법 현재완료로 이렇게 독립된 주절에 쓰지 않습니다 ✗"]},{"id":"G316","q":"____ libros tuvieron un éxito arrollador.","o":["Ambos dos","Ambos los dos","Ambos los","Ambos"],"a":3,"k":"ambos 용법","t":"두 책 모두 압도적인 성공을 거두었다.","e":"'ambos/ambas'는 '둘 다'라는 뜻으로 명사 바로 앞에 관사 없이 씁니다. 'ambos dos'는 같은 뜻이 반복되는 중복 표현이라 피해야 하고, 'ambos los'처럼 관사를 넣는 것도 틀립니다. 'éxito arrollador'는 '압도적인 성공'이라는 자주 쓰는 결합입니다.","x":["Ambos dos: '둘 다 둘'처럼 의미가 중복되는 비표준 표현입니다 ✗","Ambos los dos: 관사와 수사가 중복된 잘못된 형태입니다 ✗","Ambos los: ambos 뒤에 정관사를 쓰지 않습니다 ✗","Ambos: 명사 앞에 관사 없이 '둘 다' → 정답 ✓"]},{"id":"G317","q":"No tengo dinero ahora mismo, ____ lo tendré que comprar más tarde.","o":["tanto que","puesto que","ya que","así que"],"a":3,"k":"결과 접속사 así que","t":"지금 당장은 돈이 없으니까, 그건 나중에 사야겠다.","e":"'así que'는 '그래서, 그러니까'라는 결과를 나타내는 접속사입니다. 앞 문장(돈이 없다)이 원인이고 뒤 문장(나중에 사야 한다)이 결과이므로 así que가 맞습니다. 반면 puesto que, ya que는 뒤에 '이유'가 와야 합니다.","x":["tanto que: '너무 ~해서'라는 뜻으로 앞에 정도를 나타내는 말이 필요합니다 ✗","puesto que: '~이므로'라는 이유를 이끌어 뒤 문장이 이유가 되어야 합니다 ✗","ya que: 역시 이유를 이끄는 접속사라 원인-결과 순서가 맞지 않습니다 ✗","así que: '그래서'라는 결과 접속사 → 정답 ✓"]},{"id":"G318","q":"He sacado un sobresaliente, ____ apenas había estudiado.","o":["y eso que","pues","ya que","así que"],"a":0,"k":"y eso que(양보)","t":"거의 공부를 안 했는데도 나는 최우수 점수를 받았다.","e":"'y eso que'는 '~인데도, ~했는데 말이야'라는 뜻으로 놀라움이 섞인 양보를 나타내는 구어 표현입니다. 앞에서 말한 결과가 뒤 내용에 비해 의외라는 느낌을 줍니다. 'sobresaliente'는 스페인 성적 체계의 최고 등급(9~10점)입니다.","x":["y eso que: '~했는데도'라는 양보 표현 → 정답 ✓","pues: '왜냐하면'이라는 이유 접속사로 의미가 반대가 됩니다 ✗","ya que: '~이므로'라는 이유를 나타내 논리가 맞지 않습니다 ✗","así que: '그래서'라는 결과를 나타내 문맥과 반대됩니다 ✗"]},{"id":"G319","q":"Te ____ de menos.","o":["echado","he hecho","echo","hecho"],"a":2,"k":"echar de menos","t":"네가 보고 싶어.","e":"'echar de menos a alguien'은 '~을 그리워하다, 보고 싶어하다'라는 뜻의 관용 표현입니다. 주어가 yo이므로 echar의 직설법 현재 'echo'를 씁니다. 중남미에서는 'extrañar'를 더 많이 씁니다(Te extraño).","x":["echado: 과거분사라 haber 없이 혼자 쓸 수 없습니다 ✗","he hecho: hacer(하다)의 현재완료라 동사 자체가 틀립니다 ✗","echo: echar의 yo 현재형으로 'echar de menos'를 완성함 → 정답 ✓","hecho: hacer의 과거분사로 철자와 동사가 모두 틀립니다(echo와 혼동 주의) ✗"]},{"id":"G320","q":"____ la guerra, mis bisabuelos pasaron hambre.","o":["Cuando","Siempre y cuando","En cuanto","Entonces"],"a":0,"k":"cuando + 명사","t":"전쟁 때 우리 증조부모님은 굶주림을 겪으셨다.","e":"'cuando'는 원래 접속사지만 명사 바로 앞에 와서 '~의 때에, ~동안'(durante)이라는 뜻으로 쓸 수 있습니다. 예: cuando niño(어렸을 때), cuando la guerra(전쟁 때). 문어적이면서도 흔한 용법입니다.","x":["Cuando: 명사 앞에서 '~ 때에'라는 뜻 → 정답 ✓","Siempre y cuando: '~하기만 한다면'이라는 조건 접속사로 뒤에 접속법 절이 필요합니다 ✗","En cuanto: '~하자마자'라는 뜻으로 뒤에 동사절이 와야 합니다 ✗","Entonces: '그때, 그러면'이라는 부사라 명사와 연결되지 않습니다 ✗"]},{"id":"G321","q":"En este museo hay ____ Picasso maravilloso.","o":["un","ø","uno","el"],"a":0,"k":"작가명→작품","t":"이 미술관에는 멋진 피카소 작품이 한 점 있다.","e":"화가 이름을 작품 자체를 가리키는 말로 쓸 때는 보통 남성 관사를 붙입니다(un cuadro de Picasso의 생략). 처음 언급하는 불특정한 작품이므로 부정관사 un을 씁니다. 예: Tienen dos Velázquez. (벨라스케스 작품 두 점이 있다.)","x":["un: 불특정한 작품 한 점 → 정답 ✓","ø: 관사 없이 쓰면 화가 본인을 가리키게 되어 의미가 이상해집니다 ✗","uno: 명사 앞에서는 uno가 un으로 줄어들어야 합니다 ✗","el: 'hay' 뒤에는 보통 정관사를 쓰지 않습니다(hay는 새로운 것을 소개) ✗"]},{"id":"G322","q":"Trabajará aquí hasta que le ____ algo mejor.","o":["saldría","salga","saldrá","sale"],"a":1,"k":"hasta que + 접속법","t":"그는 더 좋은 일자리가 생길 때까지 여기서 일할 것이다.","e":"'hasta que'(~할 때까지)가 미래의 일을 가리킬 때는 접속법을 씁니다. 아직 일어나지 않은 일이기 때문입니다. 'salir algo'는 '(일자리·기회 등이) 생기다'라는 뜻이고, 'le'는 '그에게'입니다.","x":["saldría: 가능법이라 hasta que 뒤 미래 시점에 쓰지 않습니다 ✗","salga: 미래를 가리키는 시간절의 접속법 현재 → 정답 ✓","saldrá: 직설법 미래는 시간 접속사 뒤에 쓸 수 없습니다 ✗","sale: 직설법 현재는 반복적 습관에 쓰며 미래의 일에는 맞지 않습니다 ✗"]},{"id":"G323","q":"____ es cierto que no somos tan fuertes como ellos, considero que podemos ganarles.","o":["Incluso","Si bien","Por mucho que","Y eso que"],"a":1,"k":"si bien(양보)","t":"우리가 그들만큼 강하지 않은 건 사실이지만, 나는 우리가 이길 수 있다고 생각한다.","e":"'si bien'은 '비록 ~이긴 하지만'(aunque)이라는 뜻의 문어적·격식 있는 양보 접속사입니다. 사실로 인정되는 내용을 말할 때 쓰며 직설법이 옵니다. 'es cierto que'와 아주 잘 어울립니다.","x":["Incluso: '심지어'라는 부사로 두 절을 연결하는 접속사가 아닙니다 ✗","Si bien: '~이긴 하지만'이라는 양보 접속사 → 정답 ✓","Por mucho que: '아무리 ~해도'라는 뜻으로 보통 접속법이 오며 'es cierto que'와 어울리지 않습니다 ✗","Y eso que: 주절 뒤에 와서 '~인데도'라는 뜻이라 문장 맨 앞에 쓰지 않습니다 ✗"]},{"id":"G324","q":"Carlos se presentó en nuestra casa ____ madrugada.","o":["de","por","a","entre"],"a":0,"k":"de madrugada","t":"카를로스는 새벽에 우리 집에 나타났다.","e":"'de madrugada'는 '새벽에'라는 뜻의 고정 표현입니다. 비슷하게 'de día'(낮에), 'de noche'(밤에)도 관사 없이 de를 씁니다. 'presentarse'는 '(예고 없이) 나타나다'라는 뜻입니다.","x":["de: 'de madrugada'로 '새벽에' → 정답 ✓","por: 'por la madrugada'처럼 관사가 있어야 하며 관사 없이는 쓰지 않습니다 ✗","a: 'a madrugada'는 쓰지 않는 표현입니다 ✗","entre: '~사이에'라는 뜻이라 단독 시간 표현을 만들지 못합니다 ✗"]},{"id":"G325","q":"Miguelito ha cambiado ____ bien.","o":["para","a","por","hacia"],"a":0,"k":"para bien","t":"미겔리토는 좋은 쪽으로 변했다.","e":"'cambiar para bien'은 '좋은 쪽으로 변하다'라는 뜻이고, 반대는 'cambiar para mal'(나쁜 쪽으로 변하다)입니다. 여기서 para는 변화의 방향·결과를 나타냅니다. '-ito'는 애칭(지소사)으로 '꼬마 미겔' 같은 느낌입니다.","x":["para: 'para bien'으로 좋은 방향의 변화 → 정답 ✓","a: 'cambiar a mejor'처럼 쓰지 'a bien'은 쓰지 않습니다 ✗","por: 'por bien'은 이 의미의 표현이 아닙니다 ✗","hacia: 물리적 방향을 나타내며 'hacia bien'은 쓰지 않습니다 ✗"]},{"id":"G326","q":"Mientras tú ____ la cena, yo he terminado mis deberes.","o":["hiciste","has hecho","harías","hacías"],"a":3,"k":"mientras+불완료과거","t":"네가 저녁을 만드는 동안 나는 숙제를 끝냈어.","e":"'mientras'(~하는 동안)는 진행 중이던 배경 동작을 나타내므로 불완료과거(과거에 계속되던 동작을 나타내는 시제)를 씁니다. 저녁을 만드는 것은 배경, 숙제를 끝낸 것은 완료된 사건입니다. 스페인에서는 오늘 일어난 일을 현재완료(he terminado)로 말하는 경우가 많습니다.","x":["hiciste: 단순과거는 완료된 사건이라 '~하는 동안'이라는 배경을 나타내기 어렵습니다 ✗","has hecho: 현재완료도 완료된 결과를 말해 진행 중인 배경에 맞지 않습니다 ✗","harías: 가능법이라 과거의 실제 동작을 나타내지 않습니다 ✗","hacías: 진행 중이던 과거의 배경 동작 → 정답 ✓"]},{"id":"G327","q":"Anteayer ____ un percance al salir del trabajo.","o":["he tenido","había tenido","tenía","tuve"],"a":3,"k":"단순과거","t":"그저께 나는 퇴근하다가 작은 사고를 당했다.","e":"'anteayer'(그저께)처럼 현재와 끊어진 과거 시점을 나타내는 말과 함께 한 번 일어나고 끝난 사건을 말할 때는 단순과거를 씁니다. 'percance'는 '뜻밖의 작은 사고, 불상사'라는 뜻입니다. 'al + 동사원형'은 '~할 때'라는 뜻입니다.","x":["he tenido: 현재완료는 오늘·이번 주처럼 현재와 이어진 기간에 쓰여 anteayer와 어울리지 않습니다 ✗","había tenido: 과거완료(대과거)로 기준이 되는 다른 과거 시점이 필요합니다 ✗","tenía: 불완료과거는 배경·상태에 쓰여 한 번의 사건에 맞지 않습니다 ✗","tuve: 끝난 과거 사건을 나타내는 단순과거 → 정답 ✓"]},{"id":"G328","q":"____ no soy bienvenido, me marcho de aquí.","o":["Porque","Puesto que","Es que","Que"],"a":1,"k":"이유 puesto que","t":"내가 환영받지 못하니까 여기서 떠나겠다.","e":"'puesto que'는 '~이므로, ~이니까'라는 이유 접속사로, 문장 앞에 놓을 수 있습니다. 반면 'porque'는 보통 주절 뒤에 와서 이유를 설명하므로 문장 맨 앞에는 잘 쓰지 않습니다. 문장 앞에 이유를 둘 때는 'como', 'puesto que', 'ya que'가 자연스럽습니다.","x":["Porque: 일반적으로 주절 뒤에 쓰며 문장 맨 앞에서는 어색합니다 ✗","Puesto que: 문장 앞에서 이유를 나타냄 → 정답 ✓","Es que: '실은 ~해서'라는 변명 표현으로 뒤 절과 연결하는 구조가 아닙니다 ✗","Que: 단독으로 이유절을 문장 앞에 이끌 수 없습니다 ✗"]},{"id":"G329","q":"____ me esforcé, no logré pasar a la final.","o":["Por poco que","Por más que","Mientras","Cuanto"],"a":1,"k":"por más que(양보)","t":"아무리 노력했지만 나는 결승에 진출하지 못했다.","e":"'por más que'는 '아무리 ~해도'라는 양보 표현입니다. 실제로 일어난 과거 사실(노력했다)을 말할 때는 직설법(me esforcé)을, 가정적인 경우에는 접속법을 씁니다. 'lograr + 동사원형'은 '~하는 데 성공하다'입니다.","x":["Por poco que: '아무리 조금 ~해도'라는 뜻이라 의미가 반대가 됩니다 ✗","Por más que: '아무리 ~해도'라는 양보 → 정답 ✓","Mientras: '~하는 동안'이라는 뜻이라 논리가 맞지 않습니다 ✗","Cuanto: 'cuanto más ~, más ~' 비례 구문에 쓰이며 단독으로는 맞지 않습니다 ✗"]},{"id":"G330","q":"____ al principio no me apetecía, acabé yendo a la fiesta y me lo pasé estupendamente.","o":["Aunque","Ya que","Debido a que","Como"],"a":0,"k":"aunque(양보)","t":"처음엔 내키지 않았지만 결국 파티에 갔고 정말 즐겁게 놀았다.","e":"'aunque'는 '비록 ~이지만'이라는 가장 기본적인 양보 접속사입니다. 사실을 말할 때는 직설법(no me apetecía)이 옵니다. 'acabar + 현재분사'는 '결국 ~하게 되다', 'pasárselo estupendamente'는 '아주 즐겁게 보내다'라는 뜻입니다.","x":["Aunque: '~이지만'이라는 양보 → 정답 ✓","Ya que: '~이므로'라는 이유 접속사라 논리가 반대가 됩니다 ✗","Debido a que: '~때문에'라는 이유 표현으로 문맥과 맞지 않습니다 ✗","Como: 문장 앞에서 '~이므로'라는 이유를 나타내 의미가 맞지 않습니다 ✗"]},{"id":"G331","q":"____ es esencial para el cuerpo y la mente.","o":["Descansado","Descanso","Descansar","Descansando"],"a":2,"k":"동사원형 주어","t":"쉬는 것은 몸과 마음에 필수적이다.","e":"스페인어에서는 동사원형이 명사처럼 문장의 주어가 될 수 있습니다(한국어의 '~하는 것'). 'Descansar es esencial'은 '쉬는 것이 필수적이다'입니다. 영어처럼 -ing 형태(현재분사)를 주어로 쓰지 않는다는 점에 주의하세요.","x":["Descansado: 과거분사(쉰, 피로가 풀린)로 주어가 될 수 없습니다 ✗","Descanso: '휴식'이라는 명사로 쓰려면 보통 관사 'El descanso'가 필요합니다 ✗","Descansar: 동사원형이 명사처럼 주어 역할 → 정답 ✓","Descansando: 현재분사는 스페인어에서 주어로 쓰지 않습니다(영어식 오류) ✗"]},{"id":"G332","q":"Estábamos tan agotados que ____ conseguimos llegar a la meta.","o":["así","apenas","siquiera","casi"],"a":1,"k":"apenas(간신히)","t":"우리는 너무 지쳐서 간신히 결승선에 도착할 수 있었다.","e":"'apenas'는 '거의 ~않다, 간신히 ~하다'라는 뜻의 부사입니다. 여기서는 '가까스로, 겨우 도착했다'라는 의미를 줍니다. 'tan ~ que'는 '너무 ~해서 ~하다'라는 결과 구문입니다.","x":["así: '이렇게'라는 뜻이라 의미가 맞지 않습니다 ✗","apenas: '간신히, 겨우'라는 뜻 → 정답 ✓","siquiera: '~조차'라는 뜻으로 보통 ni나 부정어와 함께 씁니다 ✗","casi: '거의'라는 뜻이지만 'casi conseguimos'는 '거의 해낼 뻔했다'(실패)가 되어 문맥과 다릅니다 ✗"]},{"id":"G333","q":"Comprar una vivienda no está ____ alcance de todos.","o":["por el","en el","al","del"],"a":2,"k":"al alcance de","t":"집을 사는 것은 모든 사람이 할 수 있는 일이 아니다.","e":"'estar al alcance de alguien'은 '~의 손이 닿는 곳에 있다, ~가 감당할 수 있다'라는 뜻의 관용 표현입니다. 'al'은 'a + el'의 축약형입니다. 예: Mantener fuera del alcance de los niños. (어린이의 손이 닿지 않는 곳에 보관하세요.)","x":["por el: 'por el alcance'는 쓰지 않는 결합입니다 ✗","en el: 'en el alcance'는 이 관용 표현의 형태가 아닙니다 ✗","al: 'al alcance de'로 '감당할 수 있는 범위에' → 정답 ✓","del: 'fuera del alcance'처럼 fuera가 있을 때만 씁니다 ✗"]},{"id":"G334","q":"Dejad que os ____ lo que pasó al final de la celebración.","o":["explica","explique","expliquéis","explico"],"a":1,"k":"dejar que+접속법","t":"축하 행사 마지막에 무슨 일이 있었는지 내가 너희에게 설명할게.","e":"'dejar que + 접속법'은 '~가 ~하게 두다/허락하다'라는 뜻입니다. 'Dejad que os explique'는 '내가 너희에게 설명하게 해 줘'라는 뜻으로, 설명하는 사람은 yo이므로 접속법 현재 1인칭 'explique'가 맞습니다.","x":["explica: 직설법이라 dejar que 뒤에 쓸 수 없습니다 ✗","explique: yo의 접속법 현재 → 정답 ✓","expliquéis: vosotros 형태라 '너희가 너희에게 설명하다'가 되어 의미가 이상합니다 ✗","explico: 직설법 1인칭이라 접속법 자리에 맞지 않습니다 ✗"]},{"id":"G335","q":"Ese piloto perdió la carrera porque no logró poner el coche ____ marcha.","o":["de","con","a","en"],"a":3,"k":"poner en marcha","t":"그 레이서는 차의 시동을 걸지 못해서 경주에서 졌다.","e":"'poner algo en marcha'는 '~을 작동시키다, 시동을 걸다, 시작하다'라는 뜻의 관용 표현입니다. 기계뿐 아니라 계획·프로젝트에도 씁니다. 예: poner en marcha un proyecto(프로젝트를 시작하다).","x":["de: 'de marcha'는 '놀러 나가다(ir de marcha)'처럼 다른 뜻의 표현입니다 ✗","con: 'con marcha'는 쓰지 않는 결합입니다 ✗","a: 'a marcha'는 이 표현의 전치사가 아닙니다 ✗","en: 'poner en marcha'로 '작동시키다' → 정답 ✓"]},{"id":"G336","q":"Volvió ____ segundos después de desmayarse.","o":["en sí","por sí","a sí","de sí"],"a":0,"k":"volver en sí","t":"그는 기절한 지 몇 초 후에 정신을 차렸다.","e":"'volver en sí'는 '의식을 되찾다, 정신이 들다'라는 뜻의 관용 표현입니다. 'sí'는 재귀 전치격 대명사로 주어에 따라 바뀝니다. 예: volví en mí(내가 정신을 차렸다), volviste en ti(네가 정신을 차렸다).","x":["en sí: 'volver en sí'로 '의식을 되찾다' → 정답 ✓","por sí: 'por sí mismo'(스스로)처럼 쓰여 이 표현과 다릅니다 ✗","a sí: 'a sí mismo'(자기 자신에게)라는 뜻으로 맞지 않습니다 ✗","de sí: 'dar de sí'(늘어나다)처럼 다른 표현에 씁니다 ✗"]},{"id":"G337","q":"No os llamé porque ____ sin batería.","o":["quedé","quedó","me quedé","me quedo"],"a":2,"k":"quedarse sin","t":"배터리가 다 떨어져서 너희에게 전화하지 못했어.","e":"'quedarse sin + 명사'는 '~이 다 떨어지다, ~이 없게 되다'라는 뜻으로 재귀대명사 se가 꼭 필요합니다. 주어는 yo이고 과거의 한 사건이므로 'me quedé'(단순과거)를 씁니다. 예: Me quedé sin dinero. (돈이 다 떨어졌다.)","x":["quedé: 재귀대명사 me가 빠져 'quedarse sin'의 의미가 되지 않습니다 ✗","quedó: 3인칭이고 재귀대명사도 없어 주어와 맞지 않습니다 ✗","me quedé: yo의 단순과거 재귀형 → 정답 ✓","me quedo: 현재형이라 과거 사건(no os llamé)과 시제가 맞지 않습니다 ✗"]},{"id":"G338","q":"Tienes ____ tos horrible, debes ir al médico cuanto antes.","o":["ø","una","la","un"],"a":1,"k":"부정관사+형용사","t":"너 기침이 엄청 심하다, 가능한 한 빨리 병원에 가 봐.","e":"'tos'(기침)는 여성 명사이므로 부정관사 'una'를 씁니다. 'horrible' 같은 평가 형용사가 붙어 '아주 심한 기침'처럼 특징을 묘사할 때는 부정관사가 필요합니다. 그냥 'Tengo tos'(기침이 나)라고 할 때는 관사 없이 씁니다.","x":["ø: 형용사가 붙어 특정한 종류를 묘사하므로 관사가 필요합니다 ✗","una: 여성 명사 tos의 부정관사 → 정답 ✓","la: 정관사는 이미 알려진 특정한 기침을 가리켜 문맥과 맞지 않습니다 ✗","un: tos는 여성 명사라 남성 관사 un을 쓸 수 없습니다 ✗"]},{"id":"G339","q":"Las mantas no ____ en el armario.","o":["cabían","cupieran","cupimos","quepan"],"a":0,"k":"caber 활용","t":"담요들이 옷장에 들어가지 않았다.","e":"'caber'(들어가다, 수용되다)는 불규칙 동사입니다. 주어가 'las mantas'(3인칭 복수)이고 단순한 사실을 말하는 독립문이므로 직설법 불완료과거 'cabían'이 맞습니다. 참고로 현재형 yo는 'quepo', 단순과거는 'cupe'입니다.","x":["cabían: 3인칭 복수 직설법 불완료과거 → 정답 ✓","cupieran: 접속법 과거로 독립된 평서문에 쓸 수 없습니다 ✗","cupimos: 1인칭 복수(우리)라 주어 las mantas와 맞지 않습니다 ✗","quepan: 접속법 현재로 독립된 평서문에 쓰지 않습니다 ✗"]},{"id":"G340","q":"¿Alguien ____ a este matrimonio?","o":["se opone","se oponga","opone","oponga"],"a":0,"k":"oponerse a","t":"이 결혼에 반대하는 분 계십니까?","e":"'oponerse a algo'는 '~에 반대하다'라는 뜻으로 재귀대명사 se가 필요한 동사입니다. 결혼식에서 실제로 쓰는 질문이며, 사실을 묻는 의문문이라 직설법을 씁니다. 여기서 'matrimonio'는 '결혼(혼인)'이라는 뜻입니다.","x":["se opone: 재귀동사 oponerse의 직설법 현재 → 정답 ✓","se oponga: 접속법이라 단순 의문문에 쓰지 않습니다 ✗","opone: se가 없으면 '~을 대립시키다'라는 타동사가 되어 의미가 바뀝니다 ✗","oponga: se도 없고 접속법이라 이중으로 틀립니다 ✗"]},{"id":"G341","q":"Marisa es muy inteligente ____ la edad que tiene.","o":["en","desde","por","para"],"a":3,"k":"para(기준 대비)","t":"마리사는 나이에 비해 아주 똑똑하다.","e":"전치사 'para'는 '~에 비해서, ~치고는'이라는 비교 기준을 나타낼 수 있습니다. 예: Hace calor para ser invierno. (겨울치고는 덥다.) 'para la edad que tiene'는 '그녀가 가진 나이에 비해'라는 뜻입니다.","x":["en: 'en la edad'는 '~ 나이에'라는 시점이라 비교 의미가 없습니다 ✗","desde: '~부터'라는 기점이라 의미가 맞지 않습니다 ✗","por: 원인이나 이유를 나타내 '나이 때문에'가 되어 어색합니다 ✗","para: '~에 비해'라는 비교 기준 → 정답 ✓"]},{"id":"G342","q":"¡Qué bueno es este niño! Es ____ corazón.","o":["todo","totalmente","tanto","mucho"],"a":0,"k":"todo corazón","t":"이 아이 정말 착하다! 마음씨가 정말 따뜻해.","e":"'ser todo corazón'은 '마음이 아주 따뜻하다, 정이 많다'라는 뜻의 관용 표현입니다. 'ser todo + 명사'는 '완전히 ~ 그 자체다'라는 강조로, 예를 들어 'Es todo oídos'(귀 기울여 듣고 있다)도 같은 구조입니다.","x":["todo: 'ser todo corazón'으로 '정이 넘치다' → 정답 ✓","totalmente: '완전히'라는 부사로 명사 corazón 앞에 직접 오지 않습니다 ✗","tanto: '그만큼'이라는 뜻으로 이 관용 표현에 쓰지 않습니다 ✗","mucho: 'mucho corazón'은 '마음이 크다'처럼 들리지만 ser 뒤에 쓰는 관용형이 아닙니다 ✗"]},{"id":"G343","q":"Este cuadro es ____ una originalidad impresionante.","o":["con","sobre","de","hasta"],"a":2,"k":"ser de + 명사(특성)","t":"이 그림은 놀라울 정도로 독창적이다.","e":"'ser de + 부정관사 + 명사 + 형용사'는 '~한 성질을 지니다'라는 특성 묘사 구문입니다. 예: Es de una belleza increíble. (믿기 어려울 만큼 아름답다.) 격식 있는 글이나 예술 평에서 자주 쓰입니다.","x":["con: 'es con'은 특성을 나타내는 구조가 아닙니다 ✗","sobre: '~에 대한'이라는 뜻이라 '독창성에 관한 그림'처럼 의미가 바뀝니다 ✗","de: 'ser de una + 명사'로 특성을 강조함 → 정답 ✓","hasta: '~까지'라는 뜻이라 이 구조에 맞지 않습니다 ✗"]},{"id":"G344","q":"Que ____ un buen nivel de inglés no significa que seamos nativos.","o":["tuvimos","teníamos","tengamos","tenemos"],"a":2,"k":"que절 주어+접속법","t":"우리가 영어 실력이 좋다고 해서 원어민이라는 뜻은 아니다.","e":"'Que + 절'이 문장 맨 앞에서 주어 역할을 할 때(~라는 것은), 그 절의 동사는 보통 접속법을 씁니다. 사실이라도 '그 사실 자체'를 평가·논의의 대상으로 삼기 때문입니다. 뒤의 'no significa que seamos'도 부정 뒤 접속법입니다.","x":["tuvimos: 직설법 단순과거라 문두 que 주어절에 맞지 않습니다 ✗","teníamos: 직설법 불완료과거로 시제도 법도 맞지 않습니다 ✗","tengamos: 문두 que절의 접속법 현재 → 정답 ✓","tenemos: 직설법이라 이 구조에서는 쓰지 않습니다 ✗"]},{"id":"G345","q":"Me parece lógico que ____. Se llevan fatal.","o":["hayan divorciado","han divorciado","habrán divorciado","se hayan divorciado"],"a":3,"k":"divorciarse+접속법","t":"그들이 이혼한 건 당연한 것 같아. 사이가 너무 안 좋거든.","e":"'Me parece lógico que'처럼 가치 판단을 나타내는 표현 뒤에는 접속법을 씁니다. 이미 일어난 일이므로 접속법 현재완료(hayan + 과거분사)이고, 'divorciarse'(이혼하다)는 재귀동사라 se가 필요합니다. 'llevarse fatal'은 '사이가 아주 나쁘다'입니다.","x":["hayan divorciado: 재귀대명사 se가 빠져 있습니다 ✗","han divorciado: se도 없고 직설법이라 틀립니다 ✗","habrán divorciado: 직설법 미래완료로 가치 판단 뒤에 맞지 않고 se도 없습니다 ✗","se hayan divorciado: 재귀형 접속법 현재완료 → 정답 ✓"]},{"id":"G346","q":"¿Podemos hablar luego? Es que ahora mismo ____ a punto de salir.","o":["estaría","voy a estar","estoy","estaré"],"a":2,"k":"a punto de","t":"나중에 얘기해도 될까? 사실 지금 막 나가려던 참이야.","e":"'estar a punto de + 동사원형'은 '막 ~하려는 참이다'라는 뜻입니다. 'ahora mismo'(지금 당장)가 현재 상황을 말하므로 직설법 현재 'estoy'가 맞습니다. 'Es que'는 이유나 변명을 부드럽게 꺼낼 때 쓰는 표현입니다.","x":["estaría: 가능법이라 지금 실제 상황을 말하는 데 맞지 않습니다 ✗","voy a estar: 미래를 나타내 'ahora mismo'와 어울리지 않습니다 ✗","estoy: 현재 상황을 나타내는 직설법 현재 → 정답 ✓","estaré: 미래형이라 지금 상황이 아닙니다 ✗"]},{"id":"G347","q":"Hizo una comida tan rica que ____ en un abrir y cerrar de ojos.","o":["se desapareció","estuvo desapareciendo","desapareció","desapareciera"],"a":2,"k":"desaparecer","t":"그가 만든 음식이 너무 맛있어서 눈 깜짝할 사이에 사라졌다.","e":"'desaparecer'(사라지다)는 자동사라 재귀대명사 se 없이 씁니다. 한순간에 일어난 완료된 사건이므로 단순과거 'desapareció'가 맞습니다. 'en un abrir y cerrar de ojos'는 '눈 깜짝할 사이에'라는 관용 표현입니다.","x":["se desapareció: 표준어에서 desaparecer는 se 없이 씁니다(일부 중남미 구어에서는 들리기도 함) ✗","estuvo desapareciendo: 진행형이라 '순식간에'라는 의미와 모순됩니다 ✗","desapareció: 순간적으로 끝난 사건의 단순과거 → 정답 ✓","desapareciera: 접속법이라 tan ~ que 결과절(사실)에는 직설법을 씁니다 ✗"]},{"id":"G348","q":"Para el martes ya ____ el paquete.","o":["estamos recibiendo","hayamos recibido","recibiremos","habremos recibido"],"a":3,"k":"미래완료","t":"화요일까지는 이미 소포를 받았을 것이다.","e":"'para + 시점'(~까지는)과 함께 미래의 어느 시점에 이미 완료되어 있을 일을 말할 때는 미래완료(habré + 과거분사)를 씁니다. 'ya'(이미)도 완료의 의미를 강조합니다.","x":["estamos recibiendo: 현재진행형이라 미래 시점의 완료를 나타내지 않습니다 ✗","hayamos recibido: 접속법이라 독립된 주절에 쓸 수 없습니다 ✗","recibiremos: 단순미래로 '받을 것이다'일 뿐 '이미 받아 있을 것'이라는 완료 의미가 약합니다 ✗","habremos recibido: 미래 시점 이전 완료 → 정답 ✓"]},{"id":"G349","q":"Antes de que ____ cuenta, nos habían robado las maletas.","o":["pudiéramos darnos","podíamos darnos","podríamos darnos","pudiésemos dar"],"a":0,"k":"antes de que","t":"우리가 미처 알아채기도 전에 가방을 도둑맞았다.","e":"'antes de que'는 항상 접속법을 씁니다. 주절이 과거(nos habían robado)이므로 접속법 과거 'pudiéramos'가 맞습니다. 'darse cuenta'(알아차리다)는 재귀동사라 nos가 꼭 있어야 합니다.","x":["pudiéramos darnos: 접속법 과거 + 재귀대명사까지 갖춘 형태 → 정답 ✓","podíamos darnos: 직설법이라 antes de que 뒤에 쓸 수 없습니다 ✗","podríamos darnos: 가능법이라 antes de que 뒤에 맞지 않습니다 ✗","pudiésemos dar: 접속법 과거(-se 형)는 맞지만 재귀대명사 nos가 빠졌습니다 ✗"]},{"id":"G350","q":"Como no ____ a la hora acordada, nos iremos sin ti.","o":["vendrás","vengas","vienes","vinieras"],"a":1,"k":"como+접속법(조건)","t":"약속한 시간에 네가 안 오면 우리는 너 없이 갈 거야.","e":"'como'가 문장 앞에서 접속법과 함께 쓰이면 '만약 ~하면'이라는 조건, 특히 경고·위협의 뉘앙스를 가집니다. 직설법과 쓰면 '~이므로'(이유)가 됩니다. 예: Como no estudies, suspenderás. (공부 안 하면 낙제할 거야.)","x":["vendrás: 직설법 미래라 como 조건문에 쓰지 않습니다 ✗","vengas: como + 접속법 현재로 경고성 조건 → 정답 ✓","vienes: 직설법이면 '네가 안 오니까'라는 이유가 되어 미래 상황과 어긋납니다 ✗","vinieras: 접속법 과거라 주절의 미래(nos iremos)와 시제가 맞지 않습니다 ✗"]},{"id":"G351","q":"____ Fernando, parecía tonto pero es listísimo.","o":["Vaya","Vaya con","Y dale con","Y dale"],"a":1,"k":"vaya con(감탄)","t":"페르난도 녀석 참! 바보 같아 보였는데 엄청 똑똑하네.","e":"'¡Vaya con + 사람/사물!'은 놀람·감탄(때로 약간의 비꼼)을 나타내는 구어 표현으로 '~ 참 대단하네!, ~ 좀 봐!'라는 느낌입니다. 'vaya' 혼자는 '¡Vaya!'(어머나!)처럼 감탄사로 쓰지만, 사람 이름과 이을 때는 con이 필요합니다.","x":["Vaya: 감탄사지만 사람 이름을 바로 잇지 않고 con이 필요합니다 ✗","Vaya con: '~ 참 대단하네!'라는 감탄 표현 → 정답 ✓","Y dale con: '또 ~ 얘기야!'라는 짜증 표현이라 칭찬하는 문맥과 맞지 않습니다 ✗","Y dale: '또 시작이네!'라는 짜증 표현으로 의미가 맞지 않습니다 ✗"]},{"id":"G352","q":"____ que más me gusta es practicar deportes de equipo.","o":["La","ø","El","Lo"],"a":3,"k":"lo que(~것)","t":"내가 가장 좋아하는 건 단체 운동을 하는 것이다.","e":"'lo que'는 '~하는 것'이라는 뜻의 중성 관계사로, 특정 명사를 가리키지 않고 추상적인 내용을 가리킬 때 씁니다. 여기서는 '내가 가장 좋아하는 것'이 특정 명사가 아니라 활동이므로 중성 관사 lo를 씁니다.","x":["La: 여성 명사를 가리킬 때 쓰며 가리킬 명사가 없습니다 ✗","ø: 'Que más me gusta'는 문법적으로 성립하지 않습니다 ✗","El: 남성 명사를 가리킬 때 쓰며 여기선 가리킬 명사가 없습니다 ✗","Lo: 추상적인 '~것'을 나타내는 중성형 → 정답 ✓"]},{"id":"G353","q":"Parecen ____ muy seguros de lo que vieron.","o":["que estén","que están","estar","a estar"],"a":2,"k":"parecer+동사원형","t":"그들은 자기가 본 것에 대해 아주 확신하는 것 같다.","e":"'parecer + 동사원형'은 '~인 것 같다'라는 뜻입니다. 주어(ellos)가 parecen과 일치하고, 뒤에 동사원형 'estar'가 바로 옵니다. 'que'를 쓰려면 'Parece que están...'처럼 parecer를 3인칭 단수 무인칭으로 써야 합니다.","x":["que estén: parecen(복수 주어)과 que절을 함께 쓰는 구조가 아니며 접속법도 틀립니다 ✗","que están: 'Parece que están'이라면 맞지만 parecen과는 어울리지 않습니다 ✗","estar: 'parecer + 동사원형'으로 '~인 것 같다' → 정답 ✓","a estar: parecer 뒤에 전치사 a를 넣지 않습니다 ✗"]},{"id":"G354","q":"Juanito camina igual ____ su padre.","o":["de","tanto","que","como"],"a":2,"k":"igual que","t":"후아니토는 아빠랑 똑같이 걷는다.","e":"'igual que'는 '~와 똑같이'라는 비교 표현입니다. 표준어에서는 'igual que'가 정석이며, 'igual a'(형용사로서 ~와 같은)도 씁니다. 'igual como'는 일부 중남미 구어에서 들리지만 표준으로 권장되지 않습니다.","x":["de: 'igual de + 형용사'(똑같이 ~한)처럼 쓰며 사람과 비교할 때는 쓰지 않습니다 ✗","tanto: igual과 함께 쓰는 비교 표현이 아닙니다 ✗","que: 'igual que'로 '~와 똑같이' → 정답 ✓","como: 'tanto como'와 혼동한 형태로, 'igual como'는 비표준입니다 ✗"]},{"id":"G355","q":"¡Deja de seguirme ____ vez!","o":["a una","de una","para una","una"],"a":1,"k":"de una vez","t":"이제 그만 좀 나를 따라다녀!","e":"'de una vez'는 '단번에, 이제 그만 좀, 제발 좀'이라는 뜻으로 짜증과 재촉을 담아 말할 때 자주 씁니다. 'de una vez por todas'(이번에 확실히)도 많이 쓰는 표현입니다. 'dejar de + 동사원형'은 '~하는 것을 그만두다'입니다.","x":["a una: 'a una vez'는 쓰지 않는 표현입니다 ✗","de una: 'de una vez'로 '이제 그만 좀' → 정답 ✓","para una: 'para una vez'는 이 의미가 없습니다 ✗","una: 'una vez'는 '한 번'이라는 뜻이라 문맥에 맞지 않습니다 ✗"]},{"id":"G356","q":"¡Hace ____ frío que pela!","o":["un","ø","el","lo"],"a":0,"k":"frío que pela","t":"살을 에는 듯이 춥다!","e":"'hace un frío que pela'는 '살갗이 벗겨질 정도로 춥다, 엄청 춥다'라는 뜻의 관용 표현입니다. 날씨 명사에 'que + 절'로 정도를 강조할 때는 부정관사 un을 씁니다. 예: Hace un calor que no se puede aguantar. (참을 수 없을 만큼 덥다.)","x":["un: 강조 구문 'hace un frío que...' → 정답 ✓","ø: 'hace frío'는 가능하지만 뒤에 que pela가 오면 un이 필요합니다 ✗","el: 정관사를 쓰면 이 관용 표현이 되지 않습니다 ✗","lo: 중성 관사는 남성 명사 frío 앞에 쓰지 않습니다 ✗"]},{"id":"G357","q":"No me hizo ninguna gracia que ____ de esa forma.","o":["respondió","esté respondiendo","respondería","respondiera"],"a":3,"k":"감정+접속법 과거","t":"그가 그런 식으로 대답한 게 전혀 마음에 들지 않았다.","e":"'no me hizo gracia que'(~한 것이 달갑지 않았다)는 감정 표현이라 que절에 접속법을 씁니다. 주절이 과거(hizo)이므로 접속법 과거 'respondiera'가 맞습니다. 'hacer gracia'는 '재미있다, 마음에 들다'라는 뜻입니다.","x":["respondió: 직설법이라 감정 표현 뒤 que절에 쓰지 않습니다 ✗","esté respondiendo: 접속법 현재 진행형이라 과거 주절과 시제가 맞지 않습니다 ✗","respondería: 가능법이라 이 구조에 맞지 않습니다 ✗","respondiera: 과거 감정 표현 뒤 접속법 과거 → 정답 ✓"]},{"id":"G358","q":"____ cantidad de dinero que tiene y no le da nada a los más necesitados. ¡Increíble!","o":["Con la tal","Con lo","Con la","Con tal"],"a":2,"k":"con + 명사(양보)","t":"그 많은 돈을 가지고도 가장 어려운 사람들에게 아무것도 안 준다니. 믿을 수가 없어!","e":"'Con + 정관사 + 명사 + que...'는 '그렇게 ~한데도'라는 양보·비난의 뉘앙스를 담은 표현입니다. 'cantidad'가 여성 명사이므로 'Con la'를 씁니다. 형용사·부사일 때는 'Con lo + 형용사 + que'(예: Con lo rico que es)를 씁니다.","x":["Con la tal: 'tal'이 끼어들어 문법적으로 성립하지 않습니다 ✗","Con lo: lo는 형용사·부사 앞에 쓰며 명사 cantidad 앞에는 쓰지 않습니다 ✗","Con la: 여성 명사 cantidad와 함께 양보 표현 → 정답 ✓","Con tal: 'con tal de/que'는 '~하기만 하면'이라는 조건 표현입니다 ✗"]},{"id":"G359","q":"Elvira es una experta ____ exagerar las cosas.","o":["de","por","a","en"],"a":3,"k":"experto en","t":"엘비라는 일을 과장하는 데 전문가다.","e":"'experto/a en + 명사/동사원형'은 '~의 전문가'라는 뜻으로 전치사 en을 씁니다. 여기서는 비꼬는 뉘앙스로 '과장하는 데 선수다'라는 의미입니다. 비슷하게 'especialista en', 'maestro en'도 en을 씁니다.","x":["de: 'experto de'는 일반적이지 않은 결합입니다 ✗","por: 원인을 나타내 이 결합에 쓰지 않습니다 ✗","a: 'experto a'는 쓰지 않습니다 ✗","en: 'experto en'으로 분야를 나타냄 → 정답 ✓"]},{"id":"G360","q":"¿A qué hora ____ a laburar?","o":["comenzas","comenzás","comenzad","comience"],"a":1,"k":"voseo(아르헨티나)","t":"너 몇 시에 일하러 가기 시작해?","e":"'laburar'(일하다)는 아르헨티나·우루과이에서 쓰는 구어로, 그 지역에서는 tú 대신 'vos'를 씁니다. vos의 현재형은 어간 모음 변화가 없고 끝 음절에 강세가 옵니다: comenzar → vos comenzás (tú comienzas). 이런 지역적 특징이 이 문제의 핵심입니다.","x":["comenzas: 악센트가 빠져 있어 올바른 voseo 형태가 아닙니다 ✗","comenzás: vos의 직설법 현재(강세가 끝에) → 정답 ✓","comenzad: vosotros 명령형이라 의문문에 쓸 수 없습니다 ✗","comience: 접속법 또는 usted 명령형이라 맞지 않습니다 ✗"]},{"id":"G361","q":"¡____ nos reímos con los chistes de Tomás!","o":["Qué","Cuán","Cómo","Cuál"],"a":2,"k":"감탄문 cómo","t":"토마스의 농담에 우리가 얼마나 웃었는지!","e":"동사를 강조하는 감탄문은 '¡Cómo + 동사!'(얼마나 ~하는지!)를 씁니다. 예: ¡Cómo llueve! (비가 정말 많이 오네!) 반면 '¡Qué + 형용사/명사/부사!'는 형용사·명사를 강조할 때 씁니다.","x":["Qué: 형용사·명사·부사 앞에 쓰며 동사 바로 앞에서 정도를 강조하지 않습니다 ✗","Cuán: '얼마나'라는 뜻의 문어적 표현으로 형용사·부사 앞에 쓰며 동사에는 쓰지 않습니다 ✗","Cómo: 동사의 정도를 강조하는 감탄 → 정답 ✓","Cuál: '어느 것'이라는 뜻이라 감탄문에 쓰지 않습니다 ✗"]},{"id":"G362","q":"No vino absolutamente nadie a la clase de ayer, ____ Rosa.","o":["ni siquiera","ni incluso","hasta ni","tan siquiera"],"a":0,"k":"ni siquiera","t":"어제 수업에는 정말 아무도 오지 않았다, 로사조차도.","e":"'ni siquiera'는 '~조차도 (아니다)'라는 부정 강조 표현입니다. 앞 문장이 부정문(No vino nadie)이므로 부정을 이어 가는 ni siquiera가 자연스럽습니다. 'ni tan siquiera'도 같은 뜻이지만 'tan siquiera' 단독으로는 이 자리에 맞지 않습니다.","x":["ni siquiera: 부정문에서 '~조차도' → 정답 ✓","ni incluso: incluso는 긍정의 '심지어'라서 ni와 결합하지 않습니다 ✗","hasta ni: 존재하지 않는 결합입니다 ✗","tan siquiera: 'ni tan siquiera'처럼 ni가 있어야 부정 의미가 됩니다 ✗"]},{"id":"G363","q":"Todos nos alegraremos cuando por fin ____ paz.","o":["haya","habría","habrá","hay"],"a":0,"k":"cuando+접속법(미래)","t":"마침내 평화가 찾아오면 우리 모두 기뻐할 것이다.","e":"'cuando'가 미래의 일을 가리킬 때는 접속법을 씁니다. 주절이 미래(nos alegraremos)이고 평화는 아직 오지 않았으므로 'haber'의 접속법 현재 'haya'가 맞습니다. 'haber'는 존재(~이 있다)를 나타낼 때 3인칭 단수로만 씁니다.","x":["haya: 미래 시간절의 접속법 현재 → 정답 ✓","habría: 가능법이라 cuando 뒤에 쓰지 않습니다 ✗","habrá: 직설법 미래는 cuando 뒤에 쓸 수 없습니다 ✗","hay: 직설법 현재로 습관이나 현재 사실에만 씁니다 ✗"]},{"id":"G364","q":"____ a valerte por ti misma, te sentirás más autónoma.","o":["Aprenda","Aprende","Aprendas","Aprendes"],"a":1,"k":"tú 긍정 명령","t":"스스로 해내는 법을 배워 봐, 그러면 더 자립적으로 느껴질 거야.","e":"tú에 대한 긍정 명령형은 보통 직설법 현재 3인칭 단수와 같은 형태입니다: aprender → aprende. 'valerse por sí mismo/a'는 '혼자 힘으로 해내다, 자립하다'라는 뜻이고, 여기서는 여성(misma)에게 하는 말입니다.","x":["Aprenda: usted 명령형이라 뒤의 ti, te와 맞지 않습니다 ✗","Aprende: tú 긍정 명령형 → 정답 ✓","Aprendas: 접속법으로 부정 명령(No aprendas)에서만 씁니다 ✗","Aprendes: 직설법 현재라 명령이 아니라 사실 진술이 됩니다 ✗"]},{"id":"G365","q":"Isabel ____ por ahí que estáis en bancarrota.","o":["viene diciendo","va diciendo","lleva diciendo","se va diciendo"],"a":1,"k":"ir + 현재분사","t":"이사벨이 너희가 파산했다고 여기저기 말하고 다닌다.","e":"'ir + 현재분사'는 '~하며 다니다, 점점 ~하다'라는 뜻입니다. 'ir diciendo por ahí'는 '여기저기 말하고 다니다'라는 아주 자주 쓰는 표현입니다. 'estar en bancarrota'는 '파산 상태다'입니다.","x":["viene diciendo: '예전부터 계속 말해 왔다'라는 뜻이라 '여기저기'(por ahí)와 잘 어울리지 않습니다 ✗","va diciendo: '말하고 다닌다' → 정답 ✓","lleva diciendo: 'lleva + 기간 + 현재분사'처럼 기간이 함께 와야 자연스럽습니다 ✗","se va diciendo: ir를 재귀형으로 쓰면 이 의미가 되지 않습니다 ✗"]},{"id":"G366","q":"Espero que no se ____ más la situación.","o":["complica","complicara","complicará","complique"],"a":3,"k":"esperar que+접속법","t":"상황이 더 복잡해지지 않기를 바란다.","e":"'esperar que'(~하기를 바라다)는 바람을 나타내므로 que절에 접속법을 씁니다. 주절이 현재(Espero)이므로 접속법 현재 'complique'가 맞습니다. 'complicarse'는 '복잡해지다, 꼬이다'라는 재귀동사입니다.","x":["complica: 직설법이라 바람 표현 뒤에 맞지 않습니다 ✗","complicara: 접속법 과거라 현재 주절 Espero와 시제가 어긋납니다 ✗","complicará: 직설법 미래라 esperar que 뒤에 쓰지 않습니다 ✗","complique: 바람을 나타내는 접속법 현재 → 정답 ✓"]},{"id":"G367","q":"____ lo trabajador que es y no le dan un aumento...","o":["Por","Con","De","Para"],"a":1,"k":"con lo + 형용사","t":"그는 그렇게 열심히 일하는데도 월급을 안 올려 준다니…","e":"'Con lo + 형용사 + que + 동사'는 '그렇게 ~한데도'라는 뜻으로 놀라움이나 불만을 담은 양보 표현입니다. 예: Con lo listo que es, no aprobó. (그렇게 똑똑한데도 시험에 떨어졌다.) 'trabajador'는 '부지런한, 일 잘하는'이라는 형용사입니다.","x":["Por: 'por lo + 형용사'는 '~하기 때문에'라는 이유를 나타내 의미가 반대가 됩니다 ✗","Con: 'con lo ~ que'로 '그렇게 ~한데도' → 정답 ✓","De: 'de lo + 형용사'는 '너무 ~해서'라는 원인 표현이라 맞지 않습니다 ✗","Para: 'para lo + 형용사'는 '~한 것에 비해'라는 뜻이라 문맥과 다릅니다 ✗"]},{"id":"G368","q":"Nadie se dio cuenta ____ nada hasta la explosión.","o":["por","de","con","en"],"a":1,"k":"darse cuenta de","t":"폭발이 일어날 때까지 아무도 아무것도 눈치채지 못했다.","e":"'darse cuenta de algo'는 '~을 알아차리다, 깨닫다'라는 뜻으로 전치사 de가 꼭 필요합니다. 'que절'이 와도 'darse cuenta de que...'처럼 de를 유지합니다. de를 빼는 것은 흔한 실수(queísmo)입니다.","x":["por: darse cuenta와 결합하지 않습니다 ✗","de: 'darse cuenta de'로 '~을 알아차리다' → 정답 ✓","con: 'darse cuenta con'은 쓰지 않습니다 ✗","en: 'darse cuenta en'은 쓰지 않습니다 ✗"]},{"id":"G369","q":"En caso ____ ir, te avisaré con antelación.","o":["de no haber podido","de no poder","de no pueda","que no puedo"],"a":1,"k":"en caso de+동사원형","t":"혹시 갈 수 없게 되면 미리 알려 줄게.","e":"'en caso de + 동사원형'은 '~하는 경우에'라는 조건 표현입니다. 절이 오면 'en caso de que + 접속법'(en caso de que no pueda)을 씁니다. 'con antelación'은 '미리, 사전에'라는 뜻입니다.","x":["de no haber podido: 완료형이라 미래의 가능성을 말하는 문맥과 시제가 맞지 않습니다 ✗","de no poder: 'en caso de + 동사원형' → 정답 ✓","de no pueda: 동사 활용형 앞에는 que가 필요합니다(de que no pueda) ✗","que no puedo: de가 빠지고 직설법이라 이중으로 틀립니다 ✗"]},{"id":"G370","q":"Conocemos a una familia que cada año ____ a un país diferente.","o":["trasladan","se traslade","se traslada","traslada"],"a":2,"k":"trasladarse","t":"우리는 매년 다른 나라로 이사하는 가족을 알고 있다.","e":"'trasladarse'는 '이주하다, 옮겨 가다'라는 재귀동사입니다. 'una familia'는 여러 사람이지만 문법적으로 단수 집합명사라 동사도 3인칭 단수 'se traslada'를 씁니다. 실제로 존재하는 가족을 말하므로 직설법입니다.","x":["trasladan: 복수형이고 se도 없어 틀립니다 ✗","se traslade: 접속법은 존재 여부가 불확실한 대상을 말할 때 씁니다 ✗","se traslada: 단수 집합명사 + 재귀동사 직설법 → 정답 ✓","traslada: se가 없으면 '~을 옮기다'라는 타동사가 되어 목적어가 필요합니다 ✗"]},{"id":"G371","q":"____ un niño pequeño puede entenderlo.","o":["Ya","Todavía","Aún","Incluso"],"a":3,"k":"incluso(심지어)","t":"어린아이조차도 그것을 이해할 수 있다.","e":"'incluso'는 '~조차, 심지어 ~도'라는 뜻의 부사로, 예상 밖의 대상을 강조할 때 씁니다. 같은 뜻으로 'hasta'(Hasta un niño...)도 쓸 수 있습니다.","x":["Ya: '이미, 벌써'라는 뜻이라 의미가 맞지 않습니다 ✗","Todavía: '아직'이라는 뜻이라 문맥과 맞지 않습니다 ✗","Aún: 악센트가 있는 aún은 '아직'이라는 뜻입니다(악센트 없는 aun이면 '~조차') ✗","Incluso: '~조차'라는 강조 → 정답 ✓"]},{"id":"G372","q":"Tened cuidado con lo que decís, no sabéis ____ chivata que es Esther.","o":["lo","de lo","una","la"],"a":0,"k":"lo + 형용사 + que","t":"말조심해, 에스테르가 얼마나 고자질쟁이인지 너희는 몰라.","e":"'lo + 형용사 + que + 동사'는 '얼마나 ~한지'라는 정도 강조 구문입니다. 이때 lo는 중성이라 형용사가 여성형(chivata)이어도 lo를 그대로 씁니다. 'chivato/a'는 스페인 구어로 '고자질쟁이, 밀고자'라는 뜻입니다.","x":["lo: 'lo chivata que es'로 정도 강조 → 정답 ✓","de lo: 'de lo' 다음에는 이 구조가 이어지지 않습니다 ✗","una: 'no sabéis una chivata'는 의미가 통하지 않습니다 ✗","la: 이 강조 구문에서는 성과 상관없이 중성 lo를 씁니다 ✗"]},{"id":"G373","q":"Silencio, por favor, la película empezará ____ breve.","o":["a","por","de","en"],"a":3,"k":"en breve","t":"조용히 해 주세요, 영화가 곧 시작됩니다.","e":"'en breve'는 '곧, 머지않아'(pronto)라는 뜻의 다소 격식 있는 표현입니다. 안내 방송이나 공지에서 자주 들립니다. 예: Le atenderemos en breve. (곧 응대해 드리겠습니다.)","x":["a: 'a breve'는 쓰지 않는 표현입니다 ✗","por: 'por breve'는 이 의미의 표현이 아닙니다 ✗","de: 'de breve'는 쓰지 않습니다 ✗","en: 'en breve'로 '곧' → 정답 ✓"]},{"id":"G374","q":"Fuimos allí ____ saber qué nos íbamos a encontrar.","o":["sin","sobre","ante","entre"],"a":0,"k":"sin + 동사원형","t":"우리는 무엇을 마주하게 될지 모른 채 그곳에 갔다.","e":"'sin + 동사원형'은 '~하지 않고, ~하지 않은 채'라는 뜻입니다. 'sin saber qué...'는 '무엇을 ~할지 모른 채'라는 아주 자주 쓰는 표현입니다. 'encontrarse'는 '(예상치 못한 것을) 마주치다'입니다.","x":["sin: '~하지 않은 채' → 정답 ✓","sobre: '~에 대해'라는 뜻이라 'sobre saber'는 비문입니다 ✗","ante: '~앞에서'라는 뜻이라 동사원형과 어울리지 않습니다 ✗","entre: '~사이에'라는 뜻이라 의미가 맞지 않습니다 ✗"]},{"id":"G375","q":"Lo ____ yo, pero no tengo tiempo.","o":["traduzca","traduje","tradujera","traduciría"],"a":3,"k":"가능법(조건)","t":"내가 번역해 주고 싶지만 시간이 없어.","e":"현실에서 일어나기 어려운 일을 '~할 텐데'라고 말할 때는 가능법(조건형)을 씁니다. 'pero no tengo tiempo'에서 실제로는 못 한다는 것이 드러나므로 'traduciría'가 맞습니다. traducir는 불규칙 동사로 단순과거가 'traduje'입니다.","x":["traduzca: 접속법 현재라 독립된 주절에서 쓸 수 없습니다 ✗","traduje: 단순과거로 '번역했다'는 사실이 되어 '시간이 없다'와 모순됩니다 ✗","tradujera: 접속법 과거로 이렇게 단독 주절에는 쓰지 않습니다 ✗","traduciría: '번역해 줄 텐데'라는 가능법 → 정답 ✓"]},{"id":"G376","q":"Marta es una persona ____ confío plenamente.","o":["en la que","a la cual","de quien","a quien"],"a":0,"k":"confiar en+관계사","t":"마르타는 내가 전적으로 믿는 사람이다.","e":"'confiar en alguien'(~을 믿다)처럼 동사가 요구하는 전치사는 관계대명사 앞으로 옮겨야 합니다. 그래서 'en la que'(또는 en quien, en la cual)가 됩니다. 영어처럼 전치사를 문장 끝에 둘 수 없다는 점이 중요합니다.","x":["en la que: confiar en의 전치사를 앞에 둔 관계사 → 정답 ✓","a la cual: confiar는 a가 아니라 en을 씁니다 ✗","de quien: 'confiar de'는 쓰지 않습니다 ✗","a quien: 전치사 a는 confiar와 맞지 않습니다 ✗"]},{"id":"G377","q":"____ me ejercito, mejor me siento.","o":["Tanto que","Por más que","Tanto","Cuanto más"],"a":3,"k":"cuanto más(비례)","t":"운동을 하면 할수록 기분이 더 좋아진다.","e":"'cuanto más ~, más/mejor ~'는 '~하면 할수록 더 ~하다'라는 비례 구문입니다. 뒤 절의 'mejor'(더 좋게)와 짝을 이룹니다. 예: Cuanto más leo, más aprendo. (많이 읽을수록 더 배운다.)","x":["Tanto que: '너무 ~해서'라는 결과 표현이라 비례가 아닙니다 ✗","Por más que: '아무리 ~해도'라는 양보라 의미가 반대가 됩니다 ✗","Tanto: 단독으로는 비례 구문을 만들지 못합니다 ✗","Cuanto más: '~할수록'이라는 비례 → 정답 ✓"]},{"id":"G378","q":"No os imagináis ____ mal que lo pasamos en el barco.","o":["de lo","cuánto","lo","tan"],"a":2,"k":"lo + 부사 + que","t":"우리가 배에서 얼마나 고생했는지 너희는 상상도 못 할 거야.","e":"'lo + 형용사/부사 + que'는 '얼마나 ~한지'라는 강조 구문입니다. 여기서 'mal'은 부사로, 'lo mal que lo pasamos'는 '우리가 얼마나 힘든 시간을 보냈는지'입니다. 'pasarlo mal'은 '고생하다, 힘든 시간을 보내다'입니다.","x":["de lo: 'imaginar de lo'처럼 de를 넣지 않습니다 ✗","cuánto: '얼마나 많이'로 부사 mal 앞에는 쓰지 않습니다(qué mal은 가능) ✗","lo: 'lo mal que'로 정도 강조 → 정답 ✓","tan: 'tan mal'은 비교나 결과(tan ~ que)에 쓰여 이 구조가 아닙니다 ✗"]},{"id":"G379","q":"¿Es cierto que te cortas el pelo ____?","o":["tú mismo","tu mismo","a sí mismo","ti mismo"],"a":0,"k":"tú mismo","t":"네가 직접 머리를 자른다는 게 사실이야?","e":"'mismo/a'를 주어 대명사와 함께 쓰면 '~ 자신이, 직접'이라는 강조가 됩니다. 주어가 tú이므로 악센트가 있는 'tú mismo'가 맞습니다. 악센트 없는 'tu'는 소유사(너의)이니 구별하세요.","x":["tú mismo: 주어를 강조하는 '너 자신이' → 정답 ✓","tu mismo: 악센트가 없으면 소유사 '너의'가 되어 틀립니다 ✗","a sí mismo: 3인칭(그 자신에게)이라 te cortas와 맞지 않습니다 ✗","ti mismo: 'ti'는 전치사 뒤에서만 씁니다(a ti mismo) ✗"]},{"id":"G380","q":"Me saca de quicio que ____ por todo.","o":["se queja","se queje","quejarse","queje"],"a":1,"k":"감정동사+접속법","t":"그가 모든 일에 불평하는 게 나를 미치게 해.","e":"'sacar de quicio'(미치게 만들다, 짜증 나게 하다)는 감정을 나타내므로 que절에 접속법을 씁니다. 'quejarse'(불평하다)는 재귀동사라 se가 필요하므로 'se queje'가 맞습니다.","x":["se queja: 직설법이라 감정 표현 뒤 que절에 맞지 않습니다 ✗","se queje: 재귀형 접속법 현재 → 정답 ✓","quejarse: que 뒤에는 활용된 동사가 와야 합니다 ✗","queje: 재귀대명사 se가 빠졌습니다 ✗"]},{"id":"G381","q":"¡____ bien bailas!","o":["Qué","Cuál","Cómo","Cuánto"],"a":0,"k":"감탄문 qué+부사","t":"너 춤 정말 잘 춘다!","e":"'¡Qué + 부사/형용사 + 동사!'는 '정말 ~하구나!'라는 감탄문입니다. 'bien'은 부사이므로 'Qué bien bailas'가 됩니다. 동사만 강조할 때는 '¡Cómo bailas!'라고 할 수 있지만 bien과 함께 쓰지는 않습니다.","x":["Qué: 부사 bien을 강조하는 감탄 → 정답 ✓","Cuál: '어느 것'이라는 뜻이라 감탄문에 쓰지 않습니다 ✗","Cómo: 동사를 직접 강조할 때 쓰며 'Cómo bien'은 비문입니다 ✗","Cuánto: '얼마나 많이'라는 뜻으로 bien 앞에 쓰지 않습니다 ✗"]},{"id":"G382","q":"¿____ no os importa vuestro futuro profesional?","o":["Como que","Tal que","Por que","Es que"],"a":3,"k":"¿Es que...?","t":"그러니까 너희는 너희의 직업적 미래가 상관없다는 거야?","e":"'¿Es que + 문장?'은 '그러니까 ~라는 거야?, 설마 ~라는 거야?'라는 뜻으로 놀람·비난·의아함을 담은 의문문입니다. 구어에서 아주 자주 씁니다. 평서문에서는 'Es que...'가 '실은 ~이라서'라는 변명이 됩니다.","x":["Como que: '마치 ~인 것처럼'이라는 구어 표현으로 이 의문문에 맞지 않습니다 ✗","Tal que: 존재하지 않는 결합입니다 ✗","Por que: 띄어 쓴 por que는 '~하는 이유'를 뜻하는 드문 형태라 맞지 않습니다(왜는 por qué) ✗","Es que: '그러니까 ~라는 거야?'라는 의아함 → 정답 ✓"]},{"id":"G383","q":"¿Qué ____ aquí antes de que pusieran un banco?","o":["había habido","hubo","hay","había"],"a":3,"k":"haber 불완료과거","t":"은행이 들어서기 전에 여기에는 뭐가 있었나요?","e":"과거에 계속 존재하던 상태를 묘사할 때는 haber의 불완료과거 'había'를 씁니다. 은행이 생기기 전 오랫동안 그 자리에 있던 것을 묻기 때문입니다. 'poner un banco'는 '은행을 차리다/들이다'라는 뜻입니다.","x":["había habido: 과거완료로 특정 과거 이전의 사건을 강조해 지나치게 복잡합니다 ✗","hubo: 단순과거는 일회적 사건(Hubo un accidente)에 써서 지속적 존재 묘사에 맞지 않습니다 ✗","hay: 현재형이라 과거 질문과 맞지 않습니다 ✗","había: 과거의 지속적 존재를 나타내는 불완료과거 → 정답 ✓"]},{"id":"G384","q":"Guillermo siempre ha sido ____ lo más cariñoso.","o":["por","de","en","a"],"a":1,"k":"de lo más + 형용사","t":"기예르모는 항상 정말 다정한 사람이었다.","e":"'de lo más + 형용사'는 '매우 ~한, 더없이 ~한'이라는 강조 표현입니다. 형용사는 주어의 성·수에 맞춰 씁니다. 예: Es una chica de lo más simpática. (정말 상냥한 아이야.)","x":["por: 'por lo más'는 이런 강조 표현이 아닙니다 ✗","de: 'de lo más'로 '더없이 ~한' → 정답 ✓","en: 'en lo más'는 '가장 ~한 곳에서'라는 다른 뜻입니다 ✗","a: 'a lo más'는 '기껏해야'라는 뜻이라 의미가 다릅니다 ✗"]},{"id":"G385","q":"Se divisaba una cordillera ____ lejos.","o":["a lo","por lo","en lo","de lo"],"a":0,"k":"a lo lejos","t":"멀리 산맥이 보였다.","e":"'a lo lejos'는 '멀리, 저 멀리에'라는 뜻의 관용 표현입니다. 'divisar'는 '멀리서 어렴풋이 보다'라는 동사로 이 표현과 자주 어울립니다. 'se divisaba'는 무인칭/수동 구문으로 '보였다'라는 뜻입니다.","x":["a lo: 'a lo lejos'로 '멀리에' → 정답 ✓","por lo: 'por lo lejos'는 쓰지 않는 표현입니다 ✗","en lo: 'en lo lejos'는 비표준입니다 ✗","de lo: 'de lo lejos'는 쓰지 않습니다(de lejos는 가능) ✗"]},{"id":"G386","q":"Si no te apetece beberte el zumo, no ____.","o":["te lo bebas","lo bebas","bebas","te bebas"],"a":0,"k":"부정명령+대명사","t":"주스를 마시고 싶지 않으면 마시지 마.","e":"부정 명령은 'no + 접속법'이고, 대명사는 동사 앞에 놓습니다. 'beberse algo'(~을 다 마셔 버리다)에서 te(재귀)와 lo(el zumo)가 함께 쓰이며 순서는 'te lo'입니다. 앞 문장 'beberte el zumo'와 구조를 맞추면 'no te lo bebas'가 됩니다.","x":["te lo bebas: 재귀대명사 + 직접목적격 + 접속법 → 정답 ✓","lo bebas: 앞의 beberte와 달리 재귀 te가 빠졌습니다 ✗","bebas: 목적어 대명사 lo와 te가 모두 빠졌습니다 ✗","te bebas: 직접목적격 lo(주스)가 빠졌습니다 ✗"]},{"id":"G387","q":"En España, por lo general, ____ muy tarde.","o":["cenando","la cena","al cenar","se cena"],"a":3,"k":"무인칭 se","t":"스페인에서는 일반적으로 저녁을 아주 늦게 먹는다.","e":"'se + 3인칭 단수 동사'는 특정한 주어 없이 '사람들은 일반적으로 ~한다'라는 무인칭 구문입니다. 'se cena tarde'는 '(사람들이) 저녁을 늦게 먹는다'입니다. 스페인에서는 밤 9~10시에 저녁을 먹는 경우가 많습니다.","x":["cenando: 현재분사만으로는 문장의 동사가 될 수 없습니다 ✗","la cena: 명사라서 동사 없는 문장이 됩니다 ✗","al cenar: '저녁을 먹을 때'라는 뜻이라 주절 동사가 없습니다 ✗","se cena: 무인칭 se 구문 → 정답 ✓"]},{"id":"G388","q":"____ aquí donde nos conocimos.","o":["Ha sido","Estaba","Fue","Estuvo"],"a":2,"k":"강조 구문 ser","t":"우리가 만난 곳은 바로 여기였다.","e":"'ser + 강조할 말 + 관계사(donde, quien, cuando...)'는 '~한 것은 바로 ~이다'라는 강조 구문입니다. 과거의 일회적 사건(nos conocimos)이므로 ser도 단순과거 'fue'로 시제를 맞춥니다.","x":["Ha sido: 현재완료라 단순과거 conocimos와 시제가 맞지 않습니다 ✗","Estaba: 강조 구문에는 estar가 아니라 ser를 씁니다 ✗","Fue: 단순과거 ser로 강조 → 정답 ✓","Estuvo: estar는 이 강조 구문에 쓰지 않습니다 ✗"]},{"id":"G389","q":"Cuando volvimos a casa, todos ____ durmiendo.","o":["estarían","están","han estado","estaban"],"a":3,"k":"estar+현재분사 과거","t":"우리가 집에 돌아왔을 때 모두 자고 있었다.","e":"과거 어느 순간(우리가 돌아왔을 때)에 진행 중이던 동작은 'estar의 불완료과거 + 현재분사'로 나타냅니다. 'estaban durmiendo'는 '자고 있었다'입니다. 돌아온 것은 완료된 사건(volvimos), 자고 있던 것은 배경입니다.","x":["estarían: 가능법이라 '자고 있었을 것이다'라는 추측이 되어 사실 묘사가 아닙니다 ✗","están: 현재형이라 과거 시간절과 맞지 않습니다 ✗","han estado: 현재완료라 과거의 특정 순간에 진행 중이던 동작을 나타내지 못합니다 ✗","estaban: 과거 진행 중인 배경 동작 → 정답 ✓"]},{"id":"G390","q":"Aquí ____ un grave error.","o":["es cometido","se cometen","está cometiendo se","se está cometiendo"],"a":3,"k":"수동 se+진행형","t":"여기서 심각한 실수가 저질러지고 있다.","e":"'se + 3인칭 동사'는 수동의 의미를 만듭니다(수동 se). 진행형과 결합하면 재귀대명사는 estar 앞에 오거나 현재분사 끝에 붙습니다: 'se está cometiendo' 또는 'está cometiéndose'. 주어 'un grave error'가 단수라 동사도 단수입니다.","x":["es cometido: ser 수동태는 문법적으로 가능하지만 이 문맥에서는 매우 부자연스럽습니다 ✗","se cometen: 복수형이라 단수 주어 un error와 맞지 않습니다 ✗","está cometiendo se: se를 띄어서 뒤에 놓을 수 없습니다(붙이면 cometiéndose) ✗","se está cometiendo: 수동 se + 진행형 → 정답 ✓"]},{"id":"G391","q":"Para mí que ____ Felipe el que iba en la moto con Javi.","o":["sería","era","había sido","fue"],"a":1,"k":"para mí que","t":"내 생각엔 하비랑 오토바이를 타고 가던 사람은 펠리페였던 것 같아.","e":"'para mí que'는 '내 생각엔 ~인 것 같아'라는 구어 표현으로 뒤에 직설법이 옵니다. 과거에 진행 중이던 상황(iba en la moto)을 묘사하는 문맥이므로 ser도 불완료과거 'era'로 맞춥니다.","x":["sería: 가능법은 과거 추측(아마 ~였을 것)에 쓸 수 있지만 para mí que와 함께 쓰면 추측이 중복됩니다 ✗","era: 과거 상황 묘사의 불완료과거 → 정답 ✓","había sido: 과거완료라 기준 시점보다 앞선 일이 되어 시제가 맞지 않습니다 ✗","fue: 단순과거도 가능해 보이지만 'iba'와 맞춰 배경 묘사는 era가 자연스럽습니다 ✗"]},{"id":"G392","q":"Pedro siempre ____ hambriento.","o":["está","encuentra","se parece","es"],"a":0,"k":"estar+상태 형용사","t":"페드로는 항상 배가 고프다.","e":"'hambriento'(배고픈)는 상태를 나타내는 형용사라 estar와 함께 씁니다. 'siempre'가 있어도 '늘 배고픈 상태에 있다'는 상태의 반복이므로 estar를 씁니다. 같은 뜻으로 'Pedro siempre tiene hambre'도 자주 씁니다.","x":["está: 상태 형용사와 함께 쓰는 estar → 정답 ✓","encuentra: 'se encuentra'처럼 재귀형이어야 '~한 상태에 있다'가 됩니다 ✗","se parece: '~와 닮다'라는 뜻이라 형용사를 직접 받지 않습니다 ✗","es: ser는 본질적 특성에 쓰며 hambriento와는 잘 어울리지 않습니다 ✗"]},{"id":"G393","q":"¿Te resultó difícil ____ el carné de conducir?","o":["que te saques","sacarte","te sacas","que te sacaras"],"a":1,"k":"resultar+동사원형","t":"운전면허 따는 게 어려웠어?","e":"'resultar difícil + 동사원형'은 '~하는 것이 어렵게 느껴지다'라는 뜻입니다. 동사의 주어가 te(너)와 같으므로 동사원형을 쓰고 대명사를 붙여 'sacarte'가 됩니다. 'sacarse el carné'는 '면허를 따다'라는 스페인 표현(중남미에서는 'sacar la licencia')입니다.","x":["que te saques: 주어가 같으므로 que절 대신 동사원형을 씁니다 ✗","sacarte: 같은 주어 → 동사원형 + 재귀대명사 → 정답 ✓","te sacas: 직설법 활용형은 이 자리에 올 수 없습니다 ✗","que te sacaras: 주어가 같을 때는 que절을 쓰지 않습니다 ✗"]},{"id":"G394","q":"¡Qué bien ____ en esta cama!","o":["se duerma","duerma","duerman","se duerme"],"a":3,"k":"무인칭 se","t":"이 침대에서는 정말 잘 자진다!","e":"'se + 3인칭 단수'의 무인칭 구문으로 '(누구든) 이 침대에서는 잘 잔다'라는 일반적 경험을 말합니다. 감탄문 '¡Qué bien...!'은 사실을 말하므로 직설법 'se duerme'를 씁니다.","x":["se duerma: 접속법이라 감탄 평서문에 쓰지 않습니다 ✗","duerma: 접속법이고 주어도 불분명합니다 ✗","duerman: 접속법 복수라 맞지 않습니다 ✗","se duerme: 무인칭 se + 직설법 → 정답 ✓"]},{"id":"G395","q":"Estamos hartos de vivir ____ capital, queremos irnos al campo.","o":["en la","a la","en el","al"],"a":0,"k":"en la capital","t":"우리는 수도에서 사는 게 지긋지긋해, 시골로 가고 싶어.","e":"'vivir en + 장소'처럼 사는 곳을 말할 때는 전치사 en을 씁니다. 'capital'(수도)은 여성 명사이므로 'en la capital'입니다. 참고로 'el capital'(남성)은 '자본금'이라는 다른 뜻입니다. 'estar harto de'는 '~에 질리다'입니다.","x":["en la: 장소의 en + 여성 명사 capital → 정답 ✓","a la: a는 이동 방향(~로)이라 vivir와 맞지 않습니다 ✗","en el: 'el capital'은 '자본'이라는 뜻이 되어 의미가 바뀝니다 ✗","al: 방향을 나타내고 남성 관사라 이중으로 틀립니다 ✗"]},{"id":"G396","q":"Julián es ____ corazón, todos lo saben.","o":["mucho","tanto","todo","sumo"],"a":2,"k":"todo corazón","t":"훌리안은 정말 마음씨가 따뜻한 사람이야, 다들 알아.","e":"'ser todo corazón'은 '정이 넘치다, 마음이 아주 착하다'라는 관용 표현입니다. 여기서 todo는 '전부, 온통'이라는 강조로, 사람 전체가 마음(정) 그 자체라는 이미지입니다. 예: Mi abuela es todo corazón. (우리 할머니는 정이 넘치셔.)","x":["mucho: 'es mucho corazón'은 이 관용 표현의 형태가 아닙니다 ✗","tanto: '그만큼'이라는 뜻으로 의미가 맞지 않습니다 ✗","todo: 'ser todo corazón'으로 '정이 넘치다' → 정답 ✓","sumo: '최고의'라는 형용사로 'sumo cuidado'처럼 쓰여 이 표현과 다릅니다 ✗"]},{"id":"G397","q":"El banquete será en el jardín, ____ que llueva.","o":["de no ser","al no ser","a no ser","de ser"],"a":2,"k":"a no ser que","t":"비가 오지 않는 한 연회는 정원에서 열릴 것이다.","e":"'a no ser que + 접속법'은 '~하지 않는 한, ~이 아니라면'이라는 예외 조건 표현입니다. 'salvo que', 'a menos que'와 같은 뜻입니다. 이런 조건 표현 뒤에는 항상 접속법(llueva)이 옵니다.","x":["de no ser: 'de no ser por + 명사'(~이 아니었다면) 형태로 쓰며 que와 결합하지 않습니다 ✗","al no ser: '~이 아니어서'라는 이유 표현이라 의미가 맞지 않습니다 ✗","a no ser: 'a no ser que'로 '~하지 않는 한' → 정답 ✓","de ser: 'de ser así'(그렇다면)처럼 쓰며 이 조건이 아닙니다 ✗"]},{"id":"G398","q":"Que el gobierno ____ la medicina es muy necesario en estos momentos.","o":["financiará","financie","financia","financiase"],"a":1,"k":"문두 que절+접속법","t":"정부가 그 약값을 지원하는 것은 지금 매우 필요하다.","e":"'Que + 절'이 문장 주어가 되고 뒤에 'es muy necesario' 같은 가치 판단이 오면 que절에 접속법을 씁니다. 주절이 현재(es)이므로 접속법 현재 'financie'가 맞습니다. 'financiar'는 '자금을 대다, 비용을 지원하다'입니다.","x":["financiará: 직설법 미래라 이 구조에 맞지 않습니다 ✗","financie: 가치 판단 주어절의 접속법 현재 → 정답 ✓","financia: 직설법 현재라 접속법 자리에 맞지 않습니다 ✗","financiase: 접속법 과거라 현재 주절 'es'와 시제가 맞지 않습니다 ✗"]},{"id":"G399","q":"____ no estemos preparados para las cinco, no llegaremos a tiempo.","o":["Si","Por si","Como","Cómo"],"a":2,"k":"como+접속법(경고)","t":"5시까지 준비가 안 되면 우리는 제시간에 도착 못 할 거야.","e":"'como + 접속법'은 '만약 ~하면'이라는 조건으로, 특히 나쁜 결과를 경고할 때 씁니다. 'si'를 쓰려면 직설법(Si no estamos)을 써야 하므로 접속법 'estemos'와 맞는 것은 como입니다.","x":["Si: si 뒤에는 접속법 현재(estemos)를 쓰지 않습니다 ✗","Por si: '~할 경우를 대비해'라는 뜻으로 직설법이 오며 의미도 다릅니다 ✗","Como: 접속법과 함께 경고성 조건 → 정답 ✓","Cómo: 악센트가 있으면 '어떻게'라는 의문사가 됩니다 ✗"]},{"id":"G400","q":"Ni los médicos saben ____ le pasa.","o":["qué","que","lo qué","el qué"],"a":0,"k":"간접의문문 qué","t":"의사들조차 그에게 무슨 일이 있는지 모른다.","e":"'saber' 뒤에 '무엇이 ~인지'라는 간접의문문이 올 때는 악센트가 있는 'qué'를 씁니다. '¿Qué le pasa?'(그에게 무슨 일이야?)를 간접적으로 말한 것입니다. 'Ni + 명사'는 '~조차도 (않다)'입니다.","x":["qué: 간접의문문의 의문사 → 정답 ✓","que: 악센트 없는 que는 접속사·관계사라 '무엇'이라는 의미가 없습니다 ✗","lo qué: 의문사 qué 앞에 lo를 붙이지 않습니다(lo que는 악센트 없음) ✗","el qué: 구어로 들리지만 표준적인 간접의문문 형태가 아닙니다 ✗"]},{"id":"G401","q":"No sé ____ hacer esto.","o":["con qué","con lo que","conque","con que"],"a":0,"k":"con qué(의문사)","t":"이걸 뭘로 해야 할지 모르겠어.","e":"'no sé + 의문사 + 동사원형'은 '무엇을/어떻게 ~해야 할지 모르겠다'라는 구조입니다. 도구를 묻는 것이므로 '전치사 con + 의문사 qué'가 되어 'con qué hacer esto'(무엇으로 이걸 할지)가 됩니다. 의문사이므로 qué에 악센트가 있어야 합니다.","x":["con qué: '무엇으로'라는 간접의문 → 정답 ✓","con lo que: 관계사 구문이라 sé 뒤의 의문 의미가 되지 않습니다 ✗","conque: '그러니까'라는 결과 접속사라 의미가 맞지 않습니다 ✗","con que: 악센트 없는 que라 의문사가 아닙니다 ✗"]},{"id":"G402","q":"____ que no ibas a estar en casa, habría venido en otro momento.","o":["Aun sabiendo","Al saber","De saber","Por saber"],"a":2,"k":"de + 동사원형(조건)","t":"네가 집에 없을 줄 알았다면 다른 때 왔을 텐데.","e":"'de + 동사원형'은 '만약 ~했다면'(si + 동사)이라는 조건을 나타내는 격식 있는 표현입니다. 'De saber que...'는 'Si hubiera sabido que...'(~라는 걸 알았더라면)와 같은 뜻이며 결과절은 가능법 완료(habría venido)가 됩니다.","x":["Aun sabiendo: '알면서도'라는 양보라 의미가 반대가 됩니다 ✗","Al saber: '알았을 때'라는 시간 표현이라 가정 의미가 없습니다 ✗","De saber: '알았더라면'이라는 조건 → 정답 ✓","Por saber: '알기 때문에'라는 원인 표현이라 맞지 않습니다 ✗"]},{"id":"G403","q":"Hay demasiada gente aquí. ____.","o":["Vayamos","Vamos","Vámonos","Nos vayamos"],"a":2,"k":"vámonos 명령","t":"여기 사람이 너무 많아. 우리 가자.","e":"nosotros 긍정 명령(~하자)에 재귀대명사 nos를 붙일 때는 동사 끝의 -s가 빠집니다: vamos + nos → vámonos. 'irse'는 '(그 자리를) 떠나다'라는 뜻이라 '여기서 나가자'라는 의미에 딱 맞습니다. 악센트도 꼭 붙여야 합니다.","x":["Vayamos: '가자'라는 뜻이지만 se(떠나다)의 의미가 없고, 긍정 명령으로는 vamos가 더 일반적입니다 ✗","Vamos: '가자'라는 뜻이지만 '여기서 떠나자'라는 irse 의미가 빠집니다 ✗","Vámonos: irse의 nosotros 긍정 명령 → 정답 ✓","Nos vayamos: 긍정 명령에서는 대명사를 동사 뒤에 붙여야 합니다 ✗"]},{"id":"G404","q":"Estoy cansado ____ aguantar tus mentiras.","o":["de","a","con","por"],"a":0,"k":"cansado de","t":"네 거짓말을 참는 데 지쳤어.","e":"'estar cansado de + 명사/동사원형'은 '~에 지치다, ~이 지긋지긋하다'라는 뜻으로 전치사 de를 씁니다. 'harto de'도 같은 구조입니다. 'aguantar'는 '참다, 견디다'입니다.","x":["de: 'cansado de'로 '~에 지친' → 정답 ✓","a: 'cansado a'는 쓰지 않습니다 ✗","con: 'cansado con'은 이 의미로 쓰지 않습니다 ✗","por: 'cansado por'는 원인을 나타낼 수 있지만 '~하는 게 지긋지긋하다'라는 뜻으로는 de를 씁니다 ✗"]},{"id":"G405","q":"Dales un cuento a los niños para que ____.","o":["entreteniéndose","se entretengan","se entretienen","se entretendrán"],"a":1,"k":"para que+접속법","t":"아이들이 즐겁게 놀 수 있도록 동화책을 줘.","e":"'para que'(~하도록)는 목적을 나타내므로 항상 접속법을 씁니다. 'entretenerse'(시간을 보내다, 즐기다)는 tener처럼 불규칙 활용하여 접속법 현재가 'se entretengan'입니다.","x":["entreteniéndose: 현재분사는 que 뒤에 올 수 없습니다 ✗","se entretengan: 목적절의 접속법 현재 → 정답 ✓","se entretienen: 직설법이라 para que 뒤에 쓰지 않습니다 ✗","se entretendrán: 직설법 미래라 para que 뒤에 쓰지 않습니다 ✗"]},{"id":"G406","q":"Maruja alardea ____ que sus hijos son los más guapos.","o":["de","ø","en","a"],"a":0,"k":"alardear de","t":"마루하는 자기 자식들이 제일 잘생겼다고 자랑한다.","e":"'alardear de algo'는 '~을 자랑하다, 뽐내다'라는 뜻으로 전치사 de가 필요합니다. 뒤에 절이 와도 'alardear de que...'처럼 de를 유지해야 합니다. 비슷한 동사 'presumir de'도 같은 구조입니다.","x":["de: 'alardear de que'로 '~을 자랑하다' → 정답 ✓","ø: de를 빼면 queísmo(필요한 de를 빼는 오류)가 됩니다 ✗","en: 'alardear en'은 쓰지 않습니다 ✗","a: 'alardear a'는 쓰지 않습니다 ✗"]},{"id":"G407","q":"Este artículo todavía no está listo ____ publicarse.","o":["por","para","de","a"],"a":1,"k":"listo para","t":"이 기사는 아직 게재될 준비가 되지 않았다.","e":"'estar listo para + 명사/동사원형'은 '~할 준비가 되다'라는 뜻입니다. 'ser listo'(똑똑하다)와 'estar listo'(준비되다)의 뜻 차이도 알아 두세요.","x":["por: 'listo por'는 쓰지 않습니다 ✗","para: 'listo para'로 '~할 준비가 된' → 정답 ✓","de: 'listo de'는 이 의미로 쓰지 않습니다 ✗","a: 'listo a'는 비표준입니다 ✗"]},{"id":"G408","q":"Ha llamado ____ tal Andrés, ¿lo conocéis?","o":["uno","el","ø","un"],"a":3,"k":"un tal + 이름","t":"안드레스라는 사람이 전화했는데, 너희 그 사람 알아?","e":"'un tal + 이름'은 '~라는 (모르는) 사람'이라는 뜻으로, 화자가 그 사람을 잘 모를 때 씁니다. 약간 거리를 두는 느낌도 있습니다. 여성이면 'una tal Marta'가 됩니다.","x":["uno: 명사 앞에서는 un으로 줄어들어야 합니다 ✗","el: 'el tal Andrés'는 이미 언급된 사람을 낮춰 부를 때 쓰여 처음 소개하는 문맥에 맞지 않습니다 ✗","ø: 'tal Andrés'만으로는 성립하지 않습니다 ✗","un: 'un tal Andrés'로 '안드레스라는 사람' → 정답 ✓"]},{"id":"G409","q":"Debes sentirte orgullosa de todos y ____ de tus triunfos.","o":["cada uno","uno por uno","cada","uno a uno"],"a":0,"k":"todos y cada","t":"너는 너의 성공 하나하나 모두를 자랑스러워해야 해.","e":"'todos y cada uno de + 복수 명사'는 '~ 하나하나 모두'라는 강조 표현입니다. 모든 것을 빠짐없이 강조할 때 씁니다. 여성 명사면 'todas y cada una de'가 됩니다.","x":["cada uno: 'todos y cada uno de'로 '하나하나 모두' → 정답 ✓","uno por uno: '하나씩 차례로'라는 부사적 표현이라 이 구조에 맞지 않습니다 ✗","cada: 'cada' 뒤에는 바로 명사가 와야 하며 'cada de'는 비문입니다 ✗","uno a uno: '하나씩'이라는 뜻으로 todos y와 결합하지 않습니다 ✗"]},{"id":"G410","q":"No fuimos al final porque ____ llover a cántaros.","o":["vino a","dejó de","se puso a","acabó por"],"a":2,"k":"ponerse a","t":"비가 억수같이 쏟아지기 시작해서 우리는 결국 가지 않았다.","e":"'ponerse a + 동사원형'은 '(갑자기) ~하기 시작하다'라는 뜻입니다. 'llover a cántaros'는 '비가 억수같이 쏟아지다'(직역: 항아리로 붓듯이)라는 관용 표현입니다.","x":["vino a: 'venir a'는 '결국 ~하게 되다'라는 뜻이라 문맥과 맞지 않습니다 ✗","dejó de: '~을 그만두다'라는 뜻이라 비가 그쳤다는 의미가 되어 논리가 맞지 않습니다 ✗","se puso a: '~하기 시작하다' → 정답 ✓","acabó por: '결국 ~하게 되다'라는 뜻이라 여기선 어색합니다 ✗"]},{"id":"G411","q":"No me conformo ____ un notable, quiero un sobresaliente.","o":["de","para","con","en"],"a":2,"k":"conformarse con","t":"나는 우수(notable)로 만족하지 않아, 최우수를 받고 싶어.","e":"'conformarse con algo'는 '~로 만족하다, ~에 그치다'라는 뜻으로 전치사 con을 씁니다. 스페인 성적에서 'notable'은 7~8점, 'sobresaliente'는 9~10점입니다.","x":["de: 'conformarse de'는 쓰지 않습니다 ✗","para: 'conformarse para'는 쓰지 않습니다 ✗","con: 'conformarse con'으로 '~로 만족하다' → 정답 ✓","en: 'conformarse en'은 쓰지 않습니다 ✗"]},{"id":"G412","q":"Cuando volví a casa, mi marido ya se ____ a trabajar.","o":["ha ido","fue","iría","había ido"],"a":3,"k":"과거완료","t":"내가 집에 돌아왔을 때 남편은 이미 일하러 나가고 없었다.","e":"과거의 어느 시점(내가 돌아왔을 때)보다 더 이전에 끝난 일은 과거완료(había + 과거분사)로 나타냅니다. 'ya'(이미)가 그 순서를 분명히 해 줍니다. 'irse a trabajar'는 '일하러 떠나다'입니다.","x":["ha ido: 현재완료라 과거 기준 시점보다 앞선 일을 나타내지 못합니다 ✗","fue: 단순과거라 '이미 나가고 없었다'라는 선행 의미가 약합니다 ✗","iría: 가능법이라 사실을 나타내지 않습니다 ✗","había ido: 과거보다 앞선 과거 → 정답 ✓"]},{"id":"G413","q":"Esperamos que alguien nos ____ una explicación.","o":["dé","da","dará","de"],"a":0,"k":"dar 접속법 dé","t":"우리는 누군가 우리에게 설명해 주기를 바란다.","e":"'esperar que'(~하기를 바라다) 뒤에는 접속법을 씁니다. 'dar'의 접속법 현재 3인칭 단수는 'dé'로, 전치사 'de'(~의)와 구별하기 위해 악센트를 붙입니다.","x":["dé: dar의 접속법 현재(악센트 필수) → 정답 ✓","da: 직설법이라 바람 표현 뒤에 맞지 않습니다 ✗","dará: 직설법 미래라 esperar que 뒤에 쓰지 않습니다 ✗","de: 악센트가 없으면 전치사 '~의'가 되어 틀립니다 ✗"]},{"id":"G414","q":"Eva y Lucía no ____ ni en lo blanco de los ojos.","o":["se parecen","parecen","se parezcan","parezcan"],"a":0,"k":"관용 표현 parecerse","t":"에바와 루시아는 하나도 닮지 않았다.","e":"'parecerse'는 '서로 닮다'라는 재귀동사입니다. 'no parecerse ni en lo blanco de los ojos'는 '눈 흰자위조차 닮지 않았다', 즉 '전혀 닮지 않았다'라는 관용 표현입니다. 사실을 말하므로 직설법을 씁니다.","x":["se parecen: '서로 닮다'의 직설법 현재 → 정답 ✓","parecen: se가 없으면 '~처럼 보인다'라는 뜻이 되어 맞지 않습니다 ✗","se parezcan: 접속법이라 독립된 평서문에 쓰지 않습니다 ✗","parezcan: se도 없고 접속법이라 이중으로 틀립니다 ✗"]},{"id":"G415","q":"No ____ tan negativa. Te va a salir muy bien.","o":["estás","seas","esté","eres"],"a":1,"k":"부정 명령 ser","t":"그렇게 부정적으로 생각하지 마. 아주 잘될 거야.","e":"tú에 대한 부정 명령은 'no + 접속법 현재'입니다. 'negativo'(부정적인)는 성격·태도를 나타내므로 ser를 쓰고, ser의 접속법 현재 tú형은 'seas'입니다. 'salir bien'은 '잘되다, 좋은 결과가 나오다'입니다.","x":["estás: 직설법이라 명령이 아닌 사실 진술이 됩니다 ✗","seas: no + ser의 접속법 → 정답 ✓","esté: usted 형태이고 estar라 맞지 않습니다 ✗","eres: 직설법이라 부정 명령이 되지 않습니다 ✗"]},{"id":"G416","q":"¿Cuánto tiempo ____ que no te pasabas por el barrio?","o":["ha hecho","hizo","hacía","estaba haciendo"],"a":2,"k":"hacía ~ que","t":"너 동네에 안 들른 지 얼마나 됐었니?","e":"'hace + 기간 + que'는 '~한 지 얼마나 되었다'라는 표현입니다. 이야기의 기준이 과거(pasabas, 불완료과거)일 때는 hacer도 불완료과거 'hacía'로 맞춥니다. 'pasarse por'는 '~에 잠깐 들르다'라는 구어 표현입니다.","x":["ha hecho: 이 기간 표현에서 hacer는 완료형으로 쓰지 않습니다 ✗","hizo: 단순과거는 이 구조에서 쓰지 않습니다 ✗","hacía: 과거 기준의 기간 표현 → 정답 ✓","estaba haciendo: 진행형은 이 구조에 쓰지 않습니다 ✗"]},{"id":"G417","q":"No voy a examinarme el lunes, ____ el martes.","o":["si no","pero","sino que","sino"],"a":3,"k":"sino(대조)","t":"나는 월요일이 아니라 화요일에 시험을 볼 거야.","e":"앞 문장이 부정이고 뒤에 '대신 ~이다'라는 정정이 올 때는 'sino'를 씁니다. 뒤에 동사가 있는 절이 오면 'sino que'를 쓰지만, 여기서는 'el martes'라는 명사구만 오므로 sino가 맞습니다.","x":["si no: 띄어 쓰면 '만약 ~하지 않으면'이라는 조건이 됩니다 ✗","pero: '하지만'은 앞 내용을 대체하는 정정 의미가 아닙니다 ✗","sino que: 뒤에 동사가 있는 절이 올 때 씁니다 ✗","sino: 부정 뒤 명사구로 정정하는 '~이 아니라' → 정답 ✓"]},{"id":"G418","q":"Melisa ____ una mala racha.","o":["lleva pasando","viene a pasar","está pasando","deja de pasar"],"a":2,"k":"mala racha","t":"멜리사는 요즘 힘든 시기를 보내고 있다.","e":"'pasar (por) una mala racha'는 '안 좋은 시기를 겪다, 슬럼프를 겪다'라는 관용 표현입니다. 지금 진행 중인 상황이므로 현재진행형 'está pasando'를 씁니다. 'racha'는 '(연속된) 한 시기'라는 뜻으로 'buena racha'(좋은 흐름)도 씁니다.","x":["lleva pasando: 'llevar + 기간 + 현재분사' 구조라 기간이 빠지면 어색합니다 ✗","viene a pasar: '결국 ~이 되다'라는 뜻이라 맞지 않습니다 ✗","está pasando: 현재 진행 중인 상황 → 정답 ✓","deja de pasar: '그만 겪다'라는 뜻이라 의미가 맞지 않습니다 ✗"]},{"id":"G419","q":"Tiene fobia al agua porque de pequeño ____ a punto de ahogarse.","o":["ha estado","estuvo","estaba","estaría"],"a":1,"k":"estuvo a punto","t":"그는 어렸을 때 물에 빠져 죽을 뻔해서 물 공포증이 있다.","e":"'estar a punto de + 동사원형'을 과거에 쓰면 '~할 뻔했다'라는 뜻이 됩니다. 과거의 한 번의 사건이므로 단순과거 'estuvo'가 자연스럽습니다. 'de pequeño'는 '어렸을 때'라는 표현입니다.","x":["ha estado: 현재완료라 'de pequeño'(어렸을 때)와 어울리지 않습니다 ✗","estuvo: 과거 한 번의 사건 '~할 뻔했다' → 정답 ✓","estaba: 불완료과거는 '~하려던 참이었다'(배경)로 결과가 남은 사건에는 단순과거가 맞습니다 ✗","estaría: 가능법이라 사실을 나타내지 않습니다 ✗"]},{"id":"G420","q":"Al oír el grito, ____ la carne de gallina.","o":["se puso","me puso","se me puso","me puse"],"a":2,"k":"ponérsele a uno","t":"비명 소리를 듣자 나는 소름이 돋았다.","e":"'ponérsele a uno la carne de gallina'는 '~에게 소름이 돋다'라는 관용 표현입니다. 주어는 'la carne de gallina'(닭살)이고 경험하는 사람은 간접목적격 me로 나타냅니다. 'se + me + 동사' 구조로, 비의도적인 일이 나에게 일어났다는 느낌입니다.","x":["se puso: 경험자(나에게)를 나타내는 me가 빠졌습니다 ✗","me puso: 'me puso la carne de gallina'는 '그것이 내게 소름을 돋게 했다'로 주어가 따로 필요해 여기서는 맞지 않습니다 ✗","se me puso: 'se + me' 구조로 '내게 소름이 돋았다' → 정답 ✓","me puse: '나는 ~가 되었다'라는 재귀형이라 carne de gallina와 구조가 맞지 않습니다 ✗"]},{"id":"G421","q":"No ____ descalzo, que hay trozos de cristal en el suelo.","o":["estás caminando","caminarías","camines","caminas"],"a":2,"k":"부정 명령 tú","t":"맨발로 걷지 마, 바닥에 유리 조각이 있어.","e":"tú에 대한 부정 명령은 'no + 접속법 현재'이므로 'no camines'가 됩니다. 뒤의 'que'는 '왜냐하면'이라는 이유를 구어적으로 덧붙이는 용법입니다. 'descalzo'는 '맨발의'입니다.","x":["estás caminando: 직설법 진행형이라 명령이 되지 않습니다 ✗","caminarías: 가능법이라 명령이 아닙니다 ✗","camines: no + 접속법 현재의 부정 명령 → 정답 ✓","caminas: 직설법이라 '너는 걷지 않는다'라는 진술이 됩니다 ✗"]},{"id":"G422","q":"Eva cuenta unas historias tan raras que no ____ cree nadie.","o":["se le","se los","se las","se"],"a":2,"k":"creerse algo","t":"에바는 너무 이상한 이야기를 해서 아무도 그 이야기를 믿지 않는다.","e":"'creerse algo'는 '~을 (곧이곧대로) 믿다'라는 뜻으로 재귀 se가 들어갑니다. 믿는 대상 'unas historias'(여성 복수)를 가리키는 직접목적격 대명사는 'las'이므로 'se las cree'가 됩니다.","x":["se le: le는 간접목적격 단수라 historias(여성 복수)를 가리킬 수 없습니다 ✗","se los: los는 남성 복수라 여성 명사 historias와 맞지 않습니다 ✗","se las: 재귀 se + 여성 복수 las → 정답 ✓","se: 믿는 대상을 가리키는 대명사가 빠졌습니다 ✗"]},{"id":"G423","q":"____ Martín se mudaron a otro barrio hace unos quince años.","o":["ø","Los","Ellos","El"],"a":1,"k":"성씨 + 복수 관사","t":"마르틴 가족은 약 15년 전에 다른 동네로 이사했다.","e":"스페인어에서 성(apellido)으로 가족 전체를 가리킬 때는 'los + 성'을 씁니다. 이때 성 자체는 복수형으로 바꾸지 않습니다: los Martín, los García. 동사(se mudaron)도 복수입니다.","x":["ø: 관사가 없으면 '마르틴(한 사람)'이 되어 복수 동사와 맞지 않습니다 ✗","Los: 'los + 성'으로 가족 전체 → 정답 ✓","Ellos: 'Ellos Martín'은 성립하지 않는 결합입니다 ✗","El: 단수라 복수 동사 se mudaron과 맞지 않습니다 ✗"]},{"id":"G424","q":"Me siento muy mal ____ misma por lo que hice.","o":["conmigo","con mí","con yo","con"],"a":0,"k":"conmigo","t":"내가 한 일 때문에 나 자신에게 너무 기분이 안 좋아.","e":"전치사 con 뒤에 '나'가 올 때는 특별한 형태 'conmigo'를 씁니다(con mí는 비문). 마찬가지로 'contigo'(너와), 재귀 'consigo'(자기 자신과)가 있습니다. 'sentirse mal consigo mismo/a'는 '자기 자신에게 실망하다'라는 뜻입니다.","x":["conmigo: con + mí의 특별 형태 → 정답 ✓","con mí: con 뒤에서는 반드시 conmigo로 씁니다 ✗","con yo: 전치사 뒤에 주격 yo를 쓰지 않습니다 ✗","con: 대명사가 빠져 'con misma'는 성립하지 않습니다 ✗"]},{"id":"G425","q":"____ todas las cosas en ese cuarto, si no os importa.","o":["Dejas","Dejes","Dejad","Dejáis"],"a":2,"k":"vosotros 긍정 명령","t":"괜찮다면 모든 물건을 그 방에 두세요(너희).","e":"vosotros에 대한 긍정 명령은 동사원형의 -r을 -d로 바꿉니다: dejar → dejad. 'si no os importa'(너희가 괜찮다면)에서 대상이 vosotros임을 알 수 있습니다. 중남미에서는 vosotros 대신 ustedes(dejen)를 씁니다.","x":["Dejas: tú 직설법 현재라 명령도 아니고 인칭도 다릅니다 ✗","Dejes: tú 접속법으로 부정 명령(no dejes)에 씁니다 ✗","Dejad: vosotros 긍정 명령 → 정답 ✓","Dejáis: vosotros 직설법 현재라 명령이 아닙니다 ✗"]},{"id":"G426","q":"Se dice que ____ crímenes están relacionados.","o":["ambos","estas","las dos","ese y otro"],"a":0,"k":"ambos","t":"두 범죄가 서로 관련되어 있다고들 한다.","e":"'ambos/ambas'는 '둘 다'라는 뜻으로 명사 앞에 관사 없이 씁니다. 'crímenes'는 남성 복수이므로 'ambos'가 맞습니다. 'Se dice que'는 '~라고들 한다'라는 무인칭 표현입니다.","x":["ambos: 남성 복수 명사 앞 '둘 다' → 정답 ✓","estas: 여성 지시사라 남성 명사 crímenes와 맞지 않습니다 ✗","las dos: 여성형이라 남성 명사와 맞지 않습니다(los dos라면 가능) ✗","ese y otro: '그것과 다른 하나'는 복수 명사 앞에서 성립하지 않습니다 ✗"]},{"id":"G427","q":"No es que no me ____ el tema, es que estoy muy cansado.","o":["está interesando","interesaría","interesa","interese"],"a":3,"k":"no es que+접속법","t":"그 주제에 관심이 없는 게 아니라, 내가 너무 피곤해서 그래.","e":"'no es que + 접속법'은 '~하는 것은 아니다'라는 뜻으로 어떤 이유를 부정할 때 씁니다. 그 뒤에 'es que + 직설법'으로 진짜 이유를 말합니다. 'interesar'는 gustar처럼 '~에게 흥미를 주다'라는 구조라 me가 함께 쓰입니다.","x":["está interesando: 직설법 진행형이라 no es que 뒤에 맞지 않습니다 ✗","interesaría: 가능법이라 이 구조에 쓰지 않습니다 ✗","interesa: 직설법이라 'no es que' 뒤에는 쓰지 않습니다 ✗","interese: no es que + 접속법 현재 → 정답 ✓"]},{"id":"G428","q":"Hoy no ____ bien, estoy algo mareada.","o":["encuentro","lo encuentro","estoy encontrando","me encuentro"],"a":3,"k":"encontrarse(상태)","t":"오늘은 몸이 좋지 않아, 약간 어지러워.","e":"'encontrarse bien/mal'은 '몸·기분이 좋다/나쁘다'라는 뜻으로 재귀대명사가 필요합니다. 'estar bien/mal'보다 조금 더 정중하고 건강 상태를 말할 때 자주 씁니다. 'mareado/a'는 '어지러운, 멀미 나는'입니다.","x":["encuentro: 재귀대명사가 없으면 '~을 찾다'라는 뜻이 됩니다 ✗","lo encuentro: '그것을 찾다/좋게 여기다'라는 뜻이라 맞지 않습니다 ✗","estoy encontrando: 진행형이고 재귀대명사도 없어 틀립니다 ✗","me encuentro: '몸 상태가 ~하다' → 정답 ✓"]},{"id":"G429","q":"Os dije que ____ hoy al cine, ¿lo habéis olvidado?","o":["habríamos ido","hubiéramos ido","iríamos","vayamos"],"a":2,"k":"과거 속 미래 가능법","t":"내가 너희에게 오늘 영화 보러 갈 거라고 말했잖아, 잊었어?","e":"과거 시점(Os dije)에서 그 이후의 일을 전달할 때는 가능법(조건형)을 씁니다. 이를 '과거에서 본 미래'라고 합니다. 직접 화법 'Iremos al cine'(영화 보러 갈 거야)가 간접 화법에서 'iríamos'가 된 것입니다.","x":["habríamos ido: 가능법 완료로 '갔었을 텐데'가 되어 의미가 바뀝니다 ✗","hubiéramos ido: 접속법 과거완료로 decir(알리다) 뒤에 맞지 않습니다 ✗","iríamos: 과거에서 본 미래의 가능법 → 정답 ✓","vayamos: 접속법은 'decir que'가 명령의 뜻일 때만 씁니다 ✗"]},{"id":"G430","q":"Si no queríais venir a la fiesta, teníais que ____ dicho antes.","o":["haber lo","lo haber","haberlo","haber"],"a":2,"k":"haber+대명사 결합","t":"파티에 오기 싫었으면 미리 말했어야지.","e":"'tener que haber + 과거분사'는 '~했어야 했다'라는 과거의 의무(후회·비난)를 나타냅니다. 목적격 대명사는 동사원형 뒤에 붙여 쓰므로 'haberlo dicho'가 됩니다. 'decirlo'의 lo는 '오기 싫다는 것'을 가리킵니다.","x":["haber lo: 대명사는 동사원형에 붙여 써야 합니다 ✗","lo haber: 대명사를 동사원형 앞에 둘 수 없습니다 ✗","haberlo: 동사원형 + 대명사 결합 → 정답 ✓","haber: 'decir'의 목적어 lo가 빠져 불완전합니다 ✗"]},{"id":"G431","q":"Ayer no fui a trabajar porque ____ indispuesta.","o":["estaba","había estado","estaría","he estado"],"a":0,"k":"불완료과거(상태)","t":"어제 나는 몸이 안 좋아서 출근하지 않았다.","e":"과거의 몸 상태나 배경을 설명할 때는 불완료과거를 씁니다. 'estaba indispuesta'는 '몸이 안 좋은 상태였다'로, 출근하지 않은 이유(배경)를 나타냅니다. 'indispuesto/a'는 '몸이 불편한, 컨디션이 나쁜'이라는 격식 있는 표현입니다.","x":["estaba: 과거 상태(이유)를 나타내는 불완료과거 → 정답 ✓","había estado: 과거완료라 어제 이전의 상태가 되어 맞지 않습니다 ✗","estaría: 가능법이라 사실을 나타내지 않습니다 ✗","he estado: 현재완료라 ayer와 어울리지 않습니다 ✗"]},{"id":"G432","q":"¿Por qué ____ la foto?","o":["has roto","esté rota","te has roto","está roto"],"a":0,"k":"현재완료 romper","t":"왜 그 사진을 찢었어?","e":"'romper'는 과거분사가 불규칙 'roto'입니다. 상대가 방금(또는 최근) 한 행동을 물으므로 현재완료 'has roto'가 자연스럽습니다. 'romper una foto'는 '사진을 찢다'라는 뜻입니다.","x":["has roto: romper의 현재완료 → 정답 ✓","esté rota: 접속법이라 단순 의문문에 쓰지 않습니다 ✗","te has roto: 재귀형은 'Te has roto el brazo'(팔이 부러졌다)처럼 신체에 쓰여 맞지 않습니다 ✗","está roto: foto는 여성 명사라 rota여야 하고 질문 의도와도 다릅니다 ✗"]},{"id":"G433","q":"No me ____ para cenar; tengo que quedarme en la oficina una hora más.","o":["esperáis","esperas","esperad","esperéis"],"a":3,"k":"vosotros 부정 명령","t":"저녁 먹으려고 날 기다리지 마, 사무실에 한 시간 더 있어야 해.","e":"부정 명령은 'no + 접속법 현재'이고, 대명사(me)는 동사 앞에 옵니다. vosotros의 접속법 현재는 'esperéis'입니다. 'esperar para cenar'는 '저녁을 같이 먹으려고 기다리다'입니다.","x":["esperáis: 직설법이라 명령이 되지 않습니다 ✗","esperas: tú 직설법이라 명령이 아닙니다 ✗","esperad: 긍정 명령형이라 no와 함께 쓸 수 없습니다 ✗","esperéis: no + vosotros 접속법 → 정답 ✓"]},{"id":"G434","q":"Se preparó para el examen a conciencia, de ahí que le ____ redondo.","o":["saliera","saldría","salió","salga"],"a":0,"k":"de ahí que+접속법","t":"그는 시험 준비를 철저히 했고, 그래서 시험이 완벽하게 잘됐다.","e":"'de ahí que'는 '그래서, 그 때문에'라는 결과 표현이지만 특이하게 접속법을 씁니다. 과거 이야기이므로 접속법 과거 'saliera'입니다. 'salir redondo'는 '완벽하게 잘되다', 'a conciencia'는 '철저하게'라는 뜻입니다.","x":["saliera: de ahí que + 접속법 과거 → 정답 ✓","saldría: 가능법이라 de ahí que 뒤에 쓰지 않습니다 ✗","salió: 직설법이라 de ahí que의 규칙(접속법)에 맞지 않습니다 ✗","salga: 접속법 현재라 과거 문맥과 시제가 맞지 않습니다 ✗"]},{"id":"G435","q":"Me aconsejaron que ____ cadenas al conducir por esa región.","o":["usara","uso","usaré","usaría"],"a":0,"k":"aconsejar que","t":"그 지역에서 운전할 때 체인을 사용하라고 사람들이 내게 조언했다.","e":"'aconsejar que'(~하라고 조언하다)는 영향·요청을 나타내므로 que절에 접속법을 씁니다. 주절이 과거(aconsejaron)이므로 접속법 과거 'usara'가 맞습니다. 'cadenas'는 눈길용 타이어 체인입니다.","x":["usara: 과거 조언 뒤의 접속법 과거 → 정답 ✓","uso: 직설법 현재라 조언 동사 뒤에 쓰지 않습니다 ✗","usaré: 직설법 미래라 접속법 자리에 맞지 않습니다 ✗","usaría: 가능법이라 aconsejar que 뒤에 쓰지 않습니다 ✗"]},{"id":"G436","q":"Nos reuniremos en cuanto ____.","o":["podemos","podremos","podríamos","podamos"],"a":3,"k":"en cuanto+접속법","t":"우리는 가능해지는 대로 바로 모일 것이다.","e":"'en cuanto'(~하자마자)가 미래의 일을 가리킬 때는 접속법을 씁니다. 주절이 미래(nos reuniremos)이므로 접속법 현재 'podamos'가 맞습니다. 'cuando', 'tan pronto como'도 같은 규칙을 따릅니다.","x":["podemos: 직설법 현재라 미래 시간절에 쓰지 않습니다 ✗","podremos: 직설법 미래는 시간 접속사 뒤에 쓸 수 없습니다 ✗","podríamos: 가능법이라 이 구조에 맞지 않습니다 ✗","podamos: 미래 시간절의 접속법 현재 → 정답 ✓"]},{"id":"G437","q":"Ha sido condenado a un año ____ cárcel.","o":["en","de","con","a"],"a":1,"k":"전치사 de(형벌)","t":"그는 징역 1년형을 선고받았다.","e":"'condenar a + 기간 + de cárcel'은 '~의 징역형을 선고하다'라는 표현입니다. 'un año de cárcel'에서 de는 명사와 명사를 연결해 '감옥의 1년', 즉 '징역 1년'을 만듭니다. 'condenar a'의 a는 이미 앞에 있습니다.","x":["en: 'un año en cárcel'은 관사도 없어 비표준입니다 ✗","de: 'un año de cárcel'로 '징역 1년' → 정답 ✓","con: '감옥과 함께'라는 뜻이 되어 맞지 않습니다 ✗","a: a는 이미 'condenado a'에서 쓰였고 'año a cárcel'은 성립하지 않습니다 ✗"]},{"id":"G438","q":"¿En qué iglesia ____ el enlace?","o":["será","estará","tendrá","habrá"],"a":0,"k":"ser(행사 장소)","t":"결혼식은 어느 교회에서 열릴 예정이야?","e":"행사·이벤트(결혼식, 파티, 회의 등)가 '어디서 열리는지'를 말할 때는 estar가 아니라 ser를 씁니다. 예: La fiesta es en mi casa. (파티는 우리 집에서 해.) 'enlace'는 격식 있게 '결혼식, 혼례'를 뜻합니다.","x":["será: 행사가 열리는 장소의 ser → 정답 ✓","estará: estar는 사물·사람의 위치에 쓰며 행사 개최에는 쓰지 않습니다 ✗","tendrá: '가지다'라는 뜻이라 주어 enlace와 맞지 않습니다 ✗","habrá: 'haber'는 존재를 나타내며 정관사 붙은 명사(el enlace)와 함께 쓰지 않습니다 ✗"]},{"id":"G439","q":"____ no pueda ir él contigo, iré yo.","o":["Si","En caso de que","De","Por si"],"a":1,"k":"en caso de que","t":"그가 너와 함께 갈 수 없는 경우에는 내가 갈게.","e":"'en caso de que + 접속법'은 '~하는 경우에는'이라는 조건 표현입니다. 뒤에 접속법 'pueda'가 왔으므로 이 표현만 맞습니다. 'si'를 쓰려면 'Si no puede'처럼 직설법이 필요합니다.","x":["Si: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","En caso de que: 접속법과 함께 쓰는 조건 → 정답 ✓","De: 'de' 뒤에는 동사원형이 오며 활용된 동사는 올 수 없습니다 ✗","Por si: '~할 경우를 대비해'라는 뜻이며 보통 직설법이 옵니다 ✗"]},{"id":"G440","q":"¡____ lío en el que nos has metido!","o":["Cuál","Menos","Menudo","Más"],"a":2,"k":"menudo(감탄)","t":"우리를 무슨 엄청난 곤경에 빠뜨린 거야!","e":"'¡Menudo/a + 명사!'는 '정말 대단한 ~!, 엄청난 ~!'이라는 뜻의 감탄 표현으로 스페인 구어에서 자주 씁니다. 좋은 뜻이나 나쁜 뜻(비꼼) 모두 가능합니다. 'lío'는 '골치 아픈 일, 엉망진창'이라는 뜻입니다.","x":["Cuál: '어느 것'이라는 의문사라 감탄문에 쓰지 않습니다 ✗","Menos: '더 적게'라는 비교어라 의미가 맞지 않습니다 ✗","Menudo: '엄청난 ~!'이라는 감탄 → 정답 ✓","Más: '더'라는 비교어로 이 감탄 구조가 아닙니다 ✗"]},{"id":"G441","q":"El gato no ha cesado ____ maullar en toda la mañana.","o":["en","a","de","por"],"a":2,"k":"cesar de","t":"고양이가 아침 내내 야옹거리기를 멈추지 않았다.","e":"'cesar de + 동사원형'은 '~하기를 멈추다'라는 뜻으로 'dejar de'와 같습니다. 'no cesar de'는 '끊임없이 ~하다'라는 뜻이 됩니다. 'sin cesar'(끊임없이)라는 표현도 함께 알아 두세요.","x":["en: 'cesar en'은 '(직책에서) 물러나다'라는 다른 뜻입니다 ✗","a: 'cesar a'는 쓰지 않습니다 ✗","de: 'cesar de'로 '~하기를 멈추다' → 정답 ✓","por: 'cesar por'는 이 의미가 없습니다 ✗"]},{"id":"G442","q":"En la inauguración habría ____ doscientas personas.","o":["más de","tantas","más que","algo más"],"a":0,"k":"más de + 숫자","t":"개업식에는 아마 200명이 넘는 사람이 있었을 것이다.","e":"숫자 앞에서 '~이상, ~넘게'를 말할 때는 'más de + 숫자'를 씁니다. 'más que'는 일반 비교에 씁니다. 여기서 'habría'는 가능법으로 '아마 ~였을 것이다'라는 과거 추측을 나타냅니다.","x":["más de: 숫자 앞 '~넘게' → 정답 ✓","tantas: '그만큼 많은'이라는 뜻으로 숫자 앞에 바로 쓰지 않습니다 ✗","más que: 숫자 앞에서는 de를 써야 합니다 ✗","algo más: 'algo más de'처럼 de가 있어야 합니다 ✗"]},{"id":"G443","q":"¿Es verdad que ____ toda la mañana limpiando el almacén?","o":["estuvieseis","habéis estado","estabais","hayáis estado"],"a":1,"k":"현재완료(최근 일)","t":"너희가 오전 내내 창고를 청소했다는 게 사실이야?","e":"'Es verdad que'는 사실 확인이라 직설법을 씁니다(부정 'No es verdad que'면 접속법). 오늘 오전이라는 현재와 이어진 기간이므로 현재완료 'habéis estado'가 자연스럽습니다. 'estar + 기간 + 현재분사'는 '~ 동안 ~하고 있었다'입니다.","x":["estuvieseis: 접속법 과거라 긍정 'Es verdad que' 뒤에 쓰지 않습니다 ✗","habéis estado: 현재와 이어진 시간의 현재완료 → 정답 ✓","estabais: 불완료과거는 '오전 내내'라는 완결된 기간과 잘 맞지 않습니다 ✗","hayáis estado: 접속법이라 긍정 사실 확인 뒤에 맞지 않습니다 ✗"]},{"id":"G444","q":"____ las tareas antes de que llegue la jefa.","o":["Se las terminamos","Nos terminamos","Las terminemos","Terminemos"],"a":3,"k":"nosotros 명령","t":"사장님이 오시기 전에 일을 끝냅시다.","e":"nosotros에 대한 권유·명령(~합시다)은 접속법 현재 1인칭 복수를 씁니다: terminar → terminemos. 목적어 'las tareas'가 명사로 그대로 나와 있으므로 대명사를 따로 붙이지 않습니다.","x":["Se las terminamos: 직설법이고 불필요한 대명사가 들어 있습니다 ✗","Nos terminamos: 재귀형이 되어 '우리 자신을 끝내다'라는 이상한 뜻이 됩니다 ✗","Las terminemos: 명사 목적어가 있는데 대명사 las를 중복했고, 긍정 명령에서는 대명사가 동사 뒤에 붙어야 합니다 ✗","Terminemos: nosotros 권유형 → 정답 ✓"]},{"id":"G445","q":"Cuando se enteró de la boda de su ex, se quedó ____ piedra.","o":["en","a","de","para"],"a":2,"k":"de piedra","t":"전 연인의 결혼 소식을 듣고 그는 얼어붙은 듯 깜짝 놀랐다.","e":"'quedarse de piedra'는 '(너무 놀라서) 돌처럼 굳어 버리다, 아연실색하다'라는 관용 표현입니다. 비슷하게 'quedarse helado', 'quedarse de una pieza'도 씁니다. 'ex'는 '전 애인, 전 배우자'입니다.","x":["en: 'quedarse en piedra'는 쓰지 않습니다 ✗","a: 'quedarse a piedra'는 쓰지 않습니다 ✗","de: 'quedarse de piedra'로 '깜짝 놀라 굳다' → 정답 ✓","para: 'quedarse para piedra'는 의미가 없습니다 ✗"]},{"id":"G446","q":"____ interesados en el arte contemporáneo.","o":["Estamos","Somos","Estuviéramos","Seamos"],"a":0,"k":"ser vs estar","t":"우리는 현대 미술에 관심이 있다.","e":"'estar interesado/a en'은 '~에 관심이 있다'라는 상태를 나타내므로 estar를 씁니다. 'ser interesante'(흥미롭다)와 혼동하지 마세요. 단순 사실을 말하는 독립문이므로 직설법 'Estamos'가 맞습니다.","x":["Estamos: 관심이 있는 상태의 estar → 정답 ✓","Somos: ser + interesado는 '이해타산적인(계산적인)'이라는 다른 뜻이 됩니다 ✗","Estuviéramos: 접속법 과거라 독립된 평서문에 쓰지 않습니다 ✗","Seamos: 접속법이며 ser라 이중으로 틀립니다 ✗"]},{"id":"G447","q":"A juzgar por su cara, no creo que le ____ bien la prueba.","o":["ha salido","habrá salido","salió","haya salido"],"a":3,"k":"no creo que","t":"표정으로 보아 시험이 잘된 것 같지 않다.","e":"'creer que'를 부정(no creo que)하면 의심을 나타내므로 que절에 접속법을 씁니다. 이미 끝난 시험의 결과이므로 접속법 현재완료 'haya salido'입니다. 'a juzgar por'는 '~으로 판단하건대'라는 뜻입니다.","x":["ha salido: 직설법이라 'no creo que' 뒤에 쓰지 않습니다 ✗","habrá salido: 직설법 미래완료라 부정 믿음 뒤에 맞지 않습니다 ✗","salió: 직설법 단순과거라 접속법 자리에 맞지 않습니다 ✗","haya salido: 의심 뒤 접속법 현재완료 → 정답 ✓"]},{"id":"G448","q":"Debes disculparte ____ Rodrigo por haberle hablado en ese tono.","o":["hacia","de","a","con"],"a":3,"k":"disculparse con","t":"너는 로드리고에게 그런 말투로 말한 것에 대해 사과해야 해.","e":"'disculparse con alguien por algo'는 '~에게 ~에 대해 사과하다'라는 뜻으로, 사과 대상에는 con, 이유에는 por를 씁니다. 'pedir disculpas a alguien'이라면 a를 씁니다.","x":["hacia: '~쪽으로'라는 방향이라 사과 대상에 쓰지 않습니다 ✗","de: 'disculparse de'는 '~에 대해'(이유)로 쓰일 수 있지만 사람 앞에는 쓰지 않습니다 ✗","a: 'pedir disculpas a'와 혼동한 형태로 disculparse와는 쓰지 않습니다 ✗","con: 'disculparse con + 사람' → 정답 ✓"]},{"id":"G449","q":"Todos queremos ____ España con menos paro.","o":["una","a una","la","al"],"a":0,"k":"고유명사+부정관사","t":"우리 모두 실업률이 더 낮은 스페인을 원한다.","e":"나라 이름에는 보통 관사를 붙이지 않지만, 수식어가 붙어 '어떤 모습의 그 나라'를 말할 때는 부정관사를 씁니다. 'una España con menos paro'는 '실업이 더 적은 (그런) 스페인'입니다. 'paro'는 스페인에서 '실업'이라는 뜻(중남미는 desempleo, paro는 '파업')입니다.","x":["una: 수식어가 붙은 나라 이름의 부정관사 → 정답 ✓","a una: 사물·추상 개념을 원할 때는 전치사 a를 쓰지 않습니다 ✗","la: 'la España'는 특정 시대(la España de los 80)처럼 한정할 때 쓰여 여기선 어색합니다 ✗","al: a + el로 남성 관사이고 전치사 a도 필요 없습니다 ✗"]},{"id":"G450","q":"No les des el resultado todavía, ____ al final de la clase.","o":["dalos","delo","dáselo","les das"],"a":2,"k":"긍정명령+이중대명사","t":"아직 그들에게 결과를 알려 주지 마, 수업 끝날 때 알려 줘.","e":"tú 긍정 명령에서 대명사는 동사 끝에 붙습니다. 간접목적격 les(그들에게)와 직접목적격 lo(결과)가 함께 오면 les가 se로 바뀌어 'se lo'가 됩니다: da + se + lo → dáselo. 강세 위치를 지키기 위해 악센트가 붙습니다.","x":["dalos: 결과는 단수 el resultado라 los가 틀리고 간접목적격도 빠졌습니다 ✗","delo: usted 명령형(dé)에서 악센트도 빠지고 간접목적격도 없습니다 ✗","dáselo: tú 명령 + se(그들에게) + lo(결과) → 정답 ✓","les das: 직설법이라 명령이 되지 않습니다 ✗"]},{"id":"G451","q":"Pasé el fin de semana ayudando a Paco, por eso no pude ____ con vosotros.","o":["me quedar","al quedar","quedando","quedar"],"a":3,"k":"quedar con","t":"주말 내내 파코를 도와주느라 너희와 만날 수가 없었어.","e":"poder(~할 수 있다) 뒤에는 동사원형(부정사)이 바로 옵니다. quedar con + 사람은 스페인에서 아주 자주 쓰는 구어 표현으로 '~와 만나기로 하다, 약속을 잡고 만나다'라는 뜻입니다. 예: He quedado con Ana a las ocho.(아나와 8시에 만나기로 했어.)","x":["me quedar: 재귀대명사를 동사원형 앞에 따로 둘 수 없고(quedarme가 되어야 함), quedarse con은 '~을 갖다/차지하다'라는 다른 뜻이라 ✗","al quedar: 'al + 동사원형'은 '~할 때'라는 뜻이라 poder 뒤에 올 수 없습니다 ✗","quedando: 현재분사(~하면서)는 poder 뒤에 쓸 수 없습니다 ✗","quedar: poder + 동사원형, 'quedar con(~와 만나다)' → 정답 ✓"]},{"id":"G452","q":"Lo siento, no ____ terminar mi parte del trabajo.","o":["podido","pudiendo","he podido","pueda"],"a":2,"k":"현재완료","t":"미안해, 내가 맡은 부분의 작업을 끝내지 못했어.","e":"말하는 지금과 연결된 결과(아직 끝내지 못한 상태)를 전할 때 스페인에서는 현재완료(haber 현재 + 과거분사)를 씁니다. no he podido는 '(지금까지) ~할 수 없었다'는 뜻으로 사과할 때 아주 자연스럽습니다. 중남미에서는 같은 상황에 단순과거 no pude를 더 많이 씁니다.","x":["podido: 과거분사만 있고 조동사 haber가 빠져 문장이 성립하지 않습니다 ✗","pudiendo: 현재분사(~할 수 있으면서)라 주동사 자리에 올 수 없습니다 ✗","he podido: 현재완료 1인칭 단수, 지금과 연결된 결과 → 정답 ✓","pueda: 접속법 현재(바람·의심 등에 쓰는 형태)로, 단순한 사실 진술 문장에는 맞지 않습니다 ✗"]},{"id":"G453","q":"Debe tomar este jarabe ____ seis horas.","o":["cada","antes","después","como"],"a":0,"k":"빈도 cada","t":"이 시럽은 여섯 시간마다 드셔야 합니다.","e":"cada + 숫자 + 시간 명사는 '~마다'라는 반복 간격을 나타냅니다. 약 복용 안내에서 늘 쓰는 표현이에요. 예: cada ocho horas(8시간마다), cada dos días(이틀마다). cada는 성·수 변화가 없습니다.","x":["cada: '~마다', 반복 간격을 표시 → 정답 ✓","antes: '전에'라는 뜻이며 숫자 앞에 쓰려면 'antes de'가 필요하고 의미도 맞지 않습니다 ✗","después: '후에'라는 뜻으로 'después de seis horas'는 한 번만 '6시간 후'라는 뜻이 됩니다 ✗","como: '~처럼/약'이라는 뜻이라 복용 간격을 나타낼 수 없습니다 ✗"]},{"id":"G454","q":"El hostal donde me alojé entonces, ____ no existe.","o":["aun","todavía","ya","aún"],"a":2,"k":"ya no","t":"그때 내가 묵었던 호스텔은 이제는 없어.","e":"ya no + 동사는 '이제는 더 이상 ~하지 않다'라는 뜻으로, 예전에는 그랬지만 지금은 상황이 바뀌었음을 나타냅니다. 반대로 todavía/aún은 '아직도'라는 뜻이라 계속됨을 나타냅니다. 예: Ya no fumo.(이제 담배 안 피워.)","x":["aun: 악센트 없는 aun은 '심지어(incluso)'라는 뜻이라 문맥에 맞지 않습니다 ✗","todavía: '아직'이라는 뜻으로 todavía no existe는 '아직 생기지 않았다'가 되어 의미가 반대입니다 ✗","ya: ya no = '이제는 더 이상 ~않다', 상황 변화 → 정답 ✓","aún: 악센트 있는 aún은 todavía와 같은 '아직'이라 의미가 맞지 않습니다 ✗"]},{"id":"G455","q":"Te dije que ____ el abrigo antes de salir.","o":["ponías","te pusieras","te pondrías","pusieses"],"a":1,"k":"간접화법 명령","t":"내가 나가기 전에 외투를 입으라고 했잖아.","e":"decir que가 명령·부탁을 전할 때는 뒤에 접속법(바람·명령을 나타내는 동사 형태)을 씁니다. 주절이 과거(te dije)이므로 접속법 과거 te pusieras가 됩니다. '옷을 입다'는 재귀동사 ponerse라 te가 꼭 필요합니다. 사실 전달(그가 ~했다고 말했다)이면 직설법을 쓰는 것과 구별하세요.","x":["ponías: 직설법 불완료과거로, '네가 입곤 했다'는 사실 전달이 되고 재귀대명사도 없습니다 ✗","te pusieras: ponerse의 접속법 과거, 과거 시점의 명령 전달 → 정답 ✓","te pondrías: 가정법적 조건형(~할 텐데)이라 명령 전달에 쓰지 않습니다 ✗","pusieses: 접속법 과거 형태는 맞지만 재귀대명사 te가 빠져 '외투를 (다른 것에) 놓다'처럼 됩니다 ✗"]},{"id":"G456","q":"Ya te lo he dicho muchas veces, que no te ____ la opinión de los demás.","o":["influyen","influyas","influye","influya"],"a":3,"k":"부정명령 접속법","t":"이미 여러 번 말했잖아, 남들 의견에 휘둘리지 말라고.","e":"앞 문장을 반복하며 (te digo) que no...로 바람·충고를 전하면 접속법을 씁니다. 이 문장의 주어는 la opinión de los demás(다른 사람들의 의견, 단수)이고 te는 '너에게'입니다. 그래서 3인칭 단수 접속법 influya가 정답입니다. influir(영향을 주다)는 i→y로 바뀌는 동사입니다.","x":["influyen: 직설법 3인칭 복수로, 법(mood)도 틀리고 주어 la opinión(단수)와도 맞지 않습니다 ✗","influyas: 2인칭 단수 접속법이라 '네가 영향을 주다'가 되어 주어가 틀립니다 ✗","influye: 직설법이라 충고·명령 의미의 que절에 맞지 않습니다 ✗","influya: 주어 la opinión(3인칭 단수)에 맞는 접속법 현재 → 정답 ✓"]},{"id":"G457","q":"Se pasaron toda la noche ____ por teléfono.","o":["hablando","hablar","en hablar","a hablar"],"a":0,"k":"pasar + 현재분사","t":"그들은 밤새도록 전화로 이야기했다.","e":"pasar(se) + 시간 + 현재분사(-ando/-iendo)는 '~하면서 그 시간을 보내다'라는 뜻입니다. pasarse는 '시간을 꼬박 다 쓰다'라는 느낌을 더합니다. 예: Me pasé la tarde leyendo.(오후 내내 책을 읽으며 보냈다.)","x":["hablando: 'pasar + 시간 + 현재분사' 구조 → 정답 ✓","hablar: 동사원형은 이 구조에 쓰지 않습니다 ✗","en hablar: 'tardar en + 동사원형(~하는 데 시간이 걸리다)'과 혼동한 형태라 ✗","a hablar: 'a + 동사원형'은 목적·시작을 나타내며 이 구조와 맞지 않습니다 ✗"]},{"id":"G458","q":"¡Mira ____ barato! Este libro no llega ni a dos euros.","o":["qué","cuánto","cuál","cómo"],"a":0,"k":"감탄문 qué","t":"정말 싸다! 이 책은 2유로도 안 돼.","e":"형용사·부사를 강조하는 감탄은 ¡Qué + 형용사!로 씁니다. ¡Mira qué barato!는 '봐, 얼마나 싼지!'라는 뜻입니다. 명사의 양을 강조할 때만 cuánto(¡Cuánta gente!)를 씁니다.","x":["qué: 형용사 barato를 강조하는 감탄 → 정답 ✓","cuánto: 양·정도를 묻거나 감탄하며 주로 명사·동사와 쓰고 형용사 앞에는 쓰지 않습니다 ✗","cuál: '어느 것'이라는 선택 의문사라 감탄에 쓰지 않습니다 ✗","cómo: '어떻게'라는 뜻으로 ¡Cómo llueve!처럼 동사를 강조할 때 씁니다 ✗"]},{"id":"G459","q":"Según ____, ¿qué deberíamos hacer ahora?","o":["de ti","a ti","tú","ti"],"a":2,"k":"según + 주격대명사","t":"네 생각엔 우리가 이제 뭘 해야 할까?","e":"según(~에 따르면)은 특이하게 전치사 뒤에 쓰는 형태(mí, ti)가 아니라 주격 대명사(yo, tú)를 씁니다. 그래서 según tú, según yo가 맞습니다. entre(entre tú y yo)도 같은 예외입니다.","x":["de ti: según 뒤에 전치사를 또 붙일 수 없습니다 ✗","a ti: 전치사 a가 불필요하게 들어가 틀립니다 ✗","tú: según은 주격 대명사를 씀 → 정답 ✓","ti: 대부분의 전치사 뒤에서는 ti를 쓰지만 según은 예외라 ✗"]},{"id":"G460","q":"Nadie puede rebatir ____ sus opiniones.","o":["con","de","ø","a"],"a":2,"k":"타동사 rebatir","t":"아무도 그의 의견을 반박할 수 없다.","e":"rebatir(반박하다)는 직접목적어를 바로 받는 타동사입니다. 목적어가 사람이 아닌 사물(sus opiniones)이므로 전치사 a도 필요 없습니다. 이처럼 아무것도 넣지 않는 것(ø)이 정답인 경우도 있어요. 비슷한 동사: refutar, contradecir.","x":["con: rebatir는 전치사 con을 쓰지 않습니다(discutir con과 혼동) ✗","de: 전치사 de가 들어갈 이유가 없습니다 ✗","ø: 타동사 + 사물 직접목적어, 전치사 없음 → 정답 ✓","a: 사람 직접목적어 앞에만 쓰는 a라서, 사물인 opiniones 앞에는 ✗"]},{"id":"G461","q":"Fuencisla, ____ marido trabajaba aquí hace años, se acaba de jubilar.","o":["que su","de cuyo","cuyo","del cual"],"a":2,"k":"관계형용사 cuyo","t":"남편이 몇 년 전 이곳에서 일했던 푸엔시슬라가 막 은퇴했다.","e":"cuyo(~의)는 소유를 나타내는 관계사로, 뒤에 오는 명사(marido)와 성·수를 맞춥니다(cuyo marido, cuya casa, cuyos hijos). 'Fuencisla의 남편'이므로 cuyo marido가 됩니다. 구어에서 que su를 쓰는 사람도 있지만 규범에서는 틀린 것으로 봅니다.","x":["que su: 구어에서 들리기도 하지만 규범상 잘못된 형태(이른바 queísmo식 소유)라 ✗","de cuyo: 전치사 de가 필요한 구조가 아닙니다 ✗","cuyo: 뒤의 marido(남성 단수)에 일치하는 소유 관계사 → 정답 ✓","del cual: 'el marido del cual'처럼 명사 뒤에 와야 하며 이 위치에는 맞지 않습니다 ✗"]},{"id":"G462","q":"Son las dos, así que tu padre ya debe ____ estar de camino.","o":["a","tiene","de","que"],"a":2,"k":"deber de 추측","t":"두 시니까 네 아버지는 지금쯤 오는 길이실 거야.","e":"deber de + 동사원형은 '~임에 틀림없다, 아마 ~일 것이다'라는 추측을 나타냅니다. 반면 deber + 동사원형(de 없이)은 '~해야 한다'는 의무입니다. 실제 회화에서는 추측에도 de를 빼고 쓰는 일이 많아 RAE도 허용하지만, 문법 시험에서는 구별을 묻습니다.","x":["a: deber a + 동사원형이라는 구조는 없습니다 ✗","tiene: deber tiene는 동사가 겹쳐 문법적으로 성립하지 않습니다 ✗","de: deber de + 동사원형 = 추측 → 정답 ✓","que: deber que라는 구조는 없습니다(tener que와 혼동) ✗"]},{"id":"G463","q":"____ tres horas intentando arreglar la lavadora.","o":["Es","Está","Va","Lleva"],"a":3,"k":"llevar + 시간","t":"세 시간째 세탁기를 고치려고 애쓰고 있다.","e":"llevar + 기간 + 현재분사는 '~한 지 (기간)째다', 즉 과거에 시작해 지금도 계속되는 행동을 나타냅니다. 예: Llevo dos años estudiando español.(스페인어 공부한 지 2년 됐어.) 주어가 생략된 3인칭(그/그녀가)이라 lleva입니다.","x":["Es: ser는 시간의 지속을 나타내는 이 구조에 쓰지 않습니다 ✗","Está: estar + 현재분사는 진행형이지만 기간(tres horas)을 앞에 둘 수 없습니다 ✗","Va: ir + 현재분사는 '점점 ~해 가다'라는 뜻이고 기간 표현과 맞지 않습니다 ✗","Lleva: llevar + 기간 + 현재분사, 지속 기간 표현 → 정답 ✓"]},{"id":"G464","q":"Te veo muy tranquila, al contrario ____.","o":["de yo","conmigo","que mí","que yo"],"a":3,"k":"al contrario que","t":"너 정말 침착해 보여, 나와는 정반대로.","e":"al contrario que + 주어는 '~와는 반대로'라는 비교 표현입니다. que 뒤에는 비교 구문처럼 주격 대명사(yo)를 씁니다. 예: Al contrario que su hermano, ella es muy tímida.(오빠와 달리 그녀는 매우 수줍다.) al contrario de + 명사도 가능하지만 대명사일 때는 al contrario que yo가 자연스럽습니다.","x":["de yo: 전치사 de 뒤에는 yo를 쓸 수 없습니다(de mí가 됨) ✗","conmigo: al contrario conmigo라는 표현은 없습니다 ✗","que mí: que는 전치사가 아니므로 뒤에 mí가 아니라 yo가 와야 합니다 ✗","que yo: al contrario que + 주격 대명사 → 정답 ✓"]},{"id":"G465","q":"No te aferres ____ pasado, no merece la pena.","o":["con el","al","en el","del"],"a":1,"k":"aferrarse a","t":"과거에 집착하지 마, 그럴 가치가 없어.","e":"aferrarse(매달리다, 집착하다)는 항상 전치사 a와 함께 씁니다. a + el은 al로 축약되므로 al pasado가 됩니다. 예: Se aferró a la esperanza.(그는 희망에 매달렸다.) No merece la pena는 스페인에서 '그럴 가치가 없다'는 뜻의 관용 표현입니다.","x":["con el: aferrarse는 con을 쓰지 않습니다 ✗","al: aferrarse a + el = al → 정답 ✓","en el: 전치사 en은 aferrarse와 함께 쓰지 않습니다(empeñarse en과 혼동) ✗","del: de는 aferrarse의 전치사가 아닙니다 ✗"]},{"id":"G466","q":"Llamamos a Jorge ____ nos dijeron lo que había ocurrido.","o":["nada más","en cuanto","antes de que","siempre y cuando"],"a":1,"k":"en cuanto 시간","t":"무슨 일이 있었는지 듣자마자 우리는 호르헤에게 전화했다.","e":"en cuanto는 '~하자마자'라는 시간 접속사입니다. 과거의 실제 사실을 말할 때는 직설법(nos dijeron)을 씁니다. 미래 일이면 접속법을 씁니다: En cuanto llegue, te llamo.(도착하자마자 전화할게.)","x":["nada más: '~하자마자'라는 뜻은 같지만 nada más 뒤에는 동사원형이 옵니다(nada más saberlo) ✗","en cuanto: '~하자마자' + 과거 사실이라 직설법 → 정답 ✓","antes de que: '~하기 전에'는 뒤에 접속법이 필요하고 의미도 어색합니다 ✗","siempre y cuando: '~하는 한(조건)'이라 접속법이 필요하고 의미가 맞지 않습니다 ✗"]},{"id":"G467","q":"Noelia nos dijo que no podía venir porque ____ exhausta.","o":["estuvo","estuviera","ha estado","estaba"],"a":3,"k":"간접화법 시제","t":"노엘리아는 너무 지쳐서 올 수 없다고 우리에게 말했다.","e":"과거 시점에 '지쳐 있는 상태'를 묘사할 때는 불완료과거(estaba)를 씁니다. 간접화법에서 원래 말(Estoy exhausta)의 현재가 과거 이야기 속에서 estaba로 바뀐 것입니다. porque 뒤에는 이유(사실)가 오므로 직설법입니다.","x":["estuvo: 단순과거는 끝난 사건을 나타내 '당시 계속되던 상태'의 묘사에 맞지 않습니다 ✗","estuviera: 접속법이라 porque(이유) 뒤의 사실 진술에 맞지 않습니다 ✗","ha estado: 현재완료는 과거 간접화법(nos dijo)의 시제 일치에 맞지 않습니다 ✗","estaba: 과거의 상태 묘사, 원래 말 estoy의 시제 이동 → 정답 ✓"]},{"id":"G468","q":"En noviembre me voy a presentar ____ examen de español.","o":["en el","en","al","por"],"a":2,"k":"presentarse a","t":"11월에 나는 스페인어 시험을 보러 갈 거야.","e":"presentarse a + 시험/선거/대회는 '~에 응시하다, 출마하다'라는 뜻입니다. a + el이 al로 축약되어 al examen이 됩니다. 예: Se presentó a las elecciones.(그는 선거에 출마했다.)","x":["en el: presentarse en은 '~에 모습을 드러내다(장소)'라는 뜻이라 시험 응시에는 ✗","en: 전치사도 틀리고 관사도 빠졌습니다 ✗","al: presentarse a + el examen = 시험에 응시하다 → 정답 ✓","por: por는 이 동사와 '응시하다'라는 의미로 쓰지 않습니다 ✗"]},{"id":"G469","q":"¿Queréis ____ otra taza de té?","o":["un","ø","de una","una"],"a":1,"k":"otro 앞 관사","t":"차 한 잔 더 드실래요?","e":"otro/otra(다른, 하나 더) 앞에는 부정관사 un/una를 쓰지 않습니다. '*una otra taza'는 영어 another를 직역한 흔한 실수입니다. 그냥 otra taza라고 하면 됩니다. 정관사는 가능합니다: la otra taza(다른 그 잔).","x":["un: 부정관사 + otro는 틀리며, 성(taza는 여성)도 맞지 않습니다 ✗","ø: otro 앞에는 부정관사를 쓰지 않으므로 비움 → 정답 ✓","de una: 전치사와 관사가 불필요하게 들어가 틀립니다 ✗","una: '*una otra'는 영어식 오류라 ✗"]},{"id":"G470","q":"____ que lo intento, no me sale bien este ejercicio.","o":["Aun","Pese","Por más","A pesar"],"a":2,"k":"por más que","t":"아무리 해 봐도 이 연습문제는 잘 안 풀려.","e":"por más que + 동사는 '아무리 ~해도'라는 양보 표현입니다. 실제로 반복해서 시도하고 있는 사실이면 직설법(intento), 가정이나 불확실하면 접속법(intente)을 씁니다. No me sale bien은 '(일이) 잘 안 된다'는 회화 표현입니다.","x":["Aun: aun que로 띄어 쓰는 표현은 없습니다(aunque는 한 단어) ✗","Pese: pese a que가 되어야 하므로 a가 빠졌습니다 ✗","Por más: por más que = 아무리 ~해도 → 정답 ✓","A pesar: a pesar de que가 되어야 하므로 de가 빠졌습니다 ✗"]},{"id":"G471","q":"Las mandarinas están en la mesa de la cocina. ____ todas las que queráis.","o":["Llevarse","Llevaros","Llevéis","Llevaos"],"a":3,"k":"vosotros 명령+재귀","t":"귤은 부엌 식탁 위에 있어. 원하는 만큼 다 가져가.","e":"vosotros 긍정명령은 동사원형의 -r을 -d로 바꿉니다(llevad). 여기에 재귀대명사 os를 붙이면 -d가 빠져 llevaos가 됩니다. 구어에서 llevaros(동사원형)를 명령으로 쓰는 사람이 많지만 규범상은 틀린 형태입니다. vosotros는 스페인에서만 쓰고, 중남미에서는 Llévense(ustedes)라고 합니다.","x":["Llevarse: 동사원형이라 명령형이 아니며 인칭도 맞지 않습니다 ✗","Llevaros: 구어에서 흔하지만 규범상 명령형이 아닌 동사원형이라 ✗","Llevéis: 접속법 형태로, 부정명령(no os llevéis)에서만 씁니다 ✗","Llevaos: llevad + os에서 d가 탈락한 vosotros 긍정명령 → 정답 ✓"]},{"id":"G472","q":"Todavía no ____ si me darán la beca.","o":["sepa","se","supiera","sé"],"a":3,"k":"saber 직설법","t":"장학금을 받게 될지 나는 아직 모르겠다.","e":"'모르다'라는 단순한 사실을 말할 때는 직설법 현재 1인칭 sé를 씁니다. 악센트가 있는 sé(saber의 1인칭)와 재귀대명사 se는 다른 단어입니다. si(~인지) 뒤에는 미래형 darán을 써서 불확실한 미래를 나타냅니다.","x":["sepa: 접속법 현재로, 주절의 사실 진술에는 쓰지 않습니다 ✗","se: 악센트 없는 se는 대명사라 동사가 아닙니다 ✗","supiera: 접속법 과거라 시제와 법이 모두 맞지 않습니다 ✗","sé: saber 직설법 현재 1인칭 → 정답 ✓"]},{"id":"G473","q":"Sabemos que estás mintiendo, no creas que no te ____.","o":["conociéramos","conozcamos","conoceríamos","conocemos"],"a":3,"k":"no creas que+직설법","t":"네가 거짓말하는 거 다 알아, 우리가 널 모른다고 생각하지 마.","e":"보통 no creer que 뒤에는 접속법이 오지만, 'no creas que...'처럼 상대의 잘못된 생각을 바로잡는 명령에서는 말하는 사람이 사실이라고 확신하는 내용이므로 직설법이 자연스럽습니다. 예: No creas que no me he dado cuenta.(내가 눈치 못 챈 줄 알지 마.) 여기서 우리는 실제로 너를 잘 알고 있으므로 conocemos입니다.","x":["conociéramos: 접속법 과거라 현재 사실과 시제가 맞지 않습니다 ✗","conozcamos: 문법적으로 가능해 보이지만, 확신하는 사실을 강조하는 이 문맥에서는 직설법이 맞습니다 ✗","conoceríamos: 조건형(~할 텐데)이라 현재의 사실을 말하는 문장에 맞지 않습니다 ✗","conocemos: 화자가 확신하는 현재 사실, 직설법 → 정답 ✓"]},{"id":"G474","q":"¿A qué hora ____ el tren?","o":["salga","se sale","se va a salir","sale"],"a":3,"k":"시간표 현재형","t":"기차는 몇 시에 출발하나요?","e":"시간표·일정처럼 정해진 미래의 일은 현재형으로 말합니다. ¿A qué hora sale el tren?은 기차 시간을 물을 때 쓰는 기본 표현입니다. salir(출발하다, 나가다)는 재귀형 없이 씁니다.","x":["salga: 접속법이라 단순한 의문문에 쓰지 않습니다 ✗","se sale: salirse는 '넘치다, 이탈하다'라는 뜻이라 ✗","se va a salir: 재귀형도 틀리고, 정해진 시간표에는 현재형이 더 자연스럽습니다 ✗","sale: 시간표를 나타내는 현재형 → 정답 ✓"]},{"id":"G475","q":"Cuando no ____ en coche, lo hacía en moto.","o":["fue","iba","iría","estaba yendo"],"a":1,"k":"불완료과거 습관","t":"차로 가지 않을 때는 오토바이로 갔다.","e":"과거의 반복적인 습관(~하곤 했다)은 불완료과거로 나타냅니다. 뒤 문장의 lo hacía(그렇게 하곤 했다)도 불완료과거이므로 cuando절도 iba가 됩니다. ir en coche(차로 가다), ir en moto(오토바이로 가다)처럼 교통수단에는 en을 씁니다.","x":["fue: 단순과거는 한 번 일어난 사건이라 반복 습관에 맞지 않습니다 ✗","iba: 과거의 반복·습관을 나타내는 불완료과거 → 정답 ✓","iría: 조건형이라 과거 습관을 나타내지 않습니다 ✗","estaba yendo: 과거진행형은 '그 순간 가는 중이었다'라는 뜻이라 습관에 맞지 않습니다 ✗"]},{"id":"G476","q":"____ no cabíamos todos en el mismo coche, Ana y yo cogimos un taxi.","o":["Pues","Entonces","Como","Al"],"a":2,"k":"이유 como","t":"우리 모두가 같은 차에 탈 수 없어서 아나와 나는 택시를 탔다.","e":"como가 문장 맨 앞에 오면 '~이기 때문에, ~해서'라는 이유를 나타냅니다. 이유가 먼저 오고 결과가 뒤따르는 구조에 딱 맞습니다. 참고로 coger(타다, 잡다)는 스페인에서는 일상어지만 중남미 일부 지역에서는 비속어로 들리므로 tomar un taxi라고 하는 것이 안전합니다.","x":["Pues: pues는 이유를 나타낼 때 문장 맨 앞에 오지 않고 보통 뒤 절에 옵니다 ✗","Entonces: '그러면, 그래서'라는 결과 표현이라 이유절 앞에 쓰지 않습니다 ✗","Como: 문장 앞 이유절 '~해서' → 정답 ✓","Al: al 뒤에는 동사원형이 와야 합니다(al no caber) ✗"]},{"id":"G477","q":"Aquella es la chica ____ novio juega en un famoso equipo de fútbol.","o":["que su","cuyo","que","de la que su"],"a":1,"k":"관계형용사 cuyo","t":"저 애가 바로 남자친구가 유명한 축구팀에서 뛰는 그 여자애야.","e":"'그 여자애의 남자친구'처럼 소유 관계를 이을 때는 cuyo를 씁니다. cuyo는 소유자(chica)가 아니라 뒤의 명사(novio, 남성 단수)에 맞춰 형태가 바뀝니다. 그래서 cuya가 아니라 cuyo novio입니다.","x":["que su: 구어에서 들리지만 규범상 잘못된 관계절이라 ✗","cuyo: novio(남성 단수)에 일치하는 소유 관계사 → 정답 ✓","que: '*la chica que novio'는 소유 관계를 나타내지 못해 문장이 성립하지 않습니다 ✗","de la que su: 전치사 + 관계사 + 소유사가 겹쳐 틀린 구조입니다 ✗"]},{"id":"G478","q":"No he pegado ojo ____ toda la noche.","o":["por","hacia","entre","en"],"a":3,"k":"no pegar ojo","t":"밤새 한숨도 못 잤다.","e":"no pegar ojo는 '한숨도 못 자다'라는 관용 표현입니다. 부정문에서 기간 전체를 강조할 때 en toda la noche(밤새 한 번도)처럼 en을 씁니다. 예: No he comido nada en todo el día.(하루 종일 아무것도 못 먹었어.)","x":["por: por la noche(밤에)는 가능하지만 por toda la noche는 이 부정 강조 표현으로 쓰지 않습니다 ✗","hacia: '~쪽으로, ~경'이라는 뜻이라 맞지 않습니다 ✗","entre: '~사이에'라는 뜻이라 맞지 않습니다 ✗","en: 부정문 + en todo/toda = 그 기간 내내 한 번도 → 정답 ✓"]},{"id":"G479","q":"Anoche cenamos ____ sopa y calamares rebozados.","o":["la","ø","de la","una"],"a":1,"k":"무관사 명사","t":"어젯밤 우리는 수프와 오징어 튀김을 먹었다.","e":"cenar, comer, beber 뒤에서 막연한 음식 종류를 말할 때는 관사를 쓰지 않습니다(셀 수 없는 명사·불특정 복수). cenar sopa(수프를 먹다), comer pan(빵을 먹다)처럼요. calamares rebozados(튀김옷 입힌 오징어)도 관사 없이 나열되어 있죠.","x":["la: 정관사는 특정한 그 수프를 가리킬 때만 씁니다 ✗","ø: 불특정 음식은 관사 없이 씀 → 정답 ✓","de la: '그 수프 중 일부'라는 프랑스어식 표현이라 스페인어에서는 틀립니다 ✗","una: '수프 한 그릇'이 되어 어색하고, 뒤의 무관사 calamares와도 어울리지 않습니다 ✗"]},{"id":"G480","q":"De pequeña tenía algunos problemas de aprendizaje. ____, pude pasar todos los cursos.","o":["Por eso","Pero","No obstante","Ante eso"],"a":2,"k":"대조 담화표지","t":"어릴 때 나는 학습 문제가 좀 있었다. 그럼에도 불구하고 모든 학년을 통과할 수 있었다.","e":"no obstante는 '그럼에도 불구하고, 하지만'이라는 격식 있는 대조 표지로, 문장 맨 앞에서 쉼표와 함께 씁니다. 앞 내용(학습 문제)과 반대되는 결과(모든 학년 통과)를 이어 줍니다. 비슷한 표현: sin embargo, aun así.","x":["Por eso: '그래서'라는 결과 표현이라 앞뒤 내용이 반대인 문장에 맞지 않습니다 ✗","Pero: 대조는 맞지만 pero 뒤에는 쉼표를 찍지 않고 바로 이어 씁니다 ✗","No obstante: '그럼에도 불구하고' + 쉼표 → 정답 ✓","Ante eso: '그것에 직면해서'라는 반응 표현이라 대조를 나타내지 않습니다 ✗"]},{"id":"G481","q":"Cuando yo iba ____ primaria, este colegio era muy diferente.","o":["a","en","de","ante"],"a":0,"k":"ir a + 학교","t":"내가 초등학교에 다닐 때 이 학교는 아주 달랐다.","e":"ir a + 학교·학년은 '~에 다니다'라는 뜻입니다. ir a primaria(초등학교에 다니다), ir a la universidad(대학에 다니다)처럼 씁니다. 과거의 지속된 상황이라 불완료과거 iba를 썼어요. '초등학교 몇 학년이다'는 estar en primaria라고도 합니다.","x":["a: ir a primaria = 초등학교에 다니다 → 정답 ✓","en: estar en primaria는 가능하지만 ir 동사와는 en을 쓰지 않습니다 ✗","de: ir de는 '~ 차림으로/~하러 가다(ir de compras)'라는 뜻이라 맞지 않습니다 ✗","ante: '~앞에서'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G482","q":"____ prisa, todos estamos listos menos tú.","o":["Da","Daos","Dese","Date"],"a":3,"k":"darse prisa 명령","t":"서둘러, 너만 빼고 우리 다 준비됐어.","e":"darse prisa는 '서두르다'라는 스페인식 표현입니다. menos tú(너만 빼고)를 보면 상대가 tú이므로 tú 긍정명령 da에 재귀대명사 te를 붙여 date가 됩니다. 중남미에서는 apurarse를 많이 써서 ¡Apúrate!라고 합니다.","x":["Da: 재귀대명사 te가 빠져 '(무엇을) 서두름을 주다'가 되어 틀립니다 ✗","Daos: vosotros 명령이라 menos tú(너만 빼고)라는 상대와 맞지 않습니다 ✗","Dese: usted 명령이라 tú로 말하는 문맥과 맞지 않습니다 ✗","Date: tú 긍정명령 da + te → 정답 ✓"]},{"id":"G483","q":"No conocen a ____ que tenga su propio negocio.","o":["ningún","algunos","alguien","nadie"],"a":3,"k":"부정어 nadie","t":"그들은 자기 사업을 하는 사람을 아무도 모른다.","e":"동사 앞에 no가 있으면 뒤에도 부정어(nadie, nada, ningún)를 씁니다(이중 부정이 정상). 사람을 가리키므로 nadie(아무도)이고, 사람 목적어라 앞에 a가 붙습니다. 관계절 que tenga가 접속법인 것은 '존재하지 않는 사람'을 묘사하기 때문입니다.","x":["ningún: 형용사라서 뒤에 명사가 필요합니다(ningún empresario) ✗","algunos: 긍정어라 no와 함께 쓰면 어색하고, 접속법 관계절과도 맞지 않습니다 ✗","alguien: 긍정어라 부정문에서는 nadie로 바꿔야 합니다 ✗","nadie: no + 동사 + nadie, 존재하지 않는 사람 → 정답 ✓"]},{"id":"G484","q":"¡____ que puedes venir con nosotros a la fiesta!","o":["Efectivamente","Indudable","Claro","Natural"],"a":2,"k":"claro que","t":"물론 우리랑 같이 파티에 가도 돼!","e":"¡Claro que + 직설법!은 '물론 ~이지!'라는 강한 긍정 표현입니다. 회화에서 아주 자주 씁니다. 예: ¡Claro que sí!(당연하지!) 다른 형용사(indudable, natural)는 'es + 형용사 + que' 구조로 써야 합니다.","x":["Efectivamente: '실제로, 맞아요'라는 부사로, 뒤에 que를 붙여 쓰지 않습니다 ✗","Indudable: 'Es indudable que...'처럼 es가 필요합니다 ✗","Claro: ¡Claro que...! = 물론 ~이지 → 정답 ✓","Natural: 'Es natural que + 접속법'으로 써야 하며 의미도 '당연하다'로 다릅니다 ✗"]},{"id":"G485","q":"Con estos precios no ____ quien ahorre.","o":["hay","es","sea","está"],"a":0,"k":"no hay quien","t":"이런 물가로는 저축할 수 있는 사람이 아무도 없다.","e":"no hay quien + 접속법은 '~할 사람이 없다, 도저히 ~할 수 없다'라는 관용 구문입니다. 존재하지 않는 사람을 말하므로 뒤에 접속법(ahorre)이 옵니다. 예: No hay quien te entienda.(널 이해할 수 있는 사람은 아무도 없어.)","x":["hay: haber 존재 표현 no hay quien → 정답 ✓","es: ser는 존재를 나타내지 않습니다 ✗","sea: 접속법이라 주절에 쓰지 않습니다 ✗","está: estar는 특정한 것의 위치를 나타낼 뿐 존재 여부를 나타내지 않습니다 ✗"]},{"id":"G486","q":"Están hartos, ____ muchas horas estudiando.","o":["siguen","continúan","llevan","van"],"a":2,"k":"llevar + 시간","t":"그들은 지쳤어, 몇 시간째 공부하고 있거든.","e":"llevar + 기간 + 현재분사는 '~한 지 (기간)째다'라는 뜻입니다. 지친 이유가 오랫동안 공부해 왔기 때문이라는 문맥에 맞습니다. hartos는 '질린, 지긋지긋한'이라는 뜻입니다.","x":["siguen: seguir + 현재분사는 '계속 ~하다'는 뜻이지만 기간을 앞에 둘 수 없습니다 ✗","continúan: continuar도 seguir와 같아 기간 표현과 함께 이 구조로 쓰지 않습니다 ✗","llevan: llevar + 기간 + 현재분사 → 정답 ✓","van: ir + 현재분사는 '점차 ~해 가다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G487","q":"Tropezó ____ las escaleras y ahora no puede caminar.","o":["con el bajar","bajando","cuando haya bajado","de bajar"],"a":1,"k":"현재분사 동시동작","t":"그는 계단을 내려가다가 넘어져서 지금 걸을 수가 없다.","e":"현재분사(bajando)는 '~하면서, ~하다가'처럼 주동사와 동시에 일어난 상황을 나타냅니다. 비슷한 뜻으로 al bajar(내려갈 때)도 쓸 수 있습니다. tropezar는 '발이 걸려 넘어지다/비틀거리다'라는 뜻입니다.","x":["con el bajar: 동사원형 앞에 con el를 붙이는 표현은 쓰지 않습니다 ✗","bajando: 동시에 일어난 상황을 나타내는 현재분사 → 정답 ✓","cuando haya bajado: 접속법 현재완료는 미래 일에 쓰므로 과거 사건(tropezó)과 맞지 않습니다 ✗","de bajar: tropezar de라는 구조는 없습니다 ✗"]},{"id":"G488","q":"No me llames a las seis, que a esa hora ____.","o":["habré estado trabajando","habré trabajado","trabajaré","estaré trabajando"],"a":3,"k":"미래진행형","t":"6시에는 전화하지 마, 그 시간엔 일하고 있을 거야.","e":"estar 미래형 + 현재분사(estaré trabajando)는 '미래의 특정 시점에 ~하고 있는 중일 것이다'라는 뜻입니다. a esa hora(그 시각에)라는 특정 순간의 진행 중인 행동을 말하므로 미래진행형이 가장 자연스럽습니다. que는 여기서 '왜냐하면'이라는 회화체 이유 표현이에요.","x":["habré estado trabajando: 미래완료진행으로 '그때까지 계속 일해 왔을 것'이라는 뜻이라 맞지 않습니다 ✗","habré trabajado: 미래완료로 '그때쯤 이미 일을 끝냈을 것'이라는 뜻이라 ✗","trabajaré: 단순미래는 가능하지만 '그 시각에 진행 중'이라는 뉘앙스가 약합니다 ✗","estaré trabajando: 미래의 특정 시점에 진행 중인 동작 → 정답 ✓"]},{"id":"G489","q":"¿Cuál es la camiseta ____ más te gusta?","o":["cual","que","la que","la cual"],"a":1,"k":"관계대명사 que","t":"네가 가장 마음에 드는 티셔츠는 어느 거야?","e":"선행사(la camiseta) 바로 뒤에서 전치사 없이 관계절을 시작할 때는 que를 씁니다. el/la que, el/la cual은 보통 전치사 뒤(la camiseta con la que...)나 쉼표가 있는 설명적 관계절에서 씁니다.","x":["cual: 관사 없는 cual은 관계대명사로 쓰지 않습니다 ✗","que: 전치사 없는 한정적 관계절의 기본 관계사 → 정답 ✓","la que: 선행사 바로 뒤에 전치사 없이 쓰면 관사가 겹쳐 어색합니다 ✗","la cual: 쉼표 없는 한정적 관계절에는 쓰지 않습니다 ✗"]},{"id":"G490","q":"Opino que todo lo que hicimos ____ en vano.","o":["estuvo","estuviera","fuese","fue"],"a":3,"k":"opinar que 직설법","t":"나는 우리가 한 모든 일이 헛수고였다고 생각한다.","e":"opinar que, creer que, pensar que처럼 긍정의 의견 동사 뒤에는 직설법을 씁니다(부정이면 접속법). 끝난 과거 일을 평가하므로 단순과거 fue입니다. en vano는 '헛되이, 쓸데없이'라는 뜻이며 ser와 함께 씁니다.","x":["estuvo: estar en vano라는 표현은 쓰지 않습니다 ✗","estuviera: 접속법이라 긍정 의견 동사 opino que 뒤에 맞지 않습니다 ✗","fuese: 접속법 과거라 긍정 의견 뒤에 쓰지 않습니다 ✗","fue: 긍정 의견 + 직설법 단순과거 → 정답 ✓"]},{"id":"G491","q":"¿Para qué le preguntas si sabes que está ____ mal humor?","o":["con","a","para","de"],"a":3,"k":"estar de mal humor","t":"그가 기분이 안 좋은 걸 알면서 왜 물어봐?","e":"estar de buen/mal humor는 '기분이 좋다/나쁘다'라는 고정 표현으로 전치사 de를 씁니다. estar de + 명사는 일시적인 상태를 나타내는 경우가 많습니다: estar de vacaciones(휴가 중이다), estar de viaje(여행 중이다).","x":["con: estar con mal humor는 비표준이라 ✗","a: 전치사 a는 이 표현에 쓰지 않습니다 ✗","para: 'para mal humor'는 의미가 성립하지 않습니다 ✗","de: estar de mal humor = 기분이 나쁘다 → 정답 ✓"]},{"id":"G492","q":"José López ha sido nombrado ____ presidente de la comunidad.","o":["un","al","ø","el"],"a":2,"k":"직책 무관사","t":"호세 로페스가 주민 대표로 임명되었다.","e":"nombrar, elegir, ser 뒤에 직업·직책이 오면 관사를 쓰지 않습니다. ha sido nombrado presidente(대표로 임명되었다), Es médico(그는 의사다)처럼요. 형용사가 붙어 특징을 강조할 때만 관사를 씁니다(Es un médico excelente).","x":["un: 직책 앞에 부정관사를 쓰지 않습니다 ✗","al: a + el은 전치사가 들어간 형태라 맞지 않습니다 ✗","ø: nombrar + 직책은 관사 없음 → 정답 ✓","el: 직책 앞 정관사는 이 구조에서 쓰지 않습니다 ✗"]},{"id":"G493","q":"La obra de teatro fue tan increíble que todos ____ con la boca abierta.","o":["quedamos","nos quedamos","quedábamos","nos quedaremos"],"a":1,"k":"quedarse 상태변화","t":"연극이 너무 대단해서 우리 모두 입을 다물지 못했다.","e":"quedarse + 형용사/표현은 '(어떤 상태가) 되어 버리다'라는 변화를 나타냅니다. quedarse con la boca abierta는 '입을 떡 벌리다, 깜짝 놀라다'라는 관용 표현입니다. 한 번 일어난 반응이므로 단순과거 nos quedamos입니다.","x":["quedamos: 재귀대명사가 없으면 '만나기로 하다'라는 다른 뜻이 됩니다 ✗","nos quedamos: quedarse + 상태, 한 번의 반응을 단순과거로 → 정답 ✓","quedábamos: 재귀대명사도 없고 불완료과거라 일회적 반응에 맞지 않습니다 ✗","nos quedaremos: 미래형이라 과거 사건(fue)과 맞지 않습니다 ✗"]},{"id":"G494","q":"Como no ____ la situación económica global, muchos vamos a estar a dos velas.","o":["mejorará","mejore","mejora","mejorase"],"a":1,"k":"como + 접속법 조건","t":"세계 경제 상황이 나아지지 않으면 우리 중 많은 사람이 빈털터리가 될 거야.","e":"como가 문장 앞에서 접속법과 함께 쓰이면 이유가 아니라 '만약 ~하면(경고·위협)'이라는 조건이 됩니다. 예: Como no estudies, suspenderás.(공부 안 하면 낙제할 거야.) estar a dos velas는 스페인 구어로 '돈이 한 푼도 없다'라는 관용 표현입니다.","x":["mejorará: 직설법 미래는 como 조건절에 쓰지 않습니다 ✗","mejore: como + 접속법 현재 = 경고성 조건 → 정답 ✓","mejora: 직설법이면 como가 '~하기 때문에'라는 이유가 되어 뒷문장과 논리가 어긋납니다 ✗","mejorase: 접속법 과거라 주절의 미래(vamos a estar)와 시제가 맞지 않습니다 ✗"]},{"id":"G495","q":"Me encanta ir a la playa cuando el mar está ____ calma.","o":["a","en","de","durante"],"a":1,"k":"estar en calma","t":"바다가 잔잔할 때 해변에 가는 걸 아주 좋아해.","e":"estar en calma는 '고요하다, 잔잔하다'라는 고정 표현입니다. en + 명사로 상태를 나타내는 표현은 많습니다: estar en silencio(조용하다), estar en paz(평온하다).","x":["a: estar a calma라는 표현은 없습니다 ✗","en: estar en calma = 잔잔하다 → 정답 ✓","de: estar de calma는 쓰지 않습니다 ✗","durante: '~하는 동안'이라는 시간 전치사라 상태를 나타내지 않습니다 ✗"]},{"id":"G496","q":"¿Le cuento a Jimena ____ tu compromiso con Elías?","o":["esto con","lo sobre","lo de","esto de"],"a":2,"k":"lo de","t":"너랑 엘리아스의 약혼 일을 히메나에게 말할까?","e":"lo de + 명사는 '~에 관한 일/건'이라는 뜻의 아주 자주 쓰는 회화 표현입니다. 예: ¿Te has enterado de lo de Juan?(후안 일 들었어?) 상대가 이미 아는 화제를 간단히 가리킬 때 씁니다.","x":["esto con: esto con tu compromiso는 '그 약혼과 함께 이것'이 되어 의미가 맞지 않습니다 ✗","lo sobre: lo 뒤에 sobre를 붙이는 표현은 없습니다 ✗","lo de: '~에 관한 일' → 정답 ✓","esto de: esto de도 쓰긴 하지만 '이것, 이 ~라는 일'로 화자 쪽 화제를 가리킬 때 쓰며, 여기서는 lo de가 표준 답입니다 ✗"]},{"id":"G497","q":"Nos ordenó que ____ de allí inmediatamente.","o":["salíamos","salimos","saliéramos","salgamos"],"a":2,"k":"명령 전달 접속법","t":"그는 우리에게 그곳에서 즉시 나가라고 명령했다.","e":"ordenar que(~하라고 명령하다)처럼 명령·요구 동사 뒤에는 접속법을 씁니다. 주절이 과거(ordenó)이므로 접속법 과거 saliéramos로 시제를 맞춥니다.","x":["salíamos: 직설법 불완료과거라 명령 동사 뒤에 쓸 수 없습니다 ✗","salimos: 직설법이라 ordenar que 뒤에 맞지 않습니다 ✗","saliéramos: 과거 명령 + 접속법 과거 → 정답 ✓","salgamos: 접속법 현재라 과거 주절 ordenó와 시제가 맞지 않습니다 ✗"]},{"id":"G498","q":"La ropa está ____ tender. ¿A quién le toca tenderla hoy?","o":["por","a","para","de"],"a":0,"k":"estar por + 부정사","t":"빨래가 아직 안 널려 있어. 오늘 너는 거 누구 차례야?","e":"estar por + 동사원형은 '아직 ~되지 않은 상태다(해야 할 일이 남아 있다)'라는 뜻입니다. 예: La casa está por limpiar.(집은 아직 청소 안 됐다.) 사람 주어일 때는 '~할까 생각 중이다'라는 뜻도 됩니다. tender la ropa는 '빨래를 널다'입니다.","x":["por: estar por + 동사원형 = 아직 ~되지 않았다 → 정답 ✓","a: estar a + 동사원형은 이런 의미로 쓰지 않습니다 ✗","para: estar para + 동사원형은 '막 ~하려는 참이다'라는 뜻이라 문맥에 맞지 않습니다 ✗","de: estar de tender라는 표현은 없습니다 ✗"]},{"id":"G499","q":"Si ustedes no van, yo ____ iré.","o":["tampoco no","tampoco","también","también no"],"a":1,"k":"tampoco","t":"여러분이 안 가면 나도 안 갈 거예요.","e":"앞의 부정 내용에 '나도 ~않다'라고 동의할 때는 tampoco를 씁니다. tampoco가 동사 앞에 오면 no를 추가로 쓰지 않습니다(yo tampoco iré). 동사 뒤에 오면 no가 필요합니다: Yo no iré tampoco.","x":["tampoco no: tampoco가 동사 앞에 올 때 no를 겹쳐 쓰면 틀립니다 ✗","tampoco: 부정 동의 '~도 안' → 정답 ✓","también: '~도 (긍정)'이라 앞의 부정 조건과 논리가 어긋납니다 ✗","también no: 스페인어에서 쓰지 않는 잘못된 조합입니다 ✗"]},{"id":"G500","q":"____ una vez que voy a la peluquería y se pone a llover.","o":["Con","Por","De","Para"],"a":3,"k":"para una vez que","t":"모처럼 한 번 미용실에 갔는데 비가 오기 시작하네.","e":"Para una vez que + 동사...는 '모처럼 한 번 ~했는데 (하필)'이라는 불평·아이러니를 담은 관용 표현입니다. 드물게 한 일이 운 나쁘게 끝났을 때 씁니다. 예: Para una vez que salgo, me encuentro con mi jefe.(모처럼 나갔는데 상사를 만나다니.)","x":["Con: con una vez는 '한 번으로 (충분하다)'라는 다른 의미입니다 ✗","Por: por una vez는 '이번 한 번만'이라는 뜻이라 문맥에 맞지 않습니다 ✗","De: de una vez는 '단번에, 이제 그만'이라는 뜻이라 맞지 않습니다 ✗","Para: para una vez que = 모처럼 ~했는데 → 정답 ✓"]},{"id":"G501","q":"Cocinamos diversos platos ____ de que todos estuvieran satisfechos.","o":["al fin","con fin","para el fin","con el fin"],"a":3,"k":"con el fin de que","t":"모두가 만족하도록 우리는 여러 가지 요리를 했다.","e":"con el fin de que + 접속법은 '~하기 위해, ~하도록'이라는 목적 표현으로 para que보다 조금 격식 있습니다. 주어가 같으면 con el fin de + 동사원형을 씁니다. 과거 주절이라 estuvieran(접속법 과거)이 왔습니다.","x":["al fin: al fin은 '마침내'라는 뜻이라 목적을 나타내지 않습니다 ✗","con fin: 정관사 el이 빠져 틀립니다 ✗","para el fin: 고정 표현이 아니라 ✗","con el fin: con el fin de que = ~하도록 → 정답 ✓"]},{"id":"G502","q":"Cuando ____ nuestro segundo hijo, tendrá que venir alguien a ayudarnos con las tareas.","o":["nazca","nacería","nacerá","naciera"],"a":0,"k":"cuando + 접속법","t":"둘째 아이가 태어나면 집안일을 도와줄 사람이 와야 할 거야.","e":"cuando가 아직 일어나지 않은 미래의 일을 가리키면 뒤에 접속법 현재를 씁니다. 스페인어에서는 cuando절 안에 미래형을 쓰지 않는다는 점이 중요합니다. 예: Cuando llegues, llámame.(도착하면 전화해.)","x":["nazca: 미래 시점 cuando + 접속법 현재 → 정답 ✓","nacería: 조건형은 cuando절에 쓰지 않습니다 ✗","nacerá: cuando절 안에서는 미래형을 쓰지 않습니다 ✗","naciera: 접속법 과거라 주절의 미래(tendrá)와 시제가 맞지 않습니다 ✗"]},{"id":"G503","q":"¡____ fiesta tan aburrida!","o":["Va","Vamos","Vaya","Vayan"],"a":2,"k":"감탄 vaya","t":"정말 지루한 파티네!","e":"¡Vaya + 명사!는 '정말 대단한/형편없는 ~이군!'이라는 감탄 표현으로, ¡Qué + 명사!와 비슷합니다. 뒤에 tan/más + 형용사를 붙여 강조합니다(¡Vaya fiesta más aburrida!). 스페인에서 특히 많이 씁니다.","x":["Va: ir의 3인칭 직설법이라 감탄사로 쓰지 않습니다 ✗","Vamos: '자, 가자'라는 뜻의 감탄사이며 명사를 꾸미지 못합니다 ✗","Vaya: ¡Vaya + 명사! = 정말 ~이군 → 정답 ✓","Vayan: ustedes 명령형이라 감탄 표현이 아닙니다 ✗"]},{"id":"G504","q":"Este castillo ____ en la Edad Media.","o":["era construido","fue construido","estuvo construido","estaba construido"],"a":1,"k":"ser 수동태","t":"이 성은 중세에 지어졌다.","e":"행위(건설)가 특정 과거 시기에 끝났음을 말하는 수동태는 ser + 과거분사, 그리고 완료된 사건이므로 단순과거 fue를 씁니다. estar + 과거분사는 행위의 결과 상태(El castillo está bien conservado.)를 나타냅니다.","x":["era construido: 불완료과거라 '지어지고 있었다/지어지곤 했다'는 뜻이 되어 완료된 사건에 맞지 않습니다 ✗","fue construido: 과거에 완료된 행위의 수동태 → 정답 ✓","estuvo construido: estar는 결과 상태를 나타내므로 '중세에 지어졌다'는 행위를 표현하지 못합니다 ✗","estaba construido: '(이미) 지어진 상태였다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G505","q":"¿Dónde está el niño? —No te preocupes, ____ en su cuarto.","o":["estará jugando","estaría jugando","habrá jugado","va a estar jugando"],"a":0,"k":"미래형 추측","t":"아이는 어디 있어? —걱정 마, 자기 방에서 놀고 있을 거야.","e":"스페인어 미래형은 '현재에 대한 추측(아마 ~일 거야)'을 나타낼 수 있습니다. 지금 이 순간 진행 중인 일을 추측하므로 미래진행형 estará jugando입니다. 예: ¿Qué hora será?(지금 몇 시쯤일까?)","x":["estará jugando: 현재 진행 중인 일에 대한 추측 → 정답 ✓","estaría jugando: 조건형은 과거에 대한 추측(그때 ~하고 있었을 것)이라 ✗","habrá jugado: '(이미) 놀았을 것'이라는 완료된 일의 추측이라 ✗","va a estar jugando: 앞으로 일어날 일을 예정하는 표현이라 현재 추측에 맞지 않습니다 ✗"]},{"id":"G506","q":"____ ver que no dejaba de llorar, me senté a su lado.","o":["Al","Debido a","Puesto que","En cuanto"],"a":0,"k":"al + 동사원형","t":"그가 울음을 그치지 않는 것을 보고 나는 그의 옆에 앉았다.","e":"al + 동사원형은 '~할 때, ~하자'라는 뜻으로, 주절과 거의 동시에 일어난 일이나 그 계기를 나타냅니다. 예: Al llegar a casa, me duché.(집에 도착해서 샤워했다.) no dejar de + 동사원형은 '계속 ~하다, ~을 멈추지 않다'입니다.","x":["Al: al + 동사원형 = ~할 때/~하자 → 정답 ✓","Debido a: '~때문에'는 명사가 와야 자연스럽고 ver와는 어색합니다 ✗","Puesto que: 이유 접속사라 뒤에 활용된 동사가 필요합니다 ✗","En cuanto: '~하자마자'는 뒤에 활용된 동사가 와야 합니다(en cuanto vi) ✗"]},{"id":"G507","q":"Podemos hacer un pícnic el sábado, ____ se ponga feo el tiempo.","o":["a no ser que","siempre que","siempre y cuando","con tal de que"],"a":0,"k":"a no ser que","t":"날씨가 나빠지지 않는 한, 토요일에 소풍을 갈 수 있어.","e":"a no ser que + 접속법은 '~하지 않는 한, ~하는 경우가 아니라면'이라는 예외 조건입니다. 날씨가 나빠지면 소풍을 못 가므로 의미상 이것만 맞습니다. 비슷한 표현: salvo que, excepto que.","x":["a no ser que: '~하지 않는 한(예외 조건)' → 정답 ✓","siempre que: '~한다면'이라 '날씨가 나빠지면 소풍 간다'가 되어 의미가 반대입니다 ✗","siempre y cuando: 역시 '~하는 조건이면'이라 의미가 맞지 않습니다 ✗","con tal de que: '~하기만 하면'이라 의미가 맞지 않습니다 ✗"]},{"id":"G508","q":"Mamá dice que ____ junto al coche.","o":["esperásemos","esperamos","esperemos","esperar"],"a":2,"k":"decir que 명령","t":"엄마가 차 옆에서 기다리래.","e":"decir que가 정보가 아니라 명령·지시를 전할 때는 접속법을 씁니다. 주절이 현재(dice)이므로 접속법 현재 esperemos가 됩니다. 만약 '우리가 기다린다고 말한다'는 사실 전달이면 esperamos(직설법)가 되지만 여기선 지시입니다.","x":["esperásemos: 접속법 과거라 현재 주절 dice와 시제가 맞지 않습니다 ✗","esperamos: 직설법이면 '우리가 기다린다고 말한다'는 사실 전달이 되어 문맥에 어색합니다 ✗","esperemos: 현재 명령 전달 + 접속법 현재 → 정답 ✓","esperar: que 뒤에는 활용된 동사가 필요합니다 ✗"]},{"id":"G509","q":"¡____ seas muy feliz!","o":["Qué","Que","A que","A qué"],"a":1,"k":"que + 접속법 기원","t":"부디 아주 행복하길!","e":"문장 맨 앞의 Que + 접속법은 '~하기를!'이라는 바람·축원을 나타냅니다. 앞에 Espero가 생략된 것으로 볼 수 있어요. 예: ¡Que te mejores!(빨리 낫길!), ¡Que aproveche!(맛있게 드세요!) 악센트 없는 que라는 점에 주의하세요.","x":["Qué: 악센트 있는 qué는 감탄·의문사라 기원문에 쓰지 않습니다 ✗","Que: 기원의 que + 접속법 → 정답 ✓","A que: '~라는 데 걸게, ~지?'라는 내기·도발 표현이라 맞지 않습니다 ✗","A qué: '무엇에/무엇을 위해'라는 의문 표현이라 ✗"]},{"id":"G510","q":"¿En serio te avergüenzas ____ nosotros?","o":["de","con","sobre","hacia"],"a":0,"k":"avergonzarse de","t":"너 정말 우리가 부끄러워?","e":"avergonzarse(부끄러워하다)는 전치사 de와 함께 씁니다: avergonzarse de algo/alguien. 감정을 나타내는 재귀동사 중 de를 쓰는 것이 많습니다: alegrarse de, arrepentirse de, quejarse de.","x":["de: avergonzarse de = ~을 부끄러워하다 → 정답 ✓","con: avergonzarse는 con을 쓰지 않습니다 ✗","sobre: '~에 대해'라는 뜻이지만 이 동사의 전치사가 아닙니다 ✗","hacia: '~쪽으로'라는 방향 전치사라 맞지 않습니다 ✗"]},{"id":"G511","q":"____ libro recomendable, el último de Javier Marías.","o":["De","Para","Sobre","Por"],"a":1,"k":"para + 명사 강조","t":"추천할 만한 책이라면 단연 하비에르 마리아스의 최신작이지.","e":"Para + 무관사 명사, ...는 회화에서 '~라면 (단연) 이것이다'라는 뜻으로 대표적인 예를 제시할 때 씁니다. 예: Para ciudad bonita, Granada.(예쁜 도시라면 그라나다지.) 비슷하게 'Para + 명사, + 형용사'는 '~치고는'이라는 뜻도 있습니다(Para niño, es muy alto. 아이치고는 키가 크다).","x":["De: de libro recomendable은 이런 강조 용법이 없습니다 ✗","Para: para + 명사 = ~라면(대표 예 제시) → 정답 ✓","Sobre: '~에 관해'라는 뜻이라 추천 대상을 제시하지 못합니다 ✗","Por: por libro는 '책마다/책 때문에'라는 뜻이 되어 맞지 않습니다 ✗"]},{"id":"G512","q":"Estos zapatos ____, necesito otro número.","o":["están apretando","me aprietan","han apretado","se aprietan"],"a":1,"k":"apretar 간접목적","t":"이 신발이 꽉 껴서 다른 사이즈가 필요해.","e":"apretar(꽉 끼다, 죄다)는 gustar처럼 '불편을 겪는 사람'을 간접목적격 대명사(me, te, le...)로 나타냅니다. 주어는 estos zapatos(복수)라서 me aprietan입니다. apretar는 e→ie로 바뀌는 동사입니다. 예: La camisa le queda pequeña.(셔츠가 그에게 작다.)","x":["están apretando: 대명사가 없어 누구에게 끼는지 알 수 없고 진행형도 어색합니다 ✗","me aprietan: 간접목적격 me + 3인칭 복수 → 정답 ✓","han apretado: 현재완료는 지금의 착용감 상태를 나타내기에 어색하고 대명사도 없습니다 ✗","se aprietan: 재귀형은 '서로 죄다/스스로 조이다'라는 뜻이 되어 틀립니다 ✗"]},{"id":"G513","q":"____ insistan, no vamos a hacerles caso.","o":["Por tanto que","De tanto que","Por mucho que","Por más"],"a":2,"k":"por mucho que","t":"그들이 아무리 고집해도 우리는 그들 말을 듣지 않을 거야.","e":"por mucho que + 동사는 '아무리 ~해도'라는 양보 표현입니다. 미래의 가능성이나 가정을 말할 때는 접속법(insistan)을 씁니다. por más que와 뜻이 같습니다. hacer caso a alguien은 '~의 말을 듣다, 신경 쓰다'입니다.","x":["Por tanto que: 쓰지 않는 표현입니다(por tanto는 '그러므로') ✗","De tanto que: de tanto + 동사원형은 '너무 ~해서'라는 원인 표현이라 ✗","Por mucho que: '아무리 ~해도' + 접속법 → 정답 ✓","Por más: que가 빠져 문장이 이어지지 않습니다(por más que가 되어야 함) ✗"]},{"id":"G514","q":"En cuanto te vi, ____ que eras el amor de mi vida.","o":["supiese","había sabido","supe","sabría"],"a":2,"k":"saber 단순과거","t":"너를 보자마자 네가 내 인생의 사랑이라는 걸 알았어.","e":"saber를 단순과거(supe)로 쓰면 '알고 있었다'가 아니라 '(그 순간) 알게 되었다, 깨달았다'라는 뜻이 됩니다. en cuanto te vi(너를 보자마자)라는 특정 순간과 잘 어울립니다. 반면 sabía는 '이미 알고 있었다'라는 상태입니다.","x":["supiese: 접속법 과거라 주절의 사실 진술에 쓰지 않습니다 ✗","había sabido: 대과거는 '보기 전에 이미 알았다'가 되어 en cuanto와 논리가 맞지 않습니다 ✗","supe: 단순과거 = 그 순간 알게 되었다 → 정답 ✓","sabría: 조건형이라 실제로 일어난 과거 사실을 나타내지 못합니다 ✗"]},{"id":"G515","q":"Miguel es un poco soso, pero sus hermanos son ____ simpáticos.","o":["como","algo","así de","bien"],"a":3,"k":"bien + 형용사","t":"미겔은 좀 재미가 없지만 그의 형제들은 정말 상냥해.","e":"bien이 형용사 앞에 오면 muy처럼 '정말, 아주'라는 강조 부사가 됩니다. 특히 중남미 회화에서 많이 씁니다: Está bien rico.(정말 맛있어.) soso는 '싱거운, 재미없는(사람)'이라는 뜻입니다.","x":["como: 비교의 como는 '~처럼'이라 앞에 비교 대상이 필요합니다 ✗","algo: '약간'이라는 뜻이라 pero로 대조하는 문맥에서 강조가 약하고 어색합니다 ✗","así de: '그렇게나'라는 뜻으로 보통 몸짓이나 앞에 언급된 기준이 필요합니다 ✗","bien: 형용사 강조 '정말' → 정답 ✓"]},{"id":"G516","q":"No dejes pasar esta oportunidad. ¡Esta es ____!","o":["la tuya","tuya","por la tuya","de la tuya"],"a":0,"k":"관용 la tuya","t":"이 기회를 놓치지 마. 지금이 바로 네 차례야!","e":"¡Esta es la tuya!는 '이번이 너의 기회다!'라는 관용 표현입니다. 소유대명사 la tuya가 생략된 명사 la oportunidad(여성)를 대신합니다. 소유대명사는 관사와 함께 씁니다: el mío, la tuya, los suyos.","x":["la tuya: 관사 + 소유대명사, '네 기회' → 정답 ✓","tuya: 관사가 없으면 'Esta es tuya(이건 네 거야)'라는 소유 진술이 되어 관용 의미가 사라집니다 ✗","por la tuya: 전치사 por가 불필요하게 들어가 틀립니다 ✗","de la tuya: 전치사 de가 불필요하게 들어가 틀립니다 ✗"]},{"id":"G517","q":"Antes vivía en una zona ____ peligrosa.","o":["de las más","de los más","de lo más","de la más"],"a":2,"k":"de lo más","t":"예전에 나는 아주 위험한 동네에 살았다.","e":"de lo más + 형용사는 '아주, 더할 나위 없이'라는 강조 표현입니다. 여기서 lo는 중성이라 형용사(peligrosa)의 성·수와 상관없이 항상 lo를 씁니다. 예: Es una persona de lo más amable.(정말 친절한 사람이야.)","x":["de las más: 'una de las zonas más peligrosas'와 혼동한 형태로 이 위치엔 ✗","de los más: 남성 복수 관사라 성·수도 맞지 않습니다 ✗","de lo más: 중성 lo를 쓰는 강조 표현 → 정답 ✓","de la más: 관용 표현은 중성 lo만 씁니다 ✗"]},{"id":"G518","q":"Te ____ lo que pienso, pero prefiero callarme.","o":["digo","he dicho","diría","diré"],"a":2,"k":"조건형 완곡","t":"내 생각을 말하고 싶지만 그냥 입 다물고 있을래.","e":"조건형(diría)은 '(그럴 수 있다면) ~할 텐데'라는 실현되지 않는 행동을 나타냅니다. 뒤의 pero prefiero callarme(하지만 입 다무는 게 낫다)가 실제로는 말하지 않는다는 것을 보여 주죠. callarse는 '입을 다물다'입니다.","x":["digo: 현재형이면 '지금 말한다'가 되어 뒤의 '입 다물겠다'와 모순입니다 ✗","he dicho: '이미 말했다'가 되어 역시 뒤 내용과 모순입니다 ✗","diría: 실현되지 않는 가정의 조건형 → 정답 ✓","diré: 미래형은 '말할 것이다'라는 실제 계획이라 모순됩니다 ✗"]},{"id":"G519","q":"Solemos cenar pronto, pero hoy haremos ____ excepción.","o":["ø","la","una","de"],"a":2,"k":"부정관사 una","t":"우리는 보통 일찍 저녁을 먹지만 오늘은 예외로 할 거야.","e":"hacer una excepción은 '예외를 두다'라는 고정 표현입니다. 셀 수 있는 명사가 처음 등장하며 '하나의 예외'를 뜻하므로 부정관사 una를 씁니다. pronto는 스페인에서 '일찍(temprano)'이라는 뜻으로도 많이 쓰입니다.","x":["ø: 관사 없이 hacer excepción이라고 하면 어색합니다 ✗","la: 특정한 그 예외를 가리키는 것이 아니라 ✗","una: hacer una excepción = 예외로 하다 → 정답 ✓","de: 전치사가 들어갈 자리가 아닙니다 ✗"]},{"id":"G520","q":"Pablito siempre ____ el pantalón. No sé cómo lo hace.","o":["va manchado","está manchado","viene machado","lleva manchado"],"a":3,"k":"llevar + 과거분사","t":"파블리토는 늘 바지를 더럽혀 다녀. 어떻게 그러는지 모르겠어.","e":"llevar + 직접목적어 + 과거분사는 '(무엇을) ~한 상태로 하고 있다/다니다'라는 뜻입니다. 여기서 과거분사(manchado)는 목적어 el pantalón과 성·수를 맞춥니다. 예: Lleva el pelo teñido.(머리를 염색했다.) Pablito는 Pablo의 애칭(작은 파블로)입니다.","x":["va manchado: ir manchado는 '(주어가) 더러운 채로 다닌다'는 뜻이라 목적어 el pantalón과 구조가 맞지 않습니다 ✗","está manchado: '(주어가) 더러워져 있다'는 뜻이라 뒤에 목적어를 둘 수 없습니다 ✗","viene machado: 철자부터 틀렸고(manchado), venir도 이 구조에 맞지 않습니다 ✗","lleva manchado: llevar + 목적어 + 과거분사 상태 → 정답 ✓"]},{"id":"G521","q":"¿Qué tal si ____ hoy en casa? Estoy agotado.","o":["nos quedamos","nos quedemos","nos quedábamos","nos quedaríamos"],"a":0,"k":"qué tal si 제안","t":"오늘 집에 있는 게 어때? 난 너무 피곤해.","e":"¿Qué tal si + 직설법 현재?는 '~하는 게 어때?'라는 제안 표현입니다. si(만약) 뒤에는 접속법 현재를 쓰지 않는다는 규칙이 여기서도 적용됩니다. 예: ¿Qué tal si vamos al cine?(영화 보러 가는 게 어때?)","x":["nos quedamos: qué tal si + 직설법 현재 → 정답 ✓","nos quedemos: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","nos quedábamos: 불완료과거는 이 제안 표현에 쓰지 않습니다(구어 일부에서만) ✗","nos quedaríamos: 조건형은 si 뒤에 쓰지 않습니다 ✗"]},{"id":"G522","q":"____ en cuanto tenga los resultados.","o":["Os avisaré","Os avisé","Os habré avisado","Os avise"],"a":0,"k":"en cuanto + 미래","t":"결과가 나오는 대로 너희에게 알려 줄게.","e":"en cuanto + 접속법(tenga)은 '~하자마자'라는 미래의 시점을 나타냅니다. 그 결과 일어날 주절의 일은 미래형(avisaré)으로 씁니다. 패턴: 주절 미래 + en cuanto/cuando + 접속법 현재.","x":["Os avisaré: 미래형 주절 + en cuanto + 접속법 → 정답 ✓","Os avisé: 단순과거라 미래 시점의 접속법 tenga와 맞지 않습니다 ✗","Os habré avisado: 미래완료는 '그때쯤 이미 알렸을 것'이라 논리가 맞지 않습니다 ✗","Os avise: 접속법은 주절에 홀로 쓰지 않습니다 ✗"]},{"id":"G523","q":"Este no es un sitio adecuado. ____ de aquí.","o":["Vamos","Vayamos","Vamonos","Vámonos"],"a":3,"k":"vámonos","t":"여긴 적당한 곳이 아니야. 여기서 나가자.","e":"'(우리) ~하자'라는 nosotros 긍정명령에 재귀대명사 nos를 붙이면 끝의 -s가 빠집니다: vamos + nos → vámonos. 강세 위치를 유지하기 위해 악센트(á)가 필요합니다. irse(떠나다)의 '가자!'는 ¡Vámonos!입니다.","x":["Vamos: 재귀대명사가 없어 '가자'는 되지만 '여기서 떠나자'라는 irse의 뜻이 약하고 de aquí와 어울리지 않습니다 ✗","Vayamos: 접속법형 '가자'는 가능하지만 irse의 nos가 빠져 있습니다 ✗","Vamonos: 형태는 맞지만 악센트가 빠져 철자가 틀립니다 ✗","Vámonos: vamos + nos, -s 탈락 + 악센트 → 정답 ✓"]},{"id":"G524","q":"Estoy dispuesta a hacer ____ sea para que te sientas mejor.","o":["el que","la que","que","lo que"],"a":3,"k":"lo que sea","t":"네 기분이 나아질 수만 있다면 무엇이든 할 각오가 되어 있어.","e":"lo que sea는 '무엇이든'이라는 표현입니다. 중성 관계사 lo que(~것)는 막연한 대상을 가리키고, sea(ser의 접속법)는 정해지지 않은 무엇이라는 뜻을 더합니다. 예: Come lo que sea.(아무거나 먹어.) estar dispuesto/a a + 동사원형은 '~할 각오가 되다'입니다.","x":["el que: 남성 명사를 가리킬 때 쓰며 막연한 '무엇이든'을 나타내지 못합니다 ✗","la que: 여성 명사를 가리킬 때 쓰므로 맞지 않습니다 ✗","que: 선행사가 없어 관계사 que만으로는 '~것'이라는 의미가 안 됩니다 ✗","lo que: lo que sea = 무엇이든 → 정답 ✓"]},{"id":"G525","q":"No ____ me haya olvidado de ti, simplemente he estado muy ocupada este mes.","o":["es que","que","por que","es de que"],"a":0,"k":"no es que + 접속법","t":"너를 잊은 건 아니야, 그냥 이번 달에 너무 바빴어.","e":"no es que + 접속법은 '~라는 건 아니다'라고 상대의 오해를 부정할 때 씁니다. 부정되는 내용이므로 접속법(haya olvidado)이 옵니다. 보통 뒤에 진짜 이유가 이어집니다: simplemente..., sino que...","x":["es que: No es que + 접속법 = ~인 건 아니다 → 정답 ✓","que: No que라는 표현은 쓰지 않습니다 ✗","por que: No por que...는 이 구조로 쓰지 않으며 의미가 성립하지 않습니다 ✗","es de que: que 앞에 불필요한 de를 넣는 오류(dequeísmo, 데케이스모)라 ✗"]},{"id":"G526","q":"Hola, Amelia, ____ te llame tan tarde...","o":["perdón por","perdona si","perdona que","perdón si"],"a":2,"k":"perdona que + 접속법","t":"안녕, 아멜리아, 이렇게 늦게 전화해서 미안해...","e":"perdonar que + 접속법은 '~하는 것을 용서하다', 즉 '~해서 미안해'라는 사과 표현입니다. 감정·평가 동사 뒤의 que절은 접속법을 씁니다. 친구 사이이므로 tú 명령형 perdona를 썼어요(usted라면 perdone). perdón por + 동사원형도 가능합니다: perdón por llamarte tan tarde.","x":["perdón por: por 뒤에는 동사원형이 와야 합니다(perdón por llamarte) ✗","perdona si: si 뒤에는 직설법이 와야 해서 접속법 llame와 맞지 않습니다 ✗","perdona que: perdona que + 접속법 = ~해서 미안해 → 정답 ✓","perdón si: si 뒤 접속법 현재는 쓰지 않습니다 ✗"]},{"id":"G527","q":"Aquel día merendamos ____ el árbol más grande que encontramos.","o":["debajo","bajo","abajo","por debajo"],"a":1,"k":"bajo / debajo de","t":"그날 우리는 찾을 수 있었던 가장 큰 나무 아래에서 간식을 먹었다.","e":"bajo는 그 자체로 전치사라서 바로 명사를 받습니다(bajo el árbol). debajo는 부사라서 명사 앞에 오려면 de가 필요합니다(debajo del árbol). merendar는 스페인에서 '오후 간식(merienda)을 먹다'라는 뜻입니다.","x":["debajo: 부사라 de 없이 명사를 받을 수 없습니다(debajo del) ✗","bajo: 전치사 bajo + 명사 → 정답 ✓","abajo: '아래쪽에'라는 부사로 명사를 받지 못합니다 ✗","por debajo: 'por debajo del'처럼 de가 필요하고 '아래로 지나서'라는 뜻입니다 ✗"]},{"id":"G528","q":"Nos levantamos todos ____ escuchar el ruido.","o":["sobre","al","de","con"],"a":1,"k":"al + 동사원형","t":"우리는 그 소리를 듣자 모두 일어났다.","e":"al + 동사원형은 '~하자, ~할 때'라는 뜻으로, 동시 또는 바로 직전의 계기를 나타냅니다. 소리를 듣고 일어났다는 시간·원인 관계를 잘 나타내 줍니다. 예: Al abrir la puerta, vi a mi hermano.(문을 열자 동생이 보였다.)","x":["sobre: '~위에/~에 관해'라는 뜻이라 동사원형과 시간 관계를 나타내지 못합니다 ✗","al: al + 동사원형 = ~하자 → 정답 ✓","de: de + 동사원형은 조건(만약 ~라면)을 나타낼 수 있지만 여기선 맞지 않습니다 ✗","con: con + 동사원형은 '~하는 것만으로'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G529","q":"El libro es mío. No ____ lleves.","o":["te lo","se lo","te le","nos lo"],"a":0,"k":"llevarse 대명사 순서","t":"그 책은 내 거야. 가져가지 마.","e":"llevarse(가져가 버리다)의 재귀대명사 te와 직접목적격 lo(그 책)가 함께 오면 'te + lo' 순서입니다. 부정명령이므로 동사 앞에 둡니다: No te lo lleves. 긍정명령이면 뒤에 붙습니다: Llévatelo.","x":["te lo: 재귀 te + 직접목적 lo → 정답 ✓","se lo: '그/당신에게 그것을'이 되어 tú에게 하는 부정명령과 맞지 않습니다 ✗","te le: 사물(el libro)을 가리키는 직접목적격은 lo입니다(le는 간접목적격) ✗","nos lo: '우리에게 그것을'이 되어 주어 tú의 재귀형과 맞지 않습니다 ✗"]},{"id":"G530","q":"¿Adónde fuisteis ____ la conferencia?","o":["luego","a continuación","tras","después"],"a":2,"k":"전치사 tras","t":"강연이 끝난 뒤에 너희는 어디에 갔어?","e":"tras는 '~ 후에'라는 뜻의 전치사로, 바로 명사를 받습니다(tras la conferencia). después는 명사 앞에 de가 필요해서 después de la conferencia라고 해야 합니다. tras는 조금 문어적·격식 있는 느낌입니다.","x":["luego: 부사라 명사를 바로 받을 수 없습니다(luego de는 중남미에서 사용) ✗","a continuación: '이어서'라는 부사구로 명사를 받으려면 de가 필요합니다 ✗","tras: 전치사 tras + 명사 = ~ 후에 → 정답 ✓","después: 명사 앞에는 de가 필요합니다(después de) ✗"]},{"id":"G531","q":"¿Te ____ el vestido de novia que llevaba Ana?","o":["gustó","gustas","había gustado","gustará"],"a":0,"k":"gustar 단순과거","t":"아나가 입었던 웨딩드레스 마음에 들었어?","e":"gustar는 '마음에 드는 대상'이 주어이므로 el vestido(단수)에 맞춰 3인칭 단수 gustó가 됩니다. 결혼식이라는 과거의 한 사건에서 본 드레스에 대한 반응이므로 단순과거를 씁니다. te는 '너에게'입니다.","x":["gustó: 주어 el vestido(단수) + 과거의 한 사건 → 정답 ✓","gustas: '네가 (누군가의) 마음에 든다'는 뜻이 되어 주어가 틀립니다 ✗","había gustado: 대과거는 다른 과거 시점보다 앞선 일을 말할 때 써서 여기선 어색합니다 ✗","gustará: 미래형이라 이미 입었던(llevaba) 드레스와 시제가 맞지 않습니다 ✗"]},{"id":"G532","q":"No recuerdo ____ he dejado las llaves del coche.","o":["adonde","adónde","dónde","donde"],"a":2,"k":"간접의문 dónde","t":"차 열쇠를 어디에 두었는지 기억이 안 나.","e":"no recuerdo, no sé 같은 동사 뒤에서 '어디에 ~했는지'라는 간접의문문을 만들 때도 의문사에 악센트를 씁니다(dónde). dejar(두다)는 정지된 위치를 나타내므로 dónde입니다. adónde는 이동 방향(어디로)에 씁니다.","x":["adonde: 악센트 없는 관계부사(~로 가는 곳)이며 이동을 나타내 맞지 않습니다 ✗","adónde: '어디로'라는 방향 의문사라 dejar(두다)와 맞지 않습니다 ✗","dónde: 간접의문의 '어디에' → 정답 ✓","donde: 악센트 없는 donde는 관계부사라 간접의문문에 쓰지 않습니다 ✗"]},{"id":"G533","q":"Estamos todos, así que ____ podemos empezar a comer.","o":["siempre","aún","todavía","ya"],"a":3,"k":"ya 이제","t":"다 모였으니 이제 먹기 시작해도 돼.","e":"ya는 '이제, 벌써'라는 뜻으로, 어떤 조건이 충족되어 행동을 시작할 수 있게 되었음을 나타냅니다. Estamos todos(다 모였다) → ya podemos empezar(이제 시작할 수 있다)라는 흐름입니다. 예: Ya está.(다 됐어.)","x":["siempre: '항상'이라는 뜻이라 문맥에 맞지 않습니다 ✗","aún: '아직'이라는 뜻이라 '아직 먹을 수 있다'가 되어 어색합니다 ✗","todavía: aún과 같은 '아직'이라 맞지 않습니다 ✗","ya: 조건 충족 후 '이제' → 정답 ✓"]},{"id":"G534","q":"____ tarde, por eso perdieron el vuelo.","o":["Salen","Salían","Saldrán","Salieron"],"a":3,"k":"단순과거","t":"그들은 늦게 출발해서 비행기를 놓쳤다.","e":"늦게 출발한 것과 비행기를 놓친 것(perdieron)은 과거에 한 번 일어난 연속 사건입니다. 이런 완료된 사건은 단순과거로 씁니다. 결과를 나타내는 por eso(그래서)도 사건의 순서를 보여 줍니다.","x":["Salen: 현재형이라 과거 사건 perdieron과 시제가 맞지 않습니다 ✗","Salían: 불완료과거는 반복·배경을 나타내 '늦게 나가곤 했다'가 되어 어색합니다 ✗","Saldrán: 미래형이라 시제가 맞지 않습니다 ✗","Salieron: 완료된 과거 사건 → 정답 ✓"]},{"id":"G535","q":"____ tome esta medicación, no le aconsejo el consumo de alcohol.","o":["Durante","Si","Entretanto","Mientras"],"a":3,"k":"mientras + 접속법","t":"이 약을 복용하시는 동안에는 음주를 권하지 않습니다.","e":"mientras는 '~하는 동안'이라는 접속사입니다. 앞으로 일어날 기간을 가리키면 접속법(tome)을 쓰고, 현재·과거의 사실이면 직설법을 씁니다. 의사가 usted로 말하는 격식체 문장입니다.","x":["Durante: 전치사라 뒤에 명사가 와야 합니다(durante el tratamiento) ✗","Si: si 뒤에는 접속법 현재를 쓰지 않습니다(si toma) ✗","Entretanto: '그 사이에'라는 부사라 절을 이끌지 못합니다 ✗","Mientras: 미래 기간 mientras + 접속법 → 정답 ✓"]},{"id":"G536","q":"Me pregunto por qué no han llegado. ¿Les ____ algo?","o":["habría pasado","habrá pasado","haya pasado","ha pasado"],"a":1,"k":"미래완료 추측","t":"왜 안 왔는지 궁금하네. 그들에게 무슨 일이 생긴 걸까?","e":"미래완료(habrá + 과거분사)는 '(이미) ~했을 것이다'라는 현재 시점에서 본 과거 일에 대한 추측을 나타냅니다. 지금 오지 않은 이유를 걱정하며 추측하는 상황에 딱 맞습니다. 예: Habrá perdido el autobús.(버스를 놓쳤나 봐.)","x":["habría pasado: 조건완료는 '그랬을 텐데(과거 가정)'나 더 이전 과거 추측에 써서 ✗","habrá pasado: 지금까지 일어났을 일에 대한 추측 → 정답 ✓","haya pasado: 접속법이라 주절 의문문에 단독으로 쓰지 않습니다 ✗","ha pasado: 문법적으로 가능하지만 직접 묻는 말이라 추측(혼잣말)의 뉘앙스가 없습니다 ✗"]},{"id":"G537","q":"No comprendo que ____ tanta gente dispuesta a ir a ese concurso.","o":["haya","hay","habrá","hubo"],"a":0,"k":"감정·평가 + 접속법","t":"그렇게 많은 사람이 그 대회에 나가려고 한다는 게 이해가 안 돼.","e":"no comprendo que, me sorprende que처럼 어떤 사실에 대한 감정·평가를 나타내는 동사 뒤에는 접속법을 씁니다. haber의 접속법 현재는 haya입니다. 반면 no comprendo por qué...(왜 ~인지 모르겠다)는 간접의문이라 직설법을 씁니다.","x":["haya: 평가 동사 뒤 접속법 현재 → 정답 ✓","hay: 직설법이라 no comprendo que 뒤에 맞지 않습니다 ✗","habrá: 미래형이라 법과 시제 모두 맞지 않습니다 ✗","hubo: 직설법 단순과거라 맞지 않습니다 ✗"]},{"id":"G538","q":"Eugenio y Bea ____ de ser papás.","o":["vienen","terminan","dejan","acaban"],"a":3,"k":"acabar de","t":"에우헤니오와 베아가 막 부모가 되었다.","e":"acabar de + 동사원형은 '막 ~했다'라는 아주 가까운 과거를 나타냅니다. 예: Acabo de llegar.(방금 도착했어.) 스페인어에서 '엄마·아빠가 되다'는 ser papás라고 합니다.","x":["vienen: venir de + 동사원형은 '~하고 오다'라는 장소 이동의 뜻이라 ✗","terminan: terminar de + 동사원형은 '~하기를 끝내다'라는 뜻이라 어색합니다 ✗","dejan: dejar de + 동사원형은 '~을 그만두다'라 의미가 반대입니다 ✗","acaban: acabar de = 막 ~했다 → 정답 ✓"]},{"id":"G539","q":"____ haciendo deporte cada día consigue adelgazar.","o":["Aunque","Pese a","Si bien","Ni siquiera"],"a":3,"k":"ni siquiera","t":"매일 운동을 하는데도 살이 빠지지 않는다.","e":"ni siquiera는 '~조차도 (않다)'라는 강한 부정 강조 표현입니다. 문장 맨 앞에 오면 동사 앞에 no를 따로 쓰지 않아도 전체가 부정문이 됩니다. 매일 운동하는 것으로'조차' 살이 빠지지 않는다는 뜻입니다. 예: Ni siquiera me saludó.(그는 인사조차 안 했다.)","x":["Aunque: 'Aunque hace deporte...'처럼 활용 동사가 필요하고, 뒤에 no가 없어 '살이 빠진다'는 긍정이 됩니다 ✗","Pese a: 'pese a hacer deporte'처럼 동사원형이 와야 하고 역시 부정이 빠집니다 ✗","Si bien: '비록 ~이지만'이라는 문어 표현으로 활용 동사가 필요합니다 ✗","Ni siquiera: '~조차 ~않다', 문장 전체를 부정 → 정답 ✓"]},{"id":"G540","q":"¡____ barba que tienes! ¿Cuánto hace que no te afeitas?","o":["Para","Cómo","Una","Vaya"],"a":3,"k":"감탄 vaya","t":"수염 엄청 길었네! 면도 안 한 지 얼마나 됐어?","e":"¡Vaya + 명사 + que...!는 '정말 대단한 ~구나!'라는 놀람의 감탄 표현입니다. ¡Qué barba tienes!와 비슷한 뜻이에요. ¿Cuánto hace que no...?는 '~ 안 한 지 얼마나 됐어?'라는 기간 질문입니다.","x":["Para: 감탄 표현에 쓰지 않습니다 ✗","Cómo: ¡Cómo...!는 동사를 강조하며 명사 앞에 쓰지 않습니다 ✗","Una: '¡Una barba que tienes!'는 성립하지 않는 감탄문입니다 ✗","Vaya: ¡Vaya + 명사! 놀람의 감탄 → 정답 ✓"]},{"id":"G541","q":"No tengo ninguna intención de ____ daño.","o":["que te haga","hacerte","que te hiciera","haberte hecho"],"a":1,"k":"동일주어 부정사","t":"나는 너를 해칠 생각이 전혀 없어.","e":"intención de(~할 의도) 뒤의 행동 주체가 주절 주어(yo)와 같으면 que절이 아니라 동사원형을 씁니다. hacer daño a alguien은 '~를 다치게 하다, 상처 주다'이고, 목적격 te를 동사원형 뒤에 붙여 hacerte가 됩니다.","x":["que te haga: 주어가 같은데 que + 접속법을 써서 '내가 너에게 하도록'이라는 어색한 문장이 됩니다 ✗","hacerte: 동일 주어 + 동사원형 → 정답 ✓","que te hiciera: 주어 문제에 더해 과거형이라 현재 문장 tengo와도 맞지 않습니다 ✗","haberte hecho: 완료형 부정사는 '이미 해친 것'이라 의도를 말하는 문장에 맞지 않습니다 ✗"]},{"id":"G542","q":"Yo solo necesito ____ básico para vivir decentemente.","o":["lo","el","del","al"],"a":0,"k":"중성 lo + 형용사","t":"나는 품위 있게 살기 위해 기본적인 것만 있으면 돼.","e":"lo + 형용사(남성 단수형)는 '~한 것, ~한 부분'이라는 추상 명사를 만듭니다. lo básico(기본적인 것), lo importante(중요한 것), lo bueno(좋은 점)처럼요. 특정 명사를 가리키지 않는 막연한 대상이라 중성 lo를 씁니다.","x":["lo: 중성 lo + 형용사 = ~한 것 → 정답 ✓","el: 남성 정관사는 뒤에 생략된 특정 명사가 있어야 해서 여기선 어색합니다 ✗","del: 전치사 de가 들어갈 이유가 없습니다 ✗","al: 전치사 a가 들어갈 이유가 없습니다 ✗"]},{"id":"G543","q":"Lo siento, mientras no cobre, no puedo salir. Estoy ____ blanca.","o":["de","a","en","sin"],"a":3,"k":"estar sin blanca","t":"미안, 월급 받기 전까지는 못 나가. 빈털터리거든.","e":"estar sin blanca는 스페인 구어로 '돈이 한 푼도 없다'라는 관용 표현입니다. blanca는 옛날 스페인의 아주 작은 동전 이름에서 왔어요. 비슷한 표현: estar a dos velas, no tener un duro. 중남미에서는 estar pelado, no tener plata 등을 씁니다. cobrar는 '월급·대금을 받다'입니다.","x":["de: estar de blanca라는 표현은 없습니다 ✗","a: estar a blanca는 쓰지 않습니다(estar a dos velas와 혼동) ✗","en: estar en blanco는 '머리가 하얘지다'라는 다른 표현입니다 ✗","sin: estar sin blanca = 빈털터리다 → 정답 ✓"]},{"id":"G544","q":"No aguanto a la gente que ____ a los demás para divertirse.","o":["molesta","se está molestando","se molesta","moleste"],"a":0,"k":"관계절 직설법","t":"나는 재미 삼아 남들을 괴롭히는 사람들을 참을 수가 없다.","e":"관계절의 선행사가 실제로 존재하는 부류의 사람(la gente que...)을 가리키면 직설법을 씁니다. molestar a alguien은 '~를 귀찮게 하다, 괴롭히다'라는 타동사라 재귀형이 아닙니다. aguantar는 '참다, 견디다'입니다.","x":["molesta: 실재하는 사람들을 설명하는 직설법, 타동사 → 정답 ✓","se está molestando: 재귀형이라 '스스로 기분 상해 하다'가 되고 진행형도 어색합니다 ✗","se molesta: molestarse는 '기분이 상하다/수고하다'라는 뜻이라 a los demás와 맞지 않습니다 ✗","moleste: 접속법은 존재 여부가 불확실한 선행사에 써서 일반적 사실 묘사엔 덜 맞습니다 ✗"]},{"id":"G545","q":"Pronto tendrás tu regalo, ____ paciente.","o":["eres","sed","sé","sea"],"a":2,"k":"ser tú 명령형","t":"곧 선물 받을 거야, 조금만 참아.","e":"ser의 tú 긍정명령은 불규칙형 sé입니다(악센트 필수: se와 구별). 앞 문장에서 tendrás(너는 ~할 것이다)로 tú에게 말하고 있으므로 sé paciente(참을성 있게 굴어)가 됩니다. 다른 불규칙 tú 명령: ten, ven, pon, di, haz, ve, sal.","x":["eres: 직설법 현재라 '너는 참을성이 있다'는 서술이 되어 명령이 아닙니다 ✗","sed: vosotros 명령형이라 tú에게 하는 말과 맞지 않습니다 ✗","sé: ser의 tú 긍정명령 → 정답 ✓","sea: usted 명령형이라 tendrás(tú)와 맞지 않습니다 ✗"]},{"id":"G546","q":"No ____ conmigo, yo no soy uno de tus amigos de la escuela.","o":["equivoques","te equivoques","te hayas equivocado","equivocas"],"a":1,"k":"equivocarse con","t":"나를 잘못 보지 마, 난 네 학교 친구들 중 하나가 아니야.","e":"equivocarse con alguien은 '~를 잘못 판단하다, ~에게 함부로 굴다'라는 뜻입니다. 재귀동사라 te가 필요하고, 부정명령이므로 접속법 te equivoques를 씁니다. No te equivoques conmigo는 '날 만만히 보지 마'라는 경고 뉘앙스로도 쓰입니다.","x":["equivoques: 재귀대명사 te가 빠졌습니다 ✗","te equivoques: 재귀 + tú 부정명령(접속법) → 정답 ✓","te hayas equivocado: 접속법 현재완료는 부정명령으로 쓰지 않습니다 ✗","equivocas: 직설법이고 재귀대명사도 빠져 틀립니다 ✗"]},{"id":"G547","q":"Daniel y Juan siempre ____ bien.","o":["habían llevado","se han llevado","han llevado","se llevasen"],"a":1,"k":"llevarse bien","t":"다니엘과 후안은 항상 사이가 좋았다.","e":"llevarse bien/mal (con alguien)은 '~와 사이가 좋다/나쁘다'라는 표현으로 반드시 재귀형입니다. siempre와 함께 지금까지 계속된 관계를 말하므로 현재완료 se han llevado가 자연스럽습니다(스페인식). 중남미에서는 siempre se llevaron bien이라고도 합니다.","x":["habían llevado: 재귀대명사가 없어 '가져갔었다'라는 뜻이 됩니다 ✗","se han llevado: llevarse bien + 지금까지의 경험 → 정답 ✓","han llevado: 재귀대명사가 없어 '사이가 좋다'의 뜻이 되지 않습니다 ✗","se llevasen: 접속법 과거라 주절의 사실 진술에 쓰지 않습니다 ✗"]},{"id":"G548","q":"¡Qué listo ____! Lo pillas todo al vuelo.","o":["estás","seas","eres","que estás"],"a":2,"k":"ser listo","t":"너 정말 똑똑하구나! 모든 걸 단번에 알아듣네.","e":"listo는 ser와 쓰면 '똑똑하다(성격·자질)', estar와 쓰면 '준비가 되다'로 뜻이 바뀝니다. 뒤 문장의 Lo pillas todo al vuelo(뭐든 즉시 알아챈다)가 자질을 말하므로 ser입니다. pillar al vuelo는 스페인 구어로 '바로 알아듣다'라는 뜻입니다.","x":["estás: estar listo는 '준비됐다'라는 뜻이라 문맥에 맞지 않습니다 ✗","seas: 접속법이라 감탄문 주절에 쓰지 않습니다 ✗","eres: ser listo = 똑똑하다 → 정답 ✓","que estás: '¡Qué listo que estás!'는 준비됐다는 뜻이고 문맥에 맞지 않습니다 ✗"]},{"id":"G549","q":"Mi doctora me ha dicho que, ____ sucesivo, tengo que cuidarme más.","o":["a lo","de lo","desde lo","en lo"],"a":3,"k":"en lo sucesivo","t":"담당 의사가 앞으로는 몸을 더 잘 돌봐야 한다고 했다.","e":"en lo sucesivo는 '앞으로, 이후로는'이라는 격식 있는 고정 표현입니다. 일상적으로는 a partir de ahora, de ahora en adelante와 같은 뜻입니다. cuidarse는 '건강을 챙기다, 몸조심하다'입니다.","x":["a lo: a lo sucesivo는 쓰지 않습니다 ✗","de lo: de lo sucesivo는 쓰지 않습니다 ✗","desde lo: desde lo sucesivo도 쓰지 않는 표현입니다 ✗","en lo: en lo sucesivo = 앞으로는 → 정답 ✓"]},{"id":"G550","q":"Dígame ____ acabó tomando esa decisión.","o":["porqué","porque","por que","por qué"],"a":3,"k":"간접의문 por qué","t":"왜 결국 그런 결정을 내리셨는지 말씀해 주세요.","e":"직접·간접 의문문에서 '왜'는 두 단어 + 악센트인 por qué를 씁니다. Dígame(말씀해 주세요) 뒤에 이유를 묻는 간접의문이 이어지므로 por qué입니다. acabar + 현재분사는 '결국 ~하게 되다'라는 뜻입니다.","x":["porqué: 한 단어 porqué는 '이유'라는 명사(el porqué)라 ✗","porque: '왜냐하면'이라는 이유 접속사라 의문문에 쓰지 않습니다 ✗","por que: 전치사 por + 관계사 que로 '~하는(이유)'라는 뜻이라 의문이 아닙니다 ✗","por qué: 간접의문 '왜' → 정답 ✓"]},{"id":"G551","q":"Me dijo que ____ que irse.","o":["ha tenido","tenía","tuviera","tenga"],"a":1,"k":"간접화법 시제","t":"그는 가야 한다고 내게 말했다.","e":"과거의 간접화법(Me dijo que...)에서 원래 말의 현재형(Tengo que irme)은 불완료과거(tenía)로 바뀝니다. 이것은 명령 전달이 아니라 사실 전달이므로 직설법입니다. tener que + 동사원형은 '~해야 한다'입니다.","x":["ha tenido: 현재완료는 과거 주절 dijo와 시제가 맞지 않습니다 ✗","tenía: 원래 말의 현재 → 과거 간접화법의 불완료과거 → 정답 ✓","tuviera: 접속법은 명령 전달에 쓰므로 사실 전달에는 ✗","tenga: 접속법 현재라 시제와 법이 모두 맞지 않습니다 ✗"]},{"id":"G552","q":"Rocío ____ perpleja cuando le dijeron que le había tocado el primer premio.","o":["había quedado","quedó","se quedó","se quedaba"],"a":2,"k":"quedarse + 형용사","t":"로시오는 1등에 당첨됐다는 말을 듣고 어리둥절해졌다.","e":"quedarse + 형용사는 갑작스러운 상태 변화(~하게 되다)를 나타냅니다. quedarse perpleja는 '어안이 벙벙해지다'라는 뜻입니다. 소식을 들은 한 순간의 반응이므로 단순과거 se quedó입니다. tocar el premio는 '상에 당첨되다'입니다.","x":["había quedado: 재귀대명사가 없고, 대과거라 cuando절과 시간 순서가 맞지 않습니다 ✗","quedó: 재귀대명사 se가 빠져 '상태가 되다'의 뜻이 약하고 비표준입니다 ✗","se quedó: quedarse + 형용사, 일회적 반응의 단순과거 → 정답 ✓","se quedaba: 불완료과거는 반복·배경을 나타내 한 번의 반응에 맞지 않습니다 ✗"]},{"id":"G553","q":"En esta oficina hay ____ irresponsable, los jefes deberían saberlo.","o":["mucho","harto","un montón","muy"],"a":0,"k":"mucho + 단수명사","t":"이 사무실엔 무책임한 사람이 많아, 상사들이 알아야 할 텐데.","e":"구어에서 mucho + 단수 명사(형용사의 명사화)로 '그런 부류의 사람이 많다'라는 뜻을 나타냅니다. 예: Hay mucho listillo por aquí.(여기 잘난 척하는 사람 많아.) 의미는 hay muchos irresponsables와 같으며 약간 비꼬는 느낌이 있습니다.","x":["mucho: 구어적 mucho + 단수 명사화된 형용사 = 그런 사람이 많다 → 정답 ✓","harto: 일부 중남미 지역에서 '많은'이라는 뜻으로 쓰지만 표준어에서는 '질린'이라는 뜻이라 ✗","un montón: 'un montón de irresponsables'처럼 de와 복수 명사가 필요합니다 ✗","muy: 부사라 명사를 꾸밀 수 없고 hay 뒤에 쓰지 못합니다 ✗"]},{"id":"G554","q":"No debiste ____ dejar al perro suelto.","o":["al","a","de","ø"],"a":3,"k":"deber + 부정사","t":"개를 풀어 놓지 말았어야 했어.","e":"의무를 나타내는 deber는 전치사 없이 바로 동사원형이 옵니다. No debiste dejar...는 '~하지 말았어야 했다'라는 과거의 잘못에 대한 비판입니다. 같은 뜻으로 No deberías haber dejado...라고도 합니다.","x":["al: 'deber al + 동사원형' 구조는 없습니다 ✗","a: deber a는 '~에게 빚지다'라는 뜻이라 맞지 않습니다 ✗","de: deber de는 추측(아마 ~일 것)이라 의무·비판의 뜻과 맞지 않습니다 ✗","ø: 의무의 deber + 동사원형 → 정답 ✓"]},{"id":"G555","q":"____ tenía frío, puse la calefacción.","o":["Como","A pesar de que","Pues","Aunque"],"a":0,"k":"이유 como","t":"추웠기 때문에 난방을 틀었다.","e":"como가 문장 맨 앞에 오면 이유(~해서)를 나타내며 직설법을 씁니다. 추웠다(원인) → 난방을 틀었다(결과)라는 흐름입니다. poner la calefacción은 '난방을 켜다'라는 표현입니다.","x":["Como: 문장 앞 이유절 → 정답 ✓","A pesar de que: '~에도 불구하고'라는 양보라 원인-결과 관계와 맞지 않습니다 ✗","Pues: 이유의 pues는 보통 문장 뒤에 오며 맨 앞에 쓰면 어색합니다 ✗","Aunque: '~이지만'이라는 양보라 논리가 맞지 않습니다 ✗"]},{"id":"G556","q":"Me hice un esguince ____ las escaleras.","o":["con bajar","para","al bajar","hasta bajar"],"a":2,"k":"al + 동사원형","t":"계단을 내려가다가 발목을 삐었다.","e":"al + 동사원형은 '~할 때'라는 시간·계기를 나타냅니다. 계단을 내려가던 순간에 사고가 났음을 표현합니다. hacerse un esguince는 '삐다, 염좌가 생기다'입니다. bajando las escaleras라고 해도 됩니다.","x":["con bajar: '내려가는 것만으로'라는 뜻이 되어 의미가 맞지 않습니다 ✗","para: '~를 위해'라는 목적이라 뒤의 las escaleras와 의미가 맞지 않습니다 ✗","al bajar: '내려갈 때' → 정답 ✓","hasta bajar: '내려갈 때까지'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G557","q":"Nuestro perro nunca ____ a nadie.","o":["morderían","ha mordido","muerda","mordiera"],"a":1,"k":"현재완료 경험","t":"우리 개는 한 번도 누구를 문 적이 없다.","e":"nunca와 함께 지금까지의 경험(~한 적이 없다)을 말할 때는 현재완료를 씁니다. 주어 nuestro perro는 3인칭 단수라 ha mordido입니다. morder(물다)는 o→ue 불규칙 동사입니다. 사람 목적어 nadie 앞에 a가 붙은 점도 보세요.","x":["morderían: 3인칭 복수 조건형이라 주어와도 시제와도 맞지 않습니다 ✗","ha mordido: 지금까지의 경험을 나타내는 현재완료 → 정답 ✓","muerda: 접속법이라 주절 사실 진술에 쓰지 않습니다 ✗","mordiera: 접속법 과거라 주절에 단독으로 쓰지 않습니다 ✗"]},{"id":"G558","q":"¡Quién ____ irse ahora mismo de vacaciones!","o":["puede","pudiera","pudo","pueda"],"a":1,"k":"¡Quién + 접속법과거!","t":"나도 당장 휴가를 떠날 수 있다면 얼마나 좋을까!","e":"¡Quién + 접속법 과거!는 '(내가) ~할 수 있다면 좋겠다!'라는 이루기 어려운 바람을 나타내는 관용 감탄문입니다. 예: ¡Quién tuviera tu edad!(네 나이였으면 좋겠다!) 실제로는 그럴 수 없다는 아쉬움이 담겨 있습니다.","x":["puede: 직설법이면 '누가 갈 수 있지?'라는 의문이 되어 바람을 나타내지 못합니다 ✗","pudiera: ¡Quién + 접속법 과거! = 이룰 수 없는 바람 → 정답 ✓","pudo: 단순과거라 '누가 갈 수 있었지?'가 되어 맞지 않습니다 ✗","pueda: 이 관용 감탄문에서는 접속법 과거만 씁니다 ✗"]},{"id":"G559","q":"Si ____ aire acondicionado, no pasaríamos calor.","o":["tendríamos","tuviéramos","teníamos","tengamos"],"a":1,"k":"가정문 si","t":"에어컨이 있으면 우리가 더위에 고생하지 않을 텐데.","e":"현재 사실과 반대되는 가정(지금 에어컨이 없다)은 'si + 접속법 과거, 조건형' 구조입니다. 뒤 절이 pasaríamos(조건형)이므로 si절은 tuviéramos입니다. si 뒤에는 조건형이나 접속법 현재를 쓰지 않습니다.","x":["tendríamos: 조건형은 si절에 쓰지 않습니다 ✗","tuviéramos: si + 접속법 과거 + 조건형 → 정답 ✓","teníamos: 직설법 과거면 '(당시) 있었다면'이라는 사실 조건이 되어 조건형 주절과 맞지 않습니다 ✗","tengamos: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗"]},{"id":"G560","q":"No pienso hacer lo que tú ____.","o":["dirías","digas","dirás","dijeras"],"a":1,"k":"관계절 접속법","t":"네가 뭐라고 하든 난 그렇게 할 생각 없어.","e":"lo que + 접속법은 '아직 정해지지 않은/알 수 없는 ~것'을 가리킵니다. lo que tú digas는 '네가 (앞으로) 무슨 말을 하든'이라는 뜻입니다. 직설법 lo que dices는 '네가 지금 말하는 것(구체적 내용)'입니다. no pienso + 동사원형은 '~할 생각이 없다'라는 단호한 표현입니다.","x":["dirías: 조건형은 이 관계절의 미정 대상을 나타내지 않습니다 ✗","digas: 정해지지 않은 대상 lo que + 접속법 → 정답 ✓","dirás: 미래형은 관계절의 불확정한 미래를 나타낼 때 쓰지 않습니다 ✗","dijeras: 접속법 과거라 현재 주절 pienso와 시제가 맞지 않습니다 ✗"]},{"id":"G561","q":"¿Cuántas veces ____ decirte que no me apetece salir hoy?","o":["llego a","estoy por","tengo que","termino por"],"a":2,"k":"tener que","t":"오늘 나가고 싶지 않다고 몇 번을 말해야 해?","e":"¿Cuántas veces tengo que decirte...?는 '몇 번을 말해야 알아듣겠니?'라는 짜증 섞인 반문입니다. tener que + 동사원형은 '~해야 한다'라는 의무를 나타냅니다. no me apetece는 스페인에서 '~하고 싶지 않다, 당기지 않는다'라는 표현입니다.","x":["llego a: llegar a + 동사원형은 '결국 ~하기에 이르다'라는 뜻이라 맞지 않습니다 ✗","estoy por: estar por + 동사원형은 '~할까 말까 하다'라는 뜻이라 ✗","tengo que: '몇 번을 말해야 하니' → 정답 ✓","termino por: terminar por + 동사원형은 '결국 ~하게 되다'라 맞지 않습니다 ✗"]},{"id":"G562","q":"Si nos dieran a elegir, el evento ____ al aire libre.","o":["será","sería","estaría","estaba"],"a":1,"k":"가정문 조건형","t":"만약 우리에게 선택권을 준다면, 행사는 야외에서 열릴 텐데.","e":"si + 접속법 과거(dieran)로 현재·미래에 대한 가정을 하면, 결과는 조건형으로 씁니다. 행사가 '열리다, 개최되다'는 ser로 표현합니다(El evento es en el parque. 행사는 공원에서 열린다). 그래서 sería입니다.","x":["será: 미래형은 si + 접속법 과거 가정문의 결과절에 맞지 않습니다 ✗","sería: 가정문 결과절 + 행사 개최 장소의 ser → 정답 ✓","estaría: 행사(사건)가 열리는 장소에는 estar가 아닌 ser를 씁니다 ✗","estaba: 직설법 과거이고 estar라 이중으로 틀립니다 ✗"]},{"id":"G563","q":"No ____ mentirosa, que te va a crecer la nariz.","o":["eres","estés","seas","estás"],"a":2,"k":"ser 부정명령","t":"거짓말쟁이가 되지 마, 코가 길어진다.","e":"tú 부정명령은 접속법 현재로 만듭니다: no seas. mentiroso/a(거짓말쟁이)는 성격·특징이므로 ser를 씁니다. 피노키오처럼 '코가 길어진다'는 아이에게 하는 농담 섞인 경고입니다. que는 회화에서 '왜냐하면'의 뜻입니다.","x":["eres: 직설법이라 부정명령이 아닌 '넌 거짓말쟁이가 아니다'라는 서술이 됩니다 ✗","estés: 접속법은 맞지만 성격·특징에는 estar가 아니라 ser를 씁니다 ✗","seas: ser의 tú 부정명령 → 정답 ✓","estás: 직설법이고 estar라 이중으로 틀립니다 ✗"]},{"id":"G564","q":"Es cierto que ____ talento, pero no lo aprovecha.","o":["tiene","ha tenido","está teniendo","tenga"],"a":0,"k":"es cierto que 직설법","t":"그가 재능이 있는 건 사실이지만 그것을 활용하지 않는다.","e":"es cierto que, es verdad que, es evidente que처럼 사실임을 확인하는 표현 뒤에는 직설법을 씁니다(부정이면 접속법: No es cierto que tenga talento). 지금의 상태를 말하므로 현재형 tiene입니다.","x":["tiene: 사실 확인 표현 + 직설법 현재 → 정답 ✓","ha tenido: 현재완료는 '(지금까지) 가져 왔다'가 되어 현재의 자질 묘사엔 어색합니다 ✗","está teniendo: tener는 상태 동사라 진행형으로 잘 쓰지 않습니다 ✗","tenga: 접속법은 부정형 no es cierto que 뒤에 씁니다 ✗"]},{"id":"G565","q":"Mi tía es aquella mujer vestida ____ rojo.","o":["de","por","con","a"],"a":0,"k":"vestido de","t":"우리 이모는 빨간 옷을 입은 저 여자야.","e":"vestido/a de + 색깔/옷 종류는 '~색 옷을 입은, ~ 차림의'라는 뜻입니다. 예: ir vestido de negro(검은 옷을 입다), disfrazado de pirata(해적 분장을 한). 색깔 앞에 관사를 쓰지 않습니다.","x":["de: vestida de rojo = 빨간 옷을 입은 → 정답 ✓","por: vestida por는 '~에 의해 옷 입혀진'이라는 수동 의미라 ✗","con: con은 'vestida con un traje rojo'처럼 구체적 옷 명사와 쓸 때만 가능합니다 ✗","a: vestida a는 이 표현에 쓰지 않습니다 ✗"]},{"id":"G566","q":"____ lo cansada que estaba, fue a recoger a sus parientes a la estación.","o":["Aunque","Pese a","A pesar de que","Aun"],"a":1,"k":"pese a","t":"그녀는 그토록 피곤했는데도 역에 친척들을 마중 나갔다.","e":"pese a(~에도 불구하고)는 전치사구라 뒤에 명사·명사구가 옵니다. lo cansada que estaba는 '그녀가 얼마나 피곤했는지'라는 명사구(lo + 형용사 + que)입니다. 절(활용 동사)이 올 경우엔 pese a que / a pesar de que를 씁니다.","x":["Aunque: 접속사라 활용 동사로 시작하는 절이 필요합니다(aunque estaba cansada) ✗","Pese a: 전치사구 + 명사구 lo cansada que estaba → 정답 ✓","A pesar de que: 뒤에 절이 와야 하는데 lo...는 명사구라 ✗","Aun: '심지어'라는 부사라 양보 관계를 만들지 못합니다 ✗"]},{"id":"G567","q":"La muerte de su mujer lo sumió ____ una profunda tristeza.","o":["con","de","en","a"],"a":2,"k":"sumir en","t":"아내의 죽음은 그를 깊은 슬픔에 빠뜨렸다.","e":"sumir(빠뜨리다, 잠기게 하다)는 en과 함께 씁니다: sumir a alguien en + 상태. 주로 슬픔·혼란·위기 같은 부정적 상태에 쓰는 문어적 동사입니다. 예: El país se sumió en una crisis.(나라가 위기에 빠졌다.)","x":["con: sumir con은 쓰지 않습니다 ✗","de: sumir de는 쓰지 않습니다 ✗","en: sumir en + 상태 = ~에 빠뜨리다 → 정답 ✓","a: a는 이 동사와 쓰지 않습니다 ✗"]},{"id":"G568","q":"Hoy ____ a reunirnos con los antiguos alumnos.","o":["vamos","vayamos","nos vamos","vámonos"],"a":0,"k":"ir a + 부정사","t":"오늘 우리는 옛 동창들과 만날 거야.","e":"ir a + 동사원형은 '~할 것이다'라는 가까운 미래·계획을 나타냅니다. 주어가 nosotros이므로 vamos a reunirnos입니다. reunirse con은 '~와 모이다, 만나다'입니다. 여기서 ir는 재귀형(irse)이 아닙니다.","x":["vamos: ir a + 동사원형 = ~할 것이다 → 정답 ✓","vayamos: 접속법(또는 '~하러 가자')이라 계획을 말하는 평서문에 맞지 않습니다 ✗","nos vamos: irse는 '떠나다'라는 뜻이라 미래 표현에 재귀형을 쓰지 않습니다 ✗","vámonos: '가자!'라는 명령형이라 맞지 않습니다 ✗"]},{"id":"G569","q":"El alquiler de este piso ____ por 500 euros mensuales.","o":["lleva saliendo","viene a salir","acaba de salir","acaba por salir"],"a":1,"k":"venir a + 부정사","t":"이 아파트 월세는 대략 한 달에 500유로 정도 나온다.","e":"venir a + 동사원형은 '대략 ~에 이르다, 결국 ~인 셈이다'라는 근사치를 나타냅니다. salir por + 금액은 '(비용이) ~이 나오다'라는 회화 표현이에요. 그래서 viene a salir por 500 euros = 대략 500유로쯤 든다가 됩니다.","x":["lleva saliendo: llevar + 현재분사는 '~한 지 (기간)째'라 금액과 맞지 않습니다 ✗","viene a salir: venir a + 동사원형 = 대략 ~이 되다 → 정답 ✓","acaba de salir: '막 나왔다'라는 가까운 과거라 의미가 맞지 않습니다 ✗","acaba por salir: '결국 ~하게 되다'라는 뜻이라 월세 금액 묘사에 어색합니다 ✗"]},{"id":"G570","q":"Marina es muy buena con todo el mundo. Es ____ encanto de mujer.","o":["de un","un","ø","el"],"a":1,"k":"un encanto de","t":"마리나는 모든 사람에게 아주 잘해 줘. 정말 매력적인 여자야.","e":"ser un encanto (de persona)는 '정말 사랑스럽다, 매력적인 사람이다'라는 칭찬 표현입니다. 'un/una + 평가 명사 + de + 명사' 구조로 강조합니다: un desastre de película(엉망인 영화), una maravilla de niño(멋진 아이).","x":["de un: 앞에 de를 붙이는 구조가 아닙니다 ✗","un: un encanto de mujer = 매력적인 여자 → 정답 ✓","ø: 관사 없이 쓰면 이 관용 구조가 성립하지 않습니다 ✗","el: 정관사는 '그 매력'이 되어 칭찬 표현이 되지 않습니다 ✗"]},{"id":"G571","q":"A Jorge no ____ queda dinero para llegar a fin de mes.","o":["ø","les","le","se"],"a":2,"k":"quedar 간접목적","t":"호르헤는 월말까지 버틸 돈이 남아 있지 않다.","e":"quedar가 '남아 있다'라는 뜻일 때는 gustar처럼 '누구에게 남았는지'를 간접목적격 대명사로 씁니다. A Jorge(3인칭 단수)를 받아 le입니다. 앞에 a + 사람이 있어도 대명사 le를 함께 쓰는 것이 정상입니다. llegar a fin de mes는 '월말까지 버티다'라는 관용 표현입니다.","x":["ø: 대명사를 빼면 스페인어로 부자연스러운 문장이 됩니다 ✗","les: 3인칭 복수라 Jorge 한 명과 맞지 않습니다 ✗","le: A Jorge를 받는 간접목적격 단수 → 정답 ✓","se: 'se queda'는 '머물다'라는 뜻이 되어 맞지 않습니다 ✗"]},{"id":"G572","q":"Martín, ____ iba disfrazado de zombi, no fue reconocido ni por su madre.","o":["que","cual","de quien","cuyo"],"a":0,"k":"설명적 관계절 que","t":"좀비 분장을 했던 마르틴은 엄마조차 알아보지 못했다.","e":"쉼표로 둘러싸인 설명적 관계절에서 사람 주어를 가리킬 때는 que나 quien을 씁니다. 여기서는 Martín이 관계절의 주어(iba disfrazado)이므로 que가 맞습니다. 참고로 ni por su madre는 '엄마에 의해서조차'라는 수동태 행위자 표현입니다.","x":["que: 설명적 관계절의 주어 que → 정답 ✓","cual: 관사 없는 cual은 관계대명사로 쓰지 않습니다(el cual이 되어야 함) ✗","de quien: 전치사 de가 필요한 구조가 아닙니다 ✗","cuyo: 소유 관계사라 뒤에 명사가 필요합니다 ✗"]},{"id":"G573","q":"____ la guerra, mis padres vivían en un pueblo de Andalucía.","o":["En cuanto","Conforme","Cuando","Nada más"],"a":2,"k":"cuando + 명사","t":"전쟁 때 우리 부모님은 안달루시아의 한 마을에 살았다.","e":"cuando 뒤에 명사가 바로 오면 '~ 때, ~ 시절에'라는 뜻이 됩니다. 예: cuando niño(어렸을 때), cuando la guerra(전쟁 때). 문어적이며 durante la guerra와 비슷한 의미입니다.","x":["En cuanto: '~하자마자'는 뒤에 동사가 필요하며 명사를 바로 받지 않습니다 ✗","Conforme: '~함에 따라'는 시간의 진행을 나타내 의미가 맞지 않습니다 ✗","Cuando: cuando + 명사 = ~ 때 → 정답 ✓","Nada más: '~하자마자'는 동사원형을 받습니다 ✗"]},{"id":"G574","q":"Cuando me ofrecieron el puesto, no ____ pensé ni un momento.","o":["me lo","te lo","os lo","se lo"],"a":0,"k":"pensárselo","t":"그 자리를 제안받았을 때 나는 단 한순간도 망설이지 않았다.","e":"pensárselo는 '(무엇을 할지) 곰곰이 생각하다, 고민하다'라는 뜻으로 재귀대명사 + lo를 함께 씁니다. 주어가 yo이므로 me lo pensé입니다. no pensárselo dos veces(두 번 생각하지 않다)도 자주 쓰는 표현입니다.","x":["me lo: 주어 yo에 맞는 재귀 me + lo → 정답 ✓","te lo: 주어가 tú일 때의 형태라 맞지 않습니다 ✗","os lo: vosotros일 때의 형태라 맞지 않습니다 ✗","se lo: 3인칭(그/당신)일 때의 형태라 맞지 않습니다 ✗"]},{"id":"G575","q":"Condenamos ____ acto violento.","o":["comoquiera","cualquier","cualquiera","dondequiera"],"a":1,"k":"cualquier","t":"우리는 어떠한 폭력 행위도 규탄한다.","e":"cualquiera가 명사 앞에 오면 -a가 빠져 cualquier가 됩니다(남녀 공통). cualquier acto(어떤 행위든), cualquier persona(누구든). 명사 뒤에 오면 cualquiera를 씁니다: un acto cualquiera(아무 행위나).","x":["comoquiera: '어떤 방식으로든'이라는 부사라 명사를 꾸미지 못합니다 ✗","cualquier: 명사 앞 축약형 '어떤 ~든' → 정답 ✓","cualquiera: 명사 앞에서는 -a가 탈락해야 합니다 ✗","dondequiera: '어디든'이라는 장소 부사라 맞지 않습니다 ✗"]},{"id":"G576","q":"No está triste, está llorando ____ alegría.","o":["de","ante","sobre","por"],"a":0,"k":"원인 de","t":"슬픈 게 아니라 기뻐서 우는 거야.","e":"감정이나 신체 반응의 직접 원인은 de로 나타냅니다: llorar de alegría(기뻐서 울다), morirse de hambre(배고파 죽겠다), temblar de miedo(무서워서 떨다). 짧은 관용구처럼 외워 두면 좋습니다.","x":["de: 감정의 원인 de → 정답 ✓","ante: '~ 앞에서'라는 뜻이라 감정의 원인을 나타내지 못합니다 ✗","sobre: '~에 관해'라는 뜻이라 맞지 않습니다 ✗","por: por도 원인을 나타내지만 감정 반응 관용구(llorar de alegría)에서는 de를 씁니다 ✗"]},{"id":"G577","q":"Teníamos que ____ hace quince minutos, pero aún no veo el aeropuerto.","o":["ser aterrizados","estar aterrizado","habiendo aterrizado","haber aterrizado"],"a":3,"k":"완료 부정사","t":"15분 전에 착륙했어야 했는데 아직 공항이 안 보여.","e":"tener que + haber + 과거분사는 '(그 시점에) ~했어야 했다'라는 완료된 의무·예정을 나타냅니다. hace quince minutos(15분 전) 시점에 이미 끝났어야 할 일이므로 완료 부정사 haber aterrizado를 씁니다. aterrizar(착륙하다)는 자동사라 수동태를 쓰지 않습니다.","x":["ser aterrizados: aterrizar는 자동사라 수동태가 불가능합니다 ✗","estar aterrizado: estar + 과거분사는 결과 상태라 의미가 어색하고 주어(nosotros)와 수도 맞지 않습니다 ✗","habiendo aterrizado: 완료 현재분사는 tener que 뒤에 쓸 수 없습니다 ✗","haber aterrizado: tener que + 완료 부정사 → 정답 ✓"]},{"id":"G578","q":"Para que la pelea no ____ a más, avisaron a la directora del colegio.","o":["llegase","llegue","llegó","llegaba"],"a":0,"k":"para que + 접속법","t":"싸움이 더 커지지 않도록 그들은 교장 선생님께 알렸다.","e":"para que(~하도록) 뒤에는 항상 접속법을 씁니다. 주절이 과거(avisaron)이므로 접속법 과거 llegase(=llegara)가 됩니다. llegar a más는 '(상황이) 더 심해지다, 확대되다'라는 표현입니다.","x":["llegase: 과거 주절 + para que + 접속법 과거 → 정답 ✓","llegue: 접속법 현재라 과거 주절 avisaron과 시제가 맞지 않습니다 ✗","llegó: 직설법은 para que 뒤에 쓸 수 없습니다 ✗","llegaba: 직설법 불완료과거라 맞지 않습니다 ✗"]},{"id":"G579","q":"____ perdido el carné de identidad. Tengo que hacerme uno nuevo.","o":["Me se ha","Se me ha","Lo se ha","Se lo ha"],"a":1,"k":"비의도 se","t":"신분증을 잃어버렸어. 새로 만들어야 해.","e":"'(실수로) ~해 버리다'라는 의도치 않은 사건은 'se + 간접목적격 대명사 + 동사' 구조로 씁니다. 대명사 순서는 항상 se가 먼저: se me ha perdido(나도 모르게 잃어버렸다). 예: Se me olvidó.(깜빡했어.)","x":["Me se ha: 대명사 순서가 틀렸습니다(se가 항상 먼저) ✗","Se me ha: 비의도 se + me → 정답 ✓","Lo se ha: 대명사 순서가 틀리고 피해자(나)가 표시되지 않습니다 ✗","Se lo ha: '그가 그에게서 잃었다'처럼 되어 1인칭 문맥과 맞지 않습니다 ✗"]},{"id":"G580","q":"Tranquilo, mis problemas no tienen nada ____ contigo.","o":["que ven","a ver","de ver","que ver"],"a":3,"k":"tener que ver","t":"걱정 마, 내 문제는 너와는 전혀 상관없어.","e":"tener que ver con은 '~와 관계가 있다'라는 고정 표현입니다. 부정문 no tener nada que ver con은 '~와 전혀 상관없다'입니다. 여기서 tener que는 '~해야 한다'가 아니라 관용구의 일부라는 점에 주의하세요.","x":["que ven: ver를 활용하면 관용 표현이 깨집니다 ✗","a ver: 'a ver'는 '어디 보자'라는 다른 표현입니다 ✗","de ver: tener de ver라는 표현은 없습니다 ✗","que ver: no tener nada que ver con = 전혀 상관없다 → 정답 ✓"]},{"id":"G581","q":"¿____ cuánto tiempo completaste tus estudios universitarios?","o":["En","Desde","A","De"],"a":0,"k":"en + 기간","t":"대학 공부를 마치는 데 얼마나 걸렸어?","e":"en + 기간은 '~ 만에, ~ 걸려서'라는 뜻으로 어떤 일을 완성하는 데 든 시간을 나타냅니다. 예: Lo hice en dos horas.(두 시간 만에 했다.) 그래서 ¿En cuánto tiempo...?는 '얼마 만에 ~했어?'입니다.","x":["En: 완성에 걸린 기간 en → 정답 ✓","Desde: '~부터'라는 시작점이라 completar와 의미가 맞지 않습니다 ✗","A: a cuánto tiempo는 쓰지 않는 표현입니다 ✗","De: de cuánto tiempo는 '얼마 동안의(기간)'라 완료 동사와 맞지 않습니다 ✗"]},{"id":"G582","q":"Me gustaría ____ más tiempo para mí.","o":["tener","que tenga","tuviese","que tengo"],"a":0,"k":"동일주어 부정사","t":"나 자신을 위한 시간을 더 갖고 싶다.","e":"me gustaría(~하고 싶다) 뒤에서 하고 싶은 사람과 행동하는 사람이 같으면(나) 동사원형을 씁니다. 주어가 다르면 que + 접속법 과거를 씁니다: Me gustaría que tuvieras más tiempo.(네가 시간이 더 있으면 좋겠어.)","x":["tener: 같은 주어 + 동사원형 → 정답 ✓","que tenga: 주어가 같을 때는 que절을 쓰지 않고 시제도 맞지 않습니다 ✗","tuviese: que 없이 접속법을 바로 쓸 수 없습니다 ✗","que tengo: 직설법이라 바람 표현 뒤에 맞지 않습니다 ✗"]},{"id":"G583","q":"Nos apena que ____ que marcharte. ¿No te puedes quedar un ratito más?","o":["tendrías","tienes","tengas","tuvieras"],"a":2,"k":"감정동사 + 접속법","t":"네가 가야 한다니 우리는 아쉬워. 조금만 더 있으면 안 돼?","e":"apenar(슬프게 하다), alegrar, sentir처럼 감정을 나타내는 동사 + que 뒤에는 접속법을 씁니다. 주절이 현재(apena)이고 지금의 상황이므로 접속법 현재 tengas입니다. un ratito는 '잠깐'이라는 다정한 축소형입니다.","x":["tendrías: 조건형은 감정 동사 뒤 que절에 쓰지 않습니다 ✗","tienes: 직설법이라 감정 동사 뒤에 맞지 않습니다 ✗","tengas: 감정 동사 + 접속법 현재 → 정답 ✓","tuvieras: 접속법 과거라 현재 주절 apena와 시제가 맞지 않습니다 ✗"]},{"id":"G584","q":"____, que vamos a llegar tardísimo.","o":["Que te apuras","Apúrate","Apuras","Apure"],"a":1,"k":"apurarse 명령","t":"서둘러, 우리 엄청 늦겠어.","e":"apurarse(서두르다)는 중남미에서 주로 쓰는 동사로, 스페인의 darse prisa와 같은 뜻입니다. tú 긍정명령은 apura에 te를 붙여 apúrate가 되고 강세 유지를 위해 악센트가 붙습니다. 참고로 스페인에서 apurar는 '다 써 버리다, 곤란하게 하다'라는 뜻이 더 일반적입니다.","x":["Que te apuras: 직설법이라 명령이 아닌 '네가 서두른다'는 서술이 됩니다 ✗","Apúrate: tú 긍정명령 + te → 정답 ✓","Apuras: 재귀대명사도 없고 직설법이라 명령이 아닙니다 ✗","Apure: usted 명령인데 재귀대명사(se)도 빠져 있습니다 ✗"]},{"id":"G585","q":"Si ____ fuera, me quedaría en casa todo el fin de semana.","o":["ante mí","por mí","de mí","para mí"],"a":1,"k":"si por mí fuera","t":"내 마음대로 할 수 있다면 주말 내내 집에 있을 텐데.","e":"Si por mí fuera는 '내 마음대로라면, 나 하기에 달렸다면'이라는 관용 표현입니다. 현실과 반대되는 가정이므로 접속법 과거 fuera + 조건형 quedaría 구조입니다. 예: Si por ella fuera, viviríamos en la playa.(그녀 뜻대로라면 우리는 해변에서 살 거야.)","x":["ante mí: '내 앞에서'라는 뜻이라 관용 표현이 성립하지 않습니다 ✗","por mí: si por mí fuera = 내 마음대로라면 → 정답 ✓","de mí: 'si de mí dependiera'라면 가능하지만 fuera와는 쓰지 않습니다 ✗","para mí: '나에게는'이라는 의견 표현이라 맞지 않습니다 ✗"]},{"id":"G586","q":"____ les di la noticia.","o":["A mí mismo","Nosotros mismos","Mí mismo","Yo mismo"],"a":3,"k":"yo mismo","t":"내가 직접 그들에게 소식을 전했다.","e":"mismo/a를 주격 대명사 뒤에 붙이면 '~ 자신이, 직접'이라는 강조가 됩니다. 동사 di(내가 주었다)가 1인칭 단수이므로 주어 yo mismo입니다. 예: Lo hice yo misma.(내가 직접 했어.)","x":["A mí mismo: 전치사 a가 붙어 목적어 형태가 되므로 주어 자리에 맞지 않습니다 ✗","Nosotros mismos: 1인칭 복수라 동사 di(단수)와 맞지 않습니다 ✗","Mí mismo: mí는 전치사 뒤에서만 쓰는 형태라 주어가 될 수 없습니다 ✗","Yo mismo: 주어 yo + 강조 mismo → 정답 ✓"]},{"id":"G587","q":"No me ____ el primer premio, pero estoy muy satisfecho.","o":["daban","estaban dando","habían dado","han dado"],"a":3,"k":"현재완료","t":"1등 상은 못 받았지만 아주 만족해.","e":"방금 끝난 일의 결과(1등을 못 받음)를 현재의 감정(estoy muy satisfecho)과 연결할 때 스페인에서는 현재완료를 씁니다. no me han dado는 '나에게 주지 않았다(받지 못했다)'라는 3인칭 복수 무인칭 표현입니다(주는 사람을 특정하지 않음).","x":["daban: 불완료과거라 '주곤 했다/주고 있었다'가 되어 완료된 결과를 나타내지 못합니다 ✗","estaban dando: 과거진행이라 의미가 맞지 않습니다 ✗","habían dado: 대과거는 다른 과거 시점이 필요해서 현재 문장 estoy와 맞지 않습니다 ✗","han dado: 현재와 연결된 결과의 현재완료 → 정답 ✓"]},{"id":"G588","q":"____ esté interesado en la visita, que se apunte en la lista.","o":["Quienes","Los que","Los cuales","El que"],"a":3,"k":"el que + 접속법","t":"견학에 관심 있는 사람은 명단에 이름을 올리세요.","e":"el que + 접속법은 '~하는 사람은 누구든'이라는 일반·불특정 대상을 나타냅니다. 동사 esté가 단수이고 뒤의 que se apunte도 단수이므로 단수형 el que가 맞습니다. quien도 가능하지만 보기의 Quienes는 복수라 동사와 맞지 않습니다.","x":["Quienes: 복수형이라 단수 동사 esté와 일치하지 않습니다 ✗","Los que: 복수형이라 단수 동사 esté와 맞지 않습니다 ✗","Los cuales: 선행사 없이 독립적으로 쓸 수 없고 복수라 ✗","El que: 단수 불특정 대상 '~하는 사람' → 정답 ✓"]},{"id":"G589","q":"¿A vosotros qué ____ la decisión que tomó la junta?","o":["les parecía","os parecía","os pareció","les pareció"],"a":2,"k":"vosotros 대명사","t":"너희는 이사회가 내린 결정을 어떻게 생각했어?","e":"A vosotros(너희에게)를 받는 간접목적격 대명사는 os입니다. parecer는 gustar처럼 '어떻게 보이는 대상(la decisión)'이 주어라서 3인칭 단수입니다. 이미 내린 결정에 대한 한 번의 반응이므로 단순과거 pareció가 가장 자연스럽습니다. 중남미에서는 vosotros 대신 ustedes를 써서 ¿A ustedes qué les pareció?가 됩니다.","x":["les parecía: les는 ustedes/그들에게라 a vosotros와 맞지 않습니다 ✗","os parecía: 대명사는 맞지만 불완료과거는 결정을 들은 순간의 반응을 나타내기에 덜 자연스럽습니다 ✗","os pareció: vosotros의 os + 완료된 반응 단순과거 → 정답 ✓","les pareció: 시제는 맞지만 대명사가 vosotros와 맞지 않습니다 ✗"]},{"id":"G590","q":"Lo que ____ pasa a Merche es que no duerme bien desde hace tiempo.","o":["la","se le","ø","le"],"a":3,"k":"pasar 간접목적","t":"메르체의 문제는 오래전부터 잠을 잘 못 잔다는 거야.","e":"pasar가 '(누구에게) 일이 생기다'라는 뜻일 때는 그 사람을 간접목적격 대명사로 씁니다. a Merche(3인칭 단수)를 받아 le입니다. ¿Qué te pasa?(무슨 일 있어?)와 같은 구조예요. 여성이라도 간접목적격은 la가 아닌 le입니다.","x":["la: 직접목적격(그녀를)이라 pasar의 간접목적 자리에 쓰지 않습니다(laísmo 오류) ✗","se le: se가 들어가면 '깜빡 지나치다' 같은 비의도 의미가 되어 문맥과 맞지 않습니다 ✗","ø: 대명사를 빼면 스페인어로 부자연스럽습니다 ✗","le: a Merche를 받는 간접목적격 → 정답 ✓"]},{"id":"G591","q":"Me complazco ____ presentarles a la última ganadora del premio de poesía.","o":["en","a","sobre","de"],"a":0,"k":"complacerse en","t":"올해 시 부문 수상자를 여러분께 소개하게 되어 기쁩니다.","e":"complacerse en + 동사원형은 '기꺼이 ~하다, ~하게 되어 기쁘다'라는 매우 격식 있는 표현입니다. 시상식이나 공식 연설에서 씁니다. 같은 뜻으로 Tengo el placer de..., Me complace + 동사원형도 씁니다.","x":["en: complacerse en + 동사원형 → 정답 ✓","a: complacerse a는 쓰지 않습니다 ✗","sobre: '~에 관해'라는 뜻이라 맞지 않습니다 ✗","de: complacerse de는 표준적이지 않습니다 ✗"]},{"id":"G592","q":"Si han visto las noticias, ya ____ lo del accidente de tren.","o":["hayan sabido","sabrán","sabrían","se saben"],"a":1,"k":"미래형 추측","t":"뉴스를 보셨다면 기차 사고 소식은 이미 알고 계시겠군요.","e":"미래형은 현재에 대한 추측(~일 것이다)을 나타냅니다. 'si + 직설법 현재완료(han visto), 미래형' 구조로 '~했다면 아마 ~일 것이다'라는 논리적 추론입니다. lo del accidente는 '사고에 관한 일'이라는 뜻입니다.","x":["hayan sabido: 접속법이라 주절에 쓸 수 없습니다 ✗","sabrán: 현재에 대한 추측의 미래형 → 정답 ✓","sabrían: 조건형은 si + 접속법 과거 가정문의 결과절에 써서 직설법 si절과 맞지 않습니다 ✗","se saben: saberse는 '외우고 있다'라는 뜻이라 문맥에 맞지 않습니다 ✗"]},{"id":"G593","q":"¡Vos ____ insoportable!","o":["es","eres","sos","sois"],"a":2,"k":"voseo","t":"너 정말 못 참겠다!","e":"vos는 아르헨티나·우루과이·중미 등 여러 중남미 지역에서 tú 대신 쓰는 2인칭 단수 대명사입니다(voseo). ser 동사의 vos 형태는 sos입니다: vos sos, vos tenés, vos hablás. 스페인에서는 tú eres라고 합니다.","x":["es: 3인칭 단수(그/당신)라 vos와 맞지 않습니다 ✗","eres: tú의 형태라 voseo 지역에서는 vos와 함께 쓰지 않습니다 ✗","sos: vos의 ser 현재형 → 정답 ✓","sois: vosotros(스페인의 너희)의 형태라 맞지 않습니다 ✗"]},{"id":"G594","q":"____ ya, hacéis demasiado ruido.","o":["Calla","Te callas","Callas","Callaos"],"a":3,"k":"vosotros 명령+재귀","t":"이제 좀 조용히 해, 너희 너무 시끄러워.","e":"뒤의 hacéis(너희가 ~한다)를 보면 상대가 vosotros입니다. callarse(입 다물다)의 vosotros 긍정명령은 callad + os에서 d가 빠져 callaos가 됩니다. 중남미라면 ustedes를 써서 ¡Cállense ya!라고 합니다.","x":["Calla: tú 명령형이고 재귀대명사도 빠져 vosotros와 맞지 않습니다 ✗","Te callas: tú 직설법이라 상대도 다르고 명령형도 아닙니다 ✗","Callas: 재귀대명사가 없는 tú 직설법이라 ✗","Callaos: callad + os, d 탈락 → 정답 ✓"]},{"id":"G595","q":"Les he comprado ____ libros a mis niños.","o":["algunos de","todos","ambos los","sendos"],"a":3,"k":"sendos","t":"아이들에게 한 권씩 책을 사 주었다.","e":"sendos/sendas는 '각자 하나씩'이라는 뜻의 배분 형용사로, 항상 복수로 쓰고 명사 앞에 옵니다. sendos libros는 '아이마다 한 권씩'이라는 뜻입니다. '둘 다(ambos)'나 '큰'이라는 뜻으로 오해하기 쉬우니 주의하세요. 문어적인 표현입니다.","x":["algunos de: algunos de 뒤에는 관사가 필요합니다(algunos de los libros) ✗","todos: todos 뒤에는 관사가 필요합니다(todos los libros) ✗","ambos los: ambos는 관사 없이 바로 명사를 받습니다(ambos libros) ✗","sendos: '각자 하나씩' 배분 형용사 → 정답 ✓"]},{"id":"G596","q":"¿Vas a ir ____ cumpleaños de Marta?","o":["a","a las","al","a los"],"a":2,"k":"a + el 축약","t":"마르타 생일 파티에 갈 거야?","e":"ir a + 장소·행사 명사에서 a + el은 반드시 al로 축약됩니다. cumpleaños는 단수·복수 형태가 같지만, 한 명(Marta)의 생일이므로 단수 el cumpleaños → al cumpleaños입니다.","x":["a: 정관사가 빠져 어색합니다 ✗","a las: 여성 복수 관사라 cumpleaños(남성)와 맞지 않습니다 ✗","al: a + el cumpleaños 축약 → 정답 ✓","a los: 복수가 되어 한 사람의 생일 하나와 맞지 않습니다 ✗"]},{"id":"G597","q":"No es cierto que Óscar ____ despedido de la empresa.","o":["ha estado","haya sido","sea","haya estado"],"a":1,"k":"no es cierto que","t":"오스카가 회사에서 해고되었다는 것은 사실이 아니다.","e":"no es cierto que(~는 사실이 아니다)처럼 사실을 부정하는 표현 뒤에는 접속법을 씁니다. '해고되다'는 수동태 ser + despedido이므로 접속법 현재완료 haya sido despedido입니다. 이미 일어났다고 알려진 일을 부정하므로 완료형을 씁니다.","x":["ha estado: 직설법이고 estar라 수동 행위를 나타내지 못합니다 ✗","haya sido: 부정 + 접속법 현재완료 수동태 → 정답 ✓","sea: 접속법은 맞지만 현재형이라 '지금 해고되는 중'처럼 되어 완료된 사건과 맞지 않습니다 ✗","haya estado: estar despedido는 수동태로 쓰지 않습니다 ✗"]},{"id":"G598","q":"En el código penal se recogen las penas aplicables a las personas que ____.","o":["están delinquiendo","delinca","delinquen","delinquieran"],"a":2,"k":"관계절 직설법","t":"형법에는 범죄를 저지르는 사람에게 적용되는 형벌이 규정되어 있다.","e":"선행사 las personas는 법률이 규정하는 일반적 부류를 가리키며, 관계절은 그 정의(범죄를 저지르는 사람들)를 설명합니다. 일반적 사실을 나타내므로 직설법 현재 delinquen을 씁니다. delinquir는 c→qu 철자 변화가 있는 동사입니다(delinco, delinques...).","x":["están delinquiendo: 진행형은 '지금 범죄 중인'이라 법률의 일반 규정에 맞지 않습니다 ✗","delinca: 단수형이라 복수 선행사 las personas와 맞지 않습니다 ✗","delinquen: 일반적 사실 + 복수 직설법 현재 → 정답 ✓","delinquieran: 접속법 과거라 현재 시제 문장과 맞지 않습니다 ✗"]},{"id":"G599","q":"Eugenia y yo hemos quedado ____ vernos el domingo que viene.","o":["a","por","de","en"],"a":3,"k":"quedar en","t":"에우헤니아와 나는 다음 주 일요일에 만나기로 했다.","e":"quedar en + 동사원형은 '~하기로 합의하다, 약속하다'라는 뜻입니다. 예: Quedamos en llamarnos.(서로 전화하기로 했다.) quedar en + 장소는 '~에서 만나기로 하다'입니다. quedar para + 동사원형(~하려고 만나기로 하다)도 쓰지만 보기에는 없습니다.","x":["a: quedar a + 동사원형은 쓰지 않습니다(quedar a + 시간은 가능) ✗","por: quedar por + 동사원형은 '아직 ~할 일이 남다'라는 뜻이라 ✗","de: quedar de + 동사원형은 멕시코 등 일부 중남미에서 쓰지만 표준 답은 en입니다 ✗","en: quedar en + 동사원형 = ~하기로 하다 → 정답 ✓"]},{"id":"G600","q":"Me prometiste que no se lo ____ a nadie.","o":["cuentes","cuentas","contaras","contarías"],"a":3,"k":"간접화법 조건형","t":"너는 아무에게도 그 얘기를 하지 않겠다고 나에게 약속했잖아.","e":"과거의 약속을 전할 때 원래 말의 미래형(No se lo contaré)은 간접화법에서 조건형(contarías)으로 바뀝니다. prometer que는 명령이 아니라 약속 내용(사실 전달)이므로 직설법 계열을 씁니다. se lo는 '그에게 그것을'(le lo → se lo)입니다.","x":["cuentes: 접속법 현재라 약속 내용 전달과 과거 주절 모두 맞지 않습니다 ✗","cuentas: 현재형은 과거 약속의 시제 일치에 맞지 않습니다 ✗","contaras: 접속법 과거는 명령·요구를 전할 때 써서 약속 내용에는 ✗","contarías: 원래 말의 미래 → 과거 간접화법의 조건형 → 정답 ✓"]},{"id":"G601","q":"____ de piedra cuando supo lo que había sucedido.","o":["Se quedó","Se lo quedó","Quedó","Le quedó"],"a":0,"k":"관용 표현 quedarse","t":"그는 무슨 일이 있었는지 알았을 때 돌처럼 굳어 버렸다(너무 놀라 얼어붙었다).","e":"'quedarse de piedra'는 '돌처럼 굳다', 즉 너무 놀라거나 충격을 받아 꼼짝 못 하게 되다라는 관용 표현입니다. 여기서 quedarse는 재귀동사(주어 자신에게 돌아가는 동사)로 '어떤 상태가 되다'라는 뜻이라 반드시 se가 필요합니다. 비슷한 표현으로 'quedarse helado(얼어붙다)', 'quedarse de una pieza(어안이 벙벙하다)'도 있습니다.","x":["Se quedó: 재귀동사 quedarse(~한 상태가 되다)로 관용 표현 quedarse de piedra를 완성 → 정답 ✓","Se lo quedó: quedarse con algo(~을 가져 버리다)의 대명사 형태로 '그것을 가졌다'는 뜻이라 문맥과 맞지 않습니다 ✗","Quedó: se 없이 quedar는 '약속하다, 남다' 등의 뜻이라 관용 표현이 성립하지 않습니다 ✗","Le quedó: '그에게 ~이 남았다/어울렸다'는 뜻의 간접목적어 구문이라 의미가 맞지 않습니다 ✗"]},{"id":"G602","q":"Siempre ____ a favor de la libertad de expresión.","o":["he estado","he sido","haya estado","ha sido"],"a":0,"k":"estar a favor de","t":"나는 언제나 표현의 자유를 지지해 왔다.","e":"'~에 찬성하다, 지지하다'는 항상 'estar a favor de'로 씁니다. ser가 아니라 estar를 쓰는 고정 표현이니 통째로 외워 두세요. 'Siempre(언제나)'가 과거부터 지금까지 이어지는 경험을 나타내므로 현재완료 he estado가 자연스럽습니다. 반대 표현은 'estar en contra de(~에 반대하다)'입니다.","x":["he estado: estar a favor de의 현재완료 1인칭 → 정답 ✓","he sido: ser는 a favor de와 함께 쓰지 않습니다 ✗","haya estado: 접속법(바람·의심을 나타내는 형태)인데, 단정하는 주절이라 접속법이 올 이유가 없습니다 ✗","ha sido: ser를 쓴 데다 3인칭이라 이중으로 맞지 않습니다 ✗"]},{"id":"G603","q":"____ buena que es y siempre le pasa de todo.","o":["De lo","Por lo","Para lo","Con lo"],"a":3,"k":"con lo + 형용사 + que","t":"그녀는 그렇게나 착한데, 늘 온갖 안 좋은 일이 생긴다.","e":"'con lo + 형용사 + que + 동사'는 '그렇게 ~한데도/~한 걸 생각하면'이라는 뜻으로, 놀람이나 불만을 담은 양보·대조 표현입니다. 형용사는 주어의 성·수에 맞추므로 여기서는 buena(여성 단수)입니다. 예: 'Con lo listo que es, no aprobó.(그렇게 똑똑한데 합격을 못 했다.)' 'pasarle de todo'는 '온갖 일을 다 겪다'라는 구어 표현입니다.","x":["De lo: 'de lo + 형용사 + que'는 '너무 ~해서'라는 원인을 나타내며 보통 주절 뒤에 옵니다 ✗","Por lo: 'por lo + 형용사 + que'도 원인(~해서)을 나타내 대조의 의미와 맞지 않습니다 ✗","Para lo: 'para lo + 형용사'는 '~인 것치고는'이라는 뜻으로 문장 흐름과 맞지 않습니다 ✗","Con lo: '그렇게 ~한데도'라는 양보·불만 표현 → 정답 ✓"]},{"id":"G604","q":"No siguió las instrucciones del médico, ____ acabó sintiéndose peor de lo que ya estaba.","o":["mientras que","ya que","por lo que","puesto que"],"a":2,"k":"결과 접속사 por lo que","t":"그는 의사의 지시를 따르지 않았고, 그래서 결국 이미 안 좋던 상태보다 더 나빠졌다.","e":"'por lo que'는 앞 문장 전체를 받아 '그래서, 그 때문에'라는 결과를 이어 줍니다. 지시를 따르지 않은 것이 원인이고 몸이 더 나빠진 것이 결과이므로 결과 접속사가 필요합니다. 'acabar + 현재분사(-ndo)'는 '결국 ~하게 되다'라는 뜻입니다.","x":["mientras que: '반면에'라는 대조 접속사라 원인-결과 흐름과 맞지 않습니다 ✗","ya que: '~이기 때문에'로 원인을 나타내 순서가 거꾸로 됩니다 ✗","por lo que: '그래서'라는 결과 접속사 → 정답 ✓","puesto que: ya que와 같은 원인 접속사(~이므로)라 맞지 않습니다 ✗"]},{"id":"G605","q":"No olvides que lo que hago por ti no lo haría por ____.","o":["alguno","cualquier otro","una otra","cualquiera"],"a":3,"k":"부정 대명사 cualquiera","t":"내가 너를 위해 하는 일을 아무에게나 해 주지는 않을 거라는 걸 잊지 마.","e":"'cualquiera'는 명사 없이 홀로 쓰면 '아무나, 누구든'이라는 대명사가 됩니다. 명사 앞에서는 끝이 떨어져 'cualquier'가 됩니다(예: cualquier persona). 'por cualquiera'는 '아무에게나, 아무를 위해서나'라는 뜻으로, '너는 특별하다'는 뉘앙스를 줍니다.","x":["alguno: '어떤 사람/몇몇'이라는 뜻으로 '아무나'의 강조 의미가 없고, 단독 사용 시에도 어색합니다 ✗","cualquier otro: 'cualquier'는 보통 뒤에 명사가 오는 형태라(cualquier otro amigo) 여기서는 문장이 덜 완결적입니다 ✗","una otra: 스페인어에서는 'otra' 앞에 부정관사 una를 붙이지 않습니다 ✗","cualquiera: 단독으로 쓰는 대명사 '아무나' → 정답 ✓"]},{"id":"G606","q":"Me extraña que no ____ todavía.","o":["han vuelto","estén volviendo","hayan vuelto","van a volver"],"a":2,"k":"감정 표현 + 접속법","t":"그들이 아직 돌아오지 않았다니 이상하다.","e":"'Me extraña que ~(~라니 이상하다/놀랍다)'처럼 감정·놀람을 나타내는 표현 뒤의 que절에는 접속법(바람·의심·감정을 나타내는 동사 형태)을 씁니다. 'todavía(아직)'가 있어 지금까지 완료되지 않은 일을 말하므로 접속법 현재완료 hayan vuelto가 정답입니다.","x":["han vuelto: 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗","estén volviendo: '돌아오는 중'이라는 진행의 의미라 '아직 안 돌아왔다'와 맞지 않습니다 ✗","hayan vuelto: 접속법 현재완료로 '돌아오지 않은 상태'를 나타냄 → 정답 ✓","van a volver: 직설법 미래 표현이라 감정 표현 뒤에 맞지 않습니다 ✗"]},{"id":"G607","q":"Si te pones ____ mí, no podré ver nada.","o":["frente","enfrente","delante de","delante"],"a":2,"k":"장소 전치사구","t":"네가 내 앞에 서 있으면 나는 아무것도 볼 수 없을 거야.","e":"'delante de + 사람/사물'은 '~의 앞에'라는 뜻으로, 뒤에 대상(mí)이 올 때 반드시 de가 필요합니다. 전치사 뒤에서는 'yo'가 아니라 'mí'를 씁니다. 'ponerse delante de alguien'은 '누군가의 앞을 가로막다'라는 느낌입니다.","x":["frente: 뒤에 대상이 오려면 'frente a mí'처럼 a가 필요합니다 ✗","enfrente: 'enfrente de mí'처럼 de가 있어야 하고, 뜻도 '맞은편'이라 시야를 가리는 상황과 덜 맞습니다 ✗","delante de: '~의 앞에'라는 전치사구 → 정답 ✓","delante: de 없이 바로 mí를 붙일 수 없습니다 ✗"]},{"id":"G608","q":"Cuando pases el semáforo, gira ____ izquierda.","o":["de la","en la","a la","al"],"a":2,"k":"방향 표현 a la","t":"신호등을 지나면 왼쪽으로 돌아.","e":"'girar a la izquierda/derecha(왼쪽/오른쪽으로 돌다)'처럼 방향을 나타낼 때는 전치사 a를 씁니다. izquierda는 여성명사라 'a la'가 됩니다. 'Cuando pases'는 미래의 일을 말하는 시간절이라 접속법이 쓰였다는 점도 함께 기억하세요.","x":["de la: '~의'라는 소속을 나타내므로 방향이 되지 않습니다 ✗","en la: 위치(~에서)를 나타내 '왼쪽으로'라는 이동 방향과 맞지 않습니다 ✗","a la: 방향을 나타내는 a + 여성 관사 la → 정답 ✓","al: a + el의 축약형인데 izquierda는 여성명사입니다 ✗"]},{"id":"G609","q":"Nunca pensamos que ____ ciertos aquellos rumores.","o":["fueran","estuvieran","fueron","estaban"],"a":0,"k":"부정 생각동사 + 접속법","t":"우리는 그 소문들이 사실일 거라고는 전혀 생각하지 못했다.","e":"'pensar, creer' 같은 생각 동사가 부정(no, nunca)으로 쓰이면 뒤의 que절에 접속법이 옵니다. 주절이 과거(pensamos)이므로 접속법 과거 fueran을 씁니다. '사실이다'는 'ser cierto'로 표현하며, 사실 여부는 본질적 판단이라 ser를 씁니다.","x":["fueran: ser의 접속법 과거로 부정 + 생각동사 뒤에 맞음 → 정답 ✓","estuvieran: estar는 'cierto(사실인)'와 함께 쓰지 않습니다 ✗","fueron: 직설법이라 부정된 생각동사 뒤에 어색합니다 ✗","estaban: estar + 직설법으로 두 가지 모두 맞지 않습니다 ✗"]},{"id":"G610","q":"Supongo que no ____ a creer mi versión de los hechos.","o":["van","vayan","hayan ido","habían ido"],"a":0,"k":"suponer + 직설법","t":"그들은 내가 말한 사건 경위를 믿지 않을 것 같다.","e":"'Supongo que(~라고 생각한다/짐작한다)'는 긍정형이면 확신에 가까운 추측이라 뒤에 직설법을 씁니다. 여기서 'no'는 que절 안에 있는 것이지 suponer를 부정한 것이 아닙니다. 'ir a + 동사원형'은 '~할 것이다'라는 가까운 미래 표현입니다.","x":["van: 직설법 현재로 ir a creer(믿을 것이다)를 완성 → 정답 ✓","vayan: 접속법인데 긍정형 suponer 뒤에는 직설법을 씁니다 ✗","hayan ido: 접속법 현재완료로 서법·시제 모두 맞지 않습니다 ✗","habían ido: 과거완료라 '앞으로 믿지 않을 것'이라는 의미와 맞지 않습니다 ✗"]},{"id":"G611","q":"No estoy conforme ____ la decisión final.","o":["para","de","a","con"],"a":3,"k":"conforme con","t":"나는 최종 결정에 동의하지 않는다(만족하지 않는다).","e":"'estar conforme con algo'는 '~에 동의하다, ~에 만족하다'라는 뜻이며 전치사 con과 짝을 이룹니다. 반대말은 'estar disconforme con'입니다. 공식 문서나 서명란에서 'Conforme(이의 없음)'라고 단독으로 쓰기도 합니다.","x":["para: conforme와 짝이 되지 않는 전치사입니다 ✗","de: 'de conformidad con'은 있지만 'conforme de'는 쓰지 않습니다 ✗","a: 'conforme a'는 '~에 따라'라는 다른 뜻이라 문맥과 맞지 않습니다 ✗","con: estar conforme con(~에 동의하다) → 정답 ✓"]},{"id":"G612","q":"Cada vez que ____, acabamos discutiendo.","o":["haya venido","viene","venga","vendría"],"a":1,"k":"반복 습관 + 직설법","t":"그가 올 때마다 우리는 결국 말다툼을 하게 된다.","e":"'Cada vez que(~할 때마다)'가 현재의 반복되는 습관을 말할 때는 직설법을 씁니다. 주절 'acabamos discutiendo'가 현재형으로 늘 일어나는 일을 말하므로 viene가 맞습니다. 미래의 일을 말한다면 접속법(cada vez que venga)도 가능하지만, 그때는 주절도 미래·명령 등이 되어야 합니다.","x":["haya venido: 접속법 현재완료로 습관적 사실과 맞지 않습니다 ✗","viene: 반복되는 현재 사실을 나타내는 직설법 → 정답 ✓","venga: 미래의 일을 가정할 때 쓰는데, 주절이 현재 습관이라 맞지 않습니다 ✗","vendría: 가능법(조건)이라 맞지 않습니다 ✗"]},{"id":"G613","q":"Quien ____ semejante tontería no sabe nada de ordenadores.","o":["han dicho","haya dicho","habría dicho","dirá"],"a":1,"k":"불특정 관계사 + 접속법","t":"그런 바보 같은 말을 한 사람이 누구든 그 사람은 컴퓨터에 대해 아무것도 모른다.","e":"'Quien ~(~하는 사람)'이 누구인지 정해지지 않은 사람을 가리킬 때는 관계절에 접속법을 씁니다. 말한 사람이 누구인지 모르지만 이미 말한 일이므로 접속법 현재완료 haya dicho가 됩니다. 'semejante tontería'는 '그런 터무니없는 말'로, semejante가 명사 앞에서 '그런, 그 정도의'라는 강조 뜻입니다.","x":["han dicho: quien은 단수인데 3인칭 복수라 맞지 않습니다 ✗","haya dicho: 정해지지 않은 사람 + 완료된 행동 → 정답 ✓","habría dicho: 가능법 완료(~했을 것이다)라 관계절에 어색합니다 ✗","dirá: 미래형이라 이미 한 말이라는 뜻과 맞지 않습니다 ✗"]},{"id":"G614","q":"Me saca de quicio que ____ todo el día haciendo ruido.","o":["estén","estarían","estuviesen","están"],"a":0,"k":"감정 유발 + 접속법","t":"그들이 하루 종일 시끄럽게 구는 게 정말 짜증 난다.","e":"'sacar de quicio a alguien'은 '누군가를 미치게 하다, 몹시 짜증 나게 하다'라는 관용 표현입니다. 감정을 일으키는 내용이 que절에 오면 접속법을 쓰고, 주절이 현재(saca)이므로 접속법 현재 estén이 맞습니다. 'estar + 현재분사(haciendo)'로 지금 계속되는 행동을 나타냅니다.","x":["estén: 감정 표현 뒤의 접속법 현재 → 정답 ✓","estarían: 가능법이라 감정 표현 뒤에 맞지 않습니다 ✗","estuviesen: 접속법 과거라 현재 주절(saca)과 시제가 맞지 않습니다 ✗","están: 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗"]},{"id":"G615","q":"Belén y Celia no ____ en nada.","o":["están parecidas","parecen","se parecen","se están pareciendo"],"a":2,"k":"parecerse","t":"벨렌과 셀리아는 하나도 닮지 않았다.","e":"'서로 닮다'는 재귀동사 'parecerse'를 씁니다. '~에서/~ 면에서 닮다'는 전치사 en을 써서 'parecerse en algo'라고 하며, 'no se parecen en nada'는 '전혀 닮지 않았다'는 뜻입니다. 그냥 'parecer'는 '~처럼 보이다'라는 다른 뜻입니다.","x":["están parecidas: 'parecido'는 형용사(닮은)지만 estar와 en nada를 함께 쓰는 형태는 어색합니다 ✗","parecen: '~처럼 보이다'라는 뜻이라 '서로 닮다'가 되지 않습니다 ✗","se parecen: 재귀동사 parecerse(닮다) → 정답 ✓","se están pareciendo: 진행형으로 '점점 닮아가고 있다'는 다른 의미가 됩니다 ✗"]},{"id":"G616","q":"No sé ____ hacer con mi hija, se ha vuelto muy rebelde.","o":["a que","lo qué","qué","que"],"a":2,"k":"간접의문문 qué","t":"딸을 어떻게 해야 할지 모르겠어요. 아이가 아주 반항적으로 변했거든요.","e":"'No sé qué hacer(무엇을 해야 할지 모르겠다)'처럼 의문사 + 동사원형으로 간접의문문을 만들 때 의문사에는 악센트를 붙입니다(qué). 'volverse + 형용사'는 성격이나 상태가 '~하게 변하다'라는 뜻입니다.","x":["a que: 'a que'는 '~하기 위해/~라는 데' 등의 뜻으로 간접의문문이 되지 않습니다 ✗","lo qué: 관사 lo와 의문사 qué를 함께 쓰지 않습니다(lo que는 악센트 없음) ✗","qué: 간접의문문의 의문사 '무엇' → 정답 ✓","que: 악센트가 없으면 접속사·관계사라 '무엇을'이라는 뜻이 되지 않습니다 ✗"]},{"id":"G617","q":"Se rompió el brazo derecho, ____ no jugara en el último partido.","o":["dicho esto","debido a que","por eso","de ahí que"],"a":3,"k":"de ahí que + 접속법","t":"그는 오른팔이 부러졌고, 그래서 마지막 경기에 뛰지 못했다.","e":"'de ahí que'는 '그래서, 그 때문에'라는 결과 표현인데 특이하게도 뒤에 접속법이 옵니다. 빈칸 뒤 'jugara'가 접속법 과거이므로, 접속법을 이끄는 de ahí que만 들어갈 수 있습니다. 문어체에서 자주 쓰이는 C2 수준의 연결어입니다.","x":["dicho esto: '이렇게 말한 뒤에'라는 담화 표지로 접속법을 이끌지 않습니다 ✗","debido a que: '~때문에'라는 원인 표현이라 순서가 거꾸로 되고 직설법을 씁니다 ✗","por eso: '그래서'라는 뜻은 맞지만 뒤에 직설법(jugó)이 와야 합니다 ✗","de ahí que: 결과를 나타내며 접속법을 이끔 → 정답 ✓"]},{"id":"G618","q":"De joven, ____ a dormir en casa de mis amigas los fines de semana.","o":["me quedé","me quedaba","quedaba","me quedara"],"a":1,"k":"과거 습관 불완료","t":"어렸을 때 나는 주말마다 친구들 집에서 자곤 했다.","e":"'De joven(젊었을 때/어렸을 때)'과 '주말마다'처럼 과거의 반복되는 습관은 불완료과거(과거에 계속·반복되던 일을 나타내는 시제)로 씁니다. '어디에 머물러 자다'는 'quedarse a dormir'라는 재귀 표현이므로 me가 필요합니다.","x":["me quedé: 단순과거(한 번 끝난 일)라 반복 습관과 맞지 않습니다 ✗","me quedaba: 재귀동사 + 불완료과거로 과거 습관 → 정답 ✓","quedaba: se가 없으면 '머물다'의 뜻이 되지 않고 '약속하다/남다' 등이 됩니다 ✗","me quedara: 접속법 과거라 이유 없이 쓸 수 없습니다 ✗"]},{"id":"G619","q":"Dile a Fernán que traiga también leche cuando ____ al supermercado.","o":["irá","iría","vaya","fuese"],"a":2,"k":"미래 시간절 + 접속법","t":"페르난에게 슈퍼에 갈 때 우유도 사 오라고 말해.","e":"'cuando'가 앞으로 일어날 일(아직 안 일어난 일)을 말할 때는 접속법을 씁니다. 주절이 명령(Dile)이고 현재 시점에서 미래를 말하므로 접속법 현재 vaya가 맞습니다. 'que traiga'도 명령을 전달하는 접속법입니다.","x":["irá: 스페인어에서는 cuando 뒤에 미래형을 쓰지 않습니다 ✗","iría: 가능법이라 cuando절에 맞지 않습니다 ✗","vaya: 미래 시간절의 접속법 현재 → 정답 ✓","fuese: 접속법 과거라 현재 명령문과 시제가 맞지 않습니다 ✗"]},{"id":"G620","q":"Espero ____ el examen de inglés.","o":["que está aprobado","habiendo aprobado","haber aprobado","que he aprobado"],"a":2,"k":"주어 동일 시 원형","t":"영어 시험에 합격했기를 바란다.","e":"'esperar(바라다)'의 주어와 바라는 내용의 주어가 같으면(나=나) que절 대신 동사원형을 씁니다. 이미 친 시험의 결과를 바라는 것이므로 완료 원형 'haber aprobado(합격했기를)'가 됩니다. 주어가 다르면 'Espero que hayas aprobado(네가 합격했길 바라)'처럼 접속법을 씁니다.","x":["que está aprobado: 시험이 '합격된 상태'라는 어색한 표현이고, esperar que 뒤엔 접속법이 필요합니다 ✗","habiendo aprobado: 현재분사 형태는 esperar의 목적어가 될 수 없습니다 ✗","haber aprobado: 주어가 같을 때 쓰는 완료 원형 → 정답 ✓","que he aprobado: 주어가 같으면 que절을 쓰지 않고, 쓰더라도 접속법이어야 합니다 ✗"]},{"id":"G621","q":"Tenemos que ordenar toda la casa antes de que ____ nuestros padres.","o":["están viniendo","vienen","vengan","van a venir"],"a":2,"k":"antes de que + 접속법","t":"부모님이 오시기 전에 우리는 집 안 전체를 정리해야 한다.","e":"'antes de que(~하기 전에)'는 언제나 뒤에 접속법을 씁니다. 아직 일어나지 않은 일을 나타내기 때문입니다. 현재 시점의 일이므로 접속법 현재 vengan이 맞습니다. 주어가 같으면 'antes de + 동사원형'을 씁니다(antes de salir, 나가기 전에).","x":["están viniendo: 직설법 진행형이라 antes de que 뒤에 쓸 수 없습니다 ✗","vienen: 직설법이라 맞지 않습니다 ✗","vengan: antes de que 뒤의 접속법 현재 → 정답 ✓","van a venir: 직설법 미래 표현이라 맞지 않습니다 ✗"]},{"id":"G622","q":"Manuel está malo porque ayer ____ todas las galletas que había en el paquete.","o":["se comió","ha comido","estaba comiéndose","comió"],"a":0,"k":"강조의 재귀 se","t":"마누엘은 어제 봉지에 있던 과자를 몽땅 먹어 버려서 배탈이 났다.","e":"'comerse algo'처럼 동사에 se를 붙이면 '다 먹어 치우다'라는 완전함·강조의 의미가 생깁니다. 'todas las galletas(과자 전부)'처럼 정해진 양 전체를 먹을 때 특히 자연스럽습니다. 'ayer(어제)'가 있으므로 단순과거를 씁니다. 'estar malo'는 스페인에서 '몸이 아프다'는 구어 표현입니다.","x":["se comió: 강조의 se + 단순과거로 '몽땅 먹어 버렸다' → 정답 ✓","ha comido: 현재완료는 스페인에서 ayer와 함께 쓰지 않습니다 ✗","estaba comiéndose: 진행 중인 동작이라 원인이 된 완료된 행동을 나타내지 못합니다 ✗","comió: 문법적으로 가능하지만 '전부 먹어 치웠다'는 뉘앙스가 약해 se comió가 더 적절합니다 ✗"]},{"id":"G623","q":"El testigo ____ como si estuviera muy seguro de lo que decía.","o":["hablaría","hablara","hablará","hablaba"],"a":3,"k":"como si + 접속법 과거","t":"그 증인은 마치 자기가 하는 말에 아주 확신이 있는 것처럼 말했다.","e":"'como si(마치 ~인 것처럼)' 뒤에는 항상 접속법 과거(estuviera)가 옵니다. 주절은 과거에 어떻게 말하고 있었는지를 묘사하므로 불완료과거 hablaba가 자연스럽습니다. 이 구문은 주절의 시제와 상관없이 como si 뒤를 접속법 과거로 고정한다는 점이 특징입니다.","x":["hablaría: 가능법이라 과거 사실의 묘사가 되지 않습니다 ✗","hablara: 접속법 과거인데 주절에는 직설법이 필요합니다 ✗","hablará: 미래형이라 과거 장면과 맞지 않습니다 ✗","hablaba: 과거 장면을 묘사하는 불완료과거 → 정답 ✓"]},{"id":"G624","q":"Creo que se deja llevar fácilmente ____ la opinión de los demás.","o":["de","en","para","por"],"a":3,"k":"dejarse llevar por","t":"그는 다른 사람들의 의견에 쉽게 휩쓸리는 것 같다.","e":"'dejarse llevar por algo/alguien'은 '~에 휩쓸리다, ~에 이끌려 가다'라는 뜻의 고정 표현입니다. 수동적인 의미('~에 의해 끌려가다')라서 행위자를 나타내는 por를 씁니다. 예: 'No te dejes llevar por las emociones.(감정에 휩쓸리지 마.)'","x":["de: dejarse llevar와 짝이 되지 않습니다 ✗","en: dejarse llevar와 짝이 되지 않습니다 ✗","para: 목적(~을 위해)을 나타내 의미가 맞지 않습니다 ✗","por: 이끄는 힘(원인·행위자)을 나타내는 por → 정답 ✓"]},{"id":"G625","q":"¿Cómo ____ hablarle así a tu madre?","o":["pueda","podés","puedas","podé"],"a":1,"k":"voseo 현재형","t":"어떻게 너희 엄마한테 그렇게 말할 수 있어?","e":"정답 podés는 아르헨티나·우루과이 등에서 tú 대신 쓰는 'vos'의 현재형입니다(voseo). vos는 현재형에서 끝 모음에 악센트가 오고 어간 변화가 없습니다(puedes → podés). 스페인이나 대부분의 중남미에서는 같은 문장을 '¿Cómo puedes hablarle así?'라고 합니다.","x":["pueda: 접속법이라 직접 묻는 의문문에 맞지 않습니다 ✗","podés: vos의 직설법 현재(리오플라타 지역) → 정답 ✓","puedas: 접속법이라 맞지 않고, 직설법 puedes였다면 가능했습니다 ✗","podé: 존재하지 않는 형태입니다(vos 명령형도 아님) ✗"]},{"id":"G626","q":"Empecé a decirle lo que había pasado pero ya lo sabía porque alguien se lo ____.","o":["hubiese contado","contaba","ha contado","había contado"],"a":3,"k":"과거완료","t":"그에게 무슨 일이 있었는지 말하기 시작했지만, 누군가 이미 그에게 말해 줘서 그는 벌써 알고 있었다.","e":"과거의 어떤 시점(내가 말하기 시작한 때)보다 더 앞서 일어난 일은 과거완료(había + 과거분사)로 나타냅니다. 누군가 알려 준 것이 내가 말하려던 것보다 먼저이므로 'había contado'가 맞습니다. 'se lo'는 le lo가 se lo로 바뀐 형태로 '그에게 그것을'이라는 뜻입니다.","x":["hubiese contado: 접속법 과거완료라 사실을 말하는 porque절에 맞지 않습니다 ✗","contaba: 불완료과거라 '먼저 완료된 일'을 나타내지 못합니다 ✗","ha contado: 현재완료라 과거 이야기 속 이전 사건에 맞지 않습니다 ✗","había contado: 과거보다 더 이전의 일을 나타내는 과거완료 → 정답 ✓"]},{"id":"G627","q":"No te puedes imaginar ____ cosas que sabe hacer este niño.","o":["las de","de","la de","de las"],"a":2,"k":"la de + 복수명사","t":"이 아이가 할 줄 아는 게 얼마나 많은지 너는 상상도 못 할 거야.","e":"'la de + 복수명사 + que'는 구어에서 '얼마나 많은 ~인지'라는 양의 많음을 강조하는 표현입니다(la cantidad de의 줄임). 뒤에 남성 복수 명사가 와도(la de libros, 얼마나 많은 책) 관사는 항상 'la'로 고정된다는 점이 특이합니다. 예: '¡La de veces que te lo he dicho!(내가 너한테 몇 번이나 말했는데!)'","x":["las de: 관사를 명사에 맞춰 복수로 바꾸지 않고 항상 la de를 씁니다 ✗","de: 관사 없이는 이 강조 구문이 성립하지 않습니다 ✗","la de: '얼마나 많은 ~'이라는 강조 구문 → 정답 ✓","de las: 순서가 바뀐 형태로 문법적으로 맞지 않습니다 ✗"]},{"id":"G628","q":"¿Cómo quieres que ____ tras un viaje tan largo?","o":["estemos","seamos","estamos","somos"],"a":0,"k":"querer que + 접속법","t":"그렇게 긴 여행 끝에 우리가 어떤 상태이길 바라는 거야?(당연히 녹초지!)","e":"'¿Cómo quieres que ~?'는 '어떻게 ~하길 바라니?'라는 반문으로, '당연히 피곤하지'라는 뜻을 담고 있습니다. querer que 뒤에는 접속법을 쓰고, 여행 후의 일시적인 몸 상태는 estar로 나타내므로 'estemos'가 정답입니다.","x":["estemos: estar(상태) + querer que 뒤 접속법 → 정답 ✓","seamos: ser는 본질·정체성을 나타내 일시적 상태에 맞지 않습니다 ✗","estamos: 직설법이라 querer que 뒤에 쓸 수 없습니다 ✗","somos: ser인 데다 직설법이라 두 가지 모두 틀립니다 ✗"]},{"id":"G629","q":"¡Quién ____ a imaginar semejante historia!","o":["se fue","vas","se iba","hubiera ido"],"a":2,"k":"수사 감탄 ir a","t":"그런 이야기를 누가 상상이나 했겠어!","e":"'¡Quién iba a + 동사원형!'은 '누가 ~하리라 생각했겠어!'라는 수사적 감탄으로, 아무도 예상하지 못했다는 놀라움을 나타냅니다. 여기서는 'imaginarse(상상하다)'가 재귀동사라 'se iba a imaginar'가 되었습니다. 비슷한 표현으로 '¡Quién lo iba a decir!(누가 그럴 줄 알았겠어!)'가 아주 자주 쓰입니다.","x":["se fue: irse(떠나다)의 단순과거라 ir a + 원형 구조가 되지 않습니다 ✗","vas: 2인칭이라 주어 quién(3인칭)과 맞지 않습니다 ✗","se iba: 불완료과거 ir a + 재귀 imaginarse로 수사 감탄 → 정답 ✓","hubiera ido: 접속법 과거완료라 '상상했겠어'라는 의미가 되지 않습니다 ✗"]},{"id":"G630","q":"A a pesar de que era inocente, estuvo años en ____ cárcel.","o":["el","al","ø","la"],"a":3,"k":"정관사 la cárcel","t":"그는 무죄였는데도 몇 년 동안 감옥에 있었다.","e":"스페인어에서는 '감옥에 있다'를 'estar en la cárcel'처럼 정관사와 함께 씁니다. 영어 'in prison'과 달리 관사를 빼지 않습니다. cárcel은 여성명사이므로 la입니다. 'a pesar de que(~임에도 불구하고)'는 양보 접속사입니다(문제의 'A a'는 교재 오타로 보입니다).","x":["el: cárcel은 여성명사라 남성 관사를 쓰지 않습니다 ✗","al: a + el의 축약형으로 전치사 en 뒤에 올 수 없습니다 ✗","ø: 스페인어에서는 이 표현에서 관사를 생략하지 않습니다 ✗","la: 여성명사 cárcel의 정관사 → 정답 ✓"]},{"id":"G631","q":"____ visto, Jesús ha pedido un traslado a otro departamento.","o":["Por lo","De lo","Al","Con lo"],"a":0,"k":"관용 표현 por lo visto","t":"듣자 하니 헤수스가 다른 부서로 전근을 신청했다더라.","e":"'Por lo visto'는 '보아하니, 듣자 하니'라는 뜻으로, 직접 확인하지 않고 들은 정보를 전할 때 씁니다. 비슷한 표현으로 'al parecer', 'según parece'가 있습니다. 'pedir un traslado'는 '전근(전보)을 신청하다'입니다.","x":["Por lo: 'por lo visto(듣자 하니)'라는 고정 표현 → 정답 ✓","De lo: 'de lo visto'라는 표현은 쓰지 않습니다 ✗","Al: 'al visto'라는 표현은 없습니다('visto bueno'는 '승인'이라는 다른 표현) ✗","Con lo: 'con lo visto'는 '본 것을 가지고'라는 뜻이라 관용 표현이 되지 않습니다 ✗"]},{"id":"G632","q":"¿A qué hora ____ vosotras?","o":["meriendan","merendad","merendáis","merendéis"],"a":2,"k":"vosotras 현재형","t":"너희(여자들)는 몇 시에 간식을 먹니?","e":"'merendar(오후 간식을 먹다)'는 e→ie로 바뀌는 불규칙 동사지만, nosotros·vosotros 형태에서는 어간이 바뀌지 않습니다. 그래서 vosotras는 'merendáis'입니다. 중남미에서는 vosotros 대신 ustedes를 써서 '¿A qué hora meriendan ustedes?'라고 합니다.","x":["meriendan: ustedes·ellos 형태라 vosotras와 맞지 않습니다(중남미에서는 ustedes로 이렇게 말함) ✗","merendad: vosotros 긍정 명령형이라 의문문에 맞지 않습니다 ✗","merendáis: vosotras의 직설법 현재 → 정답 ✓","merendéis: 접속법(또는 부정 명령)이라 단순 질문에 맞지 않습니다 ✗"]},{"id":"G633","q":"Están llamando por teléfono, ¿quién ____ a estas horas de la noche?","o":["está","está siendo","estará","será"],"a":3,"k":"추측의 미래","t":"전화가 오고 있네. 이 밤늦은 시간에 누구일까?","e":"스페인어에서 단순미래는 '현재에 대한 추측'도 나타냅니다(추측의 미래). '¿Quién será?'는 '누구일까?'라는 뜻으로, 정체(누구인가)를 묻는 것이라 ser를 씁니다. 예: 'Serán las diez.(10시쯤 됐을 거야.)'","x":["está: estar는 사람의 정체를 묻는 데 쓰지 않고, 추측의 뉘앙스도 없습니다 ✗","está siendo: 진행형으로 의미가 성립하지 않습니다 ✗","estará: 추측의 미래지만 estar라서 '누구인가'를 물을 수 없습니다 ✗","será: ser의 미래형으로 현재에 대한 추측 → 정답 ✓"]},{"id":"G634","q":"La próxima vez, procurad tardar ____ menos posible.","o":["lo","ø","el","al"],"a":0,"k":"lo + 최상급 + posible","t":"다음번엔 되도록 늦지 않도록(최대한 덜 늦도록) 해라.","e":"'lo + más/menos + 부사/형용사 + posible'은 '가능한 한 ~하게'라는 고정 표현입니다. 'lo menos posible'은 '가능한 한 적게', 'lo antes posible'은 '가능한 한 빨리'입니다. 'procurad'는 vosotros 명령형으로 '~하도록 노력해라'라는 뜻입니다.","x":["lo: 중성관사 lo로 'lo menos posible'을 완성 → 정답 ✓","ø: 관사 없이는 이 표현이 성립하지 않습니다 ✗","el: 남성 정관사는 이 부사적 표현에 쓰지 않습니다 ✗","al: a + el로 의미가 맞지 않습니다 ✗"]},{"id":"G635","q":"____, somos todo oídos.","o":["Cuéntanos","Nos cuentas","Cuenta nos","Nos cuenta"],"a":0,"k":"긍정 명령 + 대명사","t":"말해 봐, 우리 모두 귀 기울이고 있어.","e":"긍정 명령형에서는 대명사를 동사 끝에 붙여서 한 단어로 씁니다(cuenta + nos = cuéntanos). 붙이면 강세 위치를 지키기 위해 악센트(é)를 표시합니다. 'ser todo oídos'는 '온 귀를 기울이다, 열심히 듣고 있다'라는 관용 표현입니다.","x":["Cuéntanos: 긍정 명령 + 대명사를 붙이고 악센트 표시 → 정답 ✓","Nos cuentas: '너는 우리에게 말한다'는 평서문(또는 부드러운 부탁)이라 명령 형태가 아닙니다 ✗","Cuenta nos: 대명사를 띄어 쓰지 않고 붙여야 하며 악센트도 필요합니다 ✗","Nos cuenta: 3인칭(그/당신이 말한다)이라 명령형이 아닙니다 ✗"]},{"id":"G636","q":"La inmensa mayoría de estos productos ____ a los países vecinos.","o":["se exportan","se les exportan","les exportan","exportan"],"a":0,"k":"재귀 수동 se","t":"이 제품들의 대다수는 이웃 나라들로 수출된다.","e":"'se + 3인칭 동사'로 '~되다'라는 수동의 뜻을 만드는 것을 재귀 수동(pasiva refleja)이라 합니다. 이때 동사는 주어 역할을 하는 명사에 수를 맞춥니다. 'La inmensa mayoría de estos productos'는 의미상 복수(제품들)로 보아 복수 동사 exportan을 씁니다(단수 exporta도 가능).","x":["se exportan: 재귀 수동 + 복수 일치 → 정답 ✓","se les exportan: les(그들에게)가 불필요하게 들어가 문법이 맞지 않습니다 ✗","les exportan: '그들에게 수출한다'는 뜻으로 주어가 바뀌어 의미가 맞지 않습니다 ✗","exportan: se가 없으면 '제품들이 수출한다'는 능동이 되어 어색합니다 ✗"]},{"id":"G637","q":"____ tú no sales de casa, hemos decidido venir nosotros a verte.","o":["Porque","De modo que","Si bien","Como"],"a":3,"k":"원인 접속사 como","t":"너는 집 밖에 나오지 않으니까, 우리가 너를 보러 가기로 했어.","e":"원인을 문장 맨 앞에 둘 때는 'como(~하니까)'를 씁니다. 'porque'는 보통 주절 뒤에 와서 이유를 설명할 때 씁니다. 예: 'Como llovía, nos quedamos en casa.(비가 와서 우리는 집에 있었다.)'","x":["Porque: 원인 접속사지만 일반적으로 문장 맨 앞에 두지 않습니다 ✗","De modo que: '그래서'라는 결과 표현이라 원인을 이끌지 못합니다 ✗","Si bien: '~이긴 하지만'이라는 양보 표현이라 맞지 않습니다 ✗","Como: 문장 앞에서 원인을 나타내는 접속사 → 정답 ✓"]},{"id":"G638","q":"Manuel, por favor, ____ la merienda a los niños.","o":["dala","dadles","dales","dale"],"a":2,"k":"tú 명령 + 간접목적어","t":"마누엘, 부탁인데 아이들에게 간식 좀 줘.","e":"Manuel 한 사람에게 하는 tú 명령형은 'da'이고, '아이들에게'라는 간접목적어는 복수 les입니다. 이를 붙이면 'dales'가 됩니다. 스페인어에서는 'a los niños'가 뒤에 있어도 간접목적격 대명사를 함께 쓰는 것이 자연스럽습니다.","x":["dala: la는 직접목적어(그것을)라 '아이들에게'를 나타내지 못합니다 ✗","dadles: vosotros 명령형이라 Manuel 한 사람에게 맞지 않습니다 ✗","dales: tú 명령 + 복수 간접목적어 les → 정답 ✓","dale: le는 단수(그에게)라 복수인 los niños와 맞지 않습니다 ✗"]},{"id":"G639","q":"¡Qué aburrimiento ____ ir a la escuela cada día!","o":["haber de","tener que","deber","teniendo que"],"a":1,"k":"tener que 의무","t":"매일 학교에 가야 하다니 정말 지루해!","e":"'tener que + 동사원형'은 외부 사정으로 '~해야 한다'는 의무를 나타내는 가장 일반적인 표현입니다. '¡Qué + 명사 + 동사원형!'은 '~하는 건 정말 ~이다!'라는 감탄 구조로, 여기에 원형 tener que가 들어갑니다. 'haber de'는 문어적·예스러운 표현이라 구어 감탄문에는 어색합니다.","x":["haber de: 문법적으로는 의무 표현이지만 문어체라 이런 구어 감탄문에 어색합니다 ✗","tener que: 일상적인 의무 표현 원형 → 정답 ✓","deber: 도덕적 의무(~해야 마땅하다) 느낌이 강해 매일 가야 하는 귀찮음을 표현하기에 부자연스럽습니다 ✗","teniendo que: 현재분사는 이 감탄 구조에 들어갈 수 없습니다 ✗"]},{"id":"G640","q":"No te dejes la comida en el plato, ____, por favor.","o":["cómetela","cómela","cómete","la comes"],"a":0,"k":"comerse + 대명사","t":"접시에 음식 남기지 마, 다 먹어, 제발.","e":"'comerse algo'는 '~을 남김없이 다 먹다'라는 강조의 재귀 표현입니다. 긍정 명령형에서는 재귀 대명사 te와 직접목적어 la(la comida)를 순서대로 동사 끝에 붙여 'cómetela'가 됩니다. 순서는 항상 '재귀(te) → 직접목적어(la)'입니다.","x":["cómetela: 명령 + 재귀 te + 직접목적어 la(음식) → 정답 ✓","cómela: 문법적으로는 가능하지만 '다 먹어 치워'라는 강조의 se(te)가 빠져 덜 자연스럽습니다 ✗","cómete: 무엇을 먹을지(la)가 빠져 문장이 불완전합니다 ✗","la comes: 평서문(너는 그것을 먹는다)이라 부탁하는 명령에 맞지 않습니다 ✗"]},{"id":"G641","q":"La charla que nos dio la experta ____ muy amena.","o":["resultó en","se resultaba","resultó","se resultó"],"a":2,"k":"resultar + 형용사","t":"그 전문가가 해 준 강연은 아주 재미있었다(흥미로운 것으로 드러났다).","e":"'resultar + 형용사'는 '결과적으로 ~하다, ~한 것으로 드러나다'라는 뜻으로, ser와 비슷하지만 경험한 뒤의 평가를 담습니다. resultar는 재귀형으로 쓰지 않습니다. 'ameno'는 '재미있고 즐거운(지루하지 않은)'이라는 뜻으로 강연·책 등에 자주 씁니다.","x":["resultó en: 'resultar en'은 '~라는 결과를 낳다'라는 뜻으로 형용사와 함께 쓰지 않습니다 ✗","se resultaba: resultar는 재귀형으로 쓰지 않습니다 ✗","resultó: '~한 것으로 드러났다'는 단순과거 → 정답 ✓","se resultó: 역시 재귀형이라 맞지 않습니다 ✗"]},{"id":"G642","q":"Te juro que no se lo ____ a nadie.","o":["diga","haya dicho","diré","vaya a decir"],"a":2,"k":"맹세 + 직설법 미래","t":"맹세하는데 그걸 아무에게도 말하지 않을게.","e":"'jurar(맹세하다)'는 단언·약속하는 동사라 뒤의 que절에 직설법을 씁니다. 앞으로의 약속이므로 미래형 'diré'가 맞습니다. 'se lo'는 '그 사람에게 그것을'이고, 'a nadie'와 함께 쓰여 '누구에게도 ~하지 않다'가 됩니다.","x":["diga: 접속법이라 맹세(단언) 뒤에 쓰지 않습니다 ✗","haya dicho: 접속법 현재완료라 맞지 않습니다 ✗","diré: 앞으로의 약속을 나타내는 직설법 미래 → 정답 ✓","vaya a decir: 접속법 형태라 맹세 뒤에 맞지 않습니다(직설법 voy a decir라면 가능) ✗"]},{"id":"G643","q":"¿Qué te gustaba hacer ____ pequeña?","o":["a","en","de","como"],"a":2,"k":"de + 나이·시기","t":"너는 어렸을 때 뭐 하는 걸 좋아했어?","e":"'de pequeño/pequeña, de niño/niña, de joven'처럼 'de + 형용사/명사'는 '~였을 때'라는 인생의 시기를 나타냅니다. 'cuando era pequeña'와 같은 뜻을 짧게 줄인 표현입니다. 듣는 사람이 여성이라 pequeña로 썼습니다.","x":["a: 'a pequeña'라는 표현은 쓰지 않습니다 ✗","en: 'en pequeña'는 '작은 규모로'라는 다른 뜻이 됩니다 ✗","de: 'de pequeña(어렸을 때)' → 정답 ✓","como: 'como pequeña'는 '작은 아이처럼/로서'라는 뜻이라 시기를 나타내지 못합니다 ✗"]},{"id":"G644","q":"Si ____, encontrarías un trabajo mejor en un pispás.","o":["querrías","querías","quisieras","quieras"],"a":2,"k":"가정 조건문 si","t":"네가 마음만 먹으면 금방 더 좋은 일자리를 찾을 텐데.","e":"현재 사실과 다르거나 가능성이 낮은 가정은 'si + 접속법 과거, 가능법(-ría)' 구조를 씁니다. 주절이 encontrarías(가능법)이므로 si절에는 quisieras가 들어갑니다. 'en un pispás'는 스페인의 구어 표현으로 '눈 깜짝할 사이에, 금방'이라는 뜻입니다.","x":["querrías: si 바로 뒤에는 가능법을 쓰지 않습니다 ✗","querías: 직설법 불완료과거라 주절의 가능법과 맞지 않습니다 ✗","quisieras: 가정의 si절에 쓰는 접속법 과거 → 정답 ✓","quieras: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗"]},{"id":"G645","q":"¿Qué tal si ____ algo ligero esta noche?","o":["cenemos","cenaríamos","cenaremos","cenamos"],"a":3,"k":"qué tal si + 직설법","t":"오늘 저녁은 가볍게 먹는 게 어때?","e":"'¿Qué tal si ~?'는 '~하는 게 어때?'라는 제안 표현이며, 뒤에 직설법 현재가 옵니다. si 뒤에는 접속법 현재나 미래형을 쓰지 않는다는 규칙을 그대로 따릅니다. 같은 뜻으로 '¿Y si cenamos algo ligero?'라고도 합니다.","x":["cenemos: 접속법 현재는 si 뒤에 올 수 없습니다(¿Cenamos?나 Cenemos는 따로 쓰면 가능) ✗","cenaríamos: 가능법이라 제안 표현과 맞지 않습니다 ✗","cenaremos: si 뒤에는 미래형을 쓰지 않습니다 ✗","cenamos: 제안의 qué tal si 뒤 직설법 현재 → 정답 ✓"]},{"id":"G646","q":"No he visto hoy a Cristina; ____ hecho, no la he visto en toda la semana.","o":["de","según","sobre","por"],"a":0,"k":"de hecho","t":"오늘 크리스티나를 못 봤어. 사실은 이번 주 내내 못 봤어.","e":"'de hecho'는 '사실은, 실제로'라는 뜻으로, 앞의 말을 더 강하게 보충하거나 덧붙일 때 씁니다. 여기서는 '오늘 못 봤다'에서 '이번 주 내내 못 봤다'로 내용을 강화합니다. 'hecho'는 hacer의 과거분사이자 '사실'이라는 명사입니다.","x":["de: 'de hecho(사실은)'라는 고정 표현 → 정답 ✓","según: 'según hecho'라는 표현은 없습니다 ✗","sobre: 'sobre hecho'라는 표현은 없습니다 ✗","por: 'por hecho'는 쓰지 않습니다('dar por hecho'는 '당연하게 여기다'라는 다른 표현) ✗"]},{"id":"G647","q":"Sergio tiene 50 años. ¡Nadie ____ diría!","o":["la","los","ø","lo"],"a":3,"k":"중성 대명사 lo","t":"세르히오는 50살이야. 아무도 그렇게 생각 못 할걸!","e":"'lo'는 앞에서 말한 내용 전체(세르히오가 50살이라는 사실)를 받는 중성 대명사입니다. '¡Nadie lo diría!'는 '아무도 그렇게 말하지(짐작하지) 못할 거야!', 즉 그렇게 안 보인다는 뜻입니다. 가능법 diría가 '~할 것이다'라는 추측의 느낌을 줍니다.","x":["la: 여성 단수 명사를 받는 대명사라 '그 사실'을 가리키지 못합니다 ✗","los: 남성 복수(예: 50 años)로 받을 수 없고, 문장 내용 전체는 중성 lo로 받습니다 ✗","ø: decir는 목적어가 필요해 대명사를 생략하면 어색합니다 ✗","lo: 앞의 내용 전체를 받는 중성 대명사 → 정답 ✓"]},{"id":"G648","q":"Por fin han pillado ____ robó en la tienda de mi tía.","o":["a que","al que","al quien","quien"],"a":1,"k":"관계사 el que","t":"드디어 우리 이모 가게에서 도둑질한 사람을 잡았대.","e":"'el que'는 '~한 사람'이라는 뜻의 관계사로, 여기서는 pillar(잡다)의 사람 목적어라 'a'가 필요해 'al que'가 됩니다(a + el que). 사람 직접목적어 앞의 a(인칭 a)를 잊지 마세요. 'pillar'는 스페인 구어로 '붙잡다, 걸리다'라는 뜻입니다.","x":["a que: 관사가 없어 '~한 사람'이라는 뜻이 되지 않습니다 ✗","al que: 인칭 a + 관계사 el que → 정답 ✓","al quien: quien 앞에는 관사를 붙이지 않습니다(a quien은 가능) ✗","quien: 사람 목적어 앞의 인칭 a가 빠져 문법적으로 맞지 않습니다 ✗"]},{"id":"G649","q":"Después de las fiestas navideñas, tengo que ponerme ____ dieta como sea.","o":["a","por","en","de"],"a":0,"k":"ponerse a dieta","t":"연말 연휴가 끝나면 무슨 일이 있어도 다이어트를 시작해야 한다.","e":"'ponerse a dieta'는 '다이어트를 시작하다', 'estar a dieta'는 '다이어트 중이다'라는 고정 표현으로 전치사 a를 씁니다. 중남미 일부와 스페인 구어에서는 'estar/ponerse de dieta'라고도 하지만 교재는 a를 기준으로 합니다. 'como sea'는 '어떻게 해서든, 무슨 일이 있어도'라는 뜻입니다.","x":["a: 'ponerse a dieta(다이어트를 시작하다)' → 정답 ✓","por: 원인·경로를 나타내 이 표현과 맞지 않습니다 ✗","en: 'en dieta'는 쓰지 않습니다 ✗","de: 'de dieta'도 일부 지역에서 쓰지만 이 교재의 기준 표현은 a dieta입니다 ✗"]},{"id":"G650","q":"No puedes salir aún. Ya te he dicho que ____ castigado.","o":["has estado","estás","estés","estuvieses"],"a":1,"k":"estar + 과거분사","t":"아직 나가면 안 돼. 너는 벌 받는 중이라고 이미 말했잖아.","e":"'estar + 과거분사'는 어떤 행동의 결과로 생긴 현재 상태를 나타냅니다. 'estar castigado'는 '벌을 받고 있는 상태다(외출 금지 중이다)'라는 뜻입니다. 'Ya te he dicho que'는 사실을 전하는 말이라 que절에 직설법을 씁니다.","x":["has estado: '벌 받아 왔다'는 현재완료로, 지금도 나가면 안 된다는 현재 상태를 직접 나타내지 못합니다 ✗","estás: 현재 상태를 나타내는 estar 현재형 → 정답 ✓","estés: 접속법이라 사실을 전하는 decir que 뒤에 맞지 않습니다 ✗","estuvieses: 접속법 과거라 서법·시제 모두 맞지 않습니다 ✗"]},{"id":"G651","q":"____ quiera participar en el concurso, que levante la mano.","o":["El quien","Que","Lo que","Quien"],"a":3,"k":"관계사 quien + 접속법","t":"대회에 참가하고 싶은 사람은 손을 드세요.","e":"'Quien'은 앞에 명사 없이 '~하는 사람(누구든)'이라는 뜻으로 홀로 쓰일 수 있습니다. 참가하고 싶은 사람이 누구인지 정해지지 않았으므로 관계절에 접속법(quiera)을 씁니다. 'que levante la mano'는 3인칭에게 하는 간접 명령(~하게 하라)입니다.","x":["El quien: quien 앞에는 관사를 붙이지 않습니다(el que는 가능) ✗","Que: 관사 없는 que 혼자서는 '~하는 사람'이라는 주어가 되지 못합니다 ✗","Lo que: '~하는 것'이라는 사물·내용을 가리켜 사람이 되지 않습니다 ✗","Quien: '~하는 사람(누구든)'이라는 관계사 → 정답 ✓"]},{"id":"G652","q":"Esos plátanos ____ a pudrir si no se los come nadie.","o":["irán","irían","van","se van"],"a":3,"k":"pudrirse 재귀","t":"아무도 안 먹으면 그 바나나들은 썩을 거야.","e":"'썩다'는 재귀동사 'pudrirse'입니다. 'ir a + 동사원형'과 함께 쓰면 대명사 se를 앞으로 빼서 'se van a pudrir'로 쓸 수 있습니다(van a pudrirse와 같음). 현재 조건(si no se los come nadie)에 따른 가까운 미래이므로 ir a 현재형이 자연스럽습니다.","x":["irán: 미래형 ir a도 이론상 가능하지만 재귀 se가 빠져 pudrir가 '썩게 하다'처럼 되어 버립니다 ✗","irían: 가능법이고 se도 빠져 맞지 않습니다 ✗","van: se가 빠져 재귀동사 pudrirse가 완성되지 않습니다 ✗","se van: 재귀 se + ir a 구문으로 '썩을 것이다' → 정답 ✓"]},{"id":"G653","q":"Nuestro hijo tiene que protegerse ____.","o":["sí mismo","a sí mismo","consigo mismo","su mismo"],"a":1,"k":"재귀 강조 a sí mismo","t":"우리 아들은 스스로를 지켜야 한다.","e":"'proteger a alguien(누구를 보호하다)'처럼 사람 목적어 앞에는 인칭 a가 붙습니다. 재귀를 강조할 때는 'a sí mismo(자기 자신을)'를 덧붙여 'protegerse a sí mismo'가 됩니다. 'sí'는 전치사 뒤에 오는 재귀 대명사로 악센트가 있습니다.","x":["sí mismo: 사람 목적어 앞의 a가 빠져 있습니다 ✗","a sí mismo: 인칭 a + 재귀 강조 → 정답 ✓","consigo mismo: '자기 자신과 함께'라는 뜻이라 보호의 대상이 되지 않습니다 ✗","su mismo: 소유사 su와 mismo를 이렇게 결합하지 않습니다 ✗"]},{"id":"G654","q":"____ ser verdad lo que dicen, tendremos que avisar a nuestros compañeros.","o":["Al","Como","De","Si"],"a":2,"k":"de + 원형 조건","t":"그들이 하는 말이 사실이라면, 우리는 동료들에게 알려야 할 것이다.","e":"'de + 동사원형'은 문장 앞에서 'si(만약 ~라면)'와 같은 조건을 나타내는 격식 있는 표현입니다. 'De ser verdad'는 'Si es verdad'와 같은 뜻입니다. 예: 'De haberlo sabido, no habría venido.(알았더라면 오지 않았을 텐데.)'","x":["Al: 'al + 원형'은 '~할 때'라는 시간을 나타내 조건이 되지 않습니다 ✗","Como: como 뒤에는 원형이 아니라 활용된 동사가 옵니다 ✗","De: 'de + 원형'의 조건 표현 → 정답 ✓","Si: si 뒤에는 원형이 올 수 없고 'Si es verdad'처럼 활용해야 합니다 ✗"]},{"id":"G655","q":"Hoy ____ particularmente nerviosa. No sé qué me pasa.","o":["se encuentra","encuentro","me encuentro","me encontraría"],"a":2,"k":"encontrarse 상태","t":"오늘 나는 유난히 초조하다. 내가 왜 이러는지 모르겠다.","e":"'encontrarse + 형용사'는 '(기분·몸 상태가) ~하다'라는 뜻으로 estar와 비슷하지만 조금 더 격식 있는 느낌입니다. 이 뜻으로 쓸 때는 반드시 재귀 형태(me encuentro)를 씁니다. nerviosa가 여성 1인칭이고 뒤에 'me pasa'가 있으므로 주어는 '나'입니다.","x":["se encuentra: 3인칭(그녀/당신)이라 뒤의 '나에게 무슨 일인지(me pasa)'와 맞지 않습니다 ✗","encuentro: se 없이 encontrar는 '찾다'라는 뜻이 됩니다 ✗","me encuentro: 재귀 encontrarse(~한 상태다) 1인칭 → 정답 ✓","me encontraría: 가능법이라 지금의 상태를 말하는 문장과 맞지 않습니다 ✗"]},{"id":"G656","q":"____ sobra sabes que te acompañaría, pero ese día tengo que trabajar.","o":["De","A","Con","Por"],"a":0,"k":"관용 표현 de sobra","t":"내가 너랑 같이 가 주고 싶다는 건 너도 충분히 알잖아. 그런데 그날 나는 일해야 해.","e":"'de sobra'는 '넘치도록, 충분히'라는 뜻으로, 'saber de sobra'는 '아주 잘 알다, 뻔히 알다'라는 관용 표현입니다. 강조를 위해 문장 앞에 두었습니다. 'sobrar(남다)'에서 나온 말로 'Tengo tiempo de sobra(시간이 남아돈다)'처럼도 씁니다.","x":["De: 'de sobra(충분히)'라는 고정 표현 → 정답 ✓","A: 'a sobra'라는 표현은 없습니다 ✗","Con: 'con sobra'는 쓰지 않습니다('con creces'는 '넘치게'라는 다른 표현) ✗","Por: 'por sobra'는 쓰지 않습니다 ✗"]},{"id":"G657","q":"Hemos avanzado, pero ____ nos queda mucho camino por recorrer.","o":["incluso","aun","aún","ya"],"a":2,"k":"aún vs aun","t":"우리가 진전은 했지만, 아직 가야 할 길이 많이 남아 있다.","e":"악센트가 있는 'aún'은 '아직(todavía)'이라는 뜻이고, 악센트가 없는 'aun'은 '~조차(incluso)'라는 뜻입니다. 여기서는 '아직 갈 길이 많다'이므로 aún이 맞습니다. 'quedar mucho camino por recorrer'는 '갈 길이 멀다'라는 표현입니다.","x":["incluso: '~조차, 심지어'라는 뜻이라 문맥과 맞지 않습니다 ✗","aun: 악센트가 없으면 '~조차'라는 뜻이 됩니다 ✗","aún: '아직(todavía)'이라는 뜻의 부사 → 정답 ✓","ya: '이미'라는 뜻이라 '갈 길이 남아 있다'와 충돌합니다 ✗"]},{"id":"G658","q":"No hay ____ remedio que llamar al electricista.","o":["tal","más","tanto","ø"],"a":1,"k":"no hay más remedio","t":"전기 기사를 부르는 것 말고는 방법이 없다.","e":"'No hay más remedio que + 동사원형'은 '~하는 수밖에 없다'라는 고정 표현입니다. 'remedio'는 '해결책, 방법'이고, 'más ~ que'가 '~ 외에 다른'이라는 뜻을 만듭니다. 같은 뜻으로 'No queda otra (opción) que ~'라고도 합니다.","x":["tal: 'tal remedio'는 '그런 방법'이라 que와 이어지지 않습니다 ✗","más: 'no hay más remedio que(~하는 수밖에 없다)' → 정답 ✓","tanto: tanto는 que와 짝이 되면 결과 표현이 되어 의미가 맞지 않습니다 ✗","ø: 'no hay remedio'만으로는 '어쩔 수 없다'는 뜻이고 que와 이어지지 않습니다 ✗"]},{"id":"G659","q":"Mi abuelo tiene la manía ____ cerrar la puerta con llave incluso estando dentro de casa.","o":["por","para","a","de"],"a":3,"k":"tener la manía de","t":"우리 할아버지는 집 안에 있을 때조차 문을 열쇠로 잠그는 버릇이 있다.","e":"'tener la manía de + 동사원형'은 '~하는 (이상한) 버릇이 있다'라는 뜻입니다. 명사 뒤에서 그 내용을 설명할 때는 전치사 de를 씁니다(la costumbre de, la idea de). 'estando dentro'는 '안에 있을 때조차'라는 현재분사 구문입니다.","x":["por: 원인·이유를 나타내 manía와 짝을 이루지 않습니다 ✗","para: 목적을 나타내 의미가 맞지 않습니다 ✗","a: manía와 함께 쓰는 전치사가 아닙니다 ✗","de: 명사 manía의 내용을 설명하는 de → 정답 ✓"]},{"id":"G660","q":"El trabajo te saldrá mejor ____ vayas adquiriendo experiencia.","o":["hasta que","nada más","a medida que","en cuanto que"],"a":2,"k":"a medida que","t":"경험을 쌓아 갈수록 너는 일을 더 잘하게 될 거야.","e":"'a medida que'는 '~함에 따라, ~할수록'이라는 뜻으로 두 가지 일이 함께 점점 변하는 것을 나타냅니다. 미래의 일이므로 뒤에 접속법(vayas)이 왔습니다. 'ir + 현재분사'는 '점점 ~해 가다'라는 뜻이라 a medida que와 잘 어울립니다.","x":["hasta que: '~할 때까지'라 '할수록 좋아진다'는 의미와 맞지 않습니다 ✗","nada más: '~하자마자'라는 뜻으로 보통 원형과 함께 쓰여 맞지 않습니다 ✗","a medida que: '~할수록'이라는 비례 표현 → 정답 ✓","en cuanto que: '~라는 점에서'라는 다른 뜻의 표현입니다 ✗"]},{"id":"G661","q":"En verano, me gusta que el café ____ bien frío.","o":["ha estado","está","esté","estuviese"],"a":2,"k":"gustar que + 접속법","t":"여름에 나는 커피가 아주 차가운 게 좋다.","e":"'Me gusta que ~(~하는 게 좋다)'처럼 좋고 싫음을 나타내는 표현 뒤 que절에는 접속법을 씁니다. 주절이 현재(gusta)이므로 접속법 현재 esté가 맞고, 커피의 일시적인 온도 상태라 estar를 씁니다.","x":["ha estado: 직설법 현재완료라 맞지 않습니다 ✗","está: 직설법이라 gustar que 뒤에 쓰지 않습니다 ✗","esté: gustar que 뒤의 접속법 현재 → 정답 ✓","estuviese: 접속법 과거라 현재 주절과 시제가 맞지 않습니다 ✗"]},{"id":"G662","q":"Ten cuidado ____ ese tipo, no es trigo limpio.","o":["con","hacia","de","por"],"a":0,"k":"tener cuidado con","t":"저 녀석 조심해, 믿을 만한 사람이 아니야.","e":"'tener cuidado con algo/alguien'은 '~을 조심하다'라는 뜻으로 전치사 con을 씁니다. 'no ser trigo limpio'는 직역하면 '깨끗한 밀이 아니다'로, '믿을 수 없는 사람이다, 수상하다'라는 관용 표현입니다. 'ese tipo'는 '저 녀석'이라는 약간 낮춘 구어 표현입니다.","x":["con: 'tener cuidado con(~을 조심하다)' → 정답 ✓","hacia: 방향(~쪽으로)을 나타내 cuidado와 짝이 되지 않습니다 ✗","de: 'tener cuidado de + 원형'은 '~하도록 주의하다'라는 다른 구조입니다 ✗","por: cuidado와 짝을 이루지 않습니다 ✗"]},{"id":"G663","q":"Mi perro, ____ me ve, se pone a ladrar como loco.","o":["puesto que","como que","antes que","siempre que"],"a":3,"k":"siempre que","t":"우리 개는 나를 볼 때마다 미친 듯이 짖기 시작한다.","e":"'siempre que + 직설법'은 '~할 때마다(cada vez que)'라는 뜻입니다. 반면 'siempre que + 접속법'은 '~하기만 하면(조건)'이라는 뜻으로 바뀝니다. 여기서는 현재의 습관이라 직설법 ve가 쓰였습니다. 'ponerse a + 원형'은 '~하기 시작하다'입니다.","x":["puesto que: '~이므로'라는 원인 접속사라 맞지 않습니다 ✗","como que: '~인 것처럼/~라는 듯이'라는 구어 표현이라 맞지 않습니다 ✗","antes que: '~보다 먼저/차라리'라는 뜻이고 접속법과 쓰여 맞지 않습니다 ✗","siempre que: 직설법과 함께 '~할 때마다' → 정답 ✓"]},{"id":"G664","q":"¡____ mal canta el abuelo!","o":["Vaya","Cómo","Qué","Menudo"],"a":2,"k":"감탄문 qué + 부사","t":"할아버지는 노래를 정말 못 부르셔!","e":"'¡Qué + 형용사/부사 + 동사!'는 '정말 ~하구나!'라는 감탄문입니다. 'Qué mal canta'는 '정말 노래를 못한다'는 뜻입니다. 'cómo'를 쓰려면 '¡Cómo canta!'처럼 부사 없이 쓰거나 '¡Cómo canta de mal!'처럼 de가 필요합니다.","x":["Vaya: 'vaya + 명사(¡Vaya voz!)' 형태로 쓰며 부사 mal 앞에는 쓰지 않습니다 ✗","Cómo: 'cómo mal'처럼 부사를 바로 붙이지 않습니다 ✗","Qué: 'qué + 부사'의 감탄문 → 정답 ✓","Menudo: '대단한 ~'이라는 뜻의 형용사로 명사 앞(menudo cantante)에 씁니다 ✗"]},{"id":"G665","q":"Nos trató como si ____ extraños.","o":["somos","fuéramos","estuviéramos","estábamos"],"a":1,"k":"como si + 접속법 과거","t":"그는 우리를 마치 모르는 사람처럼 대했다.","e":"'como si(마치 ~인 것처럼)' 뒤에는 항상 접속법 과거(또는 과거완료)를 씁니다. '모르는 사람이다'는 정체·신분이므로 ser를 쓰고, 그래서 'fuéramos'가 정답입니다. 'tratar a alguien como ~'는 '누구를 ~처럼 대하다'입니다.","x":["somos: 직설법이라 como si 뒤에 쓸 수 없습니다 ✗","fuéramos: ser의 접속법 과거 → 정답 ✓","estuviéramos: estar는 '낯선 사람'이라는 정체를 나타내지 못합니다 ✗","estábamos: estar + 직설법이라 두 가지 모두 틀립니다 ✗"]},{"id":"G666","q":"Me alegro mucho ____ ti, te lo mereces.","o":["para","hacia","de","por"],"a":3,"k":"alegrarse por","t":"정말 잘됐다, 너는 그럴 자격이 있어.","e":"'alegrarse por alguien'은 '누군가 때문에(누군가를 위해) 기뻐하다'라는 뜻으로, 상대에게 좋은 일이 생겼을 때 축하하는 말입니다. 'alegrarse de algo'는 '어떤 일이 기쁘다'로, 사람이 아니라 일·사실과 함께 씁니다(Me alegro de verte). 'Te lo mereces'는 '넌 그럴 만해'입니다.","x":["para: 목적(~을 위해 하다)이라 감정의 원인을 나타내지 못합니다 ✗","hacia: 방향·감정의 대상(~을 향한)을 나타내지만 alegrarse와 쓰지 않습니다 ✗","de: alegrarse de는 일·사실과 함께 쓰며 사람에게는 por를 씁니다 ✗","por: 사람 때문에 기뻐하다 → 정답 ✓"]},{"id":"G667","q":"Los niños ya estaban sentados en ____ asientos cuando entró la maestra.","o":["sus respectivos","sus varios","muchos de sus","unos cuantos"],"a":0,"k":"respectivo","t":"선생님이 들어왔을 때 아이들은 이미 각자 자리에 앉아 있었다.","e":"'sus respectivos + 명사'는 '각자의 ~'라는 뜻으로, 여러 사람이 각각 자기 것을 가질 때 씁니다. 아이마다 자기 자리가 하나씩 있으므로 respectivos가 자연스럽습니다. 'estar sentado'는 '앉아 있는 상태'입니다.","x":["sus respectivos: '각자의 자리' → 정답 ✓","sus varios: varios는 '여러 개의'라는 뜻으로 소유사와 이렇게 쓰지 않습니다 ✗","muchos de sus: '그들의 자리 중 많은 곳'이 되어 의미가 이상하고 구조도 맞지 않습니다 ✗","unos cuantos: '몇몇의 자리'라는 뜻으로 '각자의 자리'가 되지 않습니다 ✗"]},{"id":"G668","q":"María y yo frecuentamos ____ este restaurante porque nos encanta la comida y el servicio.","o":["a","en","ø","por"],"a":2,"k":"frecuentar 타동사","t":"마리아와 나는 음식과 서비스가 정말 좋아서 이 식당에 자주 간다.","e":"'frecuentar'는 '~에 자주 가다'라는 뜻의 타동사(목적어를 바로 받는 동사)라 전치사 없이 장소를 바로 씁니다. 장소는 사람이 아니므로 인칭 a도 필요 없습니다. 같은 뜻으로 'ir a menudo a este restaurante'라고 할 수도 있습니다.","x":["a: 사물·장소 목적어에는 인칭 a를 붙이지 않습니다 ✗","en: frecuentar는 전치사 없이 목적어를 받습니다 ✗","ø: 타동사라 목적어를 바로 받음 → 정답 ✓","por: '~ 근처를'이라는 뜻이 되어 '자주 가다'와 맞지 않습니다 ✗"]},{"id":"G669","q":"Aquí no ____ nadie, vámonos.","o":["está","es","tiene","hay"],"a":3,"k":"hay nadie","t":"여기 아무도 없어, 가자.","e":"'누가/무엇이 있다·없다'라는 존재는 'hay'(haber의 무인칭형)로 나타냅니다. 'nadie(아무도)'처럼 정해지지 않은 대상은 estar가 아니라 hay를 씁니다. estar는 'Juan no está(후안은 없다)'처럼 정해진 사람·사물의 위치를 말할 때 씁니다.","x":["está: estar는 정해진 대상의 위치를 말할 때 써서 nadie와 어울리지 않습니다 ✗","es: ser는 존재를 나타내지 않습니다 ✗","tiene: '가지다'라는 뜻이라 주어가 없어 의미가 성립하지 않습니다 ✗","hay: 불특정 대상의 존재를 나타냄 → 정답 ✓"]},{"id":"G670","q":"Nado todos los días ____ excepción del domingo.","o":["por","de","con","a"],"a":3,"k":"a excepción de","t":"나는 일요일을 제외하고 매일 수영한다.","e":"'a excepción de'는 '~을 제외하고'라는 고정 표현으로, 'excepto, salvo, menos'와 같은 뜻입니다. 같은 뜻으로 'con excepción de'도 쓰지만 이때는 de가 아니라 con이 앞에 와야 하고, 이 문제에서는 a가 기준 답입니다.","x":["por: 'por excepción'은 '예외적으로'라는 뜻으로 de와 이어지지 않습니다 ✗","de: 'de excepción'은 '예외적인'이라는 형용사구가 됩니다 ✗","con: 'con excepción de'도 쓰이지만 교재 기준 표현은 a excepción de입니다 ✗","a: 'a excepción de(~을 제외하고)' → 정답 ✓"]},{"id":"G671","q":"Siempre se van de vacaciones ____ mediados de septiembre.","o":["de","en","a","por"],"a":2,"k":"a mediados de","t":"그들은 늘 9월 중순에 휴가를 떠난다.","e":"달·해·세기의 '초/중순/말'은 'a principios de / a mediados de / a finales de'로 나타냅니다. 모두 전치사 a를 쓴다는 점이 핵심입니다. 'irse de vacaciones'는 '휴가를 떠나다'입니다.","x":["de: 'de mediados de'는 '중순부터의'라는 다른 의미가 됩니다 ✗","en: 'en mediados de'는 쓰지 않습니다 ✗","a: 'a mediados de(~ 중순에)' → 정답 ✓","por: 'por mediados'는 '중순쯤'이라는 비표준적 표현이라 기준 답이 아닙니다 ✗"]},{"id":"G672","q":"Al igual ____, no puedo permitirme comprar nada más este mes.","o":["de ti","como tú","que tú","que ti"],"a":2,"k":"al igual que","t":"너와 마찬가지로 나도 이번 달엔 더 이상 아무것도 살 여유가 없다.","e":"'al igual que + 주어'는 '~와 마찬가지로'라는 뜻입니다. que 뒤는 비교의 대상이 주어 역할을 하므로 'ti'가 아니라 주격 'tú'를 씁니다. 'permitirse + 원형'은 '~할 (경제적) 여유가 있다'라는 뜻입니다.","x":["de ti: al igual 뒤에는 de가 아니라 que가 옵니다 ✗","como tú: 'igual que'와 'como'를 섞은 형태로 맞지 않습니다 ✗","que tú: 'al igual que + 주격(tú)' → 정답 ✓","que ti: que 뒤는 전치사 뒤가 아니라서 ti를 쓰지 않습니다 ✗"]},{"id":"G673","q":"Voy a ir a trabajar ____ mal que me sienta.","o":["por muy","aun","por lo","por mucho"],"a":0,"k":"por muy + 형용사 + que","t":"아무리 몸이 안 좋아도 나는 일하러 갈 거다.","e":"'por muy + 형용사/부사 + que + 접속법'은 '아무리 ~하더라도'라는 양보 표현입니다. 여기 'me sienta'는 sentirse(몸 상태가 ~하다)의 접속법 현재입니다(직설법은 me siento). 'por mucho que + 동사'는 형용사·부사가 아니라 동사 자체를 강조할 때 씁니다(por mucho que trabaje).","x":["por muy: 부사 mal 앞에서 '아무리 ~해도' → 정답 ✓","aun: 'aun mal que'라는 구조는 없습니다 ✗","por lo: 'por lo mal que'는 '너무 안 좋아서'라는 원인이 됩니다 ✗","por mucho: 부사 mal 앞에는 mucho가 아니라 muy를 씁니다 ✗"]},{"id":"G674","q":"¿____ encargas tú de regar las plantas?","o":["ø","Lo","Se","Te"],"a":3,"k":"encargarse de","t":"화분에 물 주는 건 네가 맡아 줄래?","e":"'encargarse de algo'는 '~을 맡다, 담당하다'라는 뜻의 재귀동사입니다. 주어가 tú이므로 재귀 대명사도 te가 되어 '¿Te encargas tú de ~?'가 됩니다. 반면 'encargar algo'는 '주문하다, 맡기다'라는 다른 뜻입니다.","x":["ø: 재귀 대명사가 없으면 encargar(주문하다/맡기다)가 되어 de와 맞지 않습니다 ✗","Lo: 직접목적어 '그것을'이라 재귀동사가 되지 않습니다 ✗","Se: 3인칭 재귀라 주어 tú와 맞지 않습니다 ✗","Te: tú에 맞는 재귀 대명사 → 정답 ✓"]},{"id":"G675","q":"Lloraba para que le ____ atención.","o":["prestarían","prestaran","prestaban","presten"],"a":1,"k":"para que + 접속법","t":"그는 사람들이 자기에게 관심을 가져 주도록 울곤 했다.","e":"'para que(~하도록)'는 목적을 나타내며 항상 접속법을 씁니다. 주절이 과거(lloraba)이므로 접속법 과거 prestaran이 맞습니다. 'prestar atención a alguien'은 '누구에게 관심·주의를 기울이다'입니다.","x":["prestarían: 가능법이라 para que 뒤에 쓰지 않습니다 ✗","prestaran: 과거 주절에 맞는 접속법 과거 → 정답 ✓","prestaban: 직설법이라 para que 뒤에 쓰지 않습니다 ✗","presten: 접속법 현재라 과거 주절과 시제가 맞지 않습니다 ✗"]},{"id":"G676","q":"Repetid el ejercicio tantas veces ____ necesario hasta que os salga bien.","o":["como sea","que es","como es","que sea"],"a":0,"k":"tantas veces como","t":"제대로 될 때까지 필요한 만큼 몇 번이고 연습 문제를 반복해라.","e":"'tantas veces como sea necesario'는 '필요한 만큼 여러 번'이라는 고정 표현입니다. 'tanto ~ como'는 동등 비교의 짝이므로 que가 아니라 como를 씁니다. 몇 번이 필요할지 정해지지 않은 미래의 일이라 접속법 sea를 씁니다.","x":["como sea: tanto와 짝인 como + 미정의 접속법 → 정답 ✓","que es: tantas와 짝은 que가 아니며 직설법도 맞지 않습니다 ✗","como es: como는 맞지만 직설법이라 정해지지 않은 횟수를 나타내지 못합니다 ✗","que sea: 접속법은 맞지만 tantas와 짝은 como입니다 ✗"]},{"id":"G677","q":"Yo pienso que Inés no es ____ atractiva.","o":["nada","ninguna","algo","ni tan"],"a":0,"k":"부정 강조 nada","t":"나는 이네스가 전혀 매력적이지 않다고 생각한다.","e":"'no ~ nada + 형용사'는 '전혀 ~하지 않다'라는 강한 부정입니다. 이때 nada는 부사라서 형용사의 성·수와 상관없이 형태가 변하지 않습니다. 예: 'No es nada fácil.(전혀 쉽지 않다.)'","x":["nada: 형용사를 부정 강조하는 부사 '전혀' → 정답 ✓","ninguna: 형용사(어떤 ~도 없는)라 명사 앞에 쓰며 형용사 atractiva를 꾸미지 못합니다 ✗","algo: '약간'이라는 뜻이라 'no es algo atractiva'는 어색합니다 ✗","ni tan: 'ni tan siquiera' 등에 쓰는 형태로 이 문장에 맞지 않습니다 ✗"]},{"id":"G678","q":"¿Por qué ha tardado tanto ____ llegar?","o":["sin","de","en","a"],"a":2,"k":"tardar en","t":"그는 왜 이렇게 늦게 도착했을까?(도착하는 데 왜 그렇게 오래 걸렸지?)","e":"'tardar en + 동사원형'은 '~하는 데 시간이 걸리다'라는 고정 표현입니다. 'tardar mucho en llegar'는 '도착하는 데 오래 걸리다, 늦게 오다'입니다. 예: '¿Cuánto tardas en llegar al trabajo?(출근하는 데 얼마나 걸려?)'","x":["sin: '~하지 않고'라는 뜻이라 맞지 않습니다 ✗","de: tardar와 짝이 되는 전치사가 아닙니다 ✗","en: 'tardar en(~하는 데 걸리다)' → 정답 ✓","a: 일부 지역 구어에서 들리기도 하지만 표준은 tardar en입니다 ✗"]},{"id":"G679","q":"Este mes estoy ____ guardia en el hospital los fines de semana.","o":["para","de","con","a"],"a":1,"k":"estar de guardia","t":"이번 달 나는 주말마다 병원에서 당직을 선다.","e":"'estar de guardia'는 '당직 중이다, 당번이다'라는 뜻입니다. 'estar de + 명사'는 일시적인 역할·상태를 나타내는 구조로 'estar de vacaciones(휴가 중)', 'estar de viaje(여행 중)'처럼 씁니다. 약국의 '당번 약국'은 'farmacia de guardia'라고 합니다.","x":["para: 목적을 나타내 이 표현이 되지 않습니다 ✗","de: 'estar de guardia(당직 중이다)' → 정답 ✓","con: 'con guardia'는 '경호원과 함께'처럼 되어 의미가 다릅니다 ✗","a: 'a guardia'라는 표현은 쓰지 않습니다 ✗"]},{"id":"G680","q":"____ en varios países me ayudó a aprender idiomas.","o":["Haber vivido","Habido vivido","Habiendo vivido","Viviendo"],"a":0,"k":"완료 원형 주어","t":"여러 나라에서 살아 본 것이 내가 외국어를 배우는 데 도움이 되었다.","e":"동사가 문장의 주어(~한 것은)로 쓰일 때는 동사원형을 씁니다. 도움이 된 시점보다 먼저 산 경험이므로 완료 원형 'haber vivido(살았던 것)'가 맞습니다. 스페인어에서 현재분사(-ndo)는 영어 -ing와 달리 문장의 주어가 될 수 없습니다.","x":["Haber vivido: 주어 역할의 완료 원형 → 정답 ✓","Habido vivido: 과거분사를 두 번 쓴 잘못된 형태입니다 ✗","Habiendo vivido: 현재분사는 문장의 주어가 될 수 없습니다 ✗","Viviendo: 현재분사라 주어가 될 수 없습니다(영어 -ing와 다름) ✗"]},{"id":"G681","q":"¿Me das ____ bolígrafo? Es que este no tiene tinta.","o":["otro cualquiera","un otro","otro","ningún otro"],"a":2,"k":"otro 관사 없음","t":"다른 볼펜 하나 줄래? 이건 잉크가 없어서.","e":"'otro'는 그 자체로 '다른 하나'라는 뜻이라 앞에 부정관사 un을 붙이지 않습니다(영어 another와 달리 un otro ✗). '¿Me das ~?'는 '~ 줄래?'라는 친근한 부탁이고, 'Es que'는 '그게 말이야, ~라서'라는 이유 설명입니다.","x":["otro cualquiera: 'otro bolígrafo cualquiera'처럼 명사 뒤에 와야 자연스러운 형태라 순서가 어색합니다 ✗","un otro: otro 앞에 un을 붙이지 않습니다 ✗","otro: '다른 하나'라는 뜻의 형용사 → 정답 ✓","ningún otro: '다른 어떤 것도 아닌'이라는 부정이라 부탁 문장과 맞지 않습니다 ✗"]},{"id":"G682","q":"¿Alguien comprende el ____ de su rabieta?","o":["por que","por qué","porqué","porqué"],"a":2,"k":"명사 porqué","t":"그가 떼를 쓴 이유를 누가 이해하겠어?","e":"'el porqué'는 '이유(la razón)'라는 뜻의 명사로, 붙여 쓰고 악센트를 붙입니다. 관사 el 뒤에 왔으므로 명사 porqué가 정답입니다. 'por qué'(띄어 씀, 악센트)는 의문사 '왜', 'porque'(붙여 씀, 악센트 없음)는 '왜냐하면', 'por que'는 '전치사 + 관계사'입니다. 'rabieta'는 아이의 '떼, 짜증'입니다.","x":["por que: 전치사 + 관계사라 관사 el 뒤에 명사로 올 수 없습니다 ✗","por qué: 의문사 '왜'라 관사 el 뒤에 쓰지 않습니다 ✗","porqué: 관사와 함께 쓰는 명사 '이유' → 정답 ✓","porqué: 보기 C와 철자가 똑같아 실제로는 같은 정답입니다(교재 보기 중복) ✗"],"f":"보기 C와 D가 똑같이 'porqué'로 중복되어 D도 사실상 정답입니다."},{"id":"G683","q":"Domina el inglés ____ vivió casi 20 años en Estados Unidos.","o":["aunque","pese a que","porque","como"],"a":2,"k":"원인 porque","t":"그는 미국에서 거의 20년을 살았기 때문에 영어를 유창하게 한다.","e":"주절 뒤에서 이유를 설명할 때는 'porque(왜냐하면, ~때문에)'를 씁니다. 원인 접속사 como도 있지만 como는 문장 맨 앞에 와야 합니다(Como vivió..., domina el inglés). 'dominar un idioma'는 '언어를 완벽히 구사하다'입니다.","x":["aunque: '~에도 불구하고'라는 양보라 의미가 반대가 됩니다 ✗","pese a que: aunque와 같은 양보 표현이라 맞지 않습니다 ✗","porque: 주절 뒤에서 이유를 나타냄 → 정답 ✓","como: 원인의 como는 문장 앞에 와야 하므로 이 위치에는 맞지 않습니다 ✗"]},{"id":"G684","q":"En relación ____ la población que sigue en paro, los datos son alarmantes.","o":["de","por","con","a"],"a":2,"k":"en relación con","t":"여전히 실직 상태인 인구와 관련해서, 데이터는 우려스러운 수준이다.","e":"'~와 관련하여'는 'en relación con' 또는 'con relación a'가 표준 표현입니다. 'en relación a'도 실제로 많이 쓰이지만 규범적으로는 덜 권장되는 혼합형이라 교재는 con을 정답으로 합니다. 'estar en paro'는 스페인에서 '실업 상태다'라는 뜻이며 중남미에서는 'estar desempleado/sin trabajo'를 주로 씁니다.","x":["de: 'en relación de'는 쓰지 않습니다 ✗","por: 'en relación por'는 쓰지 않습니다 ✗","con: 표준 표현 'en relación con' → 정답 ✓","a: 'en relación a'는 흔히 쓰이지만 규범상 덜 권장되는 형태입니다 ✗"]},{"id":"G685","q":"____ a verte el sábado, pero no estabas.","o":["Venimos","Veníamos","Hemos venido","Vinimos"],"a":3,"k":"단순과거 vs 불완료","t":"토요일에 너를 보러 갔었는데, 너는 없었어.","e":"'el sábado'라는 특정 시점에 한 번 일어나고 끝난 행동은 단순과거(vinimos)로 씁니다. 반면 'no estabas'는 그때의 배경 상태라 불완료과거입니다. 스페인어에서는 상대방이 있는 곳으로 가는 것을 상대 입장에서 venir로 말하기도 합니다.","x":["Venimos: venir의 현재형이라 지난 토요일의 일을 나타내지 못합니다(과거는 vinimos) ✗","Veníamos: 불완료과거라 '오던 중이었다'는 배경이 되어 완료된 방문을 나타내지 못합니다 ✗","Hemos venido: 현재완료는 지난 토요일처럼 끝난 시점과 쓰지 않습니다(스페인 기준) ✗","Vinimos: 특정 시점에 끝난 행동의 단순과거 → 정답 ✓"]},{"id":"G686","q":"____ vayas practicando, te saldrá mejor este tipo de ejercicios.","o":["Cuanto","A medida que","Desde que","Si"],"a":1,"k":"a medida que","t":"연습을 해 나갈수록 이런 유형의 연습 문제가 더 잘 풀릴 거야.","e":"'a medida que'는 '~함에 따라, ~할수록'이라는 점진적 변화를 나타냅니다. 미래의 일이므로 접속법(vayas practicando)을 쓰고, 'ir + 현재분사'가 '점점 ~해 가다'라는 의미를 더합니다. 'salirle bien a alguien'은 '(일이) 잘되다'라는 뜻입니다.","x":["Cuanto: 'cuanto más practiques'처럼 más/menos가 있어야 '~할수록'이 됩니다 ✗","A medida que: '~할수록'의 비례 표현 → 정답 ✓","Desde que: '~한 이후로'라 과거 시작점을 나타내 미래 문장과 맞지 않습니다 ✗","Si: si 뒤에는 접속법 현재(vayas)를 쓸 수 없습니다 ✗"]},{"id":"G687","q":"Cuando llegamos anoche, ya se lo ____ todo.","o":["zampaban","han zampado","zamparon","habían zampado"],"a":3,"k":"과거완료 + zamparse","t":"어젯밤 우리가 도착했을 때 그들은 이미 다 먹어 치운 뒤였다.","e":"'zamparse algo'는 '~을 허겁지겁 먹어 치우다'라는 구어 표현입니다. 우리가 도착한 과거 시점보다 먼저 끝난 일이고 'ya(이미)'가 있으므로 과거완료 'habían zampado'를 씁니다. 'se lo ~ todo'의 se는 강조의 재귀, lo는 todo를 미리 받는 대명사입니다.","x":["zampaban: 불완료과거라 '먹고 있었다'는 진행 의미가 되어 ya와 맞지 않습니다 ✗","han zampado: 현재완료라 과거 이야기 속 이전 사건에 맞지 않습니다 ✗","zamparon: 단순과거라 도착 시점보다 먼저 끝났다는 의미가 드러나지 않습니다 ✗","habían zampado: 과거 시점 이전에 완료된 일 → 정답 ✓"]},{"id":"G688","q":"Ya le dije que ____ cuidado con ese tipo, pero no me hizo caso.","o":["tuviera","tendría","tiene","hubiese tenido"],"a":0,"k":"간접 명령 전달","t":"저 녀석 조심하라고 이미 그에게 말했는데, 그는 내 말을 듣지 않았다.","e":"'decir que + 접속법'은 '~하라고 말하다'라는 명령·충고의 전달입니다(사실 전달이면 직설법). 주절이 과거(dije)이므로 접속법 과거 tuviera를 씁니다. 'hacer caso a alguien'은 '누구의 말을 따르다/귀 기울이다'입니다.","x":["tuviera: 과거 명령 전달의 접속법 과거 → 정답 ✓","tendría: 가능법이라 '조심할 것이다'라는 예측 전달이 되어 충고 의미가 되지 않습니다 ✗","tiene: 직설법 현재라 사실 전달이 되고 시제도 맞지 않습니다 ✗","hubiese tenido: 접속법 과거완료라 '조심했어야 했다'는 완료 의미가 되어 맞지 않습니다 ✗"]},{"id":"G689","q":"Su cara ____ suena, pero no sé de qué.","o":["me la","me","ø","a mí"],"a":1,"k":"sonar 구문","t":"그 사람 얼굴이 낯익은데, 어디서 봤는지 모르겠다.","e":"'sonarle algo a alguien'은 '(누구에게) ~이 낯익다, 들어 본 것 같다'라는 뜻으로 gustar처럼 간접목적어(me)를 씁니다. 주어는 'Su cara'이고 '나에게' 낯익은 것이므로 me가 필요합니다. 예: 'Ese nombre me suena.(그 이름 들어 본 것 같아.)'","x":["me la: la(그것을)가 주어 su cara를 중복해 받아 문법적으로 맞지 않습니다 ✗","me: 간접목적어 '나에게' → 정답 ✓","ø: 대명사가 없으면 '얼굴이 소리를 낸다'는 이상한 뜻이 됩니다 ✗","a mí: 'a mí' 혼자서는 안 되고 'a mí me suena'처럼 me가 함께 있어야 합니다 ✗"]},{"id":"G690","q":"Felisa me confesó que se siente atraída ____ Manuel.","o":["a","por","para","hasta"],"a":1,"k":"atraído por","t":"펠리사는 마누엘에게 끌린다고 내게 털어놓았다.","e":"'sentirse atraído/a por alguien'은 '누구에게 (마음이) 끌리다'라는 뜻입니다. 과거분사 atraída는 수동의 의미(~에 의해 끌린)라 행위자를 나타내는 por를 씁니다. 'confesar'는 '고백하다, 털어놓다'입니다.","x":["a: atraído와 짝이 되지 않는 전치사입니다 ✗","por: 수동 의미의 행위자 por → 정답 ✓","para: 목적을 나타내 의미가 맞지 않습니다 ✗","hasta: '~까지'라 의미가 맞지 않습니다 ✗"]},{"id":"G691","q":"Al final fueron ellos quienes se apropiaron ____ las acciones de la compañía.","o":["de","para","por","a"],"a":0,"k":"apropiarse de","t":"결국 회사 주식을 가로챈 사람들은 바로 그들이었다.","e":"'apropiarse de algo'는 '~을 (부당하게) 자기 것으로 만들다, 가로채다'라는 뜻의 재귀동사로 항상 de와 함께 씁니다. 'fueron ellos quienes ~'는 '~한 것은 바로 그들이었다'라는 강조 구문입니다.","x":["de: 'apropiarse de(~을 가로채다)' → 정답 ✓","para: apropiarse와 짝이 되지 않습니다 ✗","por: apropiarse와 짝이 되지 않습니다 ✗","a: apropiarse와 짝이 되지 않습니다 ✗"]},{"id":"G692","q":"¿Te apetece que ____ una pizza?","o":["pediríamos","pidiésemos","pedimos","pidamos"],"a":3,"k":"apetecer que + 접속법","t":"우리 피자 시킬래?(피자 시키는 거 어때?)","e":"'¿Te apetece que ~?'는 '~하는 거 어때/~하고 싶어?'라는 제안으로, 바람을 나타내는 apetecer 뒤 que절에는 접속법을 씁니다. 주절이 현재(apetece)이므로 접속법 현재 pidamos(pedir: e→i)입니다. 'apetecer'는 주로 스페인에서 쓰며, 중남미에서는 '¿Tienes ganas de que pidamos...?'나 '¿Se te antoja...?'(멕시코)를 많이 씁니다.","x":["pediríamos: 가능법이라 apetecer que 뒤에 쓰지 않습니다 ✗","pidiésemos: 접속법 과거라 현재 주절과 시제가 맞지 않습니다 ✗","pedimos: 직설법이라 바람 표현 뒤에 쓰지 않습니다 ✗","pidamos: 접속법 현재 → 정답 ✓"]},{"id":"G693","q":"Mi marido siempre ha preferido trabajar ____ su cuenta.","o":["de","por","para","según"],"a":1,"k":"por su cuenta","t":"내 남편은 늘 자영업으로(스스로 독립해서) 일하는 것을 더 좋아했다.","e":"'trabajar por su cuenta'는 '자기 사업으로 일하다, 프리랜서/자영업으로 일하다'라는 표현입니다. 회사에 고용되어 일하는 것은 'trabajar por cuenta ajena'라고 합니다. 'por mi/tu/su cuenta'는 일반적으로 '혼자 힘으로, 스스로'라는 뜻도 됩니다.","x":["de: 'de su cuenta'는 '그의 계좌의'처럼 되어 의미가 다릅니다 ✗","por: 'por su cuenta(자기 힘으로/자영으로)' → 정답 ✓","para: 'para su cuenta'는 '그의 계좌를 위해'가 되어 맞지 않습니다 ✗","según: 'según su cuenta'는 '그의 말에 따르면'이 되어 의미가 다릅니다 ✗"]},{"id":"G694","q":"Qué elegante iba Augusto anoche. ¿Adónde ____?","o":["iría","ha ido","vaya","fuese"],"a":0,"k":"과거 추측 가능법","t":"어젯밤 아우구스토 정말 멋지게 차려입었더라. 어디 갔던 걸까?","e":"가능법(-ría)은 '과거의 일에 대한 추측'을 나타낼 수 있습니다. '¿Adónde iría?'는 '(어젯밤) 어디에 갔던 걸까?'라는 뜻입니다. 현재에 대한 추측은 미래형('¿Adónde irá?' 어디 가는 걸까?)으로 한다는 것과 짝지어 기억하세요.","x":["iría: 과거 추측의 가능법 → 정답 ✓","ha ido: 현재완료로 사실을 묻게 되어 추측의 뉘앙스가 없고 anoche와도 맞지 않습니다 ✗","vaya: 접속법이라 직접 의문문에 쓰지 않습니다 ✗","fuese: 접속법 과거라 직접 의문문에 쓰지 않습니다 ✗"]},{"id":"G695","q":"Íbamos a la playa cada domingo de verano, ____ hiciera mal tiempo.","o":["por si","y eso que","aunque","si bien"],"a":2,"k":"양보 aunque + 접속법","t":"우리는 날씨가 나쁘더라도 여름 매주 일요일마다 해변에 가곤 했다.","e":"'aunque + 접속법'은 '설령 ~하더라도'라는 뜻으로, 날씨가 나쁜 날이 있든 없든 상관없다는 가정적 양보를 나타냅니다. 과거 습관을 말하므로 접속법 과거 hiciera가 쓰였습니다. 'aunque + 직설법'은 '실제로 ~했지만'이라는 사실의 양보입니다.","x":["por si: '~할 경우에 대비해'라 의미가 맞지 않습니다 ✗","y eso que: '~인데도'라는 양보지만 뒤에 직설법을 씁니다 ✗","aunque: 접속법과 함께 '~하더라도' → 정답 ✓","si bien: '~이긴 하지만'이라는 양보로 뒤에 직설법을 씁니다 ✗"]},{"id":"G696","q":"____ al grano, por favor, que tengo prisa.","o":["Ve","Di","Ven","Da"],"a":0,"k":"관용 표현 ir al grano","t":"본론만 말해 줘, 부탁이야, 나 바쁘거든.","e":"'ir al grano'는 직역하면 '곡식 알맹이로 가다'로, '본론으로 들어가다, 요점만 말하다'라는 관용 표현입니다. tú 긍정 명령형은 ir의 불규칙형 've'입니다. 'que tengo prisa'의 que는 '~하니까'라는 이유를 덧붙이는 구어 용법입니다.","x":["Ve: ir의 tú 명령형으로 'ir al grano' 완성 → 정답 ✓","Di: decir의 명령형이라 'di al grano'라는 표현은 없습니다 ✗","Ven: venir의 명령형이라 관용 표현이 성립하지 않습니다 ✗","Da: dar의 명령형이라 의미가 맞지 않습니다 ✗"]},{"id":"G697","q":"¿Cómo es posible que todavía no ____ preparados para el examen de mañana?","o":["han estado","estéis","está","estés"],"a":1,"k":"es posible que + 접속법","t":"어떻게 너희가 내일 시험 준비가 아직도 안 됐을 수 있니?","e":"'Es posible que ~'처럼 가능성·판단을 나타내는 무인칭 표현 뒤에는 접속법을 씁니다. 'preparados'가 복수이므로 주어는 vosotros이고, 접속법 현재 'estéis'가 맞습니다. 중남미에서는 같은 문장을 'estén preparados(ustedes)'라고 합니다.","x":["han estado: 직설법이라 es posible que 뒤에 쓰지 않습니다 ✗","estéis: vosotros 접속법 현재 → 정답 ✓","está: 단수 직설법이라 복수 preparados와 맞지 않습니다 ✗","estés: tú 접속법이라 복수 preparados와 수가 맞지 않습니다 ✗"]},{"id":"G698","q":"Perdona, ¿____ cerrar la ventana?","o":["te importaría","le importa","importa","le importaría"],"a":0,"k":"정중한 부탁 importar","t":"미안한데, 창문 좀 닫아 줄 수 있어?","e":"'¿Te importaría + 원형?'은 '~해 줄 수 있을까?'라는 공손한 부탁입니다. 가능법(-ría)이 말을 부드럽게 만듭니다. 'Perdona'가 tú 명령형이므로 상대는 tú이고, 간접목적어도 te를 씁니다(usted이라면 Perdone, ¿le importaría...?).","x":["te importaría: tú에게 하는 공손한 부탁 → 정답 ✓","le importa: usted 형태라 'Perdona(tú)'와 맞지 않습니다 ✗","importa: '누구에게'를 나타내는 대명사가 없어 부탁이 되지 않습니다 ✗","le importaría: 공손하지만 usted 형태라 Perdona와 맞지 않습니다 ✗"]},{"id":"G699","q":"¿Dónde ____ el acto de investidura?","o":["estará siendo celebrado","se celebrará","celebrarse","se vaya a celebrar"],"a":1,"k":"재귀 수동 미래","t":"취임식은 어디에서 열릴까?","e":"'celebrarse(개최되다)'는 se를 이용한 재귀 수동으로, 행사·회의가 '열리다'라고 할 때 가장 자연스럽습니다. 미래형 'se celebrará'는 '열릴 것이다' 또는 '열리는 걸까?'라는 추측도 나타냅니다. 'acto de investidura'는 '취임식(학위 수여식)'입니다.","x":["estará siendo celebrado: 수동 진행 + 추측 미래가 겹친 매우 어색한 형태입니다 ✗","se celebrará: 재귀 수동의 미래형 → 정답 ✓","celebrarse: 원형이라 의문문의 동사가 될 수 없습니다 ✗","se vaya a celebrar: 접속법이라 직접 의문문에 쓰지 않습니다 ✗"]},{"id":"G700","q":"¡Hay que ver ____ habla tu abuelo!","o":["al que","lo que","el que","la que"],"a":1,"k":"감탄 lo que","t":"너희 할아버지 정말 말씀 많으시다!","e":"'¡Hay que ver lo que + 동사!'는 '정말 얼마나 ~하는지!'라는 놀람의 감탄 표현입니다. 중성 'lo que'가 '그 정도, 그 양'을 가리켜 'lo que habla'는 '말을 얼마나 많이 하는지'가 됩니다. 'Hay que ver'는 원래 '봐야 한다'지만 감탄에서는 '세상에, 정말'이라는 뜻입니다.","x":["al que: a + el que라 '~하는 사람에게'가 되어 의미가 맞지 않습니다 ✗","lo que: 정도·양을 나타내는 중성 lo que → 정답 ✓","el que: 남성 명사를 가리켜 '말의 양'이라는 뜻이 되지 않습니다 ✗","la que: 여성 명사를 가리켜 의미가 맞지 않습니다 ✗"]},{"id":"G701","q":"Como en casa no ____ en ninguna parte.","o":["se está","está","se es","lo es"],"a":0,"k":"무인칭 se estar","t":"집만큼 편한 곳은 어디에도 없다.","e":"'se + 3인칭 단수 동사'는 '사람들은 (일반적으로) ~하다'라는 무인칭 표현입니다. 'se está bien'은 '(그곳에서는) 지내기 좋다'라는 뜻으로, 'Como en casa no se está en ninguna parte'는 '집처럼 편하게 지낼 수 있는 곳은 없다'는 유명한 속담입니다. 주어가 특정되지 않은 일반적 경험이라 se가 필요합니다.","x":["se está: 일반 사람을 주어로 하는 무인칭 se + estar → 정답 ✓","está: 주어가 없어 '누가' 있는지 알 수 없어 속담이 성립하지 않습니다 ✗","se es: ser는 장소에서 '편히 지내다'라는 상태를 나타내지 못합니다 ✗","lo es: '그것이 그렇다'는 뜻이라 문장 의미와 맞지 않습니다 ✗"]},{"id":"G702","q":"¿De qué ____ cuando llegué yo?","o":["están hablando","han estado hablando","estabais hablando","habéis estado hablando"],"a":2,"k":"과거진행 불완료","t":"내가 도착했을 때 너희는 무슨 얘기를 하고 있었니?","e":"과거의 어떤 순간(내가 도착했을 때)에 진행 중이던 행동은 'estar의 불완료과거 + 현재분사'로 나타냅니다. 'cuando llegué'가 과거 시점을 정해 주므로 'estabais hablando'가 맞습니다. 중남미에서는 vosotros 대신 ustedes를 써서 'estaban hablando'라고 합니다.","x":["están hablando: 현재 진행이라 과거의 도착 시점과 맞지 않습니다 ✗","han estado hablando: 현재완료 진행이라 지금까지 이어진 일을 나타내 맞지 않습니다 ✗","estabais hablando: 과거 시점에 진행 중이던 행동 → 정답 ✓","habéis estado hablando: 역시 현재완료 진행이라 과거 한 시점과 맞지 않습니다 ✗"]},{"id":"G703","q":"Su carácter ingenuo hace que algunas personas ____ de él.","o":["se aprovechan","aprovechan","se aprovechen","aprovechen"],"a":2,"k":"hacer que + 접속법","t":"그의 순진한 성격 때문에 어떤 사람들은 그를 이용한다.","e":"'hacer que + 접속법'은 '~하게 만들다'라는 사역 표현입니다. '~을 이용하다(약점을 이용해 득을 보다)'는 재귀동사 'aprovecharse de alguien'을 씁니다. 두 가지를 합치면 'se aprovechen de él'이 됩니다.","x":["se aprovechan: 재귀형은 맞지만 직설법이라 hacer que 뒤에 쓰지 않습니다 ✗","aprovechan: 직설법이고 se도 빠져 'de él'과 이어지지 않습니다 ✗","se aprovechen: 재귀 aprovecharse de + 접속법 → 정답 ✓","aprovechen: 접속법이지만 se가 없으면 '~을 활용하다'라는 뜻이라 de와 맞지 않습니다 ✗"]},{"id":"G704","q":"En 1980 ya ____ a Felisa.","o":["conociera","he conocido","conocí","conocía"],"a":3,"k":"conocer 불완료","t":"1980년에 나는 이미 펠리사를 알고 있었다.","e":"'conocer'는 단순과거(conocí)로 쓰면 '처음 알게 되었다, 만났다'는 뜻이고, 불완료과거(conocía)로 쓰면 '알고 있었다'는 상태를 나타냅니다. 'ya(이미)'와 함께 1980년 당시 이미 아는 사이였다는 뜻이므로 conocía가 맞습니다.","x":["conociera: 접속법 과거라 단순한 사실 문장에 쓸 이유가 없습니다 ✗","he conocido: 현재완료라 1980년이라는 과거 시점과 맞지 않습니다 ✗","conocí: '처음 만났다'는 뜻이라 'ya(이미)'와 함께 쓰면 어색합니다 ✗","conocía: 과거의 '알고 있던 상태' → 정답 ✓"]},{"id":"G705","q":"Supongo que ____ unos días libres en agosto.","o":["tuviera","tengas","tendrá","tenga"],"a":2,"k":"suponer + 직설법 미래","t":"그(당신)는 8월에 며칠 휴가가 있겠죠.","e":"'Supongo que'는 긍정형으로 쓰면 뒤에 직설법이 옵니다. 앞으로 8월의 일에 대한 추측이므로 직설법 미래 'tendrá'(él/ella/usted)가 맞습니다. 'tengas, tenga'는 접속법이라 suponer 긍정형 뒤에 쓰지 않습니다.","x":["tuviera: 접속법 과거라 맞지 않습니다 ✗","tengas: 접속법 현재라 긍정형 suponer 뒤에 쓰지 않습니다 ✗","tendrá: 직설법 미래 → 정답 ✓","tenga: 역시 접속법이라 맞지 않습니다 ✗"]},{"id":"G706","q":"La mujer ____ se casó era una bella persona.","o":["con la que","de quien","a la que","a que"],"a":0,"k":"전치사 + 관계사","t":"그가 결혼한 여자는 정말 좋은 사람이었다.","e":"'casarse con alguien(누구와 결혼하다)'처럼 동사가 전치사 con을 요구하면, 관계절에서도 그 전치사를 관계사 앞에 둡니다. 선행사 'la mujer'가 여성 단수이므로 'con la que'가 됩니다('con quien'도 가능). 'una bella persona'는 '마음씨가 아름다운 사람'이라는 뜻입니다.","x":["con la que: casarse con에 맞는 전치사 + 관계사 → 정답 ✓","de quien: casarse는 de가 아니라 con과 씁니다 ✗","a la que: casarse a라는 표현은 없습니다 ✗","a que: 관사도 없고 전치사도 맞지 않습니다 ✗"]},{"id":"G707","q":"Queremos que ____ que estamos de tu parte.","o":["supiste","sabías","sabrías","sepas"],"a":3,"k":"querer que + 접속법","t":"우리가 네 편이라는 걸 네가 알았으면 좋겠어.","e":"'querer que'는 바람을 나타내므로 뒤 que절에 접속법이 옵니다. 주절이 현재(queremos)이고 주어가 다르므로(우리 → 너) 접속법 현재 'sepas'(saber의 불규칙형)가 맞습니다. 'estar de parte de alguien'은 '누구의 편이다'라는 표현입니다.","x":["supiste: 직설법 단순과거라 맞지 않습니다 ✗","sabías: 직설법 불완료과거라 맞지 않습니다 ✗","sabrías: 가능법이라 맞지 않습니다 ✗","sepas: saber의 접속법 현재 → 정답 ✓"]},{"id":"G708","q":"Por favor, denos un poco ____ de tiempo para acabar el examen.","o":["más","bastante","todavía","algo"],"a":0,"k":"un poco más de","t":"시험을 끝낼 수 있게 시간을 조금만 더 주세요.","e":"'un poco más de + 명사'는 '~을 조금 더'라는 표현입니다. 'más'가 '더'라는 뜻을 더해 줍니다. 'denos'는 dar의 usted 명령형 'dé'에 nos가 붙은 형태입니다(대명사가 붙어 악센트가 사라짐).","x":["más: 'un poco más de tiempo(조금 더 많은 시간)' → 정답 ✓","bastante: '꽤 많은'이라 'un poco'와 함께 쓰면 모순됩니다 ✗","todavía: '아직'이라는 부사라 이 자리에 들어갈 수 없습니다 ✗","algo: 'un poco algo'처럼 겹쳐 쓰지 않습니다 ✗"]},{"id":"G709","q":"¿Alguien conoce al chico ____ la camisa blanca?","o":["en","a","con","de"],"a":3,"k":"묘사의 de","t":"흰 셔츠 입은 남자애 아는 사람 있어?","e":"사람을 옷차림이나 특징으로 구별할 때는 'el chico de la camisa blanca(흰 셔츠의 남자애)'처럼 전치사 de를 씁니다. 'la chica de las gafas(안경 쓴 여자애)'도 같은 구조입니다. 'con'도 가능하지만 'de'가 이렇게 특정 인물을 가리킬 때 가장 자연스럽습니다.","x":["en: 'en la camisa'는 '셔츠 안에'라는 뜻이 됩니다 ✗","a: 의미가 성립하지 않습니다 ✗","con: '흰 셔츠를 입은'으로 이해는 되지만 사람을 특정해 부를 때는 de가 기준 표현입니다 ✗","de: 특징으로 사람을 가리키는 de → 정답 ✓"]},{"id":"G710","q":"____ el favor de esperar su turno.","o":["Haced","Haz","Hagan","Haces"],"a":2,"k":"hagan el favor de","t":"(여러분) 차례를 기다려 주시기 바랍니다.","e":"'hacer el favor de + 원형'은 '~해 주세요'라는 정중한(때로는 단호한) 부탁 표현입니다. 'su turno(여러분의/당신의 차례)'에서 su가 쓰였으므로 상대는 usted 또는 ustedes이고, 보기 중에서는 ustedes 명령형 'Hagan'이 맞습니다.","x":["Haced: vosotros 명령형이라 'vuestro turno'가 되어야 합니다 ✗","Haz: tú 명령형이라 'tu turno'가 되어야 합니다 ✗","Hagan: ustedes 명령형으로 su turno와 일치 → 정답 ✓","Haces: 직설법 평서문이라 부탁이 되지 않습니다 ✗"]},{"id":"G711","q":"No os llamó ____ se lo dijera su esposa, sino porque él quiso.","o":["porque","porqué","por que","por qué"],"a":0,"k":"부정된 원인 + 접속법","t":"그가 너희에게 전화한 건 아내가 시켜서가 아니라 자기가 원해서였다.","e":"'no ~ porque + 접속법, sino porque + 직설법'은 '~해서가 아니라 ~해서'라는 구조로, 부정되는 가짜 이유에는 접속법(dijera)을, 진짜 이유에는 직설법(quiso)을 씁니다. 여기서 porque는 '~때문에'라는 접속사라 붙여 쓰고 악센트가 없습니다.","x":["porque: 원인 접속사 '~때문에' → 정답 ✓","porqué: '이유'라는 명사라 관사와 함께 씁니다 ✗","por que: 전치사 + 관계사라 이 위치에 맞지 않습니다 ✗","por qué: 의문사 '왜'라 평서문에 맞지 않습니다 ✗"]},{"id":"G712","q":"Estaremos en Madrid ____ octubre.","o":["a finales de","en principio de","a través de","en medio de"],"a":0,"k":"시기 표현 a finales","t":"우리는 10월 말에 마드리드에 있을 것이다.","e":"'a finales de + 달/해'는 '~ 말에'라는 뜻입니다. 'a principios de(~ 초에)', 'a mediados de(~ 중순에)'와 함께 묶어서 외우면 좋습니다. 모두 전치사 a로 시작하고 복수형(finales, principios)을 쓴다는 점에 주의하세요.","x":["a finales de: '~ 말에' → 정답 ✓","en principio de: 'en principio'는 '원칙적으로'라는 다른 표현이고, '~ 초에'는 a principios de입니다 ✗","a través de: '~을 통해서'라는 뜻이라 시기를 나타내지 않습니다 ✗","en medio de: '~의 한가운데에'라는 공간·상황 표현이라 달과 쓰지 않습니다 ✗"]},{"id":"G713","q":"Nos pidió que ____ el texto de nuevo.","o":["escribimos","escribamos","escribiríamos","escribiéramos"],"a":3,"k":"pedir que + 접속법 과거","t":"그는 우리에게 그 글을 다시 써 달라고 부탁했다.","e":"'pedir que(~해 달라고 부탁하다)'는 요청 표현이라 뒤에 접속법이 옵니다. 주절이 과거(pidió)이므로 접속법 과거 'escribiéramos'를 써서 시제를 맞춥니다. 'de nuevo'는 '다시'라는 뜻으로 'otra vez'와 같습니다.","x":["escribimos: 직설법이라 요청 표현 뒤에 쓰지 않습니다 ✗","escribamos: 접속법 현재라 과거 주절과 시제가 맞지 않습니다 ✗","escribiríamos: 가능법이라 맞지 않습니다 ✗","escribiéramos: 과거 주절에 맞는 접속법 과거 → 정답 ✓"]},{"id":"G714","q":"Esos dos se pasan el día entero en la cafetería; son ____ vagos.","o":["unos","los","ciertos","de unos"],"a":0,"k":"강조의 unos","t":"저 둘은 하루 종일 카페에만 있어. 정말 게으름뱅이들이야.","e":"'ser unos/unas + 명사(형용사)'에서 부정관사 unos는 '정말 ~한 사람들'이라는 강조·비난의 뉘앙스를 줍니다. 'Son vagos'는 단순히 '게으르다'지만 'Son unos vagos'는 '완전 게으름뱅이들이다'라는 느낌입니다. 예: 'Eres un genio.(넌 진짜 천재야.)'","x":["unos: 강조·감정을 담은 부정관사 → 정답 ✓","los: 정관사라 '그 게으름뱅이들'이 되어 강조 뉘앙스가 없고 어색합니다 ✗","ciertos: '어떤 특정한'이라는 뜻이라 문맥과 맞지 않습니다 ✗","de unos: 전치사 de가 불필요하게 들어가 문법적으로 맞지 않습니다 ✗"]},{"id":"G715","q":"____ nerviosa cada vez que tiene que tomar un avión.","o":["Se vuelve","Se convierte","Se pone","Se hace"],"a":2,"k":"ponerse + 형용사","t":"그녀는 비행기를 타야 할 때마다 긴장한다.","e":"'ponerse + 형용사'는 감정·몸 상태가 '일시적으로 ~해지다'라는 뜻입니다(ponerse nervioso, rojo, triste). 'volverse'는 성격이 비교적 지속적으로 변할 때, 'hacerse'는 노력이나 과정으로 ~이 될 때, 'convertirse en'은 완전히 다른 것으로 변할 때 씁니다. 비행기 탈 때마다의 일시적 긴장이므로 se pone가 맞습니다.","x":["Se vuelve: 성격 등의 지속적 변화에 써서 매번의 일시적 감정과 맞지 않습니다 ✗","Se convierte: 'convertirse en + 명사'로 완전한 변신을 나타냅니다 ✗","Se pone: 일시적 감정·상태 변화 → 정답 ✓","Se hace: 노력·과정에 의한 변화(hacerse rico)라 맞지 않습니다 ✗"]},{"id":"G716","q":"No sé de nadie que ____ aconsejarte sobre el tema.","o":["ha podido","podrá","puede","pueda"],"a":3,"k":"부정 선행사 + 접속법","t":"그 문제에 대해 너에게 조언해 줄 수 있는 사람을 나는 아무도 모른다.","e":"관계절이 '존재하지 않는(nadie) 사람'을 설명할 때는 접속법을 씁니다. 'No sé de nadie que pueda ~'는 '~할 수 있는 사람을 아무도 모른다'는 뜻입니다. 'saber de alguien'은 '누군가의 존재를 알다'입니다.","x":["ha podido: 직설법이라 존재하지 않는 선행사에 쓰지 않습니다 ✗","podrá: 직설법 미래라 맞지 않습니다 ✗","puede: 직설법 현재라 nadie를 꾸미는 관계절에 맞지 않습니다 ✗","pueda: 부정 선행사 뒤의 접속법 현재 → 정답 ✓"]},{"id":"G717","q":"Les agradecí mucho que ____ por mí.","o":["se preocuparan","se han preocupado","se estaban preocupado","se preocuparían"],"a":0,"k":"agradecer que + 접속법","t":"그들이 나를 걱정해 준 것에 나는 무척 감사했다.","e":"'agradecer que ~(~해 준 것에 감사하다)'는 감정을 나타내므로 뒤에 접속법을 씁니다. 주절이 과거(agradecí)이므로 접속법 과거 'se preocuparan'이 맞습니다. 'preocuparse por alguien'은 '누구를 걱정하다'입니다.","x":["se preocuparan: 과거 주절에 맞는 접속법 과거 → 정답 ✓","se han preocupado: 직설법 현재완료라 맞지 않습니다 ✗","se estaban preocupado: 'preocupando'여야 할 자리에 과거분사가 와서 형태 자체가 틀립니다 ✗","se preocuparían: 가능법이라 감정 표현 뒤에 쓰지 않습니다 ✗"]},{"id":"G718","q":"____ mejor que vayamos en taxi.","o":["Será","Estamos","Esté","Sea"],"a":0,"k":"será mejor que","t":"택시 타고 가는 게 나을 것 같아.","e":"'Será mejor que + 접속법'은 '~하는 게 나을 것 같다'라는 부드러운 제안입니다. 미래형 será가 '~일 것이다'라는 추측의 뉘앙스로 말을 부드럽게 해 줍니다. 판단 표현 'mejor que' 뒤라서 vayamos(접속법)가 쓰였습니다.","x":["Será: ser의 미래형으로 부드러운 제안 → 정답 ✓","Estamos: 'Estamos mejor'는 '우리 상태가 더 낫다'는 뜻이라 que절과 이어지지 않습니다 ✗","Esté: 접속법이라 주절 동사가 될 이유가 없습니다 ✗","Sea: 접속법이라 독립된 주절에 쓰지 않습니다 ✗"]},{"id":"G719","q":"Te lo digo ____ última vez: es hora de acostarse.","o":["para","por","a la","de"],"a":1,"k":"por última vez","t":"마지막으로 말한다. 잘 시간이야.","e":"'por última vez'는 '마지막으로'라는 고정 표현으로 관사 없이 por를 씁니다. 'por primera vez(처음으로)'와 같은 구조입니다. 'es hora de + 원형'은 '~할 시간이다'라는 뜻입니다.","x":["para: 'para última vez'라는 표현은 없습니다 ✗","por: 'por última vez(마지막으로)' → 정답 ✓","a la: 'a la última'는 '최신 유행으로'라는 다른 표현입니다 ✗","de: 'de última vez'는 쓰지 않습니다 ✗"]},{"id":"G720","q":"Me satisface que mis padres ____ orgullosos de mí.","o":["son","estén","están","sean"],"a":1,"k":"감정 + 접속법 estar","t":"부모님이 나를 자랑스러워하신다니 만족스럽다.","e":"'Me satisface que ~(~하는 것이 만족스럽다)'는 감정 표현이라 뒤에 접속법을 씁니다. '~을 자랑스러워하다'는 'estar orgulloso de'로, 감정 상태라 estar를 씁니다(ser orgulloso는 '거만하다, 자존심이 세다'라는 성격). 그래서 'estén'이 정답입니다.","x":["son: ser + 직설법이라 두 가지 모두 맞지 않습니다 ✗","estén: estar + 접속법 현재 → 정답 ✓","están: estar는 맞지만 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗","sean: 접속법이지만 ser orgulloso는 '거만하다'는 성격이 됩니다 ✗"]},{"id":"G721","q":"No te puedes imaginar ____ calor que tengo.","o":["del","el","al","un"],"a":1,"k":"감탄 정관사 el","t":"내가 얼마나 더운지 너는 상상도 못 할 거야.","e":"'el + 명사 + que'는 '얼마나 ~한지'라는 강조를 나타냅니다. 'el calor que tengo'는 '내가 느끼는 그 더위(가 얼마나 심한지)'라는 뜻입니다. 'tener calor'는 '(사람이) 덥다'이며 calor는 남성명사라 el을 씁니다.","x":["del: de + el이라 imaginar의 목적어가 될 수 없습니다 ✗","el: 강조의 'el + 명사 + que' → 정답 ✓","al: a + el이라 사물 목적어 앞에 쓰지 않습니다 ✗","un: '어떤 더위'가 되어 강조 구문이 되지 않습니다 ✗"]},{"id":"G722","q":"¿Cuál cree que es el curso ____ más apropiado para mí?","o":["el","de lo","ø","lo"],"a":2,"k":"최상급 관사 생략","t":"제게 가장 적합한 과정은 어느 것이라고 생각하세요?","e":"스페인어 최상급은 'el/la + 명사 + más + 형용사'의 순서이며, 관사는 명사 앞에 한 번만 씁니다. 'el curso más apropiado'처럼 más 앞에 관사를 다시 쓰지 않습니다(영어 the most와 다름). 'apropiado para'는 '~에게 적합한'입니다.","x":["el: 'el curso el más ~'처럼 관사를 두 번 쓰지 않습니다 ✗","de lo: 'de lo más + 형용사'는 '아주 ~한'이라는 다른 표현으로 명사 뒤에 쓰면 최상급이 되지 않습니다 ✗","ø: 명사 앞 관사 하나로 최상급이 완성 → 정답 ✓","lo: 중성 lo는 남성 명사의 최상급에 쓰지 않습니다 ✗"]},{"id":"G723","q":"____ habiendo residido en Francia durante años, apenas habla francés.","o":["Aunque","Si bien","Incluso si","Aun"],"a":3,"k":"aun + 현재분사","t":"몇 년 동안 프랑스에 살았는데도 그는 프랑스어를 거의 못 한다.","e":"'aun + 현재분사'는 '~하면서도, ~했는데도'라는 양보 표현입니다. 여기서 aun은 '~조차'라는 뜻이라 악센트가 없습니다. 'aunque, si bien'은 접속사라 뒤에 활용된 동사가 와야 하고 현재분사와 바로 쓰지 않습니다. 'apenas'는 '거의 ~않다'입니다.","x":["Aunque: 접속사라 'aunque ha residido'처럼 활용 동사가 와야 합니다 ✗","Si bien: 역시 접속사라 현재분사와 바로 쓰지 않습니다 ✗","Incluso si: '설령 ~라 해도'라는 가정 표현이라 현재분사와 쓰지 않습니다 ✗","Aun: 'aun + 현재분사(~했는데도)' → 정답 ✓"]},{"id":"G724","q":"El tonto ____ Juan no deja de meterse conmigo.","o":["hasta","a","por","de"],"a":3,"k":"el tonto de + 이름","t":"그 바보 같은 후안이 자꾸 나한테 시비를 건다.","e":"'el/la + 형용사·명사 + de + 사람'은 '~한 그 사람'이라는 감정(주로 비난·애정)을 담은 표현입니다. 'el tonto de Juan'은 '그 바보 후안'입니다. 'meterse con alguien'은 '누구를 놀리다, 시비 걸다'이고, 'no dejar de + 원형'은 '계속 ~하다'입니다.","x":["hasta: '~까지'라는 뜻이라 의미가 맞지 않습니다 ✗","a: 의미가 성립하지 않습니다 ✗","por: 의미가 성립하지 않습니다 ✗","de: 'el tonto de Juan' 감정 표현 → 정답 ✓"]},{"id":"G725","q":"No me habría importado que ____ un poco antes de la hora prevista.","o":["has venido","hubieras venido","vendrías","hayas venido"],"a":1,"k":"접속법 과거완료","t":"네가 예정 시간보다 조금 일찍 왔더라도 나는 상관없었을 텐데.","e":"주절이 가능법 완료(habría importado)이면 que절은 접속법 과거완료(hubiera/hubiese + 과거분사)를 씁니다. 'importar que'는 '~하는 것이 신경 쓰이다'라는 감정 표현이라 접속법이 필요합니다. 과거의 일을 되돌아보는 가정이라 완료형이 됩니다.","x":["has venido: 직설법이라 맞지 않습니다 ✗","hubieras venido: 가능법 완료 주절에 맞는 접속법 과거완료 → 정답 ✓","vendrías: 가능법이라 que절에 쓰지 않습니다 ✗","hayas venido: 접속법 현재완료라 주절(habría)과 시제가 맞지 않습니다 ✗"]},{"id":"G726","q":"Sabes que vamos a ayudarte ____ todo lo que necesites.","o":["por","hasta","en","a"],"a":2,"k":"ayudar en","t":"네가 필요한 모든 일에 우리가 도와줄 거라는 거 알잖아.","e":"'ayudar a alguien en algo'는 '누구를 ~에서(~하는 데) 돕다'라는 뜻으로, 도움의 분야·일을 en으로 나타냅니다. 'todo lo que necesites'는 '네가 필요로 할 모든 것'으로, 정해지지 않은 미래의 것이라 접속법을 씁니다.","x":["por: 원인·이유를 나타내 도움의 분야가 되지 않습니다 ✗","hasta: '~까지'라 의미가 맞지 않습니다 ✗","en: 도움의 분야를 나타내는 en → 정답 ✓","a: 'ayudar a + 원형(~하는 것을 돕다)'에 쓰며 명사 todo 앞에는 en이 자연스럽습니다 ✗"]},{"id":"G727","q":"____ veces que lo he hecho, y me sigue saliendo mal este ejercicio.","o":["Cuantas","De las","De tantas","Con la de"],"a":3,"k":"con la de + 명사","t":"이걸 몇 번이나 해 봤는데도 이 연습 문제는 여전히 잘 안 풀린다.","e":"'con la de + 복수명사 + que'는 '그렇게 많은 ~을 했는데도'라는 양보·불만 표현입니다. 'con lo + 형용사 + que'와 같은 계열로, 양을 강조할 때는 'la de'를 씁니다. 'seguir + 현재분사'는 '계속 ~하다'라는 뜻입니다.","x":["Cuantas: 'cuantas veces'는 '~하는 만큼 몇 번이든'이라는 뜻이라 양보가 되지 않습니다 ✗","De las: 'de las veces que'는 '~한 횟수 중에서'라는 뜻이 되어 맞지 않습니다 ✗","De tantas: 'de tantas veces'는 '너무 여러 번 해서'라는 원인이 되어 뒤 내용과 맞지 않습니다 ✗","Con la de: '그렇게 많이 ~했는데도' → 정답 ✓"]},{"id":"G728","q":"Con lo avispado que eres, es increíble que ____.","o":["te hayan engañado","le habían engañado","le hayan engañado","te han engañado"],"a":0,"k":"con lo + 형용사 + 접속법","t":"너처럼 눈치 빠른 사람이 속았다니 믿을 수가 없다.","e":"'Con lo avispado que eres'는 '네가 그렇게 눈치가 빠른데'라는 양보 표현입니다. 'es increíble que ~(~라니 믿기지 않는다)'는 감정·판단 표현이라 접속법을 쓰고, 이미 일어난 일이라 접속법 현재완료 'hayan engañado'입니다. eres(tú)와 맞추어 목적어도 te가 됩니다. 'avispado'는 '영리한, 눈치 빠른'입니다.","x":["te hayan engañado: tú에 맞춘 대명사 + 접속법 현재완료 → 정답 ✓","le habían engañado: 대명사가 3인칭이고 직설법이라 맞지 않습니다 ✗","le hayan engañado: 접속법은 맞지만 eres(tú)와 대명사가 일치하지 않습니다 ✗","te han engañado: 대명사는 맞지만 직설법이라 es increíble que 뒤에 쓰지 않습니다 ✗"]},{"id":"G729","q":"¿Cuántos heridos ____ en el accidente de tren?","o":["han habido","habían","hubieron","hubo"],"a":3,"k":"무인칭 haber 단수","t":"기차 사고에서 부상자가 몇 명 나왔나요?","e":"'존재하다, 있다'의 haber는 무인칭이라 뒤의 명사가 복수여도 항상 3인칭 단수를 씁니다(hubo, había, ha habido). 사고라는 끝난 사건이므로 단순과거 'hubo'가 맞습니다. 'hubieron, han habido'는 일상에서 들리기도 하지만 규범상 틀린 형태입니다.","x":["han habido: 무인칭 haber는 복수형(han)을 쓰지 않으며 ha habido가 맞는 형태입니다 ✗","habían: 역시 복수형이라 틀리고, 단수 había라도 끝난 사건에는 덜 맞습니다 ✗","hubieron: 무인칭 haber를 복수로 쓴 비표준 형태입니다 ✗","hubo: 무인칭 haber의 단순과거 단수 → 정답 ✓"]},{"id":"G730","q":"En el carácter, Alba ha salido ____ su madre.","o":["por","de","a","en"],"a":2,"k":"salir a + 사람","t":"성격 면에서 알바는 엄마를 닮았다.","e":"'salir a alguien'은 '(성격·외모가) ~를 닮다'라는 구어 표현입니다. 주로 자식이 부모나 가족을 닮았을 때 씁니다. 같은 뜻으로 'parecerse a su madre'라고도 합니다. 예: 'Ha salido a su padre.(아빠를 닮았네.)'","x":["por: salir와 이 뜻으로 짝이 되지 않습니다 ✗","de: 'salir de'는 '~에서 나오다'라는 다른 뜻이 됩니다 ✗","a: 'salir a(~를 닮다)' → 정답 ✓","en: 'salir en'은 '(사진·TV 등에) 나오다'라는 뜻입니다 ✗"]},{"id":"G731","q":"Todavía no vive nadie en el ____ piso.","o":["tercio","tres","tercer","tercero"],"a":2,"k":"서수 tercer","t":"3층에는 아직 아무도 살지 않는다.","e":"서수 'primero(첫째), tercero(셋째)'는 남성 단수 명사 앞에서 끝의 -o가 떨어져 'primer, tercer'가 됩니다. 'piso'는 남성 단수이므로 'el tercer piso'입니다. 여성 명사 앞에서는 그대로 'la tercera planta'라고 씁니다.","x":["tercio: '3분의 1'이라는 분수 명사라 층을 나타내지 못합니다 ✗","tres: 기수 '3'이라 'el piso tres'처럼 명사 뒤에 쓸 수는 있지만 앞에는 쓰지 않습니다 ✗","tercer: 남성 단수 명사 앞의 어미 탈락형 → 정답 ✓","tercero: 남성 단수 명사 앞에서는 -o를 떼어야 합니다 ✗"]},{"id":"G732","q":"____ que veníais, habría hecho comida para más personas.","o":["Al saber","Por no saber","Como no sabía","De haber sabido"],"a":3,"k":"de + 완료 원형 조건","t":"너희가 오는 걸 알았더라면 더 많은 사람 몫의 음식을 만들었을 텐데.","e":"'de + haber + 과거분사'는 'si hubiera sabido(~했더라면)'와 같은 과거 사실의 반대 가정입니다. 주절이 'habría hecho(했을 텐데)'라는 가능법 완료이므로 과거의 반대 가정이 필요합니다. 격식 있고 간결한 표현이라 C2 수준에서 자주 묻습니다.","x":["Al saber: '알게 되었을 때'라는 시간 표현이라 반대 가정이 되지 않습니다 ✗","Por no saber: '몰라서'라는 원인이라 '알았더라면'과 반대의 의미가 됩니다 ✗","Como no sabía: '몰랐기 때문에'라는 원인 표현이라 주절 habría hecho와 논리가 맞지 않습니다 ✗","De haber sabido: 과거 반대 가정 '알았더라면' → 정답 ✓"]},{"id":"G733","q":"Me gustaría que me ____ atención cuando te hablo.","o":["hayas prestado","prestas","prestes","prestases"],"a":3,"k":"gustaría que + 접속법 과거","t":"내가 너에게 말할 때 네가 귀 기울여 주면 좋겠어.","e":"'Me gustaría que ~'처럼 주절이 가능법(-ría)이면 que절에는 접속법 과거(-ra/-se)를 씁니다. 그래서 'prestases(=prestaras)'가 맞습니다. 'prestar atención a alguien'은 '누구에게 주의를 기울이다'입니다.","x":["hayas prestado: 접속법 현재완료라 가능법 주절과 시제가 맞지 않습니다 ✗","prestas: 직설법이라 바람 표현 뒤에 쓰지 않습니다 ✗","prestes: 접속법 현재라 가능법 주절(gustaría)과 시제가 맞지 않습니다 ✗","prestases: 가능법 주절에 맞는 접속법 과거 → 정답 ✓"]},{"id":"G734","q":"Algunos problemas actuales ____ planeta son acuciantes.","o":["en la","de la","del","de"],"a":2,"k":"축약형 del","t":"오늘날 지구가 겪는 몇몇 문제들은 시급하다.","e":"'planeta'는 -a로 끝나지만 남성명사입니다(el planeta, el problema, el mapa 등). 그래서 'de + el = del'이 됩니다. 'acuciante'는 '절박한, 시급한'이라는 격식 있는 형용사입니다.","x":["en la: planeta는 남성명사이고 '지구의 문제'는 소속의 de가 필요합니다 ✗","de la: planeta는 남성명사라 la를 쓰지 않습니다 ✗","del: de + el(남성 정관사)의 축약 → 정답 ✓","de: 관사 없이 'de planeta'라고 하면 특정한 '지구'를 가리키지 못합니다 ✗"]},{"id":"G735","q":"¿Has terminado ____ de hablar?","o":["aún","aun","ya","todavía"],"a":2,"k":"ya 완료 확인","t":"이제 말 다 끝났니?","e":"'ya'는 '이미, 벌써, 이제'라는 뜻으로 완료 여부를 물을 때 씁니다. '¿Has terminado ya?'는 '이제 다 끝났어?'라는 뜻이며, 상황에 따라 짜증이 섞인 어조로도 쓰입니다. 'terminar de + 원형'은 '~하는 것을 끝내다'입니다.","x":["aún: '아직'이라 긍정 완료 질문에는 '아직도 끝났니?'처럼 어색합니다 ✗","aun: '~조차'라는 뜻이라 의미가 맞지 않습니다 ✗","ya: 완료를 확인하는 '이제/벌써' → 정답 ✓","todavía: '아직'이라 긍정 완료 질문과 맞지 않습니다 ✗"]},{"id":"G736","q":"Si el té quema, no ____ todavía.","o":["te lo tomes","te tomes","lo tomes","se lo tomes"],"a":0,"k":"부정명령 + 대명사","t":"차가 뜨거우면 아직 마시지 마.","e":"'tomarse algo'는 '~을 (다) 마시다'라는 강조의 재귀 표현입니다. 부정 명령에서는 대명사를 동사 앞에 두며 순서는 '재귀(te) → 직접목적어(lo = el té)'입니다. 그래서 'no te lo tomes'가 됩니다. 긍정 명령이라면 'tómatelo'입니다.","x":["te lo tomes: 부정 명령 + 재귀 te + 목적어 lo → 정답 ✓","te tomes: 무엇을 마실지(lo)가 빠져 불완전합니다 ✗","lo tomes: 문법적으로는 가능하지만 강조의 재귀가 빠져 덜 자연스럽습니다 ✗","se lo tomes: se는 3인칭이라 tú 명령과 맞지 않습니다 ✗"]},{"id":"G737","q":"La mujer ____ ayudamos está muy agradecida.","o":["a la que","a cual","la que","a que"],"a":0,"k":"인칭 a + 관계사","t":"우리가 도와준 그 여자분은 매우 고마워하고 있다.","e":"'ayudar a alguien(누구를 돕다)'처럼 사람 직접목적어에는 인칭 a가 붙습니다. 관계절에서도 a를 관계사 앞에 두어 'a la que'(또는 a quien)가 됩니다. 선행사 'la mujer'가 여성 단수라 la que입니다.","x":["a la que: 인칭 a + 관계사 la que → 정답 ✓","a cual: cual은 관사 없이 관계사로 쓰지 않습니다(a la cual은 가능) ✗","la que: 사람 목적어 앞의 인칭 a가 빠졌습니다 ✗","a que: 관사가 빠져 사람을 가리키는 관계사가 되지 않습니다 ✗"]},{"id":"G738","q":"Lo siento, esa mesa ____ reservada.","o":["esté","es","está","sea"],"a":2,"k":"estar + 과거분사","t":"죄송합니다, 그 테이블은 예약되어 있습니다.","e":"'estar + 과거분사'는 행동의 결과로 생긴 현재 상태를 나타냅니다. 'la mesa está reservada'는 '테이블이 예약된 상태다'라는 뜻입니다. 'ser + 과거분사'는 '누가 ~했다'라는 행동 자체의 수동태라 이 상황에 맞지 않습니다.","x":["esté: 접속법이라 사실을 말하는 문장에 쓰지 않습니다 ✗","es: ser 수동태는 행동 자체를 말해 '예약된 상태'를 나타내지 못합니다 ✗","está: 결과 상태를 나타내는 estar → 정답 ✓","sea: 접속법이라 맞지 않습니다 ✗"]},{"id":"G739","q":"¿Todavía ____ en paro o ha encontrado trabajo?","o":["está","estuviera","estaría","esté"],"a":0,"k":"estar en paro","t":"(그는) 아직 실직 중이에요, 아니면 일자리를 구했어요?","e":"'estar en paro'는 스페인에서 '실업 상태다'라는 뜻이며, 상태라 estar를 씁니다. 지금의 상태를 직접 묻는 의문문이므로 직설법 현재 'está'가 맞습니다. 중남미에서는 'estar desempleado' 또는 'estar sin trabajo'를 더 많이 씁니다.","x":["está: 현재 상태를 묻는 직설법 → 정답 ✓","estuviera: 접속법이라 직접 의문문에 쓰지 않습니다 ✗","estaría: 가능법이라 '~일까?'라는 추측이 되어 'ha encontrado'와 짝이 맞지 않습니다 ✗","esté: 접속법이라 직접 의문문에 쓰지 않습니다 ✗"]},{"id":"G740","q":"____ lejos se ve un barco de vela.","o":["De lo","A lo","Al","Del"],"a":1,"k":"a lo lejos","t":"멀리 돛단배 한 척이 보인다.","e":"'a lo lejos'는 '저 멀리, 멀리서'라는 고정 표현입니다. 'se ve'는 '보인다'라는 재귀 수동 표현입니다. 비슷한 표현으로 'a lo largo de(~을 따라, ~ 동안)'도 있으니 함께 기억하세요.","x":["De lo: 'de lo lejos'라는 표현은 쓰지 않습니다 ✗","A lo: 'a lo lejos(저 멀리)' → 정답 ✓","Al: 'al lejos'라는 표현은 없습니다 ✗","Del: 'del lejos'라는 표현은 없습니다 ✗"]},{"id":"G741","q":"No tengo ninguna intención ____ hacerte daño.","o":["de","a","para","por"],"a":0,"k":"intención de","t":"너를 다치게 할 생각은 전혀 없어.","e":"'tener (la) intención de + 원형'은 '~할 의도가 있다'라는 뜻입니다. 명사 intención 뒤에서 그 내용을 설명할 때는 de를 씁니다. 'hacer daño a alguien'은 '누구를 (몸이나 마음을) 아프게 하다'입니다.","x":["de: 'intención de + 원형' → 정답 ✓","a: intención과 짝이 되지 않습니다 ✗","para: 목적을 나타내지만 intención 뒤에는 de를 씁니다 ✗","por: intención과 짝이 되지 않습니다 ✗"]},{"id":"G742","q":"Te juro que no es lo que ____.","o":["parezca","se parece","parece","pareciese"],"a":2,"k":"parecer 직설법","t":"맹세하는데 이건 보이는 그런 게 아니야.","e":"'No es lo que parece'는 '보이는 것과 다르다, 오해야'라는 아주 흔한 표현입니다. 'lo que parece(그렇게 보이는 것)'는 실제로 보이는 상황을 가리키므로 직설법을 씁니다. 'parecer'는 '~처럼 보이다'이고, 'parecerse'는 '닮다'라는 다른 뜻입니다.","x":["parezca: 접속법이라 실제로 보이는 상황을 가리키는 관계절에 맞지 않습니다 ✗","se parece: parecerse는 '닮다'라는 뜻이라 의미가 다릅니다 ✗","parece: '그렇게 보이는 것'의 직설법 → 정답 ✓","pareciese: 접속법 과거라 시제도 맞지 않습니다 ✗"]},{"id":"G743","q":"____ han roto las gafas de sol.","o":["La","Me se","Se me","A mí"],"a":2,"k":"우발의 se me","t":"(실수로) 선글라스가 깨져 버렸어.","e":"'se me + 동사'는 '나도 모르게/실수로 ~해 버렸다'라는 우발적인 일을 나타냅니다. se가 먼저, 피해를 입은 사람(me)이 다음에 옵니다. 동사는 주어인 'las gafas(복수)'에 맞춰 'han roto'가 됩니다. 중남미에서는 안경을 'los lentes, los anteojos'라고도 합니다.","x":["La: 직접목적어 대명사라 이 구문을 만들지 못하고 gafas와 수도 맞지 않습니다 ✗","Me se: 순서가 틀렸습니다. 항상 se가 먼저 옵니다 ✗","Se me: 우발의 se + 피해자 me → 정답 ✓","A mí: 'A mí se me han roto'처럼 대명사가 함께 있어야 합니다 ✗"]},{"id":"G744","q":"Dudo que ____ sincero con nosotros.","o":["esté siendo","estaba siendo","está siendo","ha estado siendo"],"a":0,"k":"dudar que + 접속법","t":"그가 우리에게 솔직하게 대하고 있는지 의심스럽다.","e":"'dudar que(~인지 의심하다)'는 의심을 나타내므로 뒤에 접속법이 옵니다. 지금 이 순간 진행 중인 태도이므로 접속법 진행형 'esté siendo'를 씁니다. 'ser sincero'에 진행형을 쓰면 '(평소와 달리) 지금 솔직하게 굴고 있다'는 일시적 행동의 뉘앙스가 됩니다.","x":["esté siendo: 의심 표현 뒤 접속법 현재 진행 → 정답 ✓","estaba siendo: 직설법 과거 진행이라 dudo que 뒤에 쓰지 않습니다 ✗","está siendo: 직설법이라 의심 표현 뒤에 쓰지 않습니다 ✗","ha estado siendo: 직설법 현재완료 진행이라 맞지 않습니다 ✗"]},{"id":"G745","q":"Es normal que te ____ ciertos comentarios.","o":["molestarían","molestes","molesten","molestas"],"a":2,"k":"es normal que + 접속법","t":"네가 어떤 말들에 기분이 상하는 건 당연해.","e":"'Es normal que ~'처럼 판단·평가를 나타내는 무인칭 표현 뒤에는 접속법을 씁니다. 'molestar'는 gustar처럼 쓰는 동사로, 주어는 'ciertos comentarios(복수)'이고 기분이 상하는 사람이 te입니다. 그래서 3인칭 복수 접속법 'molesten'이 됩니다.","x":["molestarían: 가능법이라 es normal que 뒤에 쓰지 않습니다 ✗","molestes: tú를 주어로 한 형태라 '네가 남을 귀찮게 한다'는 뜻이 됩니다 ✗","molesten: 주어 comentarios(복수)에 맞춘 접속법 → 정답 ✓","molestas: 직설법이고 주어도 tú라 맞지 않습니다 ✗"]},{"id":"G746","q":"Según ____, ¿quién tiene razón?","o":["a ti","tú","ti","tu"],"a":1,"k":"según + 주격","t":"네 생각엔 누가 옳은 것 같아?","e":"'según'은 전치사지만 예외적으로 뒤에 주격 대명사(yo, tú)를 씁니다. 그래서 'según ti'가 아니라 'según tú', 'según yo'입니다. 같은 예외로 'entre tú y yo(너와 나 사이에)'도 있습니다. 'tener razón'은 '옳다'입니다.","x":["a ti: según 뒤에 a를 넣지 않습니다 ✗","tú: según 뒤의 주격 대명사 → 정답 ✓","ti: 일반 전치사 뒤 형태지만 según은 예외로 주격을 씁니다 ✗","tu: 악센트 없는 tu는 소유사(너의)라 뒤에 명사가 필요합니다 ✗"]},{"id":"G747","q":"Esta música me pone ____ buen humor.","o":["con","a","en","de"],"a":3,"k":"ponerse de buen humor","t":"이 음악은 나를 기분 좋게 만든다.","e":"'estar de buen/mal humor'는 '기분이 좋다/나쁘다'라는 표현이고, 'poner a alguien de buen humor'는 '누구를 기분 좋게 만들다'입니다. 기분 상태를 나타낼 때는 전치사 de를 씁니다. 반대로 'Me pone de mal humor'는 '짜증 나게 만든다'입니다.","x":["con: 'con buen humor'는 '좋은 기분으로(무언가를 하다)'라는 다른 쓰임입니다 ✗","a: 'a buen humor'라는 표현은 없습니다 ✗","en: 'en buen humor'는 영어식 표현으로 스페인어 기준 표현이 아닙니다 ✗","de: 'poner de buen humor(기분 좋게 하다)' → 정답 ✓"]},{"id":"G748","q":"Os lo ____, dejadme ir al concierto con Marcos.","o":["ruegue","ruego","rogaría","ruega"],"a":1,"k":"rogar 간청","t":"제발 부탁이야, 마르코스랑 콘서트 가게 해 줘.","e":"'Os lo ruego'는 '너희에게 간청한다, 제발 부탁이야'라는 강한 부탁 표현으로, 화자 자신(yo)이 지금 부탁하는 것이라 직설법 현재 1인칭 'ruego'를 씁니다. rogar는 o→ue로 바뀌는 동사입니다. 'dejadme ir'는 vosotros 명령형 '나를 가게 해 줘'입니다.","x":["ruegue: 접속법이라 독립된 주절에 쓰지 않습니다 ✗","ruego: 1인칭 직설법 현재 '간청한다' → 정답 ✓","rogaría: 가능법으로 '부탁드리고 싶다'는 정중한 표현이 되어 간절한 어조와 맞지 않고 문장 구조도 어색합니다 ✗","ruega: 3인칭이거나 tú 명령형이라 화자의 간청이 되지 않습니다 ✗"]},{"id":"G749","q":"Nos aseguró que no sabía ____ del asunto.","o":["nadie","ninguno","nada","algo"],"a":2,"k":"부정어 nada","t":"그는 그 일에 대해 아무것도 모른다고 우리에게 장담했다.","e":"'no + 동사 + nada'는 '아무것도 ~하지 않다'라는 이중 부정 구조로, 스페인어에서는 이것이 정상적인 부정입니다. 사람이 아닌 '사실·정보'를 모른다는 것이라 nada를 씁니다. 'asegurar'는 '장담하다, 확언하다'입니다.","x":["nadie: '아무도'라 사람을 가리켜 '그 일에 대해 아무도 모른다'가 되어 어색합니다 ✗","ninguno: '어느 것도/아무도'라 셀 수 있는 대상을 가리켜 의미가 맞지 않습니다 ✗","nada: '아무것도'라는 부정어 → 정답 ✓","algo: no와 함께 쓰면 '어떤 것은 모른다'가 되어 어색하고 부정 일치가 되지 않습니다 ✗"]},{"id":"G750","q":"¿____ dijiste a los niños que hoy vamos a cenar fuera?","o":["ø","Les","Le","Se"],"a":1,"k":"간접목적격 중복","t":"오늘 밖에서 저녁 먹는다고 아이들에게 말했니?","e":"스페인어에서는 간접목적어(a los niños)가 문장에 있어도 간접목적격 대명사를 함께 쓰는 것이 자연스럽고 거의 필수입니다. 'los niños'가 3인칭 복수이므로 'les'를 씁니다. 'cenar fuera'는 '외식하다'입니다.","x":["ø: 대명사 없이도 이해는 되지만 스페인어에서는 les를 함께 쓰는 것이 자연스럽습니다 ✗","Les: 3인칭 복수 간접목적격 → 정답 ✓","Le: 단수라 복수인 los niños와 맞지 않습니다(구어에서 흔한 실수) ✗","Se: 직접목적어 lo가 함께 올 때(se lo)만 le/les가 se로 바뀝니다 ✗"]}];